var It=t=>[t.textOnly?"text":"original"],A=t=>({mode:t.textOnly?"text":"original"}),E=t=>It(t)[0];function xe(t){return{question:t.textQuestion??t.question,options:t.options,answer:t.answer,alt:t.imageAlt??t.observation?.alt??"香港文化漫畫插畫",clue:""}}var K=Object.freeze([{id:"p01",tier:1,category:"環保・污泥轉身",question:"朋友話去T·PARK「源．區」睇轉廢為能。這裡主要處理哪種物料？",options:["污水處理廠的污泥","建築工程的廢木","回收站的廢玻璃","修剪樹木的枝葉"],answer:0,explanation:"源．區接收污水處理廠的污泥，再以焚化技術處理。污泥都識轉型，我份履歷仲未更新。",hint:"留意污水經處理後留下的物料。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"T·PARK・處理流程",url:"https://www.tpark.hk/tc/process"},review:"2026-11-27依列明官方或營辦機構資料核對；歷史題按指定年份，工程題按題目限定的設施或範圍作答。"},{id:"p02",tier:1,category:"環保・廚餘有下文",question:"食剩半碟飯唔係故事結局。O·PARK1主要把哪類廢物轉成能源及堆肥？",options:["廢紙","廚餘","廢金屬","廢膠樽"],answer:1,explanation:"O·PARK1用厭氧分解技術處理廚餘。你食唔落的最後一啖，原來仲有第二份工。",hint:"材料來自備餐及用餐過程。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"O·PARK1・中心介紹",url:"https://www.opark.gov.hk/tc/"},review:"2026-11-27依列明官方或營辦機構資料核對；歷史題按指定年份，工程題按題目限定的設施或範圍作答。"},{id:"p03",tier:1,category:"郵政・自助取件",question:"網購終於到貨，手機收到智郵站取件通知。智郵站主要是哪種設施？",options:["自助申領郵政信箱的機台","自助選購郵票的售賣機","自助領取郵件的儲物櫃","自助印製明信片的機台"],answer:2,explanation:"智郵站讓收件人憑通知資料自助取件。到貨訊息一響，行路速度即時升級。",hint:"把「取件」與「投寄」分開。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"政府新聞網・智能郵政",url:"https://www.news.gov.hk/chi/2023/07/20230713/20230713_184301_929.html"},review:"2026-11-27依列明官方或營辦機構資料核對；歷史題按指定年份，工程題按題目限定的設施或範圍作答。"},{id:"p04",tier:1,category:"鐵路・機場快綫",question:"去旅行前先核對站名：機場快綫在中環一帶的市區終點是哪站？",options:["中環站","金鐘站","上環站","香港站"],answer:3,explanation:"機場快綫的市區終點是香港站。行李箱識跟住你，唔代表佢識幫你揀站。",hint:"列車站名與附近地區名稱未必一樣。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"港鐵・鐵路網絡",url:"https://www.mtr.com.hk/ch/corporate/operations/detail_network.html"},review:"2026-11-27依列明官方或營辦機構資料核對；歷史題按指定年份，工程題按題目限定的設施或範圍作答。"},{id:"p05",tier:1,category:"鐵路・旺角有個東",question:"約朋友在旺角東站見，差一個字就行多幾條街。旺角東屬哪條港鐵綫？",options:["東鐵綫","觀塘綫","荃灣綫","屯馬綫"],answer:0,explanation:"旺角東是東鐵綫車站。個「東」字細細粒，行錯路的步數就大大堆。",hint:"留意旺角站與旺角東站是兩個車站。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"港鐵・旺角東站服務資料",url:"https://www.mtr.com.hk/ch/customer/services/service_hours_search.php?query_type=search&station=65"},review:"2026-11-27依列明官方或營辦機構資料核對；歷史題按指定年份，工程題按題目限定的設施或範圍作答。"},{id:"p06",tier:1,category:"鐵路・南區到站",question:"坐南港島綫去鴨脷洲，想一覺瞓到終點。鴨脷洲一端的終點是哪站？",options:["利東站","海怡半島站","黃竹坑站","海洋公園站"],answer:1,explanation:"南港島綫來往金鐘與海怡半島。可以瞓到終點，但唔保證朋友肯等你補眠。",hint:"把沿途車站與終點分清。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"港鐵・鐵路網絡",url:"https://www.mtr.com.hk/ch/corporate/operations/detail_network.html"},review:"2026-11-27依列明官方或營辦機構資料核對；歷史題按指定年份，工程題按題目限定的設施或範圍作答。"},{id:"p07",tier:1,category:"創科・園區定位",question:"去香港科學園見客，導航先救回半條命。科學園本港園區位於哪一帶？",options:["小瀝源","將軍澳","白石角","元朗"],answer:2,explanation:"香港科學園位於白石角、吐露港沿岸。創意可以天馬行空，見客地址最好落地。",hint:"園區在吐露港沿岸。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"香港科技園・交通資訊",url:"https://www.hkstp.org/zh-hk/visit/transportation"},review:"2026-11-27依列明官方或營辦機構資料核對；歷史題按指定年份，工程題按題目限定的設施或範圍作答。"},{id:"p08",tier:1,category:"創科・數碼港定位",question:"數碼港個名好似可以登入，實際去開會仍要搭車。它位於港島哪一帶？",options:["小西灣","北角","赤柱","薄扶林"],answer:3,explanation:"數碼港位於薄扶林鋼綫灣一帶。視像會議有登入掣，實體會議得一對腳。",hint:"它位於港島西南部。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"數碼港・園區交通及地址",url:"https://www.cyberport.hk/zh-hk/about_us/cyberport_campus/"},review:"2026-11-27依列明官方或營辦機構資料核對；歷史題按指定年份，工程題按題目限定的設施或範圍作答。"},{id:"p09",tier:1,category:"城市服務・一個號碼",question:"街坊想查詢政府服務，又想反映公共設施問題。1823的主要角色是哪項？",options:["接收政府服務查詢及服務要求／投訴","辦理銀行信用卡交易爭議","安排私營商店退款仲裁","代市民預約所有私人診所"],answer:0,explanation:"1823處理參與部門查詢，並接收政府服務要求及投訴再轉介。講清地點，比連續十個「嗰度」更有用。",hint:"它聯繫的是政府服務。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"1823・關於我們",url:"https://www.1823.gov.hk/tc/about-us"},review:"2026-11-27依列明官方或營辦機構資料核對；歷史題按指定年份，工程題按題目限定的設施或範圍作答。"},{id:"p10",tier:1,category:"環保基建・人工島",question:"睇I·PARK1工程介紹，先認清地點：這座設施建於哪個島嶼旁的人工島？",options:["長洲","石鼓洲","南丫島","坪洲"],answer:1,explanation:"I·PARK1位於石鼓洲旁人工島。地名認得清，睇工程新聞就唔使每次重新開地圖。",hint:"它鄰近大嶼山以南水域的島嶼。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"政府新聞公報・I·PARK1",url:"https://www.info.gov.hk/gia/general/202512/22/P2025122200378p.htm"},review:"2026-11-27依列明官方或營辦機構資料核對；歷史題按指定年份，工程題按題目限定的設施或範圍作答。"},{id:"p11",tier:1,category:"機場・短途都搭車",question:"在機場見到旅客捷運系統APM，雙腳終於鬆一口氣。它主要接載旅客往來哪類地方？",options:["中環與九龍的市區車站","東涌與昂坪的山區車站","機場客運大樓及客運廊等設施","口岸與深圳的跨境車站"],answer:2,explanation:"旅客捷運系統接駁機場內的客運設施。行李拖得幾順，都唔及有車搭咁開心。",hint:"它與連接市區的機場快綫不同。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"香港國際機場・旅客捷運系統",url:"https://www.hongkongairport.com/tc/passenger-guide/airport-facilities-services/automated-people-mover"},review:"2026-11-27依列明官方或營辦機構資料核對；歷史題按指定年份，工程題按題目限定的設施或範圍作答。"},{id:"p12",tier:1,category:"測繪・手機搵路",question:"朋友傳來「地理資訊地圖」GeoInfo Map幫你搵地方。這個平台由哪個政府部門管理？",options:["運輸署","屋宇署","渠務署","地政總署"],answer:3,explanation:"地政總署管理地理資訊地圖等空間資訊平台。地圖搵到目的地，仍要靠你肯出門。",hint:"從測量、製圖及地理數據職能想起。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"地政總署・地理空間信息服務",url:"https://www.landsd.gov.hk/tc/spatial-data/geospatial-infomation-services.html"},review:"2026-11-27依列明官方或營辦機構資料核對；歷史題按指定年份，工程題按題目限定的設施或範圍作答。"},{id:"p13",tier:1,category:"郵政・郵包中途站",question:"網購包裹仲未到，先研究它的香港旅程。香港郵政中央郵件中心設於哪區？",options:["九龍灣","長沙灣","葵涌","馬鞍山"],answer:0,explanation:"香港郵政中央郵件中心設於九龍灣。包裹有分揀流程，你的追蹤頁就有刷新流程。",hint:"留意東九龍的物流設施。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"政府新聞網・智能郵政",url:"https://www.news.gov.hk/chi/2023/07/20230713/20230713_184301_929.html"},review:"2026-11-27依列明官方或營辦機構資料核對；歷史題按指定年份，工程題按題目限定的設施或範圍作答。"},{id:"p14",tier:1,category:"郵政・機台幫你度",question:"寄包裹時見到「智郵寄」，唔使靠目測扮專家。機台可自動量度哪兩項資料？",options:["郵件尺寸與郵票面值","郵件尺寸與重量","郵件重量與申報價值","郵資金額與派送距離"],answer:1,explanation:"智郵寄用掃描及量度設備取得郵件尺寸、重量。目測「應該唔重」終於可以退休。",hint:"兩項資料都與郵件的物理大小有關。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"政府新聞網・智能郵政",url:"https://www.news.gov.hk/chi/2023/07/20230713/20230713_184301_929.html"},review:"2026-11-27依列明官方或營辦機構資料核對；歷史題按指定年份，工程題按題目限定的設施或範圍作答。"},{id:"p15",tier:2,category:"排水・截住再分流",question:"暴雨落到急過老闆催稿。港島西雨水排放隧道主要怎樣減輕下游水浸威脅？",options:["把半山雨水引入地下蓄洪池暫存","把雨水抽送至污水處理廠","截取半山雨水，經隧道直接排海","把集水區雨水導入水塘儲存"],answer:2,explanation:"隧道截取半山雨水，減低下游排水系統負荷。雨水識行捷徑，趕返工的我仲研究緊轉車。",hint:"關鍵是雨水進入密集市區渠道之前的分流。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"渠務署・港島西雨水隧道工程概覽",url:"https://www.dsd.gov.hk/others/HKWDT/tc/op_overview.html"},review:"2026-11-27依列明官方或營辦機構資料核對；歷史題按指定年份，工程題按題目限定的設施或範圍作答。"},{id:"p16",tier:2,category:"排水・地底有後備",question:"跑馬地地下蓄洪池幫暴雨「暫存行李」。它藏在哪個地方的地底？",options:["維多利亞公園","香港大球場","修頓遊樂場","跑馬地遊樂場"],answer:3,explanation:"蓄洪池建於跑馬地遊樂場地底，暴雨時暫存雨水。地面踢波，地底守住另一個波。",hint:"地面是跑馬地的康樂用地。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"渠務署・跑馬地地下蓄洪計劃",url:"https://www.dsd.gov.hk/TC/HTML/20515.html"},review:"2026-11-27依列明官方或營辦機構資料核對；歷史題按指定年份，工程題按題目限定的設施或範圍作答。"},{id:"p17",tier:2,category:"道路・山腹捷徑",question:"朋友話穿香港仔隧道就去到南區。按運輸署資料，它連接哪兩處？",options:["跑馬地與黃竹坑","北角與赤柱","筲箕灣與石澳","堅尼地城與薄扶林"],answer:0,explanation:"香港仔隧道連接跑馬地及黃竹坑。隧道名有香港仔，兩端地名仍要分開記。",hint:"灣仔區與南區之間的通道。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"運輸署・隧道及橋樑位置",url:"https://www.td.gov.hk/tc/transport_in_hong_kong/tunnels_and_bridges_n/location_map/index.html"},review:"2026-11-27依列明官方或營辦機構資料核對；歷史題按指定年份，工程題按題目限定的設施或範圍作答。"},{id:"p18",tier:2,category:"道路・過海認兩岸",question:"聽到「行東隧」就點頭，點完才發現未識兩端。東區海底隧道連接哪兩處？",options:["北角與土瓜灣","鰂魚涌與茶果嶺","柴灣與將軍澳","灣仔與尖沙咀"],answer:1,explanation:"東區海底隧道連接鰂魚涌及茶果嶺。點頭可以好快，過海最好先知去邊。",hint:"港島東區對接觀塘區。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"運輸署・隧道及橋樑位置",url:"https://www.td.gov.hk/tc/transport_in_hong_kong/tunnels_and_bridges_n/location_map/index.html"},review:"2026-11-27依列明官方或營辦機構資料核對；歷史題按指定年份，工程題按題目限定的設施或範圍作答。"},{id:"p19",tier:2,category:"橋樑・上下有分工",question:"青馬大橋上層行車，下層又唔係地下商場。下層實際設有哪組設施？",options:["鐵路路軌及公眾行人路","有蓋行車道及公眾單車徑","鐵路路軌及有蓋行車道","電車路軌及公眾行人路"],answer:2,explanation:"下層設鐵路及有蓋行車道，後者可作維修及特定情況改道之用。一條橋都比我的行程表有後備方案。",hint:"它是道路、鐵路兩用橋。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"路政署・青馬大橋資料便覽",url:"https://www.hyd.gov.hk/tc/information_corner/hyd_factsheets/doc/C_Tsing_Ma_Bridge.pdf"},review:"2026-11-27依列明官方或營辦機構資料核對；歷史題按指定年份，工程題按題目限定的設施或範圍作答。"},{id:"p20",tier:2,category:"橋樑・三種速度",question:"將軍澳跨灣連接路畀唔同步速的人各有位置。它同時提供哪三類通道？",options:["行車道、鐵路及行人路","鐵路、單車徑及行人路","行車道、電車路及單車徑","行車道、單車徑及行人路"],answer:3,explanation:"跨灣連接路同時設行車道、單車徑與行人路。趕時間、踩車、散步，終於各自有路。",hint:"留意橋上有給騎單車及步行人士的空間。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"政府新聞網・將軍澳跨灣連接路",url:"https://www.news.gov.hk/chi/2022/11/20221115/20221115_151334_582.html"},review:"2026-11-27依列明官方或營辦機構資料核對；歷史題按指定年份，工程題按題目限定的設施或範圍作答。"},{id:"p21",tier:2,category:"無障礙・上橋少啲氣喘",question:"拖住行李上天橋，未上到先做完運動。「人人暢道通行」計劃主要加建哪種設施？",options:["升降機","扶手電梯","長距離斜道","行人輸送帶"],answer:0,explanation:"計劃在既有行人通道加建升降機等無障礙設施。行李箱終於唔使每級樓梯都同你傾偈。",hint:"它改善既有天橋、隧道等的無障礙通行。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"路政署・人人暢道通行計劃",url:"https://www.hyd.gov.hk/tc/our_projects/walkability_projects/UA/"},review:"2026-11-27依列明官方或營辦機構資料核對；歷史題按指定年份，工程題按題目限定的設施或範圍作答。"},{id:"p22",tier:2,category:"能源・污泥都有下集",question:"T·PARK焚化污泥產生的熱能，主要透過哪個步驟轉成電力？",options:["讓煙氣直接推動燃氣渦輪","產生蒸汽推動渦輪機","加熱氣體驅動史特靈引擎","利用熱電材料直接發電"],answer:1,explanation:"熱能把水變成蒸汽，推動渦輪機發電。污泥的下半場咁有衝勁，我午飯後只想叉電。",hint:"先由熱把水轉成另一種狀態。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"T·PARK・處理流程",url:"https://www.tpark.hk/tc/process"},review:"2026-11-27依列明官方或營辦機構資料核對；歷史題按指定年份，工程題按題目限定的設施或範圍作答。"},{id:"p23",tier:2,category:"道路史・隧道曾改名",question:"翻舊地圖見到「機場隧道」，別急住叫車去赤鱲角。2006年改名後，它叫甚麼？",options:["尖山隧道","南灣隧道","啟德隧道","長青隧道"],answer:2,explanation:"舊機場隧道在2006年改名啟德隧道。地圖有年代，導航前記得先睇年份。",hint:"名稱保留了舊機場所在地方。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"運輸署・運輸資料年報2020",url:"https://www.td.gov.hk/mini_site/atd/2020/tc/section4_t_7.html"},review:"2026-11-27依列明官方或營辦機構資料核對；歷史題按指定年份，工程題按題目限定的設施或範圍作答。"},{id:"p24",tier:2,category:"能源・發電廠認燃料",question:"龍鼓灘發電廠於1996年投產時，把哪種燃料帶進香港的大型發電組合？",options:["泥煤","重油","褐煤","天然氣"],answer:3,explanation:"龍鼓灘是香港首個天然氣發電站。名稱似去郊遊，實際工作是替全城的插頭努力。",hint:"留意中電介紹的主要燃料。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"中電・龍鼓灘發電廠",url:"https://www.clp.com.hk/zh/about-clp/power-generation/black-point-power-station"},review:"2026-11-27依列明官方或營辦機構資料核對；歷史題按指定年份，工程題按題目限定的設施或範圍作答。"},{id:"p25",tier:2,category:"公屋・樓型有名字",question:"廣田邨是較早採用某款標準設計的屋邨之一。這款設計叫甚麼？",options:["和諧式","工字型","雙塔式","長型"],answer:0,explanation:"房委會資料把廣田邨列為早期採用和諧式的屋邨之一。樓型有名有姓，唔係全部統稱「嗰棟」。",hint:"留意1990年代公屋常見的設計名稱。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"房委會・公屋大廈設計演變",url:"https://www.housingauthority.gov.hk/tc/about-us/publications-and-statistics/housing-dimensions/article/20110902/fun-deck-public-housing-blocks-design-in-evolution.html"},review:"2026-11-27依列明官方或營辦機構資料核對；歷史題按指定年份，工程題按題目限定的設施或範圍作答。"},{id:"p26",tier:2,category:"房屋史・房協第一步",question:"房協的出租屋邨故事由哪個已拆卸的深水埗屋邨起步？",options:["祖堯邨","上李屋","真善美村","健康村"],answer:1,explanation:"上李屋是房協首個出租屋邨項目。由一個安身地方開始，先有餘力慢慢寫生活故事。",hint:"這個項目位於深水埗。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"香港房屋協會・上李屋",url:"https://www.hkhs.com/tc/housing_archive/id/27"},review:"2026-11-27依列明官方或營辦機構資料核對；歷史題按指定年份，工程題按題目限定的設施或範圍作答。"},{id:"p27",tier:2,category:"水務・原水入境",question:"東江水來港也有交接站。直接接收從深圳水庫輸來的東江水，再分送本港的是哪個抽水站？",options:["大埔頭原水抽水站","大美督原水抽水站","木湖原水抽水站","貝澳原水抽水站"],answer:2,explanation:"木湖原水抽水站接收東江水，再沿主要管道分配。原水都有轉乘，我就仲喺月台搵車頭。",hint:"它是東江水進入香港供水網絡的重要接點。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"水務署・東江水",url:"https://www.wsd.gov.hk/tc/core-businesses/water-resources/dongjiang-water/index.html"},review:"2026-11-27依列明官方或營辦機構資料核對；歷史題按指定年份，工程題按題目限定的設施或範圍作答。"},{id:"p28",tier:3,category:"污水工程・處理有層次",question:"讀昂船洲污水處理廠介紹，名詞比工作電郵更密。它採用哪種主要處理工藝？",options:["活性污泥二級處理","逆滲透膜深度處理","人工濕地自然處理","化學強化一級處理"],answer:3,explanation:"昂船洲採用化學強化一級處理，是淨化海港計劃的重要設施。處理級別要睇工藝，唔係睇廠房有幾多層。",hint:"它的英文縮寫是CEPT。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"渠務署・昂船洲污水處理廠",url:"https://www.dsd.gov.hk/TC/HTML/20524.html"},review:"2026-11-27依列明官方或營辦機構資料核對；歷史題按指定年份，工程題按題目限定的設施或範圍作答。"},{id:"p29",tier:3,category:"污水工程・微小隊友",question:"沙田污水處理廠的曝氣池不停送入空氣，主要是支援哪個處理過程？",options:["活性污泥微生物分解有機污染物","混凝劑凝聚並沉澱懸浮固體","高壓薄膜分離溶解鹽分","紫外光消毒減少病原微生物"],answer:0,explanation:"空氣為活性污泥微生物供氧，讓它們分解有機污染物。呢班微小隊友開工，唔使你逐個催進度。",hint:"它屬生物處理，而非單靠過濾或消毒。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"渠務署・沙田污水處理廠",url:"https://www.dsd.gov.hk/TC/HTML/20512.html"},review:"2026-11-27依列明官方或營辦機構資料核對；歷史題按指定年份，工程題按題目限定的設施或範圍作答。"},{id:"p30",tier:3,category:"水務工程・海水變食水",question:"將軍澳海水化淡廠用高壓推動水穿過半透膜。這套核心技術叫甚麼？",options:["多級閃蒸","逆滲透","多效蒸餾","電滲析"],answer:1,explanation:"將軍澳海水化淡採用逆滲透，讓水穿過半透膜並阻隔鹽分。加壓可以幫水過關，加班就未必幫我開竅。",hint:"核心是壓力與半透膜，並非煮沸。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"發展局・將軍澳海水化淡廠",url:"https://www.devb.gov.hk/tc/home/my_blog/index_id_1550.html"},review:"2026-11-27依列明官方或營辦機構資料核對；歷史題按指定年份，工程題按題目限定的設施或範圍作答。"},{id:"p31",tier:3,category:"隧道工程・海床下開路",question:"屯門—赤鱲角海底行車隧道建造時，採用哪種主要開挖方式穿越海床下？",options:["預製沉管逐節沉放","海床明挖後覆蓋回填","隧道鑽挖機鑽挖","鑽爆法分段開挖"],answer:2,explanation:"這條海底行車隧道採用隧道鑽挖機建造。開路靠巨型機械，我開會連個話題都未鑽入。",hint:"比較鑽挖隧道與沉管隧道。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"政府新聞公報・屯赤連接路通車",url:"https://www.info.gov.hk/gia/general/202012/26/P2020122600179.htm"},review:"2026-11-27依列明官方或營辦機構資料核對；歷史題按指定年份，工程題按題目限定的設施或範圍作答。"},{id:"p32",tier:3,category:"橋樑工程・數塔先作答",question:"汀九橋遠睇似拉起幾把巨型傘。支承主橋斜拉索的單支柱橋塔共有多少座？",options:["兩座","四座","五座","三座"],answer:3,explanation:"汀九橋有三座單支柱橋塔。數塔可以慢慢嚟，搭車經過就唔好叫司機停低畀你重數。",hint:"想想汀九、中央與青衣三個位置。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"路政署・汀九橋資料便覽",url:"https://www.hyd.gov.hk/tc/information_corner/hyd_factsheets/doc/C_TingKau_Bridge.pdf"},review:"2026-11-27依列明官方或營辦機構資料核對；歷史題按指定年份，工程題按題目限定的設施或範圍作答。"},{id:"p33",tier:3,category:"橋樑工程・主跨唔係全長",question:"青馬大橋的「主跨」與全橋長度係兩回事。按路政署資料，主跨約有多少米？",options:["1,377米","1,088米","1,177米","2,160米"],answer:0,explanation:"青馬大橋主跨為1,377米，全長為2,160米。兩個數都有出處，見到熟口熟面先最易中招。",hint:"題目要兩座主塔之間的跨距。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"路政署・青馬大橋資料便覽",url:"https://www.hyd.gov.hk/tc/information_corner/hyd_factsheets/doc/C_Tsing_Ma_Bridge.pdf"},review:"2026-11-27依列明官方或營辦機構資料核對；歷史題按指定年份，工程題按題目限定的設施或範圍作答。"},{id:"p34",tier:3,category:"鐵路工程・列車返廠",question:"東鐵綫列車也有「返廠保養」行程。港鐵列明東鐵綫的維修車廠設在哪裡？",options:["八鄉","何東樓","小蠔灣","黃竹坑"],answer:1,explanation:"東鐵綫的維修車廠設於何東樓。日日載人返工的列車，收工都要有人照顧。",hint:"分清東鐵、屯馬、機場鐵路及南港島綫的車廠。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"港鐵・車廠",url:"https://www.mtr.com.hk/ch/corporate/operations/detail_depots.html"},review:"2026-11-27依列明官方或營辦機構資料核對；歷史題按指定年份，工程題按題目限定的設施或範圍作答。"},{id:"p35",tier:3,category:"橋樑工程・中央塔點企穩",question:"汀九橋中央塔與兩端橋塔的地基安排不同。中央塔主要採用哪種地基？",options:["岩床上的筏形地基","重力式沉箱地基","鑽孔樁地基","預製打入樁地基"],answer:2,explanation:"中央塔建於人工島上的鑽孔樁，兩端塔則採岩床上的筏形地基。同一條橋，企穩的方法都有分工。",hint:"把海峽中央塔與汀九、青衣兩端塔分開比較。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"路政署・汀九橋資料便覽",url:"https://www.hyd.gov.hk/tc/information_corner/hyd_factsheets/doc/C_TingKau_Bridge.pdf"},review:"2026-11-27依列明官方或營辦機構資料核對；歷史題按指定年份，工程題按題目限定的設施或範圍作答。"},{id:"p36",tier:3,category:"測繪工程・高度先對基準",question:"睇香港地圖的陸上高程，數字之前先要認清「零位」。通常採用哪個高程基準？",options:["香港海圖基準面","世界大地測量系統1984橢球面","1965至1983年平均海平面","香港主水平基準"],answer:3,explanation:"香港地圖的陸上高程以香港主水平基準為參考。未對準零位就比高度，好似兩個人用唔同鐘約食飯。",hint:"分清陸上高度、海圖水深及平面坐標。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"香港天文台・風暴潮與基準面",url:"https://www.hko.gov.hk/tc/education/tropical-cyclone/weather-effects-and-impact/00444-know-more-about-storm-surge.html"},review:"2026-11-27依列明官方或營辦機構資料核對；歷史題按指定年份，工程題按題目限定的設施或範圍作答。"},{id:"p37",tier:3,category:"鐵路工程・電力規格",question:"同樣係港鐵，供電未必同款。東鐵綫電動車組使用哪個牽引供電規格？",options:["25千伏交流電","1,500伏直流電","750伏直流電","11千伏交流電"],answer:0,explanation:"港鐵列明東鐵綫電動車組使用25千伏交流電。列車有專屬供電規格，唔好用手機充電的直覺去估。",hint:"東鐵與屯馬採用同類規格，與部分市區綫不同。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"港鐵・車廠",url:"https://www.mtr.com.hk/ch/corporate/operations/detail_depots.html"},review:"2026-11-27依列明官方或營辦機構資料核對；歷史題按指定年份，工程題按題目限定的設施或範圍作答。"},{id:"p38",tier:3,category:"燃氣工程・名字會誤導",question:"按煤氣公司2025年介紹，香港供應的煤氣約有一半成分是哪種氣體？",options:["甲烷","氫氣","氮氣","二氧化碳"],answer:1,explanation:"煤氣公司介紹其香港燃氣約一半成分為氫氣。名字有個「煤」，成分表仍要逐項睇。",hint:"這裡問香港煤氣，並非天然氣的主要成分。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"煤氣公司・2025年氫能合作介紹",url:"https://www.towngas.com/tc/Media-Resources/Press-Releases/2025/Towngas-and-Cimc-Enric-Sign-Strategic-Partnership-Agreement-To-Jointly-Develop-Green-Methanol-and-Hydrogen-Energy"},review:"2026-11-27依列明官方或營辦機構資料核對；歷史題按指定年份，工程題按題目限定的設施或範圍作答。"},{id:"p39",tier:3,category:"污水工程・污泥坐船",question:"「淨港一號」及「淨港二號」的貨物唔賣船票。它們把昂船洲污泥運往哪座設施？",options:["小蠔灣O·PARK1","石鼓洲旁I·PARK1","屯門T·PARK源．區","西九龍廢物轉運站"],answer:2,explanation:"兩艘污泥船把昂船洲污水處理廠的污泥運往屯門源．區。污泥出海有專船，我出海仲要搵人分船費。",hint:"它的終點是專門處理污泥的設施。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"渠務署・昂船洲污水處理廠",url:"https://www.dsd.gov.hk/TC/HTML/20524.html"},review:"2026-11-27依列明官方或營辦機構資料核對；歷史題按指定年份，工程題按題目限定的設施或範圍作答。"},{id:"p40",tier:3,category:"機場工程・海泥原地穩固",question:"三跑道填海前，在污染泥料卸置坑範圍採用哪種方法作地質改良？",options:["預製垂直排水帶法","碎石樁加固法","振動壓密砂樁法","深層水泥拌合法"],answer:3,explanation:"該範圍採用深層水泥拌合法，原地穩固海泥。地基要先站得穩，飛機先可以放心起步。",hint:"留意污染泥料的原地穩固處理。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"機管局・2018／19可持續發展報告",url:"https://www.hongkongairport.com/iwov-resources/html/sustainability_report/chi/SR1819/greenest-airport/biodiversity/"},review:"2026-11-27依列明官方或營辦機構資料核對；歷史題按指定年份，工程題按題目限定的設施或範圍作答。"}].map(t=>Object.freeze({...t,options:Object.freeze(t.options),source:Object.freeze(t.source),focus:Object.freeze(t.focus),modes:Object.freeze(t.modes)})));var V=Object.freeze([{id:"q01",tier:1,category:"港隊・企定都好勁",question:"睇東京2020奧運重溫，劉慕裳的女子個人形銅牌屬於哪項運動？",options:["空手道","跆拳道","柔道","武術"],answer:0,explanation:"劉慕裳在東京2020奧運的空手道女子個人形取得銅牌。佢每個動作都收放自如，你喺梳化跟住做之前，先移開個茶几。",hint:"留意「個人形」的動作套路。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"政府新聞公報・劉慕裳東京奧運銅牌",url:"https://www.info.gov.hk/gia/general/202108/05/P2021080500740p.htm"},review:"2026-11-27核對所列一手資料；賽事、作品及傳統用語按題目所列年份或情境理解。"},{id:"q02",tier:1,category:"港隊・球拍好忙",question:"陳浩源在2024巴黎殘奧男子WH2級單打摘銀，手上用的是哪項運動的球拍？",options:["乒乓球","羽毛球","網球","壁球"],answer:1,explanation:"陳浩源在2024巴黎殘奧的羽毛球男子WH2級單打奪銀。睇佢接波快到咁，唔好以為自己追巴士嗰兩步已經同級。",hint:"分清網前飛行的小球與有羽毛的球。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"政府新聞公報・陳浩源巴黎殘奧銀牌",url:"https://www.info.gov.hk/gia/general/202409/03/P2024090300106.htm"},review:"2026-11-27核對所列一手資料；賽事、作品及傳統用語按題目所列年份或情境理解。"},{id:"q03",tier:1,category:"港隊・一球定乾坤",question:"何宛淇在2024巴黎殘奧的女子個人BC3賽事奪金，屬於哪項運動？",options:["輪椅網球","乒乓球","硬地滾球","輪椅劍擊"],answer:2,explanation:"何宛淇在巴黎殘奧硬地滾球女子個人BC3奪金。球行得唔快，形勢照樣可以緊張到你手上包薯片都停咗。",hint:"BC3是這項精準落球運動的分級。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"香港浸會大學・巴黎殘奧金銀牌",url:"https://www.hkbu.edu.hk/zh_hk/whats-new/press-release/2024/0903-hkbu-congratulates-chan-ho-yuen-and-ho-yuen-kei-on-winning-silver-and-gold-medals-respectively-at-paralympic-games.html"},review:"2026-11-27核對所列一手資料；賽事、作品及傳統用語按題目所列年份或情境理解。"},{id:"q04",tier:1,category:"港隊・落袋為安",question:"街坊講傅家俊打出一桿精彩表現，最可能正在看哪項運動？",options:["乒乓球","高爾夫球","保齡球","桌球"],answer:3,explanation:"傅家俊是香港桌球運動員。計路線、控力度樣樣講功夫，唔係支球桿揸得型就會自動清枱。",hint:"留意「一桿」以及球枱上的不同色球。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"香港體育學院・2017/18國際賽成績",url:"https://www.hksi.org.hk/annual-report/2017-18/tc/our-focus-aiming-for-excellence-in-sporting-achievements/international-results/"},review:"2026-11-27核對所列一手資料；賽事、作品及傳統用語按題目所列年份或情境理解。"},{id:"q05",tier:1,category:"港隊・劍尖見真章",question:"余翠怡在2012倫敦殘奧奪金的運動，是以下哪項？",options:["輪椅劍擊","輪椅網球","輪椅籃球","硬地滾球"],answer:0,explanation:"余翠怡在倫敦2012殘奧的輪椅劍擊女子重劍個人A級奪金。劍尖一閃就見分曉，觀眾眨眼慢咗都可能要睇重播。",hint:"這項運動講求距離、時機與劍尖的準確度。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"香港體育學院・2012年第九期體訊",url:"https://www.hksi.org.hk/hksdb/html/pdf/sb/09_12/sb_c.html"},review:"2026-11-27核對所列一手資料；賽事、作品及傳統用語按題目所列年份或情境理解。"},{id:"q06",tier:1,category:"粵劇・無馬都有馬",question:"粵劇台上冇真馬，演員拿馬鞭配合相關身段，通常表示甚麼？",options:["船隻正在靠岸","人物正在騎馬","轎夫正在抬轎","人物正在登山"],answer:1,explanation:"粵劇利用馬鞭及身段象徵騎馬，毋須把真馬帶上舞台。演員一步可以走過千里，你行到港鐵站已經想買杯嘢飲。",hint:"想想道具與身段合起來代表的交通方式。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"香港教育大學・粵劇教學協作計劃",url:"https://xich.eduhk.hk/f/page/1205/2794/25.pdf"},review:"2026-11-27核對所列一手資料；賽事、作品及傳統用語按題目所列年份或情境理解。"},{id:"q07",tier:1,category:"粵劇・袖有乾坤",question:"睇粵劇時見演員揮舞「水袖」，這部分衣飾通常位於哪裏？",options:["頭盔後方的垂纓","腰帶兩側的穗飾","衣袖前端的延長袖段","靴口外翻的布邊"],answer:2,explanation:"水袖是戲服袖端延長的部分，可配合身段傳情達意。揮得靚係功夫，唔係借個名叫你用衫袖抹枱。",hint:"留意它與手臂動作相連的位置。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"香港教育大學・粵劇教學協作計劃",url:"https://xich.eduhk.hk/f/page/1205/2794/25.pdf"},review:"2026-11-27核對所列一手資料；賽事、作品及傳統用語按題目所列年份或情境理解。"},{id:"q08",tier:1,category:"粵劇・笑位擔當",question:"粵劇台上想找主要扮演滑稽人物的行當，應留意哪一類？",options:["淨","旦","生","丑"],answer:3,explanation:"丑角主要扮演滑稽人物，男女角色皆有。好嘅笑位講節奏，唔係你喺後排大聲接住講就會獲邀上台。",hint:"它的表演常有詼諧、幽默的一面。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"香港教育大學・粵劇角色行當",url:"https://xich.eduhk.hk/zht/page/detail/1275"},review:"2026-11-27核對所列一手資料；賽事、作品及傳統用語按題目所列年份或情境理解。"},{id:"q09",tier:1,category:"飲茶・煙韌有原因",question:"飲茶咬開鹹水角，常見配方會用哪款粉料做出煙韌外皮？",options:["糯米粉","全麥麵粉","粟米澱粉","蕎麥粉"],answer:0,explanation:"常見鹹水角外皮用糯米粉配合澄麵等材料製作。外脆內煙韌係點心特色，唔代表個名有水就可以當一杯水計。",hint:"留意可做出黏糯口感的米粉。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"粵典・鹹水角",url:"https://words.hk/zidin/%E5%92%B8%E6%B0%B4%E8%A7%92"},review:"2026-11-27核對所列一手資料；賽事、作品及傳統用語按題目所列年份或情境理解。"},{id:"q10",tier:1,category:"街坊話・收工前一關",question:"同事說「做埋啲手尾先走」，在收工前通常指甚麼？",options:["把工具全部換新","完成剩下的收尾工作","預早開始下週工作","等其他同事先離開"],answer:1,explanation:"手尾指未做完或需要最後處理的工夫。做埋先走可以，唔好一執就執到下個更次又返嚟。",hint:"不是身體部位，是一件工作剩下的部分。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"粵典・手尾",url:"https://words.hk/zidin/%E6%89%8B%E5%B0%BE"},review:"2026-11-27核對所列一手資料；賽事、作品及傳統用語按題目所列年份或情境理解。"},{id:"q11",tier:1,category:"街坊話・球門好遠",question:"朋友踢完波話自己「食白果」，按入球表現通常是甚麼意思？",options:["只入一球","入球被取消","沒有入球","入球後被換走"],answer:2,explanation:"食白果可以形容沒有收穫；講球員入球表現時，就是未能取得入球。賽後食糖水真係有白果，另計。",hint:"這句說話重點是付出後沒有收穫。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"粵典・食白果",url:"https://words.hk/zidin/%E9%A3%9F%E7%99%BD%E6%9E%9C"},review:"2026-11-27核對所列一手資料；賽事、作品及傳統用語按題目所列年份或情境理解。"},{id:"q12",tier:1,category:"街坊話・格價雷達",question:"買嘢格價時講「唔想蝕底」，意思最接近哪項？",options:["不想欠款","不想換貨","不想講價","不想吃虧"],answer:3,explanation:"蝕底是吃虧、受到損失的意思。格價格到連來回車費都貴過差價，嗰下就真係要再計清楚。",hint:"重點是避免自己處於較不利的位置。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"香港中文大學・粵語審音配詞字庫：蝕底",url:"https://apps.itsc.cuhk.edu.hk/hanyu/Page/Search.aspx?id=14785"},review:"2026-11-27核對所列一手資料；賽事、作品及傳統用語按題目所列年份或情境理解。"},{id:"q13",tier:1,category:"藝文・買啱舞劇飛",question:"想欣賞香港舞蹈團擅長的演出，它主要發展哪個舞蹈方向？",options:["中國舞蹈","古典芭蕾","踢踏舞","佛蘭明高"],answer:0,explanation:"香港舞蹈團致力推廣具當代創意及香港特色的中國舞蹈。買飛前睇清團名，唔好入到場先問點解冇着足尖鞋。",hint:"留意舞團對中國舞蹈的傳承與當代創作。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"香港舞蹈團・關於舞團",url:"https://www.hkdance.com/zh-hant/%E9%A6%99%E6%B8%AF%E8%88%9E%E8%B9%88%E5%9C%98"},review:"2026-11-27核對所列一手資料；賽事、作品及傳統用語按題目所列年份或情境理解。"},{id:"q14",tier:2,category:"中樂・認清聲部",question:"香港中樂團的四個樂器組別，哪組配搭正確？",options:["拉弦、鍵盤、吹管、敲擊","拉弦、彈撥、吹管、敲擊","拉弦、彈撥、銅管、鍵盤","彈撥、木管、銅管、敲擊"],answer:1,explanation:"香港中樂團按拉弦、彈撥、吹管及敲擊分組。分類靠發聲與演奏方式，唔係按邊個部門合照企得最齊。",hint:"別把西洋管弦樂團的分組整套搬過來。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"香港中樂團・樂團簡介",url:"https://www.hkco.org/tc/About-Hkco/About-Us.html"},review:"2026-11-27核對所列一手資料；賽事、作品及傳統用語按題目所列年份或情境理解。"},{id:"q15",tier:2,category:"中樂・樂團生日",question:"香港中樂團於哪一年成立，開始走上本地專業樂團的舞台？",options:["1967年","1974年","1977年","1981年"],answer:2,explanation:"香港中樂團於1977年成立。呢條問樂團歷史，唔係問你第一次被人催交音樂科功課係邊年。",hint:"想想香港表演藝術在1970年代後期的發展。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"香港中樂團・樂團簡介",url:"https://www.hkco.org/tc/About-Hkco/About-Us.html"},review:"2026-11-27核對所列一手資料；賽事、作品及傳統用語按題目所列年份或情境理解。"},{id:"q16",tier:2,category:"港產片・留住舊街",question:"重溫永利街舊情懷，2010年《歲月神偷》的導演是誰？",options:["張婉婷","許鞍華","陳果","羅啟銳"],answer:3,explanation:"《歲月神偷》由羅啟銳執導，也融入他的成長經歷。戲名有個偷字，最想偷返嚟嘅可能係那些慢慢過的日子。",hint:"留意這對編導拍檔中，取自身童年經歷拍此片的一位。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"香港電影資料館・歲月神偷",url:"https://www.filmarchive.gov.hk/tc/web/hkfa/pe-event-2021-mna-fs-film03.html"},review:"2026-11-27核對所列一手資料；賽事、作品及傳統用語按題目所列年份或情境理解。"},{id:"q17",tier:2,category:"港產片・船頭尺去邊",question:"想跟1987年《秋天的童話》去打卡，主要故事發生在哪個海外城市？",options:["紐約","倫敦","巴黎","三藩市"],answer:0,explanation:"《秋天的童話》寫紐約留學生與唐人街居民的故事。浪漫可以跨洋，睇戲前唔使順便訂埋跨洋機票。",hint:"留意片中的美國唐人街與留學生生活。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"政府新聞公報・張婉婷羅啟銳影談系列",url:"https://www.info.gov.hk/gia/general/202104/09/P2021040800470.htm"},review:"2026-11-27核對所列一手資料；賽事、作品及傳統用語按題目所列年份或情境理解。"},{id:"q18",tier:2,category:"劇場・春天的編劇",question:"麗花皇宮姊妹情令人難忘，《我和春天有個約會》的原著話劇編劇是誰？",options:["陳尹瑩","杜國威","莊梅岩","潘惠森"],answer:1,explanation:"原著話劇由杜國威編寫，之後改編成電影等作品。戲中同春天有約，你買飛就最好同個日曆先對好。",hint:"留意原著話劇與電影改編之間的編劇署名。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"香港電影資料館・我和春天有個約會",url:"https://www.filmarchive.gov.hk/tc/web/hkfa/pe-event-2023-cs-fs-film12.html"},review:"2026-11-27核對所列一手資料；賽事、作品及傳統用語按題目所列年份或情境理解。"},{id:"q19",tier:2,category:"武俠・第一本追更",question:"入金庸館先考開場白：金庸首部武俠小說是哪部？",options:["《射鵰英雄傳》","《碧血劍》","《書劍恩仇錄》","《雪山飛狐》"],answer:2,explanation:"金庸1955年以《書劍恩仇錄》開始武俠小說創作。當年讀者追連載，唔係撳一下「下一集」就解決到。",hint:"留意1955年起步的那部作品，而非其後的代表作。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"香港文化博物館・金庸館",url:"https://www.heritagemuseum.gov.hk/tc/exhibitions/jin_yong.html"},review:"2026-11-27核對所列一手資料；賽事、作品及傳統用語按題目所列年份或情境理解。"},{id:"q20",tier:2,category:"港隊・雙打拍檔",question:"香港在2004雅典奧運的乒乓球男子雙打銀牌，由哪對拍檔取得？",options:["黃鎮廷、何鈞傑","江天一、唐鵬","陳江華、梁柱恩","高禮澤、李靜"],answer:3,explanation:"高禮澤與李靜在雅典2004奧運取得男子雙打銀牌。拍檔默契唔係靠開個群組改名「必勝」就即刻有。",hint:"留意在雅典奧運同場合作的香港男子雙打拍檔。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"政府新聞公報・雅典奧運男乒雙打銀牌",url:"https://www.info.gov.hk/gia/general/brandhk/210804c1.htm"},review:"2026-11-27核對所列一手資料；賽事、作品及傳統用語按題目所列年份或情境理解。"},{id:"q21",tier:2,category:"港足・大球場那一夜",question:"香港在2009東亞運足球決賽奪金，決賽對手是哪隊？",options:["日本","韓國","中國","朝鮮"],answer:0,explanation:"香港在2009東亞運足球決賽擊敗日本奪金。嗌到聲沙係球迷的回憶，唔好連樓上樓下都以為自己喺場內。",hint:"分清當屆決賽對手，不是其他亞洲賽事的對戰。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"政府新聞公報・香港隊大放異彩",url:"https://www.info.gov.hk/gia/general/200912/13/P200912120291.htm"},review:"2026-11-27核對所列一手資料；賽事、作品及傳統用語按題目所列年份或情境理解。"},{id:"q22",tier:2,category:"舞蹈・本地創作起步",question:"香港舞蹈團於哪一年成立？",options:["1974年","1981年","1977年","1984年"],answer:1,explanation:"香港舞蹈團於1981年成立，發展具香港特色的中國舞蹈作品。跳舞未必有得抄捷徑，年份就更加唔可以隨便跨過幾年。",hint:"它的創團年份在1980年代初。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"香港舞蹈團・關於舞團",url:"https://www.hkdance.com/zh-hant/%E9%A6%99%E6%B8%AF%E8%88%9E%E8%B9%88%E5%9C%98"},review:"2026-11-27核對所列一手資料；賽事、作品及傳統用語按題目所列年份或情境理解。"},{id:"q23",tier:2,category:"劇場・開幕以前",question:"香港話劇團的成立年份是哪一年？",options:["1971年","1974年","1977年","1981年"],answer:2,explanation:"香港話劇團於1977年成立。專業演出背後要排練、製作與教育推廣，唔係臨開場先喺後台分角色。",hint:"想想香港專業表演藝術在1970年代的發展。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"香港話劇團・劇團簡介",url:"https://www.hkrep.com/tc/About-Us/About-Us.html"},review:"2026-11-27核對所列一手資料；賽事、作品及傳統用語按題目所列年份或情境理解。"},{id:"q24",tier:2,category:"金像獎・武打影后",question:"惠英紅憑哪部電影，獲首屆香港電影金像獎最佳女主角？",options:["《爛頭何》","《十八般武藝》","《少林搭棚大師》","《長輩》"],answer:3,explanation:"惠英紅憑《長輩》獲首屆金像獎最佳女主角。片名有輩分，獎項靠表現，唔係排家族座位表排返嚟。",hint:"留意她早期邵氏時期的功夫喜劇作品。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"亞洲電影大獎學院・惠英紅",url:"https://www.afa-academy.com/zh/awards/12th-2/%E6%83%A0%E8%8B%B1%E7%B4%85-3/"},review:"2026-11-27核對所列一手資料；賽事、作品及傳統用語按題目所列年份或情境理解。"},{id:"q25",tier:2,category:"非遺・唱出水上日常",question:"香港傳承的「嘆歌」，主要與哪個社群的婚嫁及喪禮歌唱相連？",options:["漁民社群","礦工社群","印刷工人社群","茶農社群"],answer:0,explanation:"嘆歌是漁民的傳統歌唱形式，會在婚嫁和喪禮等場合嘆唱。個名有嘆，唔等於可以把你等巴士嗰聲嘆氣直接當一首歌。",hint:"留意水上生活與人生禮俗的關係。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"康文署・清音再聞",url:"https://www.lcsd.gov.hk/CE/CulturalService/Programme/tc/music/programs_1291.html"},review:"2026-11-27核對所列一手資料；賽事、作品及傳統用語按題目所列年份或情境理解。"},{id:"q26",tier:2,category:"藝文・花鳥一派",question:"睇畫想扮內行：香港文化博物館介紹的趙少昂，屬於哪個畫派？",options:["海上畫派","嶺南畫派","金陵畫派","長安畫派"],answer:1,explanation:"趙少昂是嶺南畫派的重要畫家，在香港教學並推廣中國繪畫。睇花鳥唔係數吓有幾隻雀就算，筆墨同觀察都大有學問。",hint:"這一畫派重視融會傳統與新觀察。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"香港文化博物館・趙少昂藝術館",url:"https://www.heritagemuseum.gov.hk/tc/exhibitions/chaoshaoan.html"},review:"2026-11-27核對所列一手資料；賽事、作品及傳統用語按題目所列年份或情境理解。"},{id:"q27",tier:2,category:"文物・一杯茶的收藏",question:"茶具文物館的基本藏品，主要由哪位收藏家捐贈奠基？",options:["劉作籌","何耀光","羅桂祥","利榮森"],answer:2,explanation:"羅桂祥捐贈的一批茶具，奠定茶具文物館的收藏基礎。一杯茶可以慢慢飲，背後的收藏心力就唔係等水滾嗰幾分鐘。",hint:"留意館方對基本藏品及捐贈背景的介紹。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"香港藝術館・茶具藏品",url:"https://hk.art.museum/tc/web/ma/tea-ware-collection.html"},review:"2026-11-27核對所列一手資料；賽事、作品及傳統用語按題目所列年份或情境理解。"},{id:"q28",tier:3,category:"非遺・樂譜唔同款",question:"樂譜似密碼？康文署《清音再聞》介紹潮州音樂時，提到哪種傳統記譜名稱？",options:["減字譜","燕樂半字譜","律呂字譜","二四譜"],answer:3,explanation:"節目介紹潮州音樂使用的二四譜及調式。認譜先可以合拍，唔係大家睇同一張紙就自然會一齊入。",hint:"它是潮州音樂傳承中特有的記譜稱呼。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"康文署・清音再聞",url:"https://www.lcsd.gov.hk/CE/CulturalService/Programme/tc/music/programs_1291.html"},review:"2026-11-27核對所列一手資料；賽事、作品及傳統用語按題目所列年份或情境理解。"},{id:"q29",tier:3,category:"中樂・琴膜新做法",question:"香港中樂團研發的環保胡琴，以哪種材料取代傳統蟒蛇皮琴膜？",options:["PET聚酯纖維膜","矽膠薄膜","蠶絲織膜","聚氨酯皮革"],answer:0,explanation:"環保胡琴採用PET聚酯纖維膜取代傳統蟒蛇皮，結合樂器研究與演奏需要。環保要做研究，唔係喺琴盒貼塊綠色貼紙就搞掂。",hint:"這是一種人工聚酯材料，不是另一種動物皮。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"香港中樂團・環保胡琴系列",url:"https://www.hkco.org/tc/Instrument-Rd/Eco-Huqins.html"},review:"2026-11-27核對所列一手資料；賽事、作品及傳統用語按題目所列年份或情境理解。"},{id:"q30",tier:3,category:"武俠・封筆那一本",question:"按金庸館介紹，金庸在1972年完成哪部武俠小說後封筆？",options:["《天龍八部》","《鹿鼎記》","《笑傲江湖》","《碧血劍》"],answer:1,explanation:"金庸完成《鹿鼎記》後結束武俠小說創作，後來仍有修訂。封筆唔等於讀者唔再追，重讀嗰堆書都夠排一個暑假。",hint:"把作品放回創作時間線，找出封筆前完成的一部。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"香港文化博物館・金庸館",url:"https://www.heritagemuseum.gov.hk/tc/exhibitions/jin_yong.html"},review:"2026-11-27核對所列一手資料；賽事、作品及傳統用語按題目所列年份或情境理解。"},{id:"q31",tier:3,category:"武俠・報紙追連載",question:"1955年金庸首部武俠小說《書劍恩仇錄》，最初在哪份報紙發表？",options:["《明報》","《星島日報》","《新晚報》","《華僑日報》"],answer:2,explanation:"《書劍恩仇錄》在《新晚報》發表，金庸由此展開武俠小說創作。未有手機通知的追更年代，買報紙都可以好心急。",hint:"別把後來與金庸關係密切的報章直接套進1955年。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"香港文化博物館・金庸館",url:"https://www.heritagemuseum.gov.hk/tc/exhibitions/jin_yong.html"},review:"2026-11-27核對所列一手資料；賽事、作品及傳統用語按題目所列年份或情境理解。"},{id:"q32",tier:3,category:"藏畫・虛白齋主人",question:"香港藝術館的「虛白齋」中國書畫珍藏，原由哪位收藏家建立？",options:["何耀光","利榮森","羅桂祥","劉作籌"],answer:3,explanation:"虛白齋珍藏由劉作籌建立並捐贈。認收藏要對得返主人，唔好好似去飲茶咁見到個齋字就直接叫碟素菜。",hint:"分清香港藝術館不同書畫收藏各自的建立者。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"香港藝術館・虛白齋藏中國書畫",url:"https://hk.art.museum/tc/web/ma/collections/xubaizhai-collection-of-chinese-painting-and-calligraphy.html"},review:"2026-11-27核對所列一手資料；賽事、作品及傳統用語按題目所列年份或情境理解。"},{id:"q33",tier:3,category:"藏畫・至樂樓主人",question:"香港藝術館的「至樂樓」中國書畫收藏，原由誰建立？",options:["何耀光","劉作籌","羅桂祥","利榮森"],answer:0,explanation:"至樂樓收藏由何耀光建立，名稱寄寓鑑賞藝術和為善之樂。呢個樓名唔係叫你即刻打開地產網站搵放盤。",hint:"想想至樂樓藝術發揚及這批收藏的捐贈背景。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"香港藝術館・至樂樓藏中國書畫",url:"https://hk.art.museum/tc/web/ma/collections/chih-lo-lou-collection-of-chinese-painting-and-calligraphy.html"},review:"2026-11-27核對所列一手資料；賽事、作品及傳統用語按題目所列年份或情境理解。"},{id:"q34",tier:3,category:"藏畫・齋名有來歷",question:"「虛白齋」的「虛白」二字，取自劉作籌所藏哪位清代書法家的橫披？",options:["鄧石如","伊秉綬","何紹基","趙之謙"],answer:1,explanation:"劉作籌以藏品中伊秉綬所書的「虛白」二字命名收藏。個名睇落簡單，背後唔係開會諗五分鐘就投票通過。",hint:"留意館方對齋名來源及所藏書法橫披的介紹。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"香港藝術館・虛白齋藏中國書畫",url:"https://hk.art.museum/tc/web/ma/collections/xubaizhai-collection-of-chinese-painting-and-calligraphy.html"},review:"2026-11-27核對所列一手資料；賽事、作品及傳統用語按題目所列年份或情境理解。"},{id:"q35",tier:3,category:"嶺南・師承要認真",question:"香港文化博物館介紹趙少昂時，指出他的老師是哪位嶺南畫派畫家？",options:["高劍父","陳樹人","高奇峰","黃賓虹"],answer:2,explanation:"趙少昂師承高奇峰，後在香港傳藝。畫派人名相近都要認真分，唔可以見到同姓就當同一個師傅帳號。",hint:"分清高氏兄弟與其他近現代畫家的師承關係。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"香港文化博物館・趙少昂誕辰120周年展",url:"https://www.heritagemuseum.gov.hk/tc/resources/past_events/csa_120a.html"},review:"2026-11-27核對所列一手資料；賽事、作品及傳統用語按題目所列年份或情境理解。"},{id:"q36",tier:3,category:"藝文・水鄉留稿",question:"香港藝術館所藏《寧波水鄉》（《雙燕》原稿），出自哪位畫家？",options:["林風眠","朱德群","吳昌碩","吳冠中"],answer:3,explanation:"《寧波水鄉》是吳冠中作品，也是《雙燕》的原稿。認畫家靠作品脈絡，唔係見到水鄉就順手報一個旅遊目的地。",hint:"留意這位以江南景物及抽象形式探索聞名的畫家。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"香港藝術館・主要捐贈者",url:"https://hk.art.museum/tc/web/ma/collections/major-donors.html"},review:"2026-11-27核對所列一手資料；賽事、作品及傳統用語按題目所列年份或情境理解。"},{id:"q37",tier:3,category:"粵劇・聲腔識別",question:"粵劇唱腔所說的「乞兒喉」，最常與哪位名伶相連？",options:["馬師曾","新馬師曾","薛覺先","白駒榮"],answer:0,explanation:"康文署的唱腔介紹把乞兒喉列在馬師曾的聲腔名稱之中。馬師曾同新馬師曾要分清，唔係同一帳戶按咗升級。",hint:"分清兩位名字相近的名伶，別單憑一個「馬」字作答。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"康文署・粵劇劇本唱腔及音樂區",url:"https://www.lcsd.gov.hk/tc/kst/kstnw/coeic/exhibition/pvm.html"},review:"2026-11-27核對所列一手資料；賽事、作品及傳統用語按題目所列年份或情境理解。"},{id:"q38",tier:3,category:"粵劇・聲腔唔養狗",question:"康文署唱腔資料列出的「凡腔／狗仔腔」，與哪位名伶相連？",options:["馬師曾","何非凡","白駒榮","林家聲"],answer:1,explanation:"凡腔或狗仔腔與何非凡相連，是粵劇聲腔名稱。呢題靠認聲腔，屋企隻狗就算叫得好大聲都幫唔到你。",hint:"留意名稱中與藝人名字呼應的一個字。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"康文署・粵劇劇本唱腔及音樂區",url:"https://www.lcsd.gov.hk/tc/kst/kstnw/coeic/exhibition/pvm.html"},review:"2026-11-27核對所列一手資料；賽事、作品及傳統用語按題目所列年份或情境理解。"},{id:"q39",tier:3,category:"港產片・童星那一頁",question:"1950年、李小龍主演的《細路祥》，導演是誰？",options:["胡鵬","吳回","馮峰","楚原"],answer:2,explanation:"《細路祥》由馮峰執導，李小龍當時仍是童星。識睇功夫片之外，佢細個的銀幕故事都值得補堂。",hint:"這位導演的名字為單字名，留意與其他早期粵語片導演的分別。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"政府新聞公報・李小龍電影回顧展",url:"https://www.info.gov.hk/gia/general/200011/14/1114207.htm"},review:"2026-11-27核對所列一手資料；賽事、作品及傳統用語按題目所列年份或情境理解。"},{id:"q40",tier:3,category:"港產片・威尼斯掌聲",question:"2020年獲威尼斯影展金獅終身成就獎的香港導演，是哪位？",options:["杜琪峯","王家衛","吳宇森","許鞍華"],answer:3,explanation:"許鞍華在2020年獲頒威尼斯影展金獅終身成就獎。呢座獅子表揚電影生涯，唔係答啱幾條戲名就可以抱返屋企。",hint:"分清不同導演獲此殊榮的年份。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"政府新聞公報・許鞍華金獅終身成就獎",url:"https://www.info.gov.hk/gia/general/202007/21/P2020072100275.htm"},review:"2026-11-27核對所列一手資料；賽事、作品及傳統用語按題目所列年份或情境理解。"}].map(t=>Object.freeze({...t,options:Object.freeze(t.options)})));var W=Object.freeze([{id:"r01",tier:1,category:"生態・本地植物",question:"植物叫「香港茶」，開花時卻唔係奶茶色。它的花通常是甚麼顏色？",options:["紅色","白色","黃色","淡紫色"],answer:0,explanation:"香港茶開紅花。個名有「茶」唔等於可以落單叫少甜，這裏考的是植物花色。",hint:"先將茶餐廳的餐牌收起。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"香港濕地公園・香港茶",url:"https://www.wetlandpark.gov.hk/tc/biodiversity/beauty-of-wetlands/wildlife/camellia-hongkongensis"},review:"2026-11-27已開啟列明機構原始頁面核對。核對花色；不延伸作食用或採集指引。"},{id:"r02",tier:1,category:"生態・外來物種",question:"「巴西龜」的花名成功誤導全場。紅耳龜原產於哪裏？",options:["巴西及阿根廷","美國及墨西哥","日本及韓國","印度及斯里蘭卡"],answer:1,explanation:"紅耳龜原產美國及墨西哥，並非巴西。花名可以很響，履歷仍然要查清楚；也不應把寵物放生野外。",hint:"花名未必等於出生地。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"土木工程拓展署・紅耳龜",url:"https://sslo.cedd.gov.hk/tc/exploring-more/nature-conservation/eco-logs/journey-to-terrestrial-habitats/red-eared-slider/index.html"},review:"2026-11-27已開啟列明機構原始頁面核對。核對原產地；「巴西龜」只作本地俗稱。"},{id:"r03",tier:1,category:"生態・城市鳥類",question:"同事望住天上的猛禽說：「麻鷹又巡場。」他講的是哪種雀？",options:["普通鵟","鳳頭鷹","黑鳶","遊隼"],answer:2,explanation:"香港人俗稱的麻鷹就是黑鳶。佢巡場唔使拍卡，也不代表在替你的午餐作食安檢查。",hint:"俗名與正式名稱可以指同一種鳥。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"康文署・黑鳶（麻鷹）",url:"https://www.lcsd.gov.hk/tc/green/birds/overview/bird_2.html"},review:"2026-11-27已開啟列明機構原始頁面核對。核對黑鳶的本地俗稱。"},{id:"r04",tier:1,category:"生態・溪流住客",question:"香港瘰螈要揀心水住處，哪種環境最符合牠在香港的棲地？",options:["乾燥沙灘","開闊鹹水海域","繁忙碼頭石堤","清澈山溪"],answer:3,explanation:"香港瘰螈棲息於清澈山溪，低地及較高海拔都有紀錄。牠揀樓睇水質，唔係睇海景露台。",hint:"留意牠與淡水環境的關係。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"香港生物多樣性資訊站・兩棲類",url:"https://bih.gov.hk/tc/hong-kong-species/amphibians/index.html"},review:"2026-11-27已開啟列明機構原始頁面核對。核對棲地；不提供尋找、接觸或辨識野生動物的行動指引。"},{id:"r05",tier:1,category:"生態・海岸動物",question:"飛白楓海星開「手臂點名大會」，一般會點到幾隻腕？",options:["五隻","六隻","七隻","八隻"],answer:0,explanation:"飛白楓海星通常有五隻腕。這是物種的一般形態，唔好見到「海星」就當所有品種都跟同一張規格表。",hint:"題目問一般形態，不是個別受損或再生的例子。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"漁護署・飛白楓海星",url:"https://www.afcd.gov.hk/tc_chi/country/cou_vis/cou_vis_mar/cou_vis_mar_mont.html"},review:"2026-11-27已開啟列明機構原始頁面核對。核對通常五腕；明確保留個體差異。"},{id:"r06",tier:1,category:"生態・海底居民",question:"海雞冠個名似街市檔口，其實牠屬於哪一類海洋生物？",options:["石珊瑚","軟珊瑚","海鞘","大型海藻"],answer:1,explanation:"海雞冠是軟珊瑚，身體內有小骨針支撐，並沒有石珊瑚那種堅硬外骨骼。個名再似餸，分類都唔跟餐牌。",hint:"留意名稱以外的身體構造。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"漁護署・海雞冠",url:"https://www.afcd.gov.hk/tc_chi/country/cou_vis/cou_vis_mar/cou_vis_mar_dendronephthya.html"},review:"2026-11-27已開啟列明機構原始頁面核對。核對海雞冠屬軟珊瑚；不概括所有珊瑚的營養方式。"},{id:"r07",tier:1,category:"生態・海底室友",question:"香港海域的克氏雙鋸魚，通常與哪位「室友」同住？",options:["海綿","牡蠣","海葵","海參"],answer:2,explanation:"克氏雙鋸魚會與海葵共生，雙方互有好處。海底租盤講求合拍，唔係有個殼就可以夾租。",hint:"這段關係是小丑魚的經典生存拍檔。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"漁護署・克氏雙鋸魚",url:"https://www.afcd.gov.hk/tc_chi/country/cou_vis/cou_vis_mar/cou_vis_mar_mont4.html"},review:"2026-11-27已開啟列明機構原始頁面核對。核對克氏雙鋸魚與海葵的共生關係。"},{id:"r08",tier:1,category:"生態・海草知識",question:"海草長年浸住海水，植物分類那一格應填甚麼？",options:["褐藻","苔蘚植物","蕨類植物","開花植物"],answer:3,explanation:"海草是適應海洋生活的開花植物，並不是海藻的另一個花名。水底生活照樣可以有花，唔使搬上岸打卡。",hint:"名字相近，海草與海藻的分類卻不同。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"漁護署・海草的生物學特徵",url:"https://www.afcd.gov.hk/tc_chi/conservation/con_wet/con_wet_sea/con_wet_sea_bio/con_wet_sea_bio.html"},review:"2026-11-27已開啟列明機構原始頁面核對。核對海草為海生開花植物。"},{id:"r09",tier:1,category:"地區・客家古屋",question:"在港島搵傳統客家古屋，羅屋這一站應填哪個地區？",options:["柴灣","筲箕灣","香港仔","薄扶林"],answer:0,explanation:"羅屋位於柴灣，是當地保存下來的傳統客家村屋。港島歷史唔只中環有份，柴灣今次有主場優勢。",hint:"這座古屋位於港島東部。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"古蹟辦・羅屋",url:"https://www.amo.gov.hk/tc/historic-buildings/monuments/hong-kong-island/monuments_38/index.html"},review:"2026-11-27已開啟列明機構原始頁面核對。核對羅屋所在地；不涉及現時開放安排。"},{id:"r10",tier:1,category:"地區・書室記憶",question:"芳園書室的舊生聚會要寫地名，正確是香港哪個島？",options:["青衣","馬灣","長洲","坪洲"],answer:1,explanation:"芳園書室位於馬灣田寮。書室的故事比主題公園早得多，唔好將整個島的校史都交畀遊樂設施代言。",hint:"它與田寮村的教育歷史有關。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"文物保育專員辦事處・芳園書室",url:"https://www.heritage.gov.hk/tc/revitalisation-scheme/batch-vi-of-revitalisation-scheme/virtual-tour-on-batch-vi-historic-buildings/fong-yuen-study-hall/index.html"},review:"2026-11-27已開啟列明機構原始頁面核對。核對芳園書室所在地；不涉及營運或開放狀況。"},{id:"r11",tier:1,category:"歷史・司法建築",question:"前法國外方傳道會大樓在1997至2015年間，主要是哪個法院的院址？",options:["高等法院","區域法院","終審法院","土地審裁處"],answer:2,explanation:"這座大樓於1997至2015年用作終審法院院址。同一幢樓有多段履歷，作答要睇清年份，唔好亂填上一份工。",hint:"題目已圈定回歸後的一段用途。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"終審法院・前法國外方傳道會大樓",url:"https://www.hkcfa.hk/tc/visiting/cfa_building/french_mission/index.html"},review:"2026-11-27已開啟列明機構原始頁面核對。核對1997至2015年用途，避免與大樓其他歷史用途混淆。"},{id:"r12",tier:1,category:"歷史・航海地標",question:"青洲燈塔建築群保留了幾座燈塔？唔好只數到相片中最顯眼的一座。",options:["一座","三座","四座","兩座"],answer:3,explanation:"青洲燈塔建築群包括舊燈塔及新燈塔，共兩座。升級設備有新同事加入，舊同事並沒有從歷史相簿消失。",hint:"歷代設備更新，也留下了不同時期的塔。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"古蹟辦・青洲燈塔建築群",url:"https://www.amo.gov.hk/tc/historic-buildings/monuments/hong-kong-island/monuments_86/index.html"},review:"2026-11-27已開啟列明機構原始頁面核對。核對建築群內新舊兩座燈塔；不混用興建與落成年份。"},{id:"r13",tier:1,category:"地區・龍躍頭",question:"龍躍頭鄧氏聚落常用哪組數字，概括當地的圍與村？",options:["五圍六村","三圍四村","六圍五村","七圍八村"],answer:0,explanation:"龍躍頭的鄧氏聚落有「五圍六村」之稱。今次係地方歷史，唔係酒樓圍數，對調兩個數字都算錯。",hint:"兩個數字相鄰，圍的數目比村少一。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"古蹟辦・龍躍頭文物徑",url:"https://www.amo.gov.hk/tc/heritage-trails/lung-yeuk-tau-heritage-trail/index.html"},review:"2026-11-27已開啟列明機構原始頁面核對。核對古蹟辦所列五圍六村的聚落稱謂。"},{id:"r14",tier:2,category:"生態・飛行原理",question:"黑鳶在高空長時間盤旋，點解唔使全程瘋狂撥翼？",options:["利用海面風切滑翔","借助上升氣流滑翔","交替拍翼與收翼飛行","快速拍翼作定點懸停"],answer:1,explanation:"黑鳶善用上升氣流滑翔，減少持續拍翼的需要。牠係識讀空氣，唔係飛到一半進入慳電死機模式。",hint:"能量來自牠周圍流動的空氣。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"康文署・黑鳶（麻鷹）",url:"https://www.lcsd.gov.hk/tc/green/birds/overview/bird_2.html"},review:"2026-11-27已開啟列明機構原始頁面核對。核對利用上升氣流滑翔的飛行方式。"},{id:"r15",tier:2,category:"生態・海藻構造",question:"馬尾藻底部有個似根的附著器，它主要負責甚麼？",options:["從泥中吸取養分","儲存繁殖用的種子","將藻體固定在海底","吸入空氣供給葉片"],answer:2,explanation:"馬尾藻的根型附著器主要把藻體固定在海底，並不是陸生植物那種吸收養分的根。似樣唔等於同一份工。",hint:"先分清「固定」與「吸收」兩種工作。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"漁護署・馬尾藻",url:"https://www.afcd.gov.hk/tc_chi/country/cou_vis/cou_vis_mar/cou_vis_mar_sargassum.html"},review:"2026-11-27已開啟列明機構原始頁面核對。核對附著器固定作用；不把藻體構造等同陸生植物器官。"},{id:"r16",tier:2,category:"生態・花朵拆局",question:"玉葉金花的白色「玉葉」好搶鏡，它實際是哪一部分？",options:["變白的花瓣","失綠的普通葉片","展開的種翅","膨大的萼片"],answer:3,explanation:"玉葉金花的「玉葉」是膨大的白色萼片。花的配角成功搶晒鏡，但植物學的職位名稱仍然要填啱。",hint:"別把外觀像葉的部分，直接當成普通葉片。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"香港濕地公園・玉葉金花",url:"https://www.wetlandpark.gov.hk/tc/biodiversity/beauty-of-wetlands/wildlife/mussaenda-pubescens"},review:"2026-11-27已開啟列明機構原始頁面核對。核對白色葉狀構造為萼片；不與香港四照花的苞片混用。"},{id:"r17",tier:2,category:"生態・植物構造",question:"香港四照花把四塊白色構造排在花序外圍；它們其實是甚麼？",options:["苞片","花瓣","萼片","子葉"],answer:0,explanation:"香港四照花顯眼的四塊白色構造是苞片，真正的小花集中在中央。宣傳部做得太出色，主角反而低調。",hint:"留意白色構造與中央花序的分工。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"香港植物標本室・香港發現的植物新種",url:"https://www.herbarium.gov.hk/tc/special-topics/hong-kong-plants/hong-kong-plants-detail/index-id-7.html"},review:"2026-11-27已開啟列明機構原始頁面核對。核對四枚白色苞片；與玉葉金花萼片的問題區分。"},{id:"r18",tier:2,category:"生態・潮間帶構造",question:"日本花棘石鱉黐實岩面，主要靠哪個身體部分出力？",options:["八塊殼板的尖端","肌肉發達的腹足","口部伸出的齒舌","背部環繞的剛毛"],answer:1,explanation:"日本花棘石鱉靠強壯的腹足緊貼岩石。八塊殼板負責護身，唔係八隻腳，數錯部門會誤會成場。",hint:"這種軟體動物的身體下方有寬闊的運動器官。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"漁護署・日本花棘石鱉",url:"https://www.afcd.gov.hk/tc_chi/country/cou_vis/cou_vis_mar/cou_vis_mar_mont2.html"},review:"2026-11-27已開啟列明機構原始頁面核對。核對腹足的附著作用；不提供移動或採集動物的操作。"},{id:"r19",tier:2,category:"生態・海岸分類",question:"日本笠藤壺個殼似迷你火山，牠在動物分類上屬於哪一類？",options:["雙殼類","腹足類","甲殼類","棘皮類"],answer:2,explanation:"日本笠藤壺是甲殼類，唔係有殼就自動歸入貝類。外形可以撞衫，分類戶口就不能亂過數。",hint:"別被堅硬外殼帶去蠔和蜆那一邊。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"漁護署・日本笠藤壺",url:"https://www.afcd.gov.hk/tc_chi/country/cou_vis/cou_vis_mar/cou_vis_mar_mont3.html"},review:"2026-11-27已開啟列明機構原始頁面核對。核對藤壺屬甲殼類；選項採常用動物分類名稱。"},{id:"r20",tier:2,category:"歷史・地方行政",question:"大埔舊北區理民府早年處理的核心工作，最接近哪一組？",options:["海港引水與船舶註冊","郵件分揀與郵政儲蓄","鐵路調度與車票結算","地方行政與土地登記"],answer:3,explanation:"舊北區理民府曾處理新界北部行政及土地登記事務。紅磚建築有古蹟氣質，當年辦公枱上照樣有大量文件。",hint:"「理民」的工作與管治地方及土地紀錄有關。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"古蹟辦・舊北區理民府",url:"https://www.amo.gov.hk/tc/historic-buildings/monuments/new-territories/monuments_12/index.html"},review:"2026-11-27已開啟列明機構原始頁面核對。核對早期新界北部行政及土地登記用途。"},{id:"r21",tier:2,category:"地區・書室沿革",question:"芳園書室的前身，在馬灣村史中叫甚麼名字？",options:["陳氏書齋","鄧氏書齋","李氏書齋","文氏書齋"],answer:0,explanation:"芳園書室前身是陳氏書齋，後來重建及改名。讀村校履歷要認清姓氏，唔能夠靠最熟的祠堂名亂撞。",hint:"留意前身與重建後名稱的先後。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"文物保育專員辦事處・芳園書室",url:"https://www.heritage.gov.hk/tc/revitalisation-scheme/batch-vi-of-revitalisation-scheme/virtual-tour-on-batch-vi-historic-buildings/fong-yuen-study-hall/index.html"},review:"2026-11-27已開啟列明機構原始頁面核對。核對前身陳氏書齋；不將重建年代誤作始建年份。"},{id:"r22",tier:2,category:"歷史・客家建築",question:"柴灣羅屋的平面格局，在傳統建築術語中稱為甚麼？",options:["三進兩院式","三間兩廊式","五間兩廂式","兩進三院式"],answer:1,explanation:"羅屋採用三間兩廊式格局，正屋與兩側廊房圍出天井。古屋有自己的間隔術語，唔係睇完樓就叫「實用三房」。",hint:"不要將房間橫向排列，與前後的「進」混為一談。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"古蹟辦・羅屋",url:"https://www.amo.gov.hk/tc/historic-buildings/monuments/hong-kong-island/monuments_38/index.html"},review:"2026-11-27已開啟列明機構原始頁面核對。核對三間兩廊式格局；不以現代樓宇房間數取代建築術語。"},{id:"r23",tier:2,category:"歷史・圍村建築",question:"新圍（覲龍圍）的圍牆槍孔與四角更樓，主要有甚麼共同作用？",options:["疏導雨水與量度風向","晾曬穀物與貯藏種子","防守圍村與瞭望周邊","展示族譜與供奉祖先"],answer:2,explanation:"槍孔及更樓主要用來防衛與瞭望。圍村的建築配置回應當時的安全需要，並不是為了幫合照加個高位。",hint:"把這些設施放回昔日圍村的安全需求。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"古蹟辦・新圍（覲龍圍）",url:"https://www.amo.gov.hk/tc/heritage-trails/lung-yeuk-tau-heritage-trail/san-wai/index.html"},review:"2026-11-27已開啟列明機構原始頁面核對。核對圍牆槍孔及角樓的歷史防衛用途。"},{id:"r24",tier:2,category:"生態・水下開花",question:"海草開花後的花粉，主要靠哪種媒介傳遞？",options:["海風","昆蟲","鳥類","海水"],answer:3,explanation:"海草在水中完成授粉，繁殖過程適應了水下生活。開花唔一定要等風，海底也有自己的傳粉安排。",hint:"將風媒、蟲媒與水媒授粉作比較。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"漁護署・海草的生物學特徵",url:"https://www.afcd.gov.hk/tc_chi/conservation/con_wet/con_wet_sea/con_wet_sea_bio/con_wet_sea_bio.html"},review:"2026-11-27已開啟列明機構原始頁面核對。核對海草的水中授粉；不將潮汐條件當作生態保證。"},{id:"r25",tier:2,category:"歷史・建築材料",question:"大埔舊北區理民府的外牆主調，來自哪種主要建築材料？",options:["紅磚","青磚","花崗石","夯土"],answer:0,explanation:"舊北區理民府主要以紅磚建成，磚拱遊廊也很有辨識度。今次唔係要你揀濾鏡，而是認清牆身本身的材料。",hint:"留意牆身與拱廊呈現的磚色。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"古蹟辦・舊北區理民府",url:"https://www.amo.gov.hk/tc/historic-buildings/monuments/new-territories/monuments_12/index.html"},review:"2026-11-27已開啟列明機構原始頁面核對。核對主要紅磚牆身，不聲稱全幢沒有其他材料。"},{id:"r26",tier:2,category:"生態・珊瑚營養",question:"海雞冠沒有共生蟲黃藻，主要怎樣搵食？",options:["靠共生藻類製造有機養分","用觸手濾取水中微小食物","靠寄生魚類吸取體內養分","用螯捕捉經過的小型蝦蟹"],answer:1,explanation:"海雞冠主要用觸手攝取微小浮游生物及懸浮有機顆粒。佢冇開體內太陽能餐廳，靠的是水中送來的細份餐。",hint:"這種軟珊瑚的營養來源與部分造礁珊瑚不同。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"漁護署・海雞冠",url:"https://www.afcd.gov.hk/tc_chi/country/cou_vis/cou_vis_mar/cou_vis_mar_dendronephthya.html"},review:"2026-11-27已開啟列明機構原始頁面核對。核對缺乏蟲黃藻及濾食方式；不概括所有珊瑚。"},{id:"r27",tier:3,category:"生態・海藻構造",question:"馬尾藻身上的小氣囊，主要為藻體提供哪種幫助？",options:["調節滲透壓以排走鹽分","暫存孢子以方便繁殖","增加浮力以利接收陽光","減少接觸海水的表面積"],answer:2,explanation:"小氣囊提供浮力，幫助藻體向上伸展接收陽光。馬尾藻有自己的浮力安排，並不是掛滿一串等待結果的果實。",hint:"從海水中的浮沉，想想陽光在哪個方向。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"漁護署・馬尾藻",url:"https://www.afcd.gov.hk/tc_chi/country/cou_vis/cou_vis_mar/cou_vis_mar_sargassum.html"},review:"2026-11-27已開啟列明機構原始頁面核對。核對氣囊浮力及利於光照的作用。"},{id:"r28",tier:3,category:"生態・軟體動物",question:"日本花棘石鱉的「盔甲」由幾塊互相重疊的殼板組成？",options:["六塊","七塊","九塊","八塊"],answer:3,explanation:"日本花棘石鱉背上有八塊相疊殼板。外套分件唔代表可以當活動積木，這是牠的身體構造。",hint:"題目問殼板，不是腹足或身體周圍的剛毛。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"漁護署・日本花棘石鱉",url:"https://www.afcd.gov.hk/tc_chi/country/cou_vis/cou_vis_mar/cou_vis_mar_mont2.html"},review:"2026-11-27已開啟列明機構原始頁面核對。核對八塊重疊殼板的物種構造。"},{id:"r29",tier:3,category:"生態・潮間帶適應",question:"漁護署介紹藤壺幼體的生活史：牠找到合適基質後，主要怎樣固定下來？",options:["分泌黏著物質固著生長","用殼板嵌入裂縫固定","伸出足絲纏住岩面固定","以腹足反覆吸附岩面"],answer:0,explanation:"藤壺幼體找到合適基質後，會分泌黏著物質，開始固著生長。唔係見牆就簽永久租約，落腳方式都有一套。",hint:"比較足絲、腹足及分泌物這些不同的附著方式。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"漁護署・日本笠藤壺",url:"https://www.afcd.gov.hk/tc_chi/country/cou_vis/cou_vis_mar/cou_vis_mar_mont3.html"},review:"2026-11-27已開啟列明機構原始頁面核對。核對藤壺幼體由漂浮到分泌黏著物質固著的生活史；不混淆貝類或石鱉的附著構造。"},{id:"r30",tier:3,category:"生態・魚類生活史",question:"克氏雙鋸魚能轉換性別，其正常生活史的轉換方向是哪一種？",options:["先雌後雄","先雄後雌","雌雄反覆互換","同時雌雄同體"],answer:1,explanation:"克氏雙鋸魚可由雄性轉變為雌性，接替群體內的繁殖角色。海底的職位交接，連生物學設定都可以一齊更新。",hint:"留意這種魚在優勢雌魚消失後的角色接替。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"漁護署・克氏雙鋸魚",url:"https://www.afcd.gov.hk/tc_chi/country/cou_vis/cou_vis_mar/cou_vis_mar_mont4.html"},review:"2026-11-27已開啟列明機構原始頁面核對。核對優勢雌魚消失後的雄轉雌現象；限於此物種情境。"},{id:"r31",tier:3,category:"生態・植物發現史",question:"香港鳳仙在1925年首次被發現的香港地區是哪裏？",options:["西貢","荃灣","大埔","元朗"],answer:2,explanation:"香港鳳仙於1925年在大埔被發現，後來才正式發表為新物種。發現與發表係兩個日期，唔好幫植物履歷合併欄位。",hint:"題目問首次發現的地區，並非正式命名年份。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"香港植物標本室・香港發現的植物新種",url:"https://www.herbarium.gov.hk/tc/special-topics/hong-kong-plants/hong-kong-plants-detail/index-id-7.html"},review:"2026-11-27已開啟列明機構原始頁面核對。核對1925年大埔首次發現；不與1978年發表年份混淆。"},{id:"r32",tier:3,category:"生態・植物命名",question:"以胡秀英博士命名的秀英竹，是在哪一年獲命名的新種？",options:["1973年","1978年","1988年","1983年"],answer:3,explanation:"秀英竹於1983年以胡秀英博士命名，表揚她對植物研究的貢獻。植物命名有年份，唔係長高一節就自動加一歲。",hint:"題目問正式命名年份，不是學者的出生或獲獎年份。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"香港植物標本室・香港發現的植物新種",url:"https://www.herbarium.gov.hk/tc/special-topics/hong-kong-plants/hong-kong-plants-detail/index-id-7.html"},review:"2026-11-27已開啟列明機構原始頁面核對。核對1983年命名及紀念胡秀英博士的背景。"},{id:"r33",tier:3,category:"生態・植物發現史",question:"香港茶在1849年的早期發現紀錄，位於香港哪個地方？",options:["太平山河谷","馬鞍山山脊","大帽山山頂","獅子山北坡"],answer:0,explanation:"香港茶於1849年在太平山河谷被發現。答案要對準早期紀錄，唔係揀今天聽落最像有大片茶田的山。",hint:"這段早期紀錄位於香港島。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"香港濕地公園・香港茶",url:"https://www.wetlandpark.gov.hk/tc/biodiversity/beauty-of-wetlands/wildlife/camellia-hongkongensis"},review:"2026-11-27已開啟列明機構原始頁面核對。核對1849年太平山河谷發現紀錄；不聲稱其現時僅限該處分布。"},{id:"r34",tier:3,category:"生態・海草棲地",question:"漁護署介紹荔枝窩海草床時，特別提到哪種海草？",options:["喜鹽草","矮大葉藻","貝克喜鹽草","川蔓藻"],answer:1,explanation:"荔枝窩海草床的重要植物包括矮大葉藻（Zostera japonica）。海草個名各有來頭，唔能夠一律叫「海底草坪」。",hint:"留意這片海草床與 Zostera 屬的關係。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"漁護署・印洲塘海岸公園生態監察",url:"https://www.afcd.gov.hk/tc_chi/country/cou_vis/cou_vis_mar/cou_vis_mar_mon/cou_vis_mar_mon_eco_yct.html"},review:"2026-11-27已開啟列明機構原始頁面核對。核對荔枝窩矮大葉藻海草床；不以可變面積或最大排名出題。"},{id:"r35",tier:3,category:"歷史・圍村記述",question:"按古蹟辦介紹所載，龍躍頭老圍的圍門據說由北向改為哪個方向？",options:["南向","西向","東向","西北向"],answer:2,explanation:"古蹟辦介紹記載，老圍圍門據說原向北，後改向東。這是地方歷史記述；題目不把風水理由當成科學定律。",hint:"題目問記述中的改向，留意「據說」的史料界線。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"古蹟辦・老圍",url:"https://www.amo.gov.hk/tc/heritage-trails/lung-yeuk-tau-heritage-trail/lo-wai/index.html"},review:"2026-11-27已開啟列明機構原始頁面核對。依來源以「據說」限定由北轉東的地方記述，不將傳述動機當已證史實。"},{id:"r36",tier:3,category:"歷史・燈塔光學",question:"橫瀾燈塔早期的旋轉透鏡，曾浮在甚麼液體上運作？",options:["海水","煤油","甘油","水銀"],answer:3,explanation:"橫瀾燈塔早期的旋轉透鏡浮在水銀上運轉，是當時的光學裝置設計。讀懂舊機械履歷就夠，唔係家居實驗題。",hint:"問的是承托旋轉透鏡的液體，並非燃料。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"古蹟辦・橫瀾燈塔",url:"https://www.amo.gov.hk/tc/historic-buildings/monuments/outlying-islands/monuments_71/index.html"},review:"2026-11-27已開啟列明機構原始頁面核對。核對歷史透鏡水銀承托裝置；不涉及接觸或操作材料的指引。"},{id:"r37",tier:3,category:"歷史・地名人物",question:"鶴咀的英文地名所紀念的人物，是哪位香港早期官員？",options:["德己立","彌敦","金文泰","般咸"],answer:0,explanation:"鶴咀的英文地名紀念德己立少將，他曾任香港早期副總督。地名背後有履歷，今次唔係靠哪條馬路最熟來投票。",hint:"留意早期曾出任副總督的人物。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"古蹟辦・鶴咀燈塔",url:"https://www.amo.gov.hk/tc/historic-buildings/monuments/hong-kong-island/monuments_80/index.html"},review:"2026-11-27已開啟列明機構原始頁面核對。核對英文地名紀念德己立；不重複既有題庫的燈塔啟用年份題。"},{id:"r38",tier:3,category:"地區・鄉村教育",question:"鏡蓉書屋的村校故事，發生在新界哪個地方？",options:["元朗錦田水頭","沙頭角上禾坑","大埔大埔頭村","西貢大網仔村"],answer:1,explanation:"鏡蓉書屋位於沙頭角上禾坑，由李氏族人興建作教育用途。唔同村有唔同校史，地名一字之差都可以去錯課室。",hint:"這座書屋位於新界東北部的村落。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"古蹟辦・鏡蓉書屋",url:"https://www.amo.gov.hk/tc/historic-buildings/monuments/new-territories/monuments_44/index.html"},review:"2026-11-27已開啟列明機構原始頁面核對。核對鏡蓉書屋位於沙頭角上禾坑；不推斷未明確的改名年份。"},{id:"r39",tier:3,category:"歷史・社區建築",question:"古洞何東夫人醫局在哪年落成？留意：題目唔係問開始提供服務。",options:["1923年","1928年","1933年","1938年"],answer:2,explanation:"何東夫人醫局於1933年落成，1934年開始服務。兩個日期相差一年，歷史題也會考你有冇睇清個動詞。",hint:"先把「落成」與「投入服務」拆成兩項紀錄。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"古蹟辦・何東夫人醫局歷史",url:"https://www.amo.gov.hk/tc/about-us/online-articles/20230511/index.html"},review:"2026-11-27已開啟列明機構原始頁面核對。核對1933年落成，明確區分1934年開始服務。"},{id:"r40",tier:3,category:"歷史・校園記憶",question:"赤柱聖士提反書院為紀念二戰蒙難者而建的小教堂，在哪年啟用？",options:["1930年","1940年","1960年","1950年"],answer:3,explanation:"聖士提反書院小教堂於1950年啟用，紀念在二戰及拘留期間蒙難的人士。這座校園建築也承載了需要尊重的戰爭記憶。",hint:"留意二戰結束後的校園重建年代。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"古蹟辦・聖士提反書院",url:"https://www.amo.gov.hk/tc/heritage-trails/greater-bay-area-education-trail/theme-d/st-stephens-college/index.html"},review:"2026-11-27已開啟列明機構原始頁面核對。核對1950年啟用及二戰紀念背景；避免把校舍遷址年份當教堂年份。"}].map(t=>Object.freeze({...t,options:Object.freeze(t.options),source:Object.freeze(t.source),focus:Object.freeze(t.focus),modes:Object.freeze(t.modes)})));var G=Object.freeze([{id:"k01",tier:1,category:"藝文・戲院記憶",question:"昔日看粵劇常去的新光戲院，位於港島哪個地區？",options:["北角","灣仔","筲箕灣","西營盤"],answer:0,explanation:"新光戲院昔日位於北角，是重要粵劇演出場地。今題考地點回憶，唔係叫你帶住舊戲飛去要求加開一場。",hint:"留意英皇道一帶的戲院記憶。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"政府新聞公報・粵劇場地",url:"https://www.info.gov.hk/gia/general/202412/18/P2024121800304.htm"},review:"2026-11-26依列明公開來源核對題材；藝術作品、歷史設施及地方用語按題目所限定的版本或情境作答。"},{id:"k02",tier:1,category:"藝文・趕去開場",question:"約朋友去香港演藝學院本部看表演，應前往哪個地區？",options:["沙田","灣仔","西灣河","深水埗"],answer:1,explanation:"演藝學院本部位於灣仔，另有薄扶林伯大尼古蹟校園。睇演出遲到已經夠驚，唔好再加一個去錯校園嘅支線任務。",hint:"題目指本部，並非伯大尼校園。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"香港演藝學院・到訪演藝",url:"https://www.hkapa.edu/tch/visitors/getting-here"},review:"2026-11-26依列明公開來源核對題材；藝術作品、歷史設施及地方用語按題目所限定的版本或情境作答。"},{id:"k03",tier:1,category:"港漫・童年朋友",question:"香港原創角色麥兜，在造型設定上是哪種動物？",options:["小熊","小狗","小豬","小牛"],answer:2,explanation:"麥兜是香港創作的小豬角色，出自謝立文及麥家碧的創作世界。佢有時慢半拍，但答呢題唔使連自己都進入慢動作。",hint:"想想圓鼻子及粉紅色的小主角。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"麥兜官方・角色",url:"https://mcdull.hk/cn/characters/"},review:"2026-11-26依列明公開來源核對題材；藝術作品、歷史設施及地方用語按題目所限定的版本或情境作答。"},{id:"k04",tier:1,category:"港漫・報紙副刊",question:"香港1960年代開始發表的《老夫子》系列，原作者以哪個筆名創作？",options:["黃玉郎","馬榮成","許冠文","王澤"],answer:3,explanation:"《老夫子》原作者王家禧以王澤為筆名，之後亦有家族傳承。睇漫畫笑到拍枱可以，唔好連作者名都拍走咗。",hint:"題目問原作者的筆名。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"香港電影資料館・展影103",url:"https://www.filmarchive.gov.hk/documents/5.-Exhibition-and-Screening/ProFolio/profolio103_c.pdf"},review:"2026-11-26依列明公開來源核對題材；藝術作品、歷史設施及地方用語按題目所限定的版本或情境作答。"},{id:"k05",tier:1,category:"電視・街坊故事",question:"寫實電視劇系列《獅子山下》，最初由哪個機構製作？",options:["香港電台","香港電影資料館","香港話劇團","香港管弦樂團"],answer:0,explanation:"香港電台於1972年開始製作《獅子山下》。劇中街坊有自己嘅人生難題，唔係每次都可以靠廣告時間解決。",hint:"想想港台的本地寫實劇傳統。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"香港電台・獅子山下",url:"https://www.rthk.hk/tv/dtt31/programme/btlr_hhv?lang=zh-hant"},review:"2026-11-26依列明公開來源核對題材；藝術作品、歷史設施及地方用語按題目所限定的版本或情境作答。"},{id:"k06",tier:1,category:"音樂・全場大合唱",question:"1993年粵語歌曲《海闊天空》的原唱香港樂隊是哪隊？",options:["達明一派","Beyond","太極","草蜢"],answer:1,explanation:"《海闊天空》由黃家駒創作，Beyond原唱。個歌名夠開揚，唱K房間照樣要按人頭訂，唔會自動變成體育館。",hint:"留意黃家駒所屬的樂隊。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"文體旅局・歌聲節目場刊",url:"https://www.cxlo.gov.hk/gbaf/assets/pdf/Songs_Echo_My_Voice_E_House_programme.pdf"},review:"2026-11-26依列明公開來源核對題材；藝術作品、歷史設施及地方用語按題目所限定的版本或情境作答。"},{id:"k07",tier:1,category:"電影・武俠歌單",question:"《滄海一聲笑》最初是哪部1990年電影的主題曲？",options:["《倩女幽魂》","《東邪西毒》","《笑傲江湖》","《新龍門客棧》"],answer:2,explanation:"這首黃霑作品與1990年《笑傲江湖》緊密相連。認到個歌唔使即場拔劍，先按一個答案已經夠瀟灑。",hint:"分清同屬武俠世界的電影。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"M+・笑傲江湖",url:"https://www.mplus.org.hk/tc/cinema/tsui-hark-the-free-spirited-trailblazer/the-swordsman/"},review:"2026-11-26依列明公開來源核對題材；藝術作品、歷史設施及地方用語按題目所限定的版本或情境作答。"},{id:"k08",tier:1,category:"電影・經典拍檔",question:"電影《胭脂扣》中，如花與十二少的主演是哪一組？",options:["張曼玉與梁朝偉","鍾楚紅與周潤發","林青霞與鄭少秋","梅艷芳與張國榮"],answer:3,explanation:"如花由梅艷芳飾演，十二少由張國榮飾演。經典拍檔靠演技留低印象，唔係因為佢哋個合照檔案名最易記。",hint:"想想電影資料館回顧的張、梅合作經典。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"政府新聞公報・芳華年代",url:"https://www.info.gov.hk/gia/general/201802/28/P2018022800738.htm"},review:"2026-11-26依列明公開來源核對題材；藝術作品、歷史設施及地方用語按題目所限定的版本或情境作答。"},{id:"k09",tier:1,category:"電影・英雄回憶",question:"1986年電影《英雄本色》的導演是誰？",options:["吳宇森","王家衛","許鞍華","張婉婷"],answer:0,explanation:"《英雄本色》由吳宇森執導，成為香港英雄片的重要作品。答題唔使着長褸慢鏡出場，準時揀到答案已經好有型。",hint:"留意以英雄片及動作美學著稱的導演。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"香港電影資料館・百部必看電影",url:"https://www.filmarchive.gov.hk/documents/5.-Exhibition-and-Screening/100_Must_See_Booklet.pdf"},review:"2026-11-26依列明公開來源核對題材；藝術作品、歷史設施及地方用語按題目所限定的版本或情境作答。"},{id:"k10",tier:1,category:"粵劇・任白合照",question:"粵劇界常說的「任白」，主要指哪兩位名伶？",options:["任劍輝與紅線女","任劍輝與白雪仙","薛覺先與白雪仙","新馬師曾與芳艷芬"],answer:1,explanation:"「任白」指任劍輝與白雪仙，是香港粵劇史上的經典組合。呢個縮寫唔係公司部門代號，亦唔使向人事部申請加入。",hint:"兩個字各取自兩位名伶的名字。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"中大・任白珍藏展",url:"https://www.cpr.cuhk.edu.hk/tc/press/cuhk-library-holds-yam-pak-collection-exhibition-in-honour-of-dr-pak-suet-sins-90-years/"},review:"2026-11-26依列明公開來源核對題材；藝術作品、歷史設施及地方用語按題目所限定的版本或情境作答。"},{id:"k11",tier:1,category:"茶樓・爽口糕點",question:"馬蹄糕常見一粒粒爽脆的「馬蹄」，實際是哪種食材？",options:["蓮藕","菱角","荸薺","百合"],answer:2,explanation:"粵語所說的馬蹄是荸薺，常切粒加入馬蹄糕。馬匹本人冇參與製作，糕點櫃亦唔需要附獸醫證明。",hint:"這是水生植物的可食地下部位。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"保良局・馬蹄糕活動食譜",url:"https://www.poleungkuk.org.hk/f/page/22398/59833/NewsLetter_CKHY-2024.01.pdf"},review:"2026-11-26依列明公開來源核對題材；藝術作品、歷史設施及地方用語按題目所限定的版本或情境作答。"},{id:"k12",tier:1,category:"餅店・下午茶爭奪戰",question:"常見雞尾包的甜餡，最有代表性的是哪種風味？",options:["紅豆蓉","蓮蓉鹹蛋","黑芝麻蓉","椰絲甜餡"],answer:3,explanation:"港式雞尾包常見椰絲等混合甜餡，各店配方可有不同。名字有雞，唔代表可以順便當一份雞肉蛋白餐。",hint:"留意常見餡料，別按包名猜肉類。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"雞尾包・配方與食物介紹",url:"https://zh.wikipedia.org/wiki/雞尾包"},review:"2026-11-26依列明公開來源核對題材；藝術作品、歷史設施及地方用語按題目所限定的版本或情境作答。"},{id:"k13",tier:1,category:"粥舖・即叫即滾",question:"粥舖所說的「生滾粥」，常見做法是哪一項？",options:["把鮮料放進粥底即時煮熟","先把粥凍成塊再蒸","只把冷飯拌入熱水","把全部配料放在生粥上便上枱"],answer:0,explanation:"生滾粥會把鮮料加入粥底煮熟，並不是叫客人自己吞生材料。「生」係入鑊前嘅狀態，唔係食客嘅勇氣測試。",hint:"留意粥底與鮮料即時滾熟的步驟。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"粵典・生滾粥",url:"https://words.hk/zidin/生滾粥"},review:"2026-11-26依列明公開來源核對題材；藝術作品、歷史設施及地方用語按題目所限定的版本或情境作答。"},{id:"k14",tier:1,category:"茶樓・葉香開包",question:"傳統糯米雞外面常見的大片包葉，通常是哪種葉？",options:["粽葉","荷葉","香蕉葉","紫蘇葉"],answer:1,explanation:"糯米雞常以荷葉包裹，蒸後有清香。拆包似開禮物，但唔好把包葉同餡料一齊當成豪華配菜。",hint:"它和一般粽子的細長包葉有別。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"興紀港式點心・荷葉糯米雞",url:"https://www.hsingchee.com/product_detail.php?id=22"},review:"2026-11-26依列明公開來源核對題材；藝術作品、歷史設施及地方用語按題目所限定的版本或情境作答。"},{id:"k15",tier:1,category:"茶樓・雅名點心",question:"飲茶點「豉汁鳳爪」，「鳳爪」通常是甚麼？",options:["鴨掌","豬手","雞腳","魚肚"],answer:2,explanation:"鳳爪是雞腳的食物雅稱，做法可先炸再燜蒸等。個名好有仙氣，價錢牌仍然要睇，唔會自動列入神話文物。",hint:"食物雅稱不等於真的神話動物。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"粵典・鳳爪",url:"https://words.hk/zidin/鳳爪"},review:"2026-11-26依列明公開來源核對題材；藝術作品、歷史設施及地方用語按題目所限定的版本或情境作答。"},{id:"k16",tier:1,category:"粥舖・雙重碳水",question:"早茶想加一碟「炸兩」，最常見是哪種組合？",options:["春卷包着粉絲","薄餅包着蛋撻","腐皮包着飯糰","腸粉包着油條"],answer:3,explanation:"炸兩常以腸粉裹油條，配醬汁吃。兩種碳水合作無間，唔代表你食完就可以把午飯當成已取消。",hint:"看清外面的粉皮與內裡的炸物。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"粵典・炸兩",url:"https://words.hk/zidin/炸兩"},review:"2026-11-26依列明公開來源核對題材；藝術作品、歷史設施及地方用語按題目所限定的版本或情境作答。"},{id:"k17",tier:1,category:"麵舖・名字不等於滋補",question:"香港餐牌上的「豬潤」，一般指豬的哪個部位？",options:["肝臟","腎臟","胃部","心臟"],answer:0,explanation:"「豬潤」是豬肝的常見粵語名稱。認食材可以靠行話，唔好單憑一個「潤」字就替自己開健康保證。",hint:"它是內臟名稱，不是口感評級。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"粵典・豬潤",url:"https://words.hk/zidin/豬潤"},review:"2026-11-26依列明公開來源核對題材；藝術作品、歷史設施及地方用語按題目所限定的版本或情境作答。"},{id:"k18",tier:1,category:"茶記・每日一湯",question:"茶餐廳餐牌寫「例湯」，一般是甚麼意思？",options:["當日只在早餐供應的清湯","當日按店舖安排供應的湯","每間分店必須統一的湯底","由客人自行點料煮成的湯"],answer:1,explanation:"例湯通常是店家當日供應的湯，材料與做法要按店舖了解。叫「例」唔代表老闆要逐條背出餐飲條例。",hint:"重點是當日店方安排，不保證固定配方。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"粵典・例（例湯用法）",url:"https://words.hk/zidin/例"},review:"2026-11-26依列明公開來源核對題材；藝術作品、歷史設施及地方用語按題目所限定的版本或情境作答。"},{id:"k19",tier:1,category:"藝文・找對劇院",question:"壽臣劇院屬於哪個灣仔藝文場館？",options:["香港文化中心","香港中央圖書館","香港藝術中心","香港電影資料館"],answer:2,explanation:"壽臣劇院位於香港藝術中心，可作戲劇、舞蹈、放映等用途。名字有「中心」嘅場館好多，唔好把集合地點只寫成「中心見」。",hint:"留意灣仔港灣道的場館。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"香港藝術中心・壽臣劇院",url:"https://hkac.org.hk/tc/venue_detail/shouson"},review:"2026-11-26依列明公開來源核對題材；藝術作品、歷史設施及地方用語按題目所限定的版本或情境作答。"},{id:"k20",tier:1,category:"茶記・快餐用語",question:"街坊說「煮包公仔麵」，在香港日常用語通常泛指甚麼？",options:["生麵條","烏冬","米粉","即食麵"],answer:3,explanation:"「公仔麵」在本地口語常被用來泛指即食麵，也原是品牌名稱。個名有公仔，打開個袋都唔包收藏人偶。",hint:"留意品牌名變成日常泛稱的用法。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"粵典・公仔麵",url:"https://words.hk/zidin/公仔麵"},review:"2026-11-26依列明公開來源核對題材；藝術作品、歷史設施及地方用語按題目所限定的版本或情境作答。"},{id:"k21",tier:2,category:"食肆・宵夜暗號",question:"相約去「打冷」，香港常見是吃哪種菜式的冷盤與小菜？",options:["潮州菜","客家菜","上海菜","順德菜"],answer:0,explanation:"打冷通常指吃潮州風味食物，包括滷水及小菜等，未必每道都冷食。唔使自備頸巾，先問朋友訂咗邊間。",hint:"它是飲食習慣用語，不是食物溫度規定。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"粵典・打冷",url:"https://words.hk/zidin/打冷"},review:"2026-11-26依列明公開來源核對題材；藝術作品、歷史設施及地方用語按題目所限定的版本或情境作答。"},{id:"k22",tier:2,category:"餅家・一物兩名",question:"香港餅店俗稱「馬仔」的甜點，通常也叫甚麼？",options:["沙翁","沙琪瑪","蛋散","牛脷酥"],answer:1,explanation:"馬仔通常指沙琪瑪，由麵條狀炸麵與糖漿等結合。個名聽落似細匹馬，實際上入袋之後只會令你想再拎一舊。",hint:"留意條狀麵食黏成的一塊甜點。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"粵典・薩其馬（馬仔）",url:"https://words.hk/zidin/薩其馬"},review:"2026-11-26依列明公開來源核對題材；藝術作品、歷史設施及地方用語按題目所限定的版本或情境作答。"},{id:"k23",tier:2,category:"糖水・沒有內餡的主角",question:"傳統糖不甩的丸子，通常是哪種製法？",options:["芝麻餡湯圓浸清湯","魚膠丸子浸甜豆漿","無餡糯米團配糖及花生芝麻等","芋泥包住一粒蓮子"],answer:2,explanation:"糖不甩常用無餡糯米丸配糖、花生及芝麻等。唔係每粒圓碌碌都收埋秘密，佢係把甜蜜直接黐喺外面。",hint:"不要把它與有餡湯圓混為一談。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"粵典・糖不甩",url:"https://words.hk/zidin/糖不甩"},review:"2026-11-26依列明公開來源核對題材；藝術作品、歷史設施及地方用語按題目所限定的版本或情境作答。"},{id:"k24",tier:2,category:"茶樓・馬拉糕",question:"香港茶樓常見的馬拉糕，屬於哪類糕點？",options:["層層摺疊的烘焗酥點","以糖漿黏合的炸麵條","以米漿冷卻凝固的甜糕","蒸製的鬆軟糕點"],answer:3,explanation:"馬拉糕是常見蒸糕，鬆軟組織與配方、發酵或膨鬆方式有關。上枱熱辣辣，唔好為咗驗證鬆軟就用全副手力揑落去。",hint:"先分清蒸、炸、焗與冷凝。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"食安中心・食品分類",url:"https://www.cfs.gov.hk/english/public/public_fifdrs/files/fehe245_a1.pdf"},review:"2026-11-26依列明公開來源核對題材；藝術作品、歷史設施及地方用語按題目所限定的版本或情境作答。"},{id:"k25",tier:2,category:"餐牌・銀芽不是金屬",question:"港式菜名中的「銀芽」，通常指經怎樣處理的豆芽？",options:["去掉頭尾的豆芽","保留豆殼的完整豆芽","輕輕醃漬過的豆芽","切碎拌入粉漿的豆芽"],answer:0,explanation:"銀芽一般是去掉頭尾的豆芽，菜式更顯整齊。名字似珠寶，埋單仍然按餐牌，唔會按銀價計。",hint:"留意豆芽修整後的形態。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"粵典・銀芽",url:"https://words.hk/zidin/銀芽"},review:"2026-11-26依列明公開來源核對題材；藝術作品、歷史設施及地方用語按題目所限定的版本或情境作答。"},{id:"k26",tier:2,category:"糖水・薄片的來歷",question:"腐竹糖水裡的腐竹，主要來自製豆漿時哪一部分？",options:["沉到鍋底的沙粒","加熱後表面形成的薄膜","把豆殼搓成的紙片","黃豆發芽後的嫩葉"],answer:1,explanation:"腐竹來自豆漿加熱時表面形成的膜，再加工乾燥。名字有竹，唔代表糖水師傅要先上山斬竹。",hint:"它屬豆製品，不是植物竹片。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"食安中心・豆製品分類",url:"https://www.cfs.gov.hk/sc_chi/whatsnew/whatsnew_fstr/files/FSO_Guide_to_Application_c.pdf"},review:"2026-11-26依列明公開來源核對題材；藝術作品、歷史設施及地方用語按題目所限定的版本或情境作答。"},{id:"k27",tier:2,category:"糖水・雪耳的分類",question:"糖水舖常用的雪耳，實際屬於哪類食材？",options:["海藻","果實","真菌","動物軟骨"],answer:2,explanation:"雪耳又稱銀耳，是真菌，並非海裡的雪白海藻。佢有好多褶邊，唔代表要先送去熨衫舖先可以入煲。",hint:"外表像花或海藻，不等於分類相同。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"香港植物標本室・真菌",url:"https://www.herbarium.gov.hk/filemanager/leaflets/en/upload/3/13/7_en.pdf"},review:"2026-11-26依列明公開來源核對題材；藝術作品、歷史設施及地方用語按題目所限定的版本或情境作答。"},{id:"k28",tier:2,category:"廚房・分工合作",question:"中菜廚房的「打荷」職位，主要協助哪方面工作？",options:["專責收銀與找續","專責接待客人及帶位","專責調配酒吧飲品","配合出菜、擺碟及廚師備料"],answer:3,explanation:"打荷會協助廚師備料、擺碟及銜接出菜等，分工可因店舖而異。唔係打開荷包嘅職位，雖然成晚都好忙。",hint:"把廚房後勤與樓面或酒吧分工分開。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"粵典・打荷",url:"https://words.hk/zidin/打荷"},review:"2026-11-26依列明公開來源核對題材；藝術作品、歷史設施及地方用語按題目所限定的版本或情境作答。"},{id:"k29",tier:2,category:"茶記・水吧師傅",question:"香港茶餐廳的「水吧」，主要負責哪類出品？",options:["茶、咖啡等飲品","燒味斬件","點心蒸製","海鮮刺身切配"],answer:0,explanation:"水吧是沖調飲品的重要工作位置，常處理奶茶、咖啡及凍飲。出品好多水，功夫可唔係隨便加水就算。",hint:"留意奶茶及咖啡的製作位置。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"職業訓練局・飲食業職位（飲品調配員／水吧服務員）",url:"https://manpower-survey.vtc.edu.hk/tc/industry/catering/jobs"},review:"2026-11-26依列明公開來源核對題材；藝術作品、歷史設施及地方用語按題目所限定的版本或情境作答。"},{id:"k30",tier:2,category:"手藝・小小花鈕",question:"傳統長衫上的花鈕，常以甚麼材料盤製？",options:["整塊陶瓷","幼布條","透明玻璃片","金屬拉鏈齒"],answer:1,explanation:"花鈕以幼布條盤製成各種紋樣，兼具扣合與裝飾功能。細細粒都可以做得咁講究，難怪扣錯一粒都幾心痛。",hint:"想想柔軟布條如何盤出結形。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"非遺辦・花鈕示範",url:"https://www.icho.hk/tc/web/icho/past_event35.html"},review:"2026-11-26依列明公開來源核對題材；藝術作品、歷史設施及地方用語按題目所限定的版本或情境作答。"},{id:"k31",tier:2,category:"手藝・量身剪裁",question:"香港中式長衫製作技藝中，「量身」最主要是為了甚麼？",options:["按衣服重量選擇包裝紙","按布匹顏色決定鈕扣數量","按穿者身形安排紙樣與裁剪","按店舖面積統一衣服長度"],answer:2,explanation:"量身有助按身形製作合適紙樣及衣服。師傅記住你嘅腰圍，通常比你記住自己上次話要早瞓更準。",hint:"這是服裝與人體尺寸的配合。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"非遺辦・香港非遺清單",url:"https://www.icho.hk/documents/Intangible-Cultural-Heritage-Inventory/2024/ich_inventory_2024_cn.pdf"},review:"2026-11-26依列明公開來源核對題材；藝術作品、歷史設施及地方用語按題目所限定的版本或情境作答。"},{id:"k32",tier:2,category:"手藝・木工接口",question:"香港傳統木器及傢俬手藝中的「榫卯」，最接近哪種接合方法？",options:["用鐵釘穿接兩件木材","在兩塊平面之間塗膠黏合","以麻繩纏繞木件外側","以凸出的榫嵌入相應凹槽"],answer:3,explanation:"榫卯以形狀相配的凸凹部位接合木件。兩件木啱位先穩，唔係單靠一句「我哋好夾」就可以承重。",hint:"留意凸出部位與凹槽的相配。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"非遺辦・傳統木工",url:"https://www.icho.hk/documents/Intangible-Cultural-Heritage-Inventory/2024/ich_inventory_2024_cn.pdf"},review:"2026-11-26依列明公開來源核對題材；藝術作品、歷史設施及地方用語按題目所限定的版本或情境作答。"},{id:"k33",tier:2,category:"手藝・節慶獅頭",question:"南獅的「點睛」儀式，主要承載哪種文化意思？",options:["象徵啟動獅子、祈求吉祥","以眼部顏色標示比賽級別","按瞳孔大小決定舞獅人數","把獅頭按重量分配演出角色"],answer:0,explanation:"點睛是帶祝願及象徵啟動意義的儀式，不是保證表演成功的科學程序。獅子醒神，舞嗰兩位仍然要靠練習。",hint:"把象徵祝願與實際視力檢查分開。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"非遺辦・獅舞傳統",url:"https://www.icho.hk/documents/Intangible-Cultural-Heritage-Inventory/2024/ich_inventory_2024_cn.pdf"},review:"2026-11-26依列明公開來源核對題材；藝術作品、歷史設施及地方用語按題目所限定的版本或情境作答。"},{id:"k34",tier:3,category:"語言・圍村聲音",question:"圍頭話最主要屬於哪個漢語方言系統的地方變體？",options:["閩南語","粵語","吳語","湘語"],answer:1,explanation:"圍頭話是新界原居民社群的重要語言，屬粵語系統的地方變體。聽唔明可以請教長輩，唔好即刻話人哋部收音機未調啱。",hint:"不要把圍頭話與同在新界流傳的客家話混同。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"非遺辦・本土語言傳承",url:"https://www.icho.hk/tc/web/icho/funding_scheme_products.html"},review:"2026-11-26依列明公開來源核對題材；藝術作品、歷史設施及地方用語按題目所限定的版本或情境作答。"},{id:"k35",tier:2,category:"民間聲音・南音傳承",question:"香港「地水南音」的歷史傳承，與哪類藝人關係特別密切？",options:["只表演無聲手語的藝人","專演西洋歌劇的合唱團","失明說唱藝人","專做皮影幕後剪紙的藝人"],answer:2,explanation:"地水南音與失明說唱藝人的歷史傳承密切相關，今天亦由不同表演者延續。藝術靠耳、口、心同功夫，唔係用標籤就可以概括人生。",hint:"題目問歷史傳承，不限制今天誰可以演唱。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"非遺辦・南音代表作簡介",url:"https://gia.info.gov.hk/general/201708/14/P2017081400644_265202_1_1502705234028.pdf"},review:"2026-11-26依列明公開來源核對題材；藝術作品、歷史設施及地方用語按題目所限定的版本或情境作答。"},{id:"k36",tier:2,category:"離島・小堂鐘聲",question:"西貢鹽田梓的聖若瑟小堂，屬於哪個宗教傳統？",options:["道教","佛教","伊斯蘭教","天主教"],answer:3,explanation:"聖若瑟小堂是鹽田梓天主教社群歷史的一部分。看建築先尊重使用者，唔好把每個小堂都當成婚紗攝影佈景。",hint:"留意聖若瑟與天主教村落的關係。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"民政事務總署・鹽田仔",url:"https://www.gohk.gov.hk/tc/spots/spot_detail.php?spot=Yim+Tin+Tsai"},review:"2026-11-26依列明公開來源核對題材；藝術作品、歷史設施及地方用語按題目所限定的版本或情境作答。"},{id:"k37",tier:2,category:"藝文・舊戲院復修",question:"油麻地戲院原建築落成於哪一年？",options:["1930年","1910年","1954年","1972年"],answer:0,explanation:"油麻地戲院於1930年建成，後經活化成為粵劇表演場地。戲院由老地方變成新舞台，唔等於建築生日要跟住重新計。",hint:"分清原建築落成與2012年活化啟用。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"康文署・油麻地戲院",url:"https://www.lcsd.gov.hk/tc/ymtt/aboutus/introduction.html"},review:"2026-11-26依列明公開來源核對題材；藝術作品、歷史設施及地方用語按題目所限定的版本或情境作答。"},{id:"k38",tier:2,category:"藝文・找路牌",question:"高山劇場的官方地址，位於九龍哪條街道？",options:["高陞街","高山道","高士威道","高街"],answer:1,explanation:"高山劇場位於紅磡高山道。香港有好多個「高」字地名，唔係見到個字熟就可以直接叫司機轉入去。",hint:"劇場名稱與街道名稱有直接關係。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"康文署・場地地址",url:"https://www.lcsd.gov.hk/clpss/tc/webApp/PhoneAddress.do"},review:"2026-11-26依列明公開來源核對題材；藝術作品、歷史設施及地方用語按題目所限定的版本或情境作答。"},{id:"k39",tier:2,category:"藝文・葵青之夜",question:"葵青劇院位於哪條街道？",options:["興發街","青山公路","興寧路","德士古道"],answer:2,explanation:"葵青劇院位於葵涌興寧路，鄰近葵芳站。地圖睇清楚，唔好把「葵青」當成所有新界地方嘅萬用地址。",hint:"想想葵芳站附近的場館地址。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"康文署・表演場地",url:"https://www.lcsd.gov.hk/clpss/tc/webApp/PVenue.do"},review:"2026-11-26依列明公開來源核對題材；藝術作品、歷史設施及地方用語按題目所限定的版本或情境作答。"},{id:"k40",tier:2,category:"港漫・分工搭檔",question:"麥兜漫畫中，謝立文與麥家碧的常見創作分工是哪項？",options:["謝立文作曲、麥家碧指揮","謝立文配樂、麥家碧剪電影","謝立文舞獅、麥家碧製獅頭","謝立文寫故事、麥家碧繪畫"],answer:3,explanation:"麥兜由謝立文創作故事、麥家碧繪畫，形成獨特文字與圖像世界。分工清楚，唔係一齊望住張白紙等隻豬自己行出嚟。",hint:"分清故事文字與繪畫工作。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"麥兜官方・關於我們",url:"https://mcdull.hk/cn/aboutus/"},review:"2026-11-26依列明公開來源核對題材；藝術作品、歷史設施及地方用語按題目所限定的版本或情境作答。"},{id:"k41",tier:3,category:"粵劇・反串行當",question:"粵劇所稱的「乾旦」，通常指哪種表演者？",options:["男演員扮演旦角","女演員扮演生角","女演員扮演旦角","男演員扮演生角"],answer:0,explanation:"乾旦指男演員演旦角；反串是戲曲表演傳統的一部分。台上角色同演員本人要分清，唔好把角色履歷直接填成人事紀錄。",hint:"留意演員性別與所演角色的區別。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"教大・粵劇角色行當",url:"https://xich.eduhk.hk/zht/page/detail/1275"},review:"2026-11-26依列明公開來源核對題材；藝術作品、歷史設施及地方用語按題目所限定的版本或情境作答。"},{id:"k42",tier:3,category:"粵劇・聲腔內行",question:"粵劇常說的「梆黃」，主要合稱哪兩個聲腔系統？",options:["南音與木魚","梆子與二黃","粵謳與龍舟","小調與兒歌"],answer:1,explanation:"梆黃主要指梆子及二黃，是粵劇重要板腔體系。聽到兩個字唔使先去搵姓黃嘅樂師，呢度講緊唱腔。",hint:"把板腔體系與說唱曲種分開。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"香港電台・板腔體系",url:"https://www.rthk.hk/oldassets/files/extra_file/20211007151827_1583901845.pdf"},review:"2026-11-26依列明公開來源核對題材；藝術作品、歷史設施及地方用語按題目所限定的版本或情境作答。"},{id:"k43",tier:3,category:"粵劇・劇本封面",question:"任白名劇《帝女花》的著名粵劇版本，主要由誰編撰？",options:["麥嘯霞","李少芸","唐滌生","葉紹德"],answer:2,explanation:"唐滌生編撰的《帝女花》成為任白重要代表作。背得到劇名未必背到唱詞，但至少唔好把編劇席派畀另一位大師。",hint:"題目指定任白演出的著名粵劇版本。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"中大圖書館・粵劇劇本",url:"https://archives.lib.cuhk.edu.hk/repositories/5/archival_objects/243718"},review:"2026-11-26依列明公開來源核對題材；藝術作品、歷史設施及地方用語按題目所限定的版本或情境作答。"},{id:"k44",tier:3,category:"粵劇・經典劇團",question:"任劍輝與白雪仙於1956年組成的劇團叫甚麼？",options:["雛鳳鳴劇團","覺先聲劇團","新艷陽劇團","仙鳳鳴劇團"],answer:3,explanation:"任白於1956年組成仙鳳鳴劇團；雛鳳鳴則是後來另一段重要傳承。兩個名都似識飛，成立背景唔可以跟住亂飛。",hint:"分清仙鳳鳴與雛鳳鳴。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"中華文化研究院・仙鳳長鳴",url:"https://chiculture.org.hk/en/node/4416"},review:"2026-11-26依列明公開來源核對題材；藝術作品、歷史設施及地方用語按題目所限定的版本或情境作答。"},{id:"k45",tier:3,category:"手藝・瓷彩比較",question:"欣賞香港廣彩手藝時，比較青花與廣彩工藝，哪個描述較準確？",options:["青花典型屬釉下彩，廣彩典型屬釉上彩","青花典型屬釉上彩，廣彩典型屬釉下彩","兩者都典型只用釉下鈷藍彩","兩者都典型先雕穿瓷胎再填彩"],answer:0,explanation:"青花典型是釉下彩，廣彩典型是在釉面上繪彩再燒製。顏色都靚，工序層次唔同，唔係同一支藍筆換個名就算。",hint:"注意彩繪在釉層上方還是下方。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"故宮博物院・廣彩瓷與青花",url:"https://www.dpm.org.cn/collection/ceramic/227350.html"},review:"2026-11-26依列明公開來源核對題材；藝術作品、歷史設施及地方用語按題目所限定的版本或情境作答。"},{id:"k46",tier:3,category:"文學・筆名名冊",question:"香港作家西西的本名是甚麼？",options:["梁秉鈞","張彥","盧瑋鑾","林燕妮"],answer:1,explanation:"西西是張彥的筆名，創作涵蓋小說、詩及散文等。筆名可以好多個，考試表格嗰格仍然只需要一個正確答案。",hint:"不要把不同香港作家的本名混在一起。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"中大香港文學特藏・西西",url:"https://hklit.lib.cuhk.edu.hk/writers_xixi_about/"},review:"2026-11-26依列明公開來源核對題材；藝術作品、歷史設施及地方用語按題目所限定的版本或情境作答。"},{id:"k47",tier:3,category:"文學・另一個名字",question:"以「也斯」為筆名的香港作家，本名是甚麼？",options:["劉以鬯","董啟章","梁秉鈞","鍾曉陽"],answer:2,explanation:"也斯本名梁秉鈞，兼具詩人、小說家及文化評論者等身分。個筆名好短，文學世界可一啲都唔細。",hint:"留意嶺南大學及香港文學研究中的作家介紹。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"嶺南大學・梁秉鈞介紹",url:"https://www.ln.edu.hk/cht/news/press-releases/20050314/01"},review:"2026-11-26依列明公開來源核對題材；藝術作品、歷史設施及地方用語按題目所限定的版本或情境作答。"},{id:"k48",tier:3,category:"文學・書架辨認",question:"香港文學作品《酒徒》的作者是誰？",options:["西西","也斯","金庸","劉以鬯"],answer:3,explanation:"《酒徒》是劉以鬯的重要小說，常在意識流文學討論中出現。書名有酒，借書時仍然唔使出示酒量證明。",hint:"分清小說作者，不要按書名猜人物習慣。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"香港公共圖書館・意識流書目",url:"https://www.hkpl.gov.hk/tc/common/attachments/extension-activities/literature/Appreciation-of-Literature/Consciousness-Booklist.pdf"},review:"2026-11-26依列明公開來源核對題材；藝術作品、歷史設施及地方用語按題目所限定的版本或情境作答。"},{id:"k49",tier:3,category:"電影獎・第一位主角",question:"第一屆香港電影金像獎的最佳電影是哪部？",options:["《父子情》","《胡越的故事》","《摩登保鏢》","《長輩》"],answer:0,explanation:"首屆最佳電影是《父子情》；其餘選項亦與早期金像獎有關。幾部都係熟面口，唔代表可以一口氣頒四個最佳電影。",hint:"把最佳電影與演員、編劇得獎作品分開。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"香港電影金像獎・第一屆",url:"https://www.hkfaa.com/winnerlist01.html"},review:"2026-11-26依列明公開來源核對題材；藝術作品、歷史設施及地方用語按題目所限定的版本或情境作答。"},{id:"k50",tier:3,category:"電影獎・首屆影帝",question:"許冠文憑哪部電影獲首屆香港電影金像獎最佳男主角？",options:["《半斤八兩》","《摩登保鏢》","《鬼馬雙星》","《賣身契》"],answer:1,explanation:"許冠文以《摩登保鏢》獲首屆最佳男主角。幾套都令人笑，但獎項紀錄唔係按你笑得最大聲嗰套計。",hint:"四個選項都是許氏喜劇相關作品，留意首屆得獎紀錄。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"香港電影金像獎・首屆男主角",url:"https://www.hkfaa.com/winnerlist01.html"},review:"2026-11-26依列明公開來源核對題材；藝術作品、歷史設施及地方用語按題目所限定的版本或情境作答。"},{id:"k51",tier:2,category:"電影・導演手筆",question:"電影《花樣年華》由哪位香港導演執導？",options:["杜琪峯","陳果","王家衛","關錦鵬"],answer:2,explanation:"《花樣年華》由王家衛執導，2000年上映。畫面靚到想截圖做桌布，答導演嗰陣都要記得先睇選項。",hint:"留意《阿飛正傳》《重慶森林》導演的創作脈絡。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"M+・花樣年華",url:"https://www.mplus.org.hk/tc/cinema/mplus-cinema-second-anniversary/in-the-mood-for-love/"},review:"2026-11-26依列明公開來源核對題材；藝術作品、歷史設施及地方用語按題目所限定的版本或情境作答。"},{id:"k52",tier:3,category:"電影・雙導演署名",question:"2002年《無間道》的兩位導演是哪一組？",options:["杜琪峯與韋家輝","陳嘉上與林超賢","徐克與程小東","劉偉強與麥兆輝"],answer:3,explanation:"《無間道》由劉偉強及麥兆輝共同執導。戲中人物身份複雜，片頭導演署名倒係清清楚楚，唔需要再查卧底紀錄。",hint:"留意該片的共同導演，而非其他常見電影搭檔。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"香港電影金像獎・第二十二屆",url:"https://www.hkfaa.com/winnerlist22.html"},review:"2026-11-26依列明公開來源核對題材；藝術作品、歷史設施及地方用語按題目所限定的版本或情境作答。"},{id:"k53",tier:3,category:"電影・小說改編",question:"電影《胭脂扣》改編自哪位作家的同名小說？",options:["李碧華","亦舒","張愛玲","鍾曉陽"],answer:0,explanation:"《胭脂扣》改編自李碧華小說，再由關錦鵬執導電影。小說同電影可以互相回味，作者同導演就唔好幫佢哋交換名牌。",hint:"分清原著作者與電影創作職位。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"香港電影資料館・胭脂扣",url:"https://www.filmarchive.gov.hk/documents/5.-Exhibition-and-Screening/100_Must_See_Booklet.pdf"},review:"2026-11-26依列明公開來源核對題材；藝術作品、歷史設施及地方用語按題目所限定的版本或情境作答。"},{id:"k54",tier:3,category:"電影・許鞍華作品",question:"《投奔怒海》的導演是哪一位？",options:["張婉婷","許鞍華","羅卓瑤","黃蜀芹"],answer:1,explanation:"《投奔怒海》由許鞍華執導，是她1980年代的重要作品。戲名有怒海，入場睇戲唔使自備防水袋。",hint:"留意香港電影新浪潮導演的作品。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"香港電影資料館・投奔怒海",url:"https://www.filmarchive.gov.hk/tc/web/hkfa/pe-event-2015-9-1-12.html"},review:"2026-11-26依列明公開來源核對題材；藝術作品、歷史設施及地方用語按題目所限定的版本或情境作答。"},{id:"k55",tier:3,category:"音樂・作詞作曲分開記",question:"歌曲《獅子山下》的經典「煇黃」創作分工是哪項？",options:["黃霑作曲、顧嘉煇填詞","顧嘉煇作曲、羅文填詞","顧嘉煇作曲、黃霑填詞","羅文作曲、顧嘉煇填詞"],answer:2,explanation:"《獅子山下》由顧嘉煇作曲、黃霑填詞，羅文主唱。首歌合作得好，唔代表幾個職位可以像打麻雀咁隨便調位。",hint:"分清作曲、填詞及演唱三種工作。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"政府新聞公報・黃霑展覽",url:"https://www.info.gov.hk/gia/general/202407/16/P2024071600264p.htm"},review:"2026-11-26依列明公開來源核對題材；藝術作品、歷史設施及地方用語按題目所限定的版本或情境作答。"},{id:"k56",tier:3,category:"音樂・主題曲名單",question:"1980年電視劇《上海灘》的經典主題曲，作曲人是誰？",options:["黎小田","盧冠廷","倫永亮","顧嘉煇"],answer:3,explanation:"經典《上海灘》主題曲由顧嘉煇作曲、黃霑填詞。音樂一響就有畫面，唔等於聽眾可以跳過創作名單。",hint:"留意「煇黃」組合的分工。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"政府新聞公報・煇黃作品",url:"https://www.info.gov.hk/gia/general/202407/16/P2024071600264p.htm"},review:"2026-11-26依列明公開來源核對題材；藝術作品、歷史設施及地方用語按題目所限定的版本或情境作答。"},{id:"k57",tier:3,category:"文學・城市想像",question:"香港小說《我城》出自哪位作家？",options:["西西","也斯","劉以鬯","舒巷城"],answer:0,explanation:"《我城》是西西的重要作品，從不同人物與敘述角度觀看城市。書名話「我城」，唔代表全幢樓嘅管理費都由作者負責。",hint:"留意以細膩、富想像的城市書寫著稱的作者。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"藝發局・西西作品回顧",url:"https://www.hkadc.org.hk/whats-on/press-release/hkadc-expresses-the-deepest-condolences-over-the-passing-of-renowned-writer-cheung-yin-ellen-xi-xi"},review:"2026-11-26依列明公開來源核對題材；藝術作品、歷史設施及地方用語按題目所限定的版本或情境作答。"},{id:"k58",tier:3,category:"港漫・另一位童年朋友",question:"香港漫畫《牛仔》的作者是誰？",options:["王澤","王司馬","黃玉郎","馬榮成"],answer:1,explanation:"《牛仔》是王司馬的代表作之一，透過家庭日常留下港人共同回憶。漫畫角色叫牛仔，唔代表要戴牛仔帽先可以睇。",hint:"把不同香港漫畫作者與角色分開記。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"香港公共圖書館・小思文庫",url:"https://www.hkpl.gov.hk/tc/common/attachments/extension-activities/about%20us/LO%20Wai-luen%20Collection.pdf"},review:"2026-11-26依列明公開來源核對題材；藝術作品、歷史設施及地方用語按題目所限定的版本或情境作答。"},{id:"k59",tier:3,category:"音樂史・由業餘到職業",question:"香港管弦樂團於哪一年正式職業化？",options:["1947年","1957年","1974年","1989年"],answer:2,explanation:"港樂前身於1947年成立，1957年改名，1974年職業化。三個年份都有份，唔好把成立、改名、轉型合併成一場生日會。",hint:"分清樂團起源、改名與職業化。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"香港管弦樂團・歷史",url:"https://www.hkphil.org/tc/about-hkphil"},review:"2026-11-26依列明公開來源核對題材；藝術作品、歷史設施及地方用語按題目所限定的版本或情境作答。"},{id:"k60",tier:3,category:"藝文・古蹟校園",question:"演藝學院伯大尼古蹟校園，主要供哪個學院作教育設施？",options:["舞蹈學院","中醫學院","建築學院","電影電視學院"],answer:3,explanation:"伯大尼是演藝學院電影電視教育的重要設施，位於薄扶林。古蹟有歷史，學生拍片照樣要交功課，唔會因為樓齡高就自動延期。",hint:"留意本部與電影電視古蹟校園的分工。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"香港演藝學院・簡介",url:"https://www.hkapa.edu/tch/about-hkapa"},review:"2026-11-26依列明公開來源核對題材；藝術作品、歷史設施及地方用語按題目所限定的版本或情境作答。"}].map(t=>Object.freeze({...t,options:Object.freeze(t.options),source:Object.freeze(t.source),focus:Object.freeze(t.focus),modes:Object.freeze(t.modes)})));var Y=Object.freeze([{id:"t01",tier:1,category:"社區・河邊散步",question:"沙田市中心兩旁有步道和單車徑的主要河道，是哪一條？",options:["城門河","林村河","梧桐河","屯門河"],answer:0,explanation:"城門河流經沙田市區，是新市鎮的重要地理骨幹。行河邊可以慢慢吹風，答題就唔好一路沿河漂走咗。",hint:"留意沙田新市鎮的河道。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"環保署・河溪資料",url:"https://www.epd.gov.hk/epd/sites/default/files/epd/tc_chi/environmentinhk/water/hkwqrc/files/waterquality/annual-report/riverreport2025.pdf"},review:"2026-11-26依列明公開來源核對題材；藝術作品、歷史設施及地方用語按題目所限定的版本或情境作答。"},{id:"t02",tier:1,category:"社區・大埔海濱",question:"在大埔海濱公園望出去，主要面向哪個海灣？",options:["后海灣","吐露港","大鵬灣","銀線灣"],answer:1,explanation:"大埔海濱面向吐露港，連起新界東部海岸景觀。個名有吐露，唔代表坐低就一定要交代所有心事。",hint:"想想大埔東面的內灣。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"康文署・大埔海濱公園",url:"https://www.lcsd.gov.hk/tc/parks/tpwp/"},review:"2026-11-26依列明公開來源核對題材；藝術作品、歷史設施及地方用語按題目所限定的版本或情境作答。"},{id:"t03",tier:1,category:"產業・園區名字",question:"將軍澳創新園重新定位前，常用的名稱是甚麼？",options:["將軍澳科學園","將軍澳物流園","將軍澳工業邨","將軍澳科技城"],answer:2,explanation:"將軍澳創新園前身名稱是將軍澳工業邨，園區支援製造及科技相關產業。唔係名有「園」就一定可以帶野餐墊入去。",hint:"留意香港工業邨轉向創新製造的定位。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"科技園・將軍澳創新園",url:"https://www.hkstp.org/zh-hk/discover/sites/tseung-kwan-o-innopark"},review:"2026-11-26依列明公開來源核對題材；藝術作品、歷史設施及地方用語按題目所限定的版本或情境作答。"},{id:"t04",tier:1,category:"海港・巨型吊機",question:"葵青貨櫃碼頭一排排吊機，主要處理哪種運輸貨物？",options:["航空貨運行李","油輪散裝原油","內河木材放排","海運貨櫃"],answer:3,explanation:"貨櫃碼頭以海運貨櫃裝卸為主要用途，連接船舶與陸路物流。個櫃大到似間房，都唔代表可以即場問月租。",hint:"先看貨櫃船與岸邊吊機的配合。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"海事處・香港港口便覽",url:"https://www.mardep.gov.hk/tc/materials-and-publications/publications/hk-fact-sheet/index.html"},review:"2026-11-26依列明公開來源核對題材；藝術作品、歷史設施及地方用語按題目所限定的版本或情境作答。"},{id:"t05",tier:1,category:"濕地・識行的魚",question:"濕地泥灘上能用胸鰭活動的彈塗魚，屬於哪類動物？",options:["魚類","兩棲類","爬蟲類","甲殼類"],answer:0,explanation:"彈塗魚是魚類，能在泥灘活動不代表變成蛙。佢識短暫離水覓食，唔等於你可以請佢加入行山群。",hint:"不要單憑能在泥灘走動便判斷分類。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"香港濕地公園・彈塗魚",url:"https://www.wetlandpark.gov.hk/tc/biodiversity/beauty-of-wetlands/wildlife/periophthalmus-modestus"},review:"2026-11-26依列明公開來源核對題材；藝術作品、歷史設施及地方用語按題目所限定的版本或情境作答。"},{id:"t06",tier:1,category:"觀鳥・藍橙小獵手",question:"香港濕地的普通翠鳥，長而尖的嘴喙主要方便捕捉甚麼？",options:["樹上的硬殼果實","水中的小魚","地底的大型薯塊","空中飄落的種子"],answer:1,explanation:"普通翠鳥常俯衝入水捕捉小魚，也吃其他小型水生生物。嘴尖係獵食工具，唔係用嚟評論隔籬隻雀嘅髮型。",hint:"留意池邊停立再入水的動作。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"香港濕地公園・普通翠鳥",url:"https://wetlandpark.gov.hk/filemanager/files/public/Download/Common-Kingfisher.pdf"},review:"2026-11-26依列明公開來源核對題材；藝術作品、歷史設施及地方用語按題目所限定的版本或情境作答。"},{id:"t07",tier:1,category:"街道・英雄樹",question:"香港俗稱「英雄樹」、春天常開紅橙色大花的樹是哪種？",options:["白千層","細葉榕","木棉","樟樹"],answer:2,explanation:"木棉有「英雄樹」的俗稱，春季大花很搶眼。佢唔使戴披風，枝頭一紅已經有足夠出場氣勢。",hint:"想想先開大花、後來有棉絮的樹。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"香港植物資料庫・木棉",url:"https://hkcww.org/hkplant/readid.php?id=671"},review:"2026-11-26依列明公開來源核對題材；藝術作品、歷史設施及地方用語按題目所限定的版本或情境作答。"},{id:"t08",tier:1,category:"街道・樹上的鬚",question:"細葉榕從枝幹垂下的「鬚」，主要是甚麼？",options:["纏在樹上的攀藤","未展開的垂生嫩芽","樹枝上的寄生植物","氣根"],answer:3,explanation:"細葉榕會長出氣根，部分伸到地面後可木質化，成為支撐。條條鬚都好認真生長，唔係園丁忘記替棵樹修面。",hint:"它是根的一種，不是花或果。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"發展局綠化・樹木標籤",url:"https://www.greening.gov.hk/tc/community-outreach/qrcode-tree-labels/index_id_4.html"},review:"2026-11-26依列明公開來源核對題材；藝術作品、歷史設施及地方用語按題目所限定的版本或情境作答。"},{id:"t09",tier:1,category:"離島・水口泥灘",question:"大嶼山水口受關注的幼鱟棲息環境，主要是哪種生境？",options:["潮間帶泥灘","潮下帶深水珊瑚礁","山區淡水溪流","海邊岩岸懸崖"],answer:0,explanation:"水口泥灘是本地海岸生物的重要生境之一，幼鱟在潮間帶覓食及成長。去欣賞可以，唔好把人哋個育嬰室當踩沙競技場。",hint:"留意潮退後露出的海岸泥灘。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"海洋公園保育基金・大嶼山泥灘",url:"https://www.opcf.org.hk/tc/community-education/safeguarding-the-lantau-intertidal-mudflat-biodiversity"},review:"2026-11-26依列明公開來源核對題材；藝術作品、歷史設施及地方用語按題目所限定的版本或情境作答。"},{id:"t10",tier:1,category:"公園・舊地新用途",question:"九龍公園所在土地，以前主要是哪個軍事設施？",options:["摩星嶺炮台","威菲路軍營","鯉魚門炮台","東涌炮台"],answer:1,explanation:"九龍公園由昔日威菲路軍營用地發展而來。今日行公園唔使操練，但行完一圈都可能開始想飲杯凍嘢。",hint:"留意尖沙咀市區的軍營舊址。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"康文署・九龍公園",url:"https://www.lcsd.gov.hk/tc/parks/kp/"},review:"2026-11-26依列明公開來源核對題材；藝術作品、歷史設施及地方用語按題目所限定的版本或情境作答。"},{id:"t11",tier:1,category:"海旁・掌印名人",question:"尖沙咀星光大道的影人掌印，主要向香港哪個行業致敬？",options:["電視廣播業","流行音樂唱片業","電影業","粵劇戲曲行業"],answer:2,explanation:"星光大道以影人、雕塑及掌印等呈現香港電影文化。手掌印得大唔代表票房一定高，記錄嘅係電影人嘅貢獻。",hint:"想想電影明星與幕後工作者。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"星光大道官方・電影文化",url:"https://www.avenueofstars.com.hk/"},review:"2026-11-26依列明公開來源核對題材；藝術作品、歷史設施及地方用語按題目所限定的版本或情境作答。"},{id:"t12",tier:1,category:"能源・風車回憶",question:"2006年啟用的南丫風采發電站，主要把哪種自然能量轉為電力？",options:["潮汐能","地熱能","水庫水能","風能"],answer:3,explanation:"南丫風采是香港風力發電的歷史設施，已於2026年關閉。今題回顧原理，唔係叫你即刻出發追住風車打卡。",hint:"名稱與大型風力發電機已提示能源。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"香港工程師學會・南丫風采",url:"https://hkie.org.hk/ea/tc/project/76"},review:"2026-11-26依列明公開來源核對題材；藝術作品、歷史設施及地方用語按題目所限定的版本或情境作答。"},{id:"t13",tier:1,category:"離島・船形建築",question:"香港挪亞方舟主題公園位於哪個島？",options:["馬灣","坪洲","長洲","吉澳"],answer:0,explanation:"挪亞方舟位於馬灣，是島上的主題設施。答到個島名已經得，唔使照故事安排兩隻動物一齊搭車。",hint:"想想青馬大橋旁的小島。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"民政署・挪亞方舟",url:"https://www.gohk.gov.hk/tc/spots/spot_detail.php?spot=Noah%27s+Ark"},review:"2026-11-26依列明公開來源核對題材；藝術作品、歷史設施及地方用語按題目所限定的版本或情境作答。"},{id:"t14",tier:1,category:"香港往昔・夜市記憶",question:"昔日香港的「大笪地」，最接近哪種市民生活空間？",options:["專供批發魚貨的封閉市場","露天娛樂及小販聚集場地","供行會議事的室內會館","專供學校考試的公共禮堂"],answer:1,explanation:"大笪地是昔日市民消閒、看表演及買小食的露天地方。唔係塊地夠大就自動有表演，背後仲有無數街坊同藝人嘅生計。",hint:"留意露天、平民娛樂及小販文化。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"古蹟辦・上環大笪地",url:"https://www.amo.gov.hk/tc/heritage-trails/cw-trails/sheungwan/section-b/b30/index.html"},review:"2026-11-26依列明公開來源核對題材；藝術作品、歷史設施及地方用語按題目所限定的版本或情境作答。"},{id:"t15",tier:1,category:"海旁・跑道變碼頭",question:"啟德郵輪碼頭所在的位置，與哪項舊設施最直接相關？",options:["前九龍城汽車渡輪碼頭","前紅磡貨運碼頭堆場","前啟德機場跑道末端","前昂船洲軍營操場"],answer:2,explanation:"郵輪碼頭位於昔日啟德機場跑道末端，城市交通由飛機接力到大船。兩樣都載客，唔代表登船可以用登機閘口號碼搵路。",hint:"留意啟德機場舊跑道的再利用。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"民政署・啟德郵輪碼頭",url:"https://www.gohk.gov.hk/tc/spots/spot_detail.php?spot=Kai+Tak+Cruise+Terminal"},review:"2026-11-26依列明公開來源核對題材；藝術作品、歷史設施及地方用語按題目所限定的版本或情境作答。"},{id:"t16",tier:1,category:"社區・寨城遺址",question:"九龍寨城公園位於哪個九龍行政區？",options:["油尖旺區","深水埗區","觀塘區","九龍城區"],answer:3,explanation:"九龍寨城公園位於九龍城區，保留寨城歷史遺跡。個區名同歷史有關，唔係見到有圍牆就叫佢做另一個寨城。",hint:"先把九龍城與其他九龍地區分清。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"民政署・九龍寨城公園",url:"https://www.gohk.gov.hk/tc/spots/spot_detail.php?spot=Kowloon+Walled+City+Park"},review:"2026-11-26依列明公開來源核對題材；藝術作品、歷史設施及地方用語按題目所限定的版本或情境作答。"},{id:"t17",tier:1,category:"邊境・街名記憶",question:"歷史街道「中英街」位於哪個新界社區？",options:["沙頭角","流浮山","蓮麻坑","打鼓嶺"],answer:0,explanation:"中英街位於沙頭角，有特殊邊界歷史。這裡只考地理，實際到訪安排仍要看相關官方資訊，唔好把遊戲答案當通行證。",hint:"留意新界東北邊境的海邊社區。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"旅發局・沙頭角",url:"https://www.discoverhongkong.com/tc/neighbourhoods/sha-tau-kok.html"},review:"2026-11-26依列明公開來源核對題材；藝術作品、歷史設施及地方用語按題目所限定的版本或情境作答。"},{id:"t18",tier:1,category:"郊遊・小水塘",question:"河背水塘主要位於元朗哪個地區一帶？",options:["屏山","八鄉","新田","洪水橋"],answer:1,explanation:"河背水塘位於八鄉河背村附近，是新界西北的郊遊景點。名字有河有背，都唔使你背住成條河去行山。",hint:"想想元朗東南面的八鄉山谷。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"漁護署郊野樂行・河背水塘",url:"https://www.hiking.gov.hk/promote/info/id/MHQzMHVZSGU5S3dNUEdYdEl1bUFHdz09"},review:"2026-11-26依列明公開來源核對題材；藝術作品、歷史設施及地方用語按題目所限定的版本或情境作答。"},{id:"t19",tier:1,category:"社區・河水去哪裡",question:"林村河流過大埔市區後，最終流入哪個海灣？",options:["后海灣","大鵬灣","吐露港","銀礦灣"],answer:2,explanation:"林村河匯合大埔河後流入吐露港，連繫大埔市區與海岸。河水有清楚去向，放工約食飯都可以參考一下呢種交代方法。",hint:"留意大埔東面的內灣。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"環保署・林村河資料",url:"https://www.epd.gov.hk/epd/sites/default/files/epd/tc_chi/environmentinhk/water/hkwqrc/files/waterquality/annual-report/riverreport2025.pdf"},review:"2026-11-26依列明公開來源核對題材；藝術作品、歷史設施及地方用語按題目所限定的版本或情境作答。"},{id:"t20",tier:1,category:"交通・鐵路合併",question:"2007年兩鐵合併所指的兩個鐵路系統，是哪一組？",options:["電車與山頂纜車","輕鐵與昂坪纜車","機場快綫與電車","地鐵與九鐵"],answer:3,explanation:"兩鐵合併指地鐵及九鐵系統整合，並非把所有有路軌嘅交通工具一齊搬入同一間辦公室。",hint:"分清城市鐵路公司與其他軌道交通。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"港鐵・公司歷史",url:"https://www.mtr.com.hk/ch/corporate/overview/profile_index.html"},review:"2026-11-26依列明公開來源核對題材；藝術作品、歷史設施及地方用語按題目所限定的版本或情境作答。"},{id:"t21",tier:2,category:"生態・海底找食",question:"香港中華白海豚在混濁水域找獵物，重要的感知方式是哪種？",options:["回聲定位","靠嗅覺沿海底聞氣味","只靠辨認水面顏色","只靠感應月光方向"],answer:0,explanation:"中華白海豚利用發聲及回聲等感知環境和獵物。水混都可以搵食，唔代表佢會幫你搵返跌咗落海嗰隻耳機。",hint:"想想聲音反射，而非只靠視覺。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"香港生物多樣性資訊站・白海豚",url:"https://bih.gov.hk/tc/fast-facts/iconic-species/index-id-7.html"},review:"2026-11-26依列明公開來源核對題材；藝術作品、歷史設施及地方用語按題目所限定的版本或情境作答。"},{id:"t22",tier:2,category:"生態・海面灰影",question:"香港水域的江豚，一項明顯外形特徵是哪個？",options:["有高而尖的背鰭","沒有背鰭","嘴喙特別細長突出","尾鰭呈垂直魚尾狀"],answer:1,explanation:"江豚沒有背鰭，也沒有海豚般明顯突出的嘴喙，因此較難在海面觀察。低調唔代表冇存在感，係你要更細心。",hint:"別把江豚與中華白海豚的輪廓混同。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"漁護署・江豚辨識",url:"https://www.afcd.gov.hk/tc_chi/conservation/con_mar/con_mar_fin/con_mar_fin_fin/con_mar_fin_fin_int_how.html"},review:"2026-11-26依列明公開來源核對題材；藝術作品、歷史設施及地方用語按題目所限定的版本或情境作答。"},{id:"t23",tier:2,category:"生態・夜裡的小燈",question:"香港螢火蟲的冷光，主要來自哪種過程？",options:["表皮反射月光","吸收日光後持續發出磷光","體內物質參與的化學發光","翅膀拍動產生的靜電"],answer:2,explanation:"螢火蟲以化學反應產生光，不是身上裝有小燈泡。夜裡閃一閃係生物訊號，唔係提示你幫佢交電費。",hint:"分清生物化學發光與反射光。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"香港螢火蟲・發光原理",url:"https://fireflies.hk/whyfirefliesglow/"},review:"2026-11-26依列明公開來源核對題材；藝術作品、歷史設施及地方用語按題目所限定的版本或情境作答。"},{id:"t24",tier:2,category:"地質・岩石的行間",question:"在香港沉積岩見到「層理」，主要反映哪種形成過程？",options:["岩體冷卻收縮形成裂隙","岩體沿斷層錯動的擦痕","雨水沿岩面溶蝕成凹紋","沉積物一層層堆積的差異"],answer:3,explanation:"層理反映沉積時材料或環境等變化，並非所有線都係斷層。石頭有自己嘅履歷，唔需要每條線都加一句「曾任地震」。",hint:"留意沉積層與裂縫的分別。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"土拓署・香港地質考察",url:"https://www.cedd.gov.hk/filemanager/tc/content_429/hkgeologyguidebook_c.pdf"},review:"2026-11-26依列明公開來源核對題材；藝術作品、歷史設施及地方用語按題目所限定的版本或情境作答。"},{id:"t25",tier:2,category:"地質・海蝕的結局",question:"破邊洲與花山分離，最後成為哪種海岸地形？",options:["海蝕柱","沙嘴","珊瑚礁","連島沙洲"],answer:0,explanation:"海浪侵蝕薄弱帶，海蝕拱倒塌後留下分離的海蝕柱。唔係海面升起一座新山，而係舊山被時間慢慢修剪。",hint:"看清洞、拱及拱頂倒塌後的演變。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"漁護署・破邊洲觀景台",url:"https://www.hiking.gov.hk/promote/info/id/dzBtZmZ6LytKNGQ4bWpMamZPUGd4UT09"},review:"2026-11-26依列明公開來源核對題材；藝術作品、歷史設施及地方用語按題目所限定的版本或情境作答。"},{id:"t26",tier:2,category:"海岸・潮退小水盆",question:"香港石岸退潮後留下、仍盛有海水的小凹位，通常稱為甚麼？",options:["河階","潮池","沙嘴","沖積扇"],answer:1,explanation:"潮池是海岸凹位在退潮後留下的水體，容納不同小生物。佢唔係迷你水族館，唔好擅自替住客搬屋。",hint:"留意退潮後岩面凹位的海水。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"鄉郊保育辦・海岸生態小冊子",url:"https://cco.gov.hk/documents/projects/38-feasibility-study-and-pilot-scheme-of-water-bus-for-inter-village-and-coastal-eco-tour-service-for-lai-chi-wo-and-nearby-villages/booklet-on-the-scenic-views-along-the-kaito-trip.pdf"},review:"2026-11-26依列明公開來源核對題材；藝術作品、歷史設施及地方用語按題目所限定的版本或情境作答。"},{id:"t27",tier:2,category:"海岸・動物還是植物",question:"香港海域的石珊瑚，活的主體是甚麼？",options:["大型海藻群落","海草的根莖系統","珊瑚蟲群體","完全無機的礦物結晶"],answer:2,explanation:"石珊瑚由珊瑚蟲等組成，外面可形成碳酸鈣骨骼。外形似花又似石，都唔代表可以摘一枝放入旅行袋。",hint:"看清活的珊瑚蟲與外部骨骼。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"漁護署・珊瑚簡介",url:"https://www.afcd.gov.hk/tc_chi/conservation/con_mar/con_mar_cor/con_mar_cor_intro/con_mar_cor_intro1.html"},review:"2026-11-26依列明公開來源核對題材；藝術作品、歷史設施及地方用語按題目所限定的版本或情境作答。"},{id:"t28",tier:2,category:"海水・突然變色",question:"香港水域所說的「紅潮」，主要由甚麼現象形成？",options:["河流挾帶鐵質泥沙入海","沿岸海水鹽度持續升高","強浪令海底泥沙翻起","某些浮游微藻大量繁殖聚集"],answer:3,explanation:"紅潮通常指高濃度藻華令海水變色，顏色不一定只有紅色，也不代表每次都含毒。個名係慣稱，唔係海洋只准用一隻色。",hint:"留意微小藻類大量繁殖，而非單看顏色。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"漁護署・紅潮是甚麼",url:"https://www.afcd.gov.hk/tc_chi/fisheries/hkredtide/redtide/red.html"},review:"2026-11-26依列明公開來源核對題材；藝術作品、歷史設施及地方用語按題目所限定的版本或情境作答。"},{id:"t29",tier:2,category:"古蹟・東涌城牆",question:"清代東涌炮台的歷史角色，主要與哪類任務相關？",options:["水師及海防","鹽務收貯","漁貨批發","內河客運"],answer:0,explanation:"東涌炮台在清代稱東涌所城，與水師及海防有關。城牆有歷史，唔好見到幾門炮就自動開始拍戰爭電影。",hint:"留意沿海水師據點的背景。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"古蹟辦・東涌文物",url:"https://www.amo.gov.hk/filemanager/amo/common/download-area/pamphlet/relics_in_tung_chung.pdf"},review:"2026-11-26依列明公開來源核對題材；藝術作品、歷史設施及地方用語按題目所限定的版本或情境作答。"},{id:"t30",tier:2,category:"古蹟・宗族名字",question:"龍躍頭的松嶺鄧公祠，主要屬於哪個宗族的祖祠？",options:["廖氏","鄧氏","侯氏","文氏"],answer:1,explanation:"松嶺鄧公祠是龍躍頭鄧氏的重要宗祠。祠堂個名係家族歷史線索，唔係所有大門兩邊有對聯就屬同一姓。",hint:"留意祠名中的姓氏提示。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"古蹟辦・法定古蹟名錄",url:"https://www.amo.gov.hk/filemanager/amo/common/form/Declared_Monuments_in_HK_Part_A.pdf"},review:"2026-11-26依列明公開來源核對題材；藝術作品、歷史設施及地方用語按題目所限定的版本或情境作答。"},{id:"t31",tier:2,category:"古蹟・從前的課室",question:"屏山覲廷書室最主要的傳統用途，是哪一類？",options:["族產收租與貨倉","海防守望與更樓","教學及族中子弟讀書","墟市粵劇演出的戲棚"],answer:2,explanation:"書室是傳統村落教育空間，覲廷書室亦與屏山鄧族歷史相連。個名有書，唔代表你今日可以去即場補交功課。",hint:"留意「書室」在村落教育中的角色。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"古蹟辦・屏山文物徑導賞",url:"https://www.amo.gov.hk/filemanager/amo/common/download-area/docent.pdf"},review:"2026-11-26依列明公開來源核對題材；藝術作品、歷史設施及地方用語按題目所限定的版本或情境作答。"},{id:"t32",tier:2,category:"古蹟・上水大堂",question:"上水廖萬石堂，最直接屬於哪類傳統建築？",options:["族塾","圍村門樓","書室","宗祠"],answer:3,explanation:"廖萬石堂是上水廖族宗祠，與宗族祭祖和聚會等傳統相連。堂名有萬石，唔係門口要交一萬嚿石先可以認識歷史。",hint:"不要把宗祠與書室或一般商業會堂混同。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"古蹟辦・宗祠古蹟名錄",url:"https://www.amo.gov.hk/filemanager/amo/common/form/Declared_Monuments_in_HK_Part_A.pdf"},review:"2026-11-26依列明公開來源核對題材；藝術作品、歷史設施及地方用語按題目所限定的版本或情境作答。"},{id:"t33",tier:2,category:"古蹟・村落工業",question:"西貢上窰村昔日興盛的傳統工業，主要是哪一項？",options:["燒造石灰","製陶燒瓷","曬製海鹽","煉製鐵礦"],answer:0,explanation:"上窰村曾以燒造殼灰等發展，後來窰業衰落。呢個「窰」真係同生計有關，唔係每條村都要有一部巨型焗爐。",hint:"留意窰、灰泥及建築材料的關係。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"古蹟辦・上窰村",url:"https://www.amo.gov.hk/tc/historic-buildings/monuments/new-territories/monuments_13/index.html"},review:"2026-11-26依列明公開來源核對題材；藝術作品、歷史設施及地方用語按題目所限定的版本或情境作答。"},{id:"t34",tier:2,category:"古蹟・灰窰原料",question:"上窰村傳統製灰工業所用的「殼灰」，主要與哪類原料相關？",options:["花崗岩礫石","貝殼等含鈣物料","燒過的木炭","乾燥稻草"],answer:1,explanation:"舊時以貝殼等含鈣物料燒灰作灰泥、肥料等，這是歷史工藝介紹，不是鼓勵今天採集海岸生物。師傅搵原料，唔係去海灘隨便執紀念品。",hint:"想想貝殼的含鈣特性。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"古蹟辦・上窰灰業",url:"https://www.amo.gov.hk/tc/historic-buildings/monuments/new-territories/monuments_13/index.html"},review:"2026-11-26依列明公開來源核對題材；藝術作品、歷史設施及地方用語按題目所限定的版本或情境作答。"},{id:"t35",tier:2,category:"地圖・海峽兩岸",question:"鯉魚門海峽把哪兩個大地域分隔開？",options:["大嶼山與坪洲","南丫島與長洲","香港島與九龍半島東端","青衣與馬灣"],answer:2,explanation:"鯉魚門是維港東面通往外海的水道，兩岸分屬港島及九龍一帶。名字有魚，唔代表過海一定要先買條魚。",hint:"留意維多利亞港東端的位置。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"土拓署・香港海岸地形",url:"https://www.cedd.gov.hk/filemanager/tc/content_429/hkgeologyguidebook_c.pdf"},review:"2026-11-26依列明公開來源核對題材；藝術作品、歷史設施及地方用語按題目所限定的版本或情境作答。"},{id:"t36",tier:2,category:"傳統・包糉葉香",question:"客家常見「露兜糉」的包葉，主要來自哪種植物？",options:["荷花","芭蕉","紫蘇","露兜樹"],answer:3,explanation:"露兜糉以露兜葉等包裹，葉材與一般粽葉或荷葉不同。拆開之前可以先認清香氣，唔使把所有綠葉都叫同一個名字。",hint:"題名中的植物名稱是重要線索。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"非遺辦・香港傳統飲食",url:"https://www.icho.hk/documents/Intangible-Cultural-Heritage-Inventory/2024/ich_inventory_2024_cn.pdf"},review:"2026-11-26依列明公開來源核對題材；藝術作品、歷史設施及地方用語按題目所限定的版本或情境作答。"},{id:"t37",tier:2,category:"古蹟・紅磚屋前身",question:"油麻地俗稱「紅磚屋」的歷史建築，原與哪項公共服務有關？",options:["抽水及供水","街市批發","發電配電","城市消防"],answer:0,explanation:"紅磚屋原是舊水務署抽水站建築的一部分，見證九龍供水發展。紅色外牆唔代表以前係消防局，先睇歷史資料再落判斷。",hint:"把建築顏色與真正用途分開。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"民政署・紅磚屋",url:"https://www.gohk.gov.hk/tc/spots/spot_detail.php?spot=Yau+Ma+Tei+Theatre+and+Red+Brick+Building"},review:"2026-11-26依列明公開來源核對題材；藝術作品、歷史設施及地方用語按題目所限定的版本或情境作答。"},{id:"t38",tier:2,category:"交通・跨海新線",question:"2021年屯馬綫全綫通車，把哪兩個原有鐵路部分連成一綫？",options:["東鐵綫與荃灣綫","原馬鞍山綫與西鐵綫","港島綫與將軍澳綫","東涌綫與迪士尼綫"],answer:1,explanation:"屯馬綫把原馬鞍山綫與西鐵綫等路段連通。名字兩端好易記，條線中間嘅街坊生活可唔止兩個地名。",hint:"想想新界東與新界西的既有鐵路。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"港鐵・2021年報網絡拓展",url:"https://www.mtr.com.hk/archive/corporate/ch/investor/annual2021/CMTRAR21.pdf"},review:"2026-11-26依列明公開來源核對題材；藝術作品、歷史設施及地方用語按題目所限定的版本或情境作答。"},{id:"t39",tier:2,category:"古蹟・屋頂的曲線",question:"中式傳統瓦屋頂的「正脊」，一般指哪個位置？",options:["屋坡與簷口相接的下緣","兩坡斜向相交的凹線","兩面主屋坡相交的最高橫脊","院牆頂部的壓頂"],answer:2,explanation:"正脊位於主屋坡相交的高處，常見灰塑或裝飾。名字話正，唔代表企到上面拍照先叫姿勢正確。",hint:"留意屋坡交會的頂部，而非門窗。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"古蹟辦・景賢里建築修復",url:"https://www.amo.gov.hk/filemanager/amo/common/form/research_king_yin_lei_c.pdf"},review:"2026-11-26依列明公開來源核對題材；藝術作品、歷史設施及地方用語按題目所限定的版本或情境作答。"},{id:"t40",tier:2,category:"地質・海灘上的顆粒",question:"香港海灘的沙粒，常由哪類長期作用形成及搬運？",options:["海鹽在岸邊反覆結晶","植物落葉長期完全碳化","火山灰不經搬運直接燒結","岩石風化侵蝕及水流搬運"],answer:3,explanation:"沙可來自岩石風化、侵蝕及搬運，也可混有生物碎屑。沙灘係自然過程嘅集合，唔係海洋開咗間糖水舖。",hint:"留意岩石碎屑的形成與搬運。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"土拓署・地質與地貌",url:"https://www.cedd.gov.hk/filemanager/tc/content_429/hkgeologyguidebook_c.pdf"},review:"2026-11-26依列明公開來源核對題材；藝術作品、歷史設施及地方用語按題目所限定的版本或情境作答。"},{id:"t41",tier:3,category:"海岸・外來紅樹",question:"在本地泥灘保育討論中，無瓣海桑通常被視為哪類紅樹？",options:["外來品種","香港特有種","本地原生種","只在淡水生長的植物"],answer:0,explanation:"無瓣海桑是香港的外來紅樹品種，擴展可能改變泥灘生境。見到棵樹綠油油，唔代表生態履歷可以全部剔「本地」。",hint:"分清在香港出現與原生於香港。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"海洋公園保育基金・泥灘生態",url:"https://www.opcf.org.hk/tc/community-education/safeguarding-the-lantau-intertidal-mudflat-biodiversity"},review:"2026-11-26依列明公開來源核對題材；藝術作品、歷史設施及地方用語按題目所限定的版本或情境作答。"},{id:"t42",tier:3,category:"地質・鴨洲碎石",question:"鴨洲著名的粗粒岩石地貌，主要與哪種岩石相關？",options:["大理岩","角礫岩","板岩","玄武岩"],answer:1,explanation:"鴨洲有明顯角礫岩地貌，岩內包含帶角的碎屑。島名有鴨，岩石分類唔可以直接填「禽類製品」。",hint:"留意粗大而有角的岩石碎屑。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"旅發局・鴨洲及吉澳",url:"https://www.discoverhongkong.com/tc/place-to-go/travel.guide-ap-chau-kat-o.html"},review:"2026-11-26依列明公開來源核對題材；藝術作品、歷史設施及地方用語按題目所限定的版本或情境作答。"},{id:"t43",tier:3,category:"地質・紅色不是油漆",question:"赤洲部分岩層呈褐紅色，主要與哪種成分及作用有關？",options:["銅質形成綠色碳酸鹽","石英吸收海水而變紅","鐵質氧化形成氧化鐵","碳質經燃燒後形成紅灰"],answer:2,explanation:"赤洲部分岩石的鐵質氧化，形成紅褐色的氧化鐵。大自然自己調咗色，唔係政府工程每季幫個島翻髹。",hint:"把岩石中的鐵質與氧化作用連起來。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"土拓署・香港地質指引",url:"https://www.cedd.gov.hk/filemanager/tc/content_429/hkgeologyguidebook_c.pdf"},review:"2026-11-26依列明公開來源核對題材；藝術作品、歷史設施及地方用語按題目所限定的版本或情境作答。"},{id:"t44",tier:3,category:"地質・西貢六角柱",question:"西貢萬宜一帶六角岩柱的主要岩性，與哪項最接近？",options:["一般黑色玄武岩","由貝殼堆積成的石灰岩","經高壓變質的板岩","富含二氧化矽的流紋質凝灰岩"],answer:3,explanation:"香港西貢六角岩柱主要是流紋質火山凝灰岩，不是見到六角柱就一律當玄武岩。形狀似朋友，身世未必同一間屋出嚟。",hint:"分清岩柱形狀與實際岩性。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"香港地質公園・萬宜岩柱",url:"https://www.geopark.gov.hk/sites/default/files/web/type/leaflet/pdf/2023-06/High%20Island%20Hexagonal%20Rock%20columns.pdf"},review:"2026-11-26依列明公開來源核對題材；藝術作品、歷史設施及地方用語按題目所限定的版本或情境作答。"},{id:"t45",tier:3,category:"地質・線條要分清",question:"香港火山岩的柱狀節理與沉積岩層理，主要差別是哪項？",options:["前者是冷卻收縮裂隙，後者是沉積分層","前者是沉積分層，後者是冷卻裂隙","前者是變質片理，後者是岩層斷裂","前者是侵蝕坑紋，後者是海浪刻痕"],answer:0,explanation:"柱狀節理與冷卻收縮有關；層理反映沉積分層，形成原因不同。石頭上有線唔等於同一種線，正如人有皺紋唔等於地圖有等高線。",hint:"把裂隙與原本的沉積層分開。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"土拓署・香港岩石構造",url:"https://www.cedd.gov.hk/filemanager/tc/content_429/hkgeologyguidebook_c.pdf"},review:"2026-11-26依列明公開來源核對題材；藝術作品、歷史設施及地方用語按題目所限定的版本或情境作答。"},{id:"t46",tier:3,category:"地質・角與圓的分別",question:"區分角礫岩與礫岩，常用的碎屑外形線索是哪項？",options:["角礫岩碎屑較磨圓，礫岩較有棱角","角礫岩碎屑較有棱角，礫岩較磨圓","角礫岩全部是玻璃，礫岩全部是金屬","角礫岩碎屑全是化石，礫岩全是晶體"],answer:1,explanation:"角礫岩與礫岩都可含粗碎屑，重要差別之一是磨圓程度。石頭有冇稜角係地質線索，唔係用嚟做性格測驗。",hint:"留意搬運磨蝕對碎屑外形的影響。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"土拓署・沉積岩辨識",url:"https://www.cedd.gov.hk/filemanager/tc/content_429/hkgeologyguidebook_c.pdf"},review:"2026-11-26依列明公開來源核對題材；藝術作品、歷史設施及地方用語按題目所限定的版本或情境作答。"},{id:"t47",tier:3,category:"海洋・珊瑚合作伙伴",question:"有共生蟲黃藻的造礁珊瑚，蟲黃藻的重要貢獻是哪項？",options:["把海水中的鹽直接變成氧氣","替珊瑚過濾大型泥沙","光合作用提供有機營養","直接分泌全部外部碳酸鈣骨架"],answer:2,explanation:"蟲黃藻透過光合作用供應有機物，與珊瑚形成共生關係。合作有回報，唔係同住一個屋企就自然叫生態共生。",hint:"留意藻類的光合作用及營養交換。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"漁護署・珊瑚共生",url:"https://www.afcd.gov.hk/tc_chi/conservation/con_mar/con_mar_cor/con_mar_cor_intro/con_mar_cor_intro2.html"},review:"2026-11-26依列明公開來源核對題材；藝術作品、歷史設施及地方用語按題目所限定的版本或情境作答。"},{id:"t48",tier:3,category:"海洋・認得同一隻海豚",question:"研究香港白海豚時，相片辨識常利用哪種個體差異？",options:["每次都只按出現位置分組","只按當天海水顏色分組","只按體長相近便當成同一隻","背鰭形狀、缺刻與身體斑紋"],answer:3,explanation:"研究者會利用自然標記與相片追蹤個體；體色亦可能隨成長改變，不能只看顏色。海豚冇身份證相，但有自己嘅辨認線索。",hint:"想想可在多次照片中比對的自然標記。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"生物多樣性資訊站・白海豚研究",url:"https://bih.gov.hk/tc/fast-facts/iconic-species/index-id-7.html"},review:"2026-11-26依列明公開來源核對題材；藝術作品、歷史設施及地方用語按題目所限定的版本或情境作答。"},{id:"t49",tier:3,category:"濕地・換一件外套",question:"蟹在成長時需要蛻去舊外骨骼，主要因為甚麼？",options:["硬殼不能像軟組織般一直伸展","每次換殼都會轉成另一個物種","蛻殼主要只為改變殼的顏色","硬殼遇海水便會完全溶解"],answer:0,explanation:"硬外骨骼限制身體持續增大，蛻殼後才有空間成長。蟹換殼有生物需要，唔係每季追新衫嘅購物習慣。",hint:"留意硬外殼與身體增大的關係。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"香港濕地公園・野生動植物圖冊",url:"https://wetlandpark.gov.hk/filemanager/files/public/Download/Pictorial_Guide_Wildlife__TC.pdf"},review:"2026-11-26依列明公開來源核對題材；藝術作品、歷史設施及地方用語按題目所限定的版本或情境作答。"},{id:"t50",tier:3,category:"天氣・風從哪邊來",question:"天文台說「吹東北風」，氣象風向主要指甚麼？",options:["風正吹往東北方","風從東北方吹來","風只在香港東北部吹起","風只會沿東北岸線平行吹"],answer:1,explanation:"風向按來向命名；香港秋冬常受東北季候風影響。風有來處，唔係你想佢吹去邊就改個名。",hint:"看清「來向」與「去向」的分別。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"天文台・冬季季候風",url:"https://www.hko.gov.hk/tc/education/weather/meteorology-basics/00068-why-the-winter-monsoon-in-hong-kong-is-generally-called-the-northeast-monsoon.html"},review:"2026-11-26依列明公開來源核對題材；藝術作品、歷史設施及地方用語按題目所限定的版本或情境作答。"},{id:"t51",tier:3,category:"天文・分日不必剛好平分",question:"香港春分日的日出至日落時間，為何未必剛好十二小時？",options:["香港當日會把鐘撥快一小時","春分當日太陽公轉速度突然加倍","日面大小及大氣折射影響日出日落定義","月球引力令香港白晝固定延長"],answer:2,explanation:"日出日落按太陽邊緣等計算，亦受大氣折射影響，所以春分日的白晝不必恰為十二小時。個「分」字唔係分帳App，未必自動五五分。",hint:"把幾何上太陽中心過地平線與實際日出定義分開。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"天文台・太陽周年路徑",url:"https://www.hko.gov.hk/tc/gts/astron2015/files/2015paths-sun.pdf"},review:"2026-11-26依列明公開來源核對題材；藝術作品、歷史設施及地方用語按題目所限定的版本或情境作答。"},{id:"t52",tier:3,category:"天文・最接近頭頂",question:"按天文台資料，太陽每年約有多少次最接近香港天頂？",options:["一次","三次","四次","兩次"],answer:3,explanation:"香港位於北回歸線以南，太陽每年約在六月初及七月上旬兩度最接近天頂。太陽照到頭頂都唔係鼓勵你抬頭直望。",hint:"留意太陽赤緯一年往返的變化。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"天文台・香港太陽能資源",url:"https://www.hko.gov.hk/tc/education/weather/sunshine-and-uv/00443-solar-energy-resources-in-hong-kong-from-a-climatological-point-of-view.html"},review:"2026-11-26依列明公開來源核對題材；藝術作品、歷史設施及地方用語按題目所限定的版本或情境作答。"},{id:"t53",tier:3,category:"天氣・海旁吹來的風",question:"晴朗日間香港沿岸出現海風，主要因為甚麼？",options:["陸地升溫較快，近地面空氣由海吹向陸","海面日間升溫較快，氣流由陸吹海","海陸溫差只會影響雨量，不影響氣流","只由地球自轉固定推動近岸空氣"],answer:0,explanation:"晴天日間海陸升溫差異可形成局地環流，近地面海風由海向陸。海旁涼一涼係物理過程，唔係大海特登開冷氣招呼你。",hint:"留意日間海陸受熱與低層氣流。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"天文台・海風介紹",url:"https://www.hko.gov.hk/en/aviat/articles/files/WS-turb-booklet-Chinese-web-ver.PDF"},review:"2026-11-26依列明公開來源核對題材；藝術作品、歷史設施及地方用語按題目所限定的版本或情境作答。"},{id:"t54",tier:3,category:"橋樑・青馬大橋的受力",question:"青馬大橋的主要結構形式是哪種？",options:["斜拉橋","懸索橋","鋼拱橋","連續梁橋"],answer:1,explanation:"青馬大橋採懸索橋形式，主纜及吊索等承托橋面。橋上有好多線，唔係每一條都係用嚟收電視訊號。",hint:"留意主纜跨過橋塔並以吊索承托橋面。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"路政署・青馬大橋",url:"https://www.hyd.gov.hk/tc/information_corner/trivia/longest_span_bridge/index.html"},review:"2026-11-26依列明公開來源核對題材；藝術作品、歷史設施及地方用語按題目所限定的版本或情境作答。"},{id:"t55",tier:3,category:"橋樑・昂船洲的斜線",question:"昂船洲大橋的主要結構形式是哪種？",options:["懸索橋","鋼拱橋","斜拉橋","連續梁橋"],answer:2,explanation:"昂船洲大橋屬斜拉橋，以斜拉索連接橋塔與橋面。唔係見到鋼索就一律叫懸索橋，兩款受力佈置有分別。",hint:"想想斜拉索由橋塔直接連到橋面。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"運輸署・橋樑資料",url:"https://www.td.gov.hk/tc/transport_in_hong_kong/tunnels_and_bridges_n/location_map/index.html"},review:"2026-11-26依列明公開來源核對題材；藝術作品、歷史設施及地方用語按題目所限定的版本或情境作答。"},{id:"t56",tier:3,category:"橋樑・無限的設計",question:"將軍澳跨灣連接路主橋「活力無限」設計，兩個外傾橋拱呼應哪個符號？",options:["加號＋","除號÷","百分號％","無限符號∞"],answer:3,explanation:"外傾雙拱與漸收橋墩的設計，呼應無限符號，並非憑空加兩個圈做裝飾。踩單車可以享受風景，但體力仍然唔會變無限。",hint:"留意兩個外傾橋拱的整體視覺。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"土拓署・跨灣連接路",url:"https://www.ceddreport202024.gov.hk/sc/our-projects/Cross_Bay_Link/"},review:"2026-11-26依列明公開來源核對題材；藝術作品、歷史設施及地方用語按題目所限定的版本或情境作答。"},{id:"t57",tier:3,category:"航空史・三跑一起運作",question:"香港國際機場三跑道系統正式啟用，是哪一年？",options:["2024年","2016年","2022年","2025年"],answer:0,explanation:"三跑道系統於2024年11月28日啟用；新跑道較早投入服務與整個三跑系統啟用是不同事件。多咗跑道，答題都唔可以任意轉線。",hint:"分清第三跑道先行運作與整體系統啟用。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"香港機場管理局・三跑系統啟用",url:"https://www.hongkongairport.com/tc/media-centre/press-release/2024/pr_1763"},review:"2026-11-26依列明公開來源核對題材；藝術作品、歷史設施及地方用語按題目所限定的版本或情境作答。"},{id:"t58",tier:3,category:"場館史・科學館開門",question:"香港科學館正式開幕的年份是哪一年？",options:["1980年","1991年","1989年","1998年"],answer:1,explanation:"香港科學館於1991年開幕，與太空館及文化中心等場館的年份不同。科學可以做實驗，歷史年份就唔好用四個答案輪流試。",hint:"留意科學館而非太空館。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"香港科學館・發展歷史",url:"https://hk.science.museum/en/web/scm/about.html"},review:"2026-11-26依列明公開來源核對題材；藝術作品、歷史設施及地方用語按題目所限定的版本或情境作答。"},{id:"t59",tier:3,category:"授時・時間的元素",question:"香港天文台維持香港標準時間所用的高精度原子鐘，採用哪種元素？",options:["氦","鐵","銫","碳"],answer:2,explanation:"天文台以銫原子鐘等高精度授時設備維持標準時間。你隻鬧鐘遲五分鐘，唔好即刻打去叫天文台遷就一下。",hint:"留意授時資料所述的原子鐘種類。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"天文台・香港標準時間",url:"https://www.hko.gov.hk/tc/gts/time/hk_standard_time.htm"},review:"2026-11-26依列明公開來源核對題材；藝術作品、歷史設施及地方用語按題目所限定的版本或情境作答。"},{id:"t60",tier:3,category:"城市工程・半山電梯",question:"中環至半山自動扶梯系統，在哪一年啟用？",options:["1983年","1988年","1998年","1993年"],answer:3,explanation:"系統於1993年啟用，結合有蓋步道、自動扶梯與行人道。上山省到腳骨力，唔代表返工都可以由條梯代你行埋。",hint:"把系統最初啟用與後來更新工程分開。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"運輸署・半山電梯",url:"https://www.td.gov.hk/tc/transport_in_hong_kong/pedestrians/hillside_escalator/index.html"},review:"2026-11-26依列明公開來源核對題材；藝術作品、歷史設施及地方用語按題目所限定的版本或情境作答。"}].map(t=>Object.freeze({...t,options:Object.freeze(t.options),source:Object.freeze(t.source),focus:Object.freeze(t.focus),modes:Object.freeze(t.modes)})));var Z=Object.freeze([{id:"f01",tier:1,category:"小食・糖水舖",question:"擂沙湯圓外面那層香口「沙」，常見主要是哪種碎粉？",options:["花生碎及糖粉","咖啡粉及鹽","可可粉及奶粉","粟米粉及胡椒"],answer:0,explanation:"常見擂沙湯圓會滾上花生碎與糖粉，亦有芝麻等配搭。「沙」係口感形容，唔係師傅帶咗你去沙灘。",hint:"想想糖水舖常用的堅果香。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"AndThen・小店手製湯圓",url:"https://www.andthen.hk/eat/52800_小店手製湯圓-傳統糖水-自煮湯圓/"},review:"2026-11-26按列明來源核對；用語按情境解釋，年份限定事件，不以信仰或傳說作效果保證。"},{id:"f02",tier:1,category:"小食・懷舊脆餅",question:"零食袋裡的「牛耳餅」，名字最直接來自甚麼？",options:["主要用牛耳肉製作","薄片輪廓像牛耳","只在牛年才生產","必須用牛奶浸一晚"],answer:1,explanation:"牛耳餅是鹹甜香脆的麵粉小食，名字與耳形外觀有關。牛本人冇借出耳仔，更冇要求收肖像費。",hint:"先看外形，不要按名字認定肉類成分。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"元朗合興・牛耳餅",url:"https://www.foodpanda.hk/zh/restaurant/yu8b/yuen-long-hop-hing-to-kwa-wan"},review:"2026-11-26按列明來源核對；用語按情境解釋，年份限定事件，不以信仰或傳說作效果保證。"},{id:"f03",tier:1,category:"小食・白糖糕",question:"白糖糕切開有細孔、微酸又彈牙，常見主要粉料是甚麼？",options:["鷹粟粉","馬蹄粉","粘米粉","杏仁粉"],answer:2,explanation:"傳統白糖糕以粘米粉配糖發酵後蒸製。個糕有氣孔，唔代表師傅偷咗一半材料；發酵先係幕後功臣。",hint:"它是發酵米糕，不是果仁蛋糕。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"米芝蓮指南・傳統地道甜品",url:"https://guide.michelin.com/hk/zh_HK/article/features/must-eat-traditional-desserts-hong-kong"},review:"2026-11-26按列明來源核對；用語按情境解釋，年份限定事件，不以信仰或傳說作效果保證。"},{id:"f04",tier:1,category:"小食・名字陷阱",question:"懷舊香蕉糕聞落有香蕉香，以下哪項理解較準確？",options:["一定包着完整香蕉片","黃色版本才有香蕉味","名字保證完全不加糖","可用香蕉香料，不一定有鮮香蕉"],answer:3,explanation:"傳統常見配方用米粉、糖及香蕉油調味，未必含鮮香蕉。香蕉有份出香味，未必有份出席切餅儀式。",hint:"食物名稱不等於完整配料表。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"米芝蓮指南・傳統地道甜品",url:"https://guide.michelin.com/hk/zh_HK/article/features/must-eat-traditional-desserts-hong-kong"},review:"2026-11-26按列明來源核對；用語按情境解釋，年份限定事件，不以信仰或傳說作效果保證。"},{id:"f05",tier:1,category:"小食・糖蔥餅",question:"買糖蔥餅時，當中的「糖蔥」通常是甚麼？",options:["帶孔而鬆脆的糖塊","撒糖後焗乾的蔥花","白色蔥頭醃成的蜜餞","蔥味雪糕切成的小條"],answer:0,explanation:"糖蔥是拉製成帶孔的糖塊，配薄餅皮等吃，並不是蔥段。今次唔使叫「走青」，蔥根本冇報名。",hint:"名稱借外形，不是蔥菜配料。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"思考香港・糖蔥餅",url:"https://www.thinkhk.com/article/2019-11/01/37256.html"},review:"2026-11-26按列明來源核對；用語按情境解釋，年份限定事件，不以信仰或傳說作效果保證。"},{id:"f06",tier:1,category:"街市・豆品檔",question:"打邊爐的豆腐卜像海綿般吸湯，一般經哪種加工？",options:["把鮮奶冷凍再切件","把豆腐油炸至膨起","把米漿焗成小空心包","把豆腐曬成完全乾片"],answer:1,explanation:"豆腐卜是炸豆腐，鬆孔會吸入湯汁。吸湯能力咁強，食之前記得小心熱；佢唔係餐桌上嘅隔熱棉。",hint:"「卜」的蓬鬆內部與炸製有關。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"食安中心・食品分類",url:"https://www.cfs.gov.hk/sc_chi/whatsnew/whatsnew_fstr/files/FSO_Guide_to_Application_c.pdf"},review:"2026-11-26按列明來源核對；用語按情境解釋，年份限定事件，不以信仰或傳說作效果保證。"},{id:"f07",tier:1,category:"餅家・月餅櫃",question:"蓮蓉月餅那層細滑甜餡，主要用哪種材料製作？",options:["蓮藕","菱角","蓮子","芋頭"],answer:2,explanation:"蓮蓉以蓮子加工成蓉，再按配方調糖和油。蓮子同蓮藕係植物親戚，但唔係可以隨便互換嘅同事。",hint:"看「蓮」字，也要分清植物部位。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"美心月餅・白蓮蓉月餅",url:"https://www.maximsproducts.com.hk/tc/"},review:"2026-11-26按列明來源核對；用語按情境解釋，年份限定事件，不以信仰或傳說作效果保證。"},{id:"f08",tier:1,category:"粥檔・水上滋味",question:"艇仔粥的「艇仔」，與哪種傳統生活最有關？",options:["茶樓用船形碟上粥","只在颱風天才吃的粥","以魚骨雕成的小湯匙","水上小艇販粥的生活"],answer:3,explanation:"艇仔粥的名稱與廣州及珠江一帶水上販粥文化相連，後亦成為香港熟悉的粥品。食一碗唔包船票，亦唔使自備救生衣。",hint:"題目問名字的水上生活背景。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"旅發局・粥品文化",url:"https://www.discoverhongkong.com/tc/explore/dining.html"},review:"2026-11-26按列明來源核對；用語按情境解釋，年份限定事件，不以信仰或傳說作效果保證。"},{id:"f09",tier:1,category:"粵語・放工之後",question:"朋友話「今晚煲劇」，在追電視劇的情境是甚麼意思？",options:["連續看多集劇集","把電視劇改寫成劇本","聽電台重播的新聞","只重看一段廣告"],answer:0,explanation:"「煲劇」指投入地連續追看劇集。煲唔需要開火，但凌晨三點嗰句「再一集」通常比鬧鐘更有影響力。",hint:"留意追劇的語境，並非烹調。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"粵典・煲劇",url:"https://words.hk/zidin/煲劇"},review:"2026-11-26按列明來源核對；用語按情境解釋，年份限定事件，不以信仰或傳說作效果保證。"},{id:"f10",tier:1,category:"粵語・演唱會戰況",question:"同事說「我放飯要撲飛」，在演唱會售票的情境是想做甚麼？",options:["去機場接一位朋友","設法購買或找門票","幫演唱會拍宣傳照","把已買的票摺成飛機"],answer:1,explanation:"「飛」在此指票，「撲飛」就是設法找票或搶購。午飯可以遲食，開售畫面個轉圈圈可唔會同你客氣。",hint:"把「飛」理解為票券。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"粵典・撲飛",url:"https://words.hk/zidin/撲飛"},review:"2026-11-26按列明來源核對；用語按情境解釋，年份限定事件，不以信仰或傳說作效果保證。"},{id:"f11",tier:1,category:"粵語・被婉拒",question:"約人食飯被婉拒後說「食咗檸檬」，主要是在形容甚麼？",options:["赴約時點錯了飲品","收到一份酸味甜品","遭到拒絕","為對方解決了難題"],answer:2,explanation:"這個情境的「食檸檬」指被拒絕。冇人真係端碟檸檬出嚟，但個心可能已經自動加咗冰同苦味。",hint:"題目已限定為邀約被拒的情境。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"粵典・食檸檬",url:"https://words.hk/zidin/食檸檬"},review:"2026-11-26按列明來源核對；用語按情境解釋，年份限定事件，不以信仰或傳說作效果保證。"},{id:"f12",tier:1,category:"粵語・街坊排隊",question:"輪到你埋櫃前，有人突然插到前面；街坊叫佢唔好「打尖」，即係？",options:["不要提高說話音量","不要在地上做記號","不要替後面的人付款","不要插隊"],answer:3,explanation:"「打尖」是沒有依次序排隊而插入前面。條隊唔係剪片軟件，唔可以見到空位就直接插一段自己入去。",hint:"焦點是排隊先後次序。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"粵典・打尖",url:"https://words.hk/zidin/打尖"},review:"2026-11-26按列明來源核對；用語按情境解釋，年份限定事件，不以信仰或傳說作效果保證。"},{id:"f13",tier:1,category:"粵語・找續時刻",question:"老闆問「有冇散紙？」，結帳時通常想要甚麼？",options:["較小面額的鈔票或硬幣","可以重用的包裝紙","未填寫的收據表格","記下貨價的便條紙"],answer:0,explanation:"結帳時「散紙」指較小面額金錢，方便付款或找續。唔使幫老闆碎紙，佢想開錢櫃，唔係開環保工作坊。",hint:"留意找續及面額的關係。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"粵典・唱散（散紙用法）",url:"https://words.hk/zidin/唱散"},review:"2026-11-26按列明來源核對；用語按情境解釋，年份限定事件，不以信仰或傳說作效果保證。"},{id:"f14",tier:1,category:"粵語・小店日常",question:"舖頭成朝冇客，老闆話「今日拍烏蠅」，通常形容甚麼？",options:["店內正在拍攝廣告","生意冷清，閒着沒事做","客人爭相購買驅蟲用品","店員忙着核對大量訂單"],answer:1,explanation:"「拍烏蠅」在這情境形容生意清淡或很閒。唔係叫你評論老闆拍手嘅節奏，最好幫襯杯嘢先。",hint:"它是冷清狀態的比喻。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"粵典・拍烏蠅",url:"https://words.hk/zidin/拍烏蠅"},review:"2026-11-26按列明來源核對；用語按情境解釋，年份限定事件，不以信仰或傳說作效果保證。"},{id:"f15",tier:1,category:"城中・文化之夜",question:"相約去香港文化中心聽音樂會，應去哪個地區？",options:["西灣河","沙田","尖沙咀","柴灣"],answer:2,explanation:"香港文化中心位於尖沙咀海旁。睇海可以同場加映，但買咗音樂會飛就唔好全晚企喺海邊等開場。",hint:"它與鐘樓及維港海旁相鄰。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"康文署・香港文化中心",url:"https://www.lcsd.gov.hk/tc/hkcc/"},review:"2026-11-26按列明來源核對；用語按情境解釋，年份限定事件，不以信仰或傳說作效果保證。"},{id:"f16",tier:1,category:"城中・兵頭花園",question:"街坊口中的「兵頭花園」，通常指哪個公園？",options:["九龍公園","香港濕地公園","荔枝角公園","香港動植物公園"],answer:3,explanation:"「兵頭花園」是香港動植物公園的俗稱，與鄰近昔日總督府等歷史背景相連。行花園唔使操步，保持安靜睇動物就得。",hint:"這個俗稱與中區歷史有關。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"古蹟辦・香港動植物公園",url:"https://www.amo.gov.hk/tc/heritage-trails/cw-trails/central/section-b/central-b19/index.html"},review:"2026-11-26按列明來源核對；用語按情境解釋，年份限定事件，不以信仰或傳說作效果保證。"},{id:"f17",tier:1,category:"城中・抬頭找主角",question:"走進香港公園的尤德觀鳥園，最切題是觀察哪類動物？",options:["鳥類","蝴蝶類","爬蟲類","淡水魚類"],answer:0,explanation:"尤德觀鳥園讓遊人觀察鳥類與林間環境。主角識飛，搵唔到唔好即刻俾一星，先試吓抬頭。",hint:"名稱中的動作已提示觀察對象。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"康文署・香港公園觀鳥園",url:"https://hkp.lcsd.gov.hk/tc/facilities/aviary"},review:"2026-11-26按列明來源核對；用語按情境解釋，年份限定事件，不以信仰或傳說作效果保證。"},{id:"f18",tier:1,category:"生態・潮來潮去",question:"在香港濕地看紅樹林，它們典型適應哪種環境？",options:["完全乾燥的沙漠沙丘","潮水漲退的海岸潮間帶","全年結冰的高山雪線","沒有水分的密封岩洞"],answer:1,explanation:"紅樹林適應沿岸潮間帶，部分能忍受鹽分及泥土缺氧。佢哋每日迎送潮水，返工時間表由月亮幫手排。",hint:"留意海岸潮汐，不是單純樹葉顏色。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"香港濕地公園・紅樹林",url:"https://www.wetlandpark.gov.hk/tc/biodiversity/beauty-of-wetlands/wetland-habitats/mangroves"},review:"2026-11-26按列明來源核對；用語按情境解釋，年份限定事件，不以信仰或傳說作效果保證。"},{id:"f19",tier:1,category:"地圖・西邊日落",question:"摩星嶺看日落很有氣氛，它位於香港哪個大區域？",options:["九龍半島東部","大嶼山北部","香港島西部","新界東北部"],answer:2,explanation:"摩星嶺位於香港島西部。名字聽落似太空站，其實約人過去，先查本地交通，唔使申請升空。",hint:"想想堅尼地城再往西的方向。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"旅發局・摩星嶺",url:"https://www.discoverhongkong.com/tc/tours/mt-davis-military-history-tour.html"},review:"2026-11-26按列明來源核對；用語按情境解釋，年份限定事件，不以信仰或傳說作效果保證。"},{id:"f20",tier:1,category:"體育・混雙拍檔",question:"鄧俊文與謝影雪的香港混雙組合，參與哪項運動？",options:["網球","乒乓球","壁球","羽毛球"],answer:3,explanation:"鄧俊文及謝影雪是香港羽毛球混雙組合。兩個人合作接殺球，唔代表可以把辦公室啲波一齊傳畀佢哋。",hint:"想想羽毛球賽場上的混合雙打。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"體院・羽毛球",url:"https://www.hksi.org.hk/tc/sports/badminton"},review:"2026-11-26按列明來源核對；用語按情境解釋，年份限定事件，不以信仰或傳說作效果保證。"},{id:"f21",tier:2,category:"生態・泥灘小森林",question:"海欖雌旁一枝枝伸出泥面的呼吸根，主要幫它做甚麼？",options:["在缺氧泥土環境交換氣體","把海水蒸成淡水供鳥飲","捉住小蟹直接吸收營養","把樹葉染成紅色吸引昆蟲"],answer:0,explanation:"呼吸根幫紅樹植物在缺氧泥土中進行氣體交換。泥灘上嗰堆「迷你天線」唔係收訊，係樹木嘅呼吸後勤。",hint:"留意泥土缺氧與根的氣體交換。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"香港植物資料庫・海欖雌",url:"https://www.hkcww.org/hkplant/readid.php?id=1356"},review:"2026-11-26按列明來源核對；用語按情境解釋，年份限定事件，不以信仰或傳說作效果保證。"},{id:"f22",tier:2,category:"生態・大螯招牌",question:"濕地裡一大螯一小螯的弧邊管招潮蟹，通常是哪一性別？",options:["雌蟹","雄蟹","兩者成年後都必定有大螯","只有剛出生幼蟹有大螯"],answer:1,explanation:"雄性弧邊管招潮蟹有一大螯，用來示意、護領土及吸引異性；小螯負責取食。大螯似巨型名片，唔係免費升級餐具。",hint:"分清求偶展示的大螯和日常進食的小螯。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"香港濕地公園・弧邊管招潮蟹",url:"https://www.wetlandpark.gov.hk/tc/biodiversity/beauty-of-wetlands/wildlife/tubuca-arcuata"},review:"2026-11-26按列明來源核對；用語按情境解釋，年份限定事件，不以信仰或傳說作效果保證。"},{id:"f23",tier:2,category:"生態・黃昏飛客",question:"香港常見的蝙蝠能飛，但在動物分類上屬於甚麼？",options:["鳥類","爬蟲類","哺乳類","昆蟲類"],answer:2,explanation:"蝙蝠是哺乳動物，部分本地種類吃昆蟲，果蝠也可幫植物傳粉及播種。有翼唔等於雀，正如有公事包唔一定係老闆。",hint:"分類看身體與繁殖特徵，不只看能否飛行。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"漁護署・香港哺乳動物",url:"https://www.afcd.gov.hk/tc_chi/conservation/hkbiodiversity/speciesgroup/speciesgroup_mammals.html"},review:"2026-11-26按列明來源核對；用語按情境解釋，年份限定事件，不以信仰或傳說作效果保證。"},{id:"f24",tier:2,category:"生態・海豚BB",question:"中華白海豚剛出生時，身體通常是甚麼顏色？",options:["純白色","鮮粉紅色","橙黃色","深灰色"],answer:3,explanation:"初生中華白海豚呈深灰色，隨成長逐漸變淡。唔係海水未沖乾淨，而係海豚BB自己嘅成長配色。",hint:"不要把成年常見體色套到新生幼豚。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"漁護署・中華白海豚生活史",url:"https://www.afcd.gov.hk/tc_chi/conservation/con_mar/con_mar_chi/con_mar_chi_chi/con_mar_chi_chi_life.html"},review:"2026-11-26按列明來源核對；用語按情境解釋，年份限定事件，不以信仰或傳說作效果保證。"},{id:"f25",tier:2,category:"生態・穿山甲盔甲",question:"香港有紀錄的穿山甲，其鱗片主要由甚麼物質組成？",options:["角蛋白","碳酸鈣","幾丁質","二氧化矽"],answer:0,explanation:"鱗片主要是角蛋白，和人的指甲同類，並非神奇藥材；穿山甲是受保護野生動物。穿得似盔甲，唔代表想接角色扮演工作。",hint:"想想人的指甲與毛髮的主要蛋白。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"香港生物多樣性資訊站・穿山甲",url:"https://bih.gov.hk/tc/fast-facts/iconic-species/index-id-15.html"},review:"2026-11-26按列明來源核對；用語按情境解釋，年份限定事件，不以信仰或傳說作效果保證。"},{id:"f26",tier:2,category:"水務・第一個水塘",question:"回看香港供水史，1863年落成的首個水塘是哪個？",options:["黃泥涌水塘","薄扶林水塘","城門水塘","香港仔上水塘"],answer:1,explanation:"首個薄扶林水塘於1863年落成，其後另有上游擴建。佢係供水元老，唔係見到山谷有水就自動當選。",hint:"先分清首個水塘與後來的大型工程。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"水務署・水務里程",url:"https://www.wsd.gov.hk/tc/about-us/our-milestone/index.html"},review:"2026-11-26按列明來源核對；用語按情境解釋，年份限定事件，不以信仰或傳說作效果保證。"},{id:"f27",tier:2,category:"水務・名字背後",question:"城門水塘的「銀禧水塘」稱呼，主要紀念哪位英王登基二十五周年？",options:["愛德華七世","喬治六世","喬治五世","威廉四世"],answer:2,explanation:"「銀禧」稱呼紀念喬治五世登基二十五周年。行水塘可以唔背王室族譜，但今題四位都唔係隔籬村村長。",hint:"留意1930年代的銀禧紀念背景。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"水務署・城門水塘",url:"https://www.wsd.gov.hk/tc/customer-services/other-customer-services/fishing-in-reservoirs/brief-introduction-of-reservoirs/shing-mun-reservoir/index.html"},review:"2026-11-26按列明來源核對；用語按情境解釋，年份限定事件，不以信仰或傳說作效果保證。"},{id:"f28",tier:2,category:"社區・三院由來",question:"東華三院名稱中的「三院」，原來是哪三所醫院？",options:["東華醫院、廣華醫院、瑪麗醫院","廣華醫院、東華東院、伊利沙伯醫院","東華醫院、瑪麗醫院、基督教聯合醫院","東華醫院、廣華醫院、東華東院"],answer:3,explanation:"名稱源自東華醫院、廣華醫院及東華東院的聯合管理歷史，機構今天服務遠不止三院。個名係歷史，唔係即時分店數字。",hint:"三間都屬東華歷史體系，別被其他醫院混入。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"東華三院・機構簡介",url:"https://www.tungwah.org.hk/about/milestones/"},review:"2026-11-26按列明來源核對；用語按情境解釋，年份限定事件，不以信仰或傳說作效果保證。"},{id:"f29",tier:2,category:"流行文化・功夫名片",question:"翻看李小龍的生平展覽，他的原名是甚麼？",options:["李鎮藩","李小麟","李翰祥","李兆基"],answer:0,explanation:"李小龍原名李鎮藩，以Bruce Lee之名蜚聲國際。答名唔使出寸拳，坐穩張凳睇清楚已經夠有功夫。",hint:"原名不是後來的藝名。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"香港文化博物館・李小龍",url:"https://www.heritagemuseum.gov.hk/tc/exhibitions/bruce_lee.html"},review:"2026-11-26按列明來源核對；用語按情境解釋，年份限定事件，不以信仰或傳說作效果保證。"},{id:"f30",tier:2,category:"流行文化・武俠書架",question:"書架滿是金庸小說，這位作家的本名是甚麼？",options:["倪匡","查良鏞","梁羽生","黃霑"],answer:1,explanation:"金庸是查良鏞的筆名，作品深深影響香港流行文化。認到本名唔會即刻學識輕功，但搵資料至少唔會走錯門派。",hint:"分清筆名與本名，另外幾個名字也是文化人物。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"香港記憶・金庸特藏",url:"https://www.hkmemory.hk/tc/collections-jinyong-about.html"},review:"2026-11-26按列明來源核對；用語按情境解釋，年份限定事件，不以信仰或傳說作效果保證。"},{id:"f31",tier:2,category:"古蹟・藝術中心前身",question:"香港視覺藝術中心所在的卡素樓，前身是哪類建築？",options:["舊域多利監獄的囚室","舊大會堂的音樂教室","舊域多利軍營的已婚英軍宿舍","舊海軍船塢的機房"],answer:2,explanation:"卡素樓原為軍營已婚英軍宿舍，後改作藝術中心。由安頓家庭到安頓創意，間屋轉行比我哋仲成功。",hint:"它屬昔日域多利軍營的建築群。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"康文署・香港公園古蹟",url:"https://hkp.lcsd.gov.hk/tc/facilities/heritage"},review:"2026-11-26按列明來源核對；用語按情境解釋，年份限定事件，不以信仰或傳說作效果保證。"},{id:"f32",tier:2,category:"古蹟・搬過家的樓",question:"赤柱的美利樓，其建築構件原先在哪個地區拆卸保存？",options:["北角","油麻地","深水埗","中環"],answer:3,explanation:"美利樓原在中環，後拆卸保存構件並於赤柱重建。搬屋通常搬傢俬，佢連成幢樓嘅石材都要點算。",hint:"看舊軍營與中環發展的歷史。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"旅發局・美利樓",url:"https://www.discoverhongkong.com/tc/place-to-go/travel.guide-murray-house.html"},review:"2026-11-26按列明來源核對；用語按情境解釋，年份限定事件，不以信仰或傳說作效果保證。"},{id:"f33",tier:2,category:"場館・星空不是直播",question:"香港太空館天象廳把星空投到穹頂，主要是哪種展示方式？",options:["以天象投影及影像模擬星空","打開屋頂讓日光直接入場","只靠窗外當晚肉眼所見","把真正星體縮小移進場內"],answer:0,explanation:"天象廳以投影等設備模擬星空與宇宙景象，不受當晚雲量直接限制。買飛入場唔使幫月亮預留鄰座。",hint:"想想室內穹頂與投影設備。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"香港太空館・天象廳",url:"https://hk.space.museum/tc/web/spm/facilities/space-theatre.html"},review:"2026-11-26按列明來源核對；用語按情境解釋，年份限定事件，不以信仰或傳說作效果保證。"},{id:"f34",tier:2,category:"城中・不同信仰的街景",question:"香港九龍清真寺暨伊斯蘭中心，位於哪個地區？",options:["上環","尖沙咀","觀塘","灣仔"],answer:1,explanation:"九龍清真寺暨伊斯蘭中心位於尖沙咀彌敦道，見證香港多元宗教生活。認建築唔靠衝入去打卡，先尊重現場安排。",hint:"留意彌敦道與九龍公園一帶。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"旅發局・九龍清真寺",url:"https://www.discoverhongkong.com/tc/explore/attractions/kowloon-mosque-and-islamic-centre.html"},review:"2026-11-26按列明來源核對；用語按情境解釋，年份限定事件，不以信仰或傳說作效果保證。"},{id:"f35",tier:2,category:"古蹟・石階街燈",question:"中環著名的石階及四支煤氣路燈，位於哪條街？",options:["雪廠街","砵典乍街","都爹利街","威靈頓街"],answer:2,explanation:"都爹利街石階及煤氣路燈是法定古蹟。石板街亦有石階感，但地址唔可以憑「都差唔多有級」就亂填。",hint:"把石板街與煤氣燈石階分開辨認。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"古蹟辦・都爹利街",url:"https://www.amo.gov.hk/tc/historic-buildings/monuments/hong-kong-island/monuments_08/index.html"},review:"2026-11-26按列明來源核對；用語按情境解釋，年份限定事件，不以信仰或傳說作效果保證。"},{id:"f36",tier:2,category:"廟宇・黃大仙的名字",question:"黃大仙信仰中的人物，通常被稱為哪個名字？",options:["呂洞賓","張三丰","葛洪","黃初平"],answer:3,explanation:"黃大仙通常指黃初平；這是宗教文化辨識，不是保證願望實現。認啱名字就得，唔好順便幫神明承諾包過關。",hint:"留意嗇色園對黃大仙生平的介紹。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"嗇色園・黃大仙信仰",url:"https://www2.siksikyuen.org.hk/zh-HK/cultural-affairs/wong-tai-sin-belief"},review:"2026-11-26按列明來源核對；用語按情境解釋，年份限定事件，不以信仰或傳說作效果保證。"},{id:"f37",tier:2,category:"非遺・粵劇後台",question:"粵劇的「生、旦、淨、丑」，主要在分類甚麼？",options:["角色行當","鑼鼓敲擊節奏","戲服布料種類","舞台燈光顏色"],answer:0,explanation:"生、旦、淨、丑是角色行當分類，並非演員本人性格測試。台上演奸角，落台都可能會幫你扶門。",hint:"不要與唱、唸、做、打的表演功架混淆。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"教大戲曲與非遺傳承中心・行當",url:"https://xich.eduhk.hk/zht/page/detail/1275"},review:"2026-11-26按列明來源核對；用語按情境解釋，年份限定事件，不以信仰或傳說作效果保證。"},{id:"f38",tier:2,category:"銀包・十元仔",question:"現行香港十元硬幣的雙色設計，一般是哪個配搭？",options:["金黃色外圈、銀色圓心","銀色外圈、金黃色圓心","整枚銀色、藍色圓心","整枚金黃、紅色外圈"],answer:1,explanation:"十元硬幣採雙金屬結構，外圈銀色、圓心金黃色。望清配色先好答，唔好把朱古力金幣當埋法定貨幣。",hint:"把外圈與圓心的顏色次序看清。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"金管局・流通硬幣",url:"https://www.hkma.gov.hk/media/eng/doc/key-functions/monetary-stability/notes-and-coins/coins_accepted.pdf"},review:"2026-11-26按列明來源核對；用語按情境解釋，年份限定事件，不以信仰或傳說作效果保證。"},{id:"f39",tier:2,category:"天氣・風眼不是散場",question:"風暴眼接近令風勢短暫減弱，哪個判斷最恰當？",options:["風已停便可忽略警告信號","只要冇雨便代表風暴已遠離","危險可能迅速再來，繼續留在安全地方","見到天空較亮便可去海邊追風"],answer:2,explanation:"風眼可帶來短暫平靜，之後風向與強風可能急變；應持續留意官方資訊。呢段唔係散場字幕，係可能仲有下半場。",hint:"短暫平靜不等於警告已解除。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"天文台・熱帶氣旋警告",url:"https://www.hko.gov.hk/tc/informtc/precaution.htm"},review:"2026-11-26按列明來源核對；用語按情境解釋，年份限定事件，不以信仰或傳說作效果保證。"},{id:"f40",tier:2,category:"時間・午夜前一題",question:"香港標準時間相對協調世界時UTC，通常是哪個時差？",options:["UTC+7小時","UTC+9小時","UTC+10小時","UTC+8小時"],answer:3,explanation:"香港標準時間為UTC+8。遊戲每日更新跟香港午夜，唔會因為你個心仲留喺昨晚就額外延長。",hint:"確認東八區，不要按其他城市時間猜。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"天文台・本地時間",url:"https://www.hko.gov.hk/tc/gts/time/basicterms-localtime.htm"},review:"2026-11-26按列明來源核對；用語按情境解釋，年份限定事件，不以信仰或傳說作效果保證。"},{id:"f41",tier:3,category:"郵政史・第一套郵票",question:"香港第一套郵票正式發行於哪一年？",options:["1862年","1841年","1865年","1891年"],answer:0,explanation:"香港首套郵票於1862年12月8日發行；1841是本地郵政早期歷史的另一年份。貼郵票唔使考古，但今題要分清年代。",hint:"郵政機構成立與首套郵票發行不是同一事件。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"香港記憶・首套香港郵票",url:"https://www.hkmemory.hk/tc/collections-stamps-evolution_of_design-first_set_stamps_subsequent_denominations.html"},review:"2026-11-26按列明來源核對；用語按情境解釋，年份限定事件，不以信仰或傳說作效果保證。"},{id:"f42",tier:3,category:"天氣史・風球數字",question:"香港首次採用數字熱帶氣旋警告信號，是哪一年？",options:["1884年","1917年","1931年","1973年"],answer:1,explanation:"1917年首次採用數字信號；1884是鼓、球、錐形信號時期，1931及1973另有改制。幾個年份都似熟客，唔好俾佢哋打尖入答案。",hint:"題目問首次數字系統，而非後來八號信號改制。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"天文台・信號歷史",url:"https://www.hko.gov.hk/tc/informtc/tcsignal_history.htm"},review:"2026-11-26按列明來源核對；用語按情境解釋，年份限定事件，不以信仰或傳說作效果保證。"},{id:"f43",tier:3,category:"天氣史・觀測台起步",question:"香港天文台在哪一年成立？",options:["1874年","1884年","1883年","1912年"],answer:2,explanation:"天文台於1883年成立；1884開始有系統的氣象觀測，1912獲皇家名銜。成立、開工、改名三個日子，唔好一張請帖寫晒。",hint:"分清成立與翌年觀測服務的時間。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"天文台・歷史",url:"https://www.hko.gov.hk/tc/abouthko/history.htm"},review:"2026-11-26按列明來源核對；用語按情境解釋，年份限定事件，不以信仰或傳說作效果保證。"},{id:"f44",tier:3,category:"閱讀史・大會堂書香",question:"現代香港公共圖書館系統首間大會堂圖書館，在哪一年啟用？",options:["1957年","1965年","1971年","1962年"],answer:3,explanation:"大會堂圖書館於1962年啟用，是現代公營公共圖書館發展的重要起點；不把更早舊大會堂大書樓混在同一事件。借書可以續期，成立年份唔可以。",hint:"看清現代公營系統，不是所有早期閱覽場所。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"政府新聞公報・公共圖書館歷史",url:"https://www.info.gov.hk/gia/general/200001/31/0131170.htm"},review:"2026-11-26按列明來源核對；用語按情境解釋，年份限定事件，不以信仰或傳說作效果保證。"},{id:"f45",tier:3,category:"場館史・海旁開幕",question:"香港文化中心的正式開幕年份是哪一年？",options:["1989年","1977年","1983年","1991年"],answer:0,explanation:"香港文化中心於1989年11月開幕。尖沙咀海旁見證過無數合照，但相機日期唔一定幫你記得場館生日。",hint:"不要與藝術節首辦或其他公園開幕年份混淆。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"政府新聞公報・文化中心二十周年",url:"https://www.info.gov.hk/gia/general/200911/08/P200911080182.htm"},review:"2026-11-26按列明來源核對；用語按情境解釋，年份限定事件，不以信仰或傳說作效果保證。"},{id:"f46",tier:3,category:"體育史・倫敦銅牌",question:"李慧詩在2012倫敦奧運奪得銅牌的項目是哪一個？",options:["女子爭先賽","女子凱林賽","女子全能賽","女子個人追逐賽"],answer:1,explanation:"2012倫敦奧運的銅牌來自女子凱林賽；東京2020奧運的銅牌則是爭先賽。兩段都踩得快，答案都要慢半拍睇清年份。",hint:"分清倫敦與東京兩屆的項目。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"香港體院・2012傑出運動員回顧",url:"https://www.hksi.org.hk/f/publication/519/se_issue17.pdf"},review:"2026-11-26按列明來源核對；用語按情境解釋，年份限定事件，不以信仰或傳說作效果保證。"},{id:"f47",tier:3,category:"體育史・世界冠軍",question:"黃金寶在2007世界場地單車錦標賽奪金的項目是甚麼？",options:["男子個人追逐賽","男子一公里計時賽","男子捕捉賽","男子全能賽"],answer:2,explanation:"黃金寶於2007年贏得男子捕捉賽世界冠軍。名字有金，獎牌亦真係金，但唔可以靠個名當答題證據。",hint:"這是集體出發、先到終點決勝的場地項目。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"香港體院・年度報告",url:"https://hksi.org.hk/f/publication/500/AnnualReport07_08_22.pdf"},review:"2026-11-26按列明來源核對；用語按情境解釋，年份限定事件，不以信仰或傳說作效果保證。"},{id:"f48",tier:3,category:"社區體育・十八區開賽",question:"第一屆全港運動會，在哪一年舉行？",options:["2005年","2009年","2011年","2007年"],answer:3,explanation:"首屆全港運動會於2007年舉行，以地區為參賽單位。地區榮譽可以拚，唔使連樓下邊間魚蛋最好食都一併比賽。",hint:"別與2009香港東亞運動會混淆。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"全港運動會・首屆網站",url:"https://www.hongkonggames.hk/hkg2007/"},review:"2026-11-26按列明來源核對；用語按情境解釋，年份限定事件，不以信仰或傳說作效果保證。"},{id:"f49",tier:3,category:"金融史・四會合一",question:"四家證券交易所停業、聯交所在交易廣場開始運作，是哪一年？",options:["1986年","1980年","1983年","2000年"],answer:0,explanation:"四所於1986年3月停業，聯交所在同年4月2日開始運作；1980是聯交所公司成立的年份，2000另屬港交所整合。開公司同開市，真係兩件事。",hint:"分清公司成立、統一交易與港交所整合。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"港交所・交易大堂大事記",url:"https://www.hkex.com.hk/-/media/HKEX-Market/News/News-Release/2017/171027news/1027_Trading-Hall-Fact-Sheet_CHI.pdf"},review:"2026-11-26按列明來源核對；用語按情境解釋，年份限定事件，不以信仰或傳說作效果保證。"},{id:"f50",tier:3,category:"海岸保育・第一批",question:"海下灣列為香港首批海岸公園之一，是哪一年？",options:["1995年","1996年","1997年","2001年"],answer:1,explanation:"海下灣於1996年7月指定為首批海岸公園之一；東平洲海岸公園則於2001年指定。海底住客冇投票，但保育年份有正式紀錄。",hint:"把首批海岸公園與後來東平洲的年份分開。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"漁護署・海下灣海岸公園",url:"https://www.afcd.gov.hk/tc_chi/country/cou_vis/cou_vis_mar/cou_vis_mar_des/cou_vis_mar_des_hoi.html"},review:"2026-11-26按列明來源核對；用語按情境解釋，年份限定事件，不以信仰或傳說作效果保證。"},{id:"f51",tier:3,category:"郊野保育・法例起點",question:"香港《郊野公園條例》在哪一年制定，為劃定郊野公園建立框架？",options:["1971年","1977年","1976年","1979年"],answer:2,explanation:"條例於1976年制定，隨後才逐步指定郊野公園。法例出場同公園掛牌唔一定同日，唔好一見鄰近年份就拍板。",hint:"分清法例制定與首批公園指定。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"漁護署・郊野公園",url:"https://www.afcd.gov.hk/tc_chi/country/cou_lea/cou_lea.html"},review:"2026-11-26按列明來源核對；用語按情境解釋，年份限定事件，不以信仰或傳說作效果保證。"},{id:"f52",tier:3,category:"地質・獅子山石身",question:"獅子山的主要岩石類型，最接近以下哪一項？",options:["玄武岩","石灰岩","頁岩","花崗岩"],answer:3,explanation:"獅子山主要由花崗岩構成，山形亦與節理、風化及侵蝕有關。佢個樣似獅子，唔代表地質分類要填哺乳類。",hint:"不要把所有香港山岩都當成西貢的火山岩。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"土拓署・香港地質",url:"https://www.cedd.gov.hk/eng/about-us/organisation/geo/pub_info/memoirs/geology/geological-landscapes/index.html"},review:"2026-11-26按列明來源核對；用語按情境解釋，年份限定事件，不以信仰或傳說作效果保證。"},{id:"f53",tier:3,category:"地質・鬼手的手指",question:"黃竹角咀「鬼手岩」的手指狀外形，主要與哪種自然過程有關？",options:["岩層受風化及侵蝕而形成差異輪廓","珊瑚在岸邊長成拳頭形","熔岩剛流出地面便凝成手掌","人手把整塊石雕成巨掌"],answer:0,explanation:"鬼手岩由沉積岩受風化、侵蝕等過程塑造，海浪亦影響底部形態。自然鬼斧神工，唔等於真係有位師傅用雕刻刀收工。",hint:"留意原有岩層與長期風化侵蝕。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"香港地質學會・黃竹角咀",url:"https://www.rocks.org.hk/images/Knowledge/2009-06-13-mingpao-port-island20131023101547.pdf"},review:"2026-11-26按列明來源核對；用語按情境解釋，年份限定事件，不以信仰或傳說作效果保證。"},{id:"f54",tier:3,category:"地質・不能食的菠蘿包",question:"橋咀洲著名「菠蘿包石」的岩石，主要是哪一種？",options:["流紋岩","石英二長岩","砂岩","玄武岩"],answer:1,explanation:"橋咀洲的菠蘿包石主要是石英二長岩巨礫，裂紋經風化侵蝕而顯著。唔加牛油，唔可以外賣，亦唔好敲走一嚿留念。",hint:"它是侵入岩，別只憑六角岩柱印象選火山岩。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"香港地質公園・菠蘿包的一生",url:"https://geopark.gov.hk/tc/education/science_popularisation/life-pineapple-bun"},review:"2026-11-26按列明來源核對；用語按情境解釋，年份限定事件，不以信仰或傳說作效果保證。"},{id:"f55",tier:3,category:"農業史・山坡新生",question:"白牛石的嘉道理農場基地，最初於哪一年建立？",options:["1949年","1961年","1956年","1971年"],answer:2,explanation:"白牛石農場基地於1956年建立，用於農業援助、培訓等；後來逐步轉向保育及教育。前身唔只係一個好靚嘅郊遊背景板。",hint:"題目指白牛石基地，不是後來機構轉型的年份。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"嘉道理農場・機構歷史",url:"https://www.kfbg.org/images/download/WildlifePondManualEd1.pdf"},review:"2026-11-26按列明來源核對；用語按情境解釋，年份限定事件，不以信仰或傳說作效果保證。"},{id:"f56",tier:3,category:"工業史・礦山收工",question:"馬鞍山鐵礦的採礦業務，在哪一年停止？",options:["1967年","1972年","1983年","1976年"],answer:3,explanation:"馬鞍山鐵礦在1976年停止採礦，礦業歷史成為社區記憶。山名有馬，山裡有礦，唔代表當年係用馬蹄掘出嚟。",hint:"看清停止採礦，不是最初開採的年份。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"土拓署・香港礦產與礦業",url:"https://hkss.cedd.gov.hk/hkss/tc/publications-and-resources/educational-materials/hong-kong-geology/chapter-8/index.html"},review:"2026-11-26按列明來源核對；用語按情境解釋，年份限定事件，不以信仰或傳說作效果保證。"},{id:"f57",tier:3,category:"交通史・斜路元老",question:"山頂纜車首次投入載客服務，是哪一年？",options:["1888年","1873年","1904年","1910年"],answer:0,explanation:"山頂纜車於1888年開始服務，之後多次更新車廂及系統。纜車有換代，開業年份就唔會跟住每次翻新重新計。",hint:"把山頂纜車與電車、九鐵的啟用年份分開。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"山頂纜車・歷史",url:"https://www.thepeak.com.hk/zh-hant/heritage/history-of-the-peak-tram"},review:"2026-11-26按列明來源核對；用語按情境解釋，年份限定事件，不以信仰或傳說作效果保證。"},{id:"f58",tier:3,category:"電影史・影迷筆記",question:"第一屆香港國際電影節，在哪一年舉辦？",options:["1973年","1977年","1982年","1986年"],answer:1,explanation:"首屆香港國際電影節於1977年舉行，香港大會堂亦是早期重要場地。影迷可以一日睇幾場，歷史題仍然只收一個答案。",hint:"不要與第一屆香港藝術節的1973年混淆。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"康文署・香港大會堂歷史",url:"https://www.lcsd.gov.hk/tc/hkch/aboutus/introduction.html"},review:"2026-11-26按列明來源核對；用語按情境解釋，年份限定事件，不以信仰或傳說作效果保證。"},{id:"f59",tier:3,category:"古蹟・大宅舊名字",question:"司徒拔道景賢里最初名為甚麼？",options:["甘棠第","梅夫人婦女會","禧廬","虎豹別墅"],answer:2,explanation:"景賢里原稱禧廬，約建於1937年；不是甘棠第或虎豹別墅。香港大宅改過名，記錯唔會有人幫你重新派門匙。",hint:"留意這座司徒拔道大宅的早期名稱。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"發展局・景賢里資料冊",url:"https://www.heritage.gov.hk/filemanager/heritage/tc/content_225/KYL_Resource_Kit_Chi.pdf"},review:"2026-11-26按列明來源核對；用語按情境解釋，年份限定事件，不以信仰或傳說作效果保證。"},{id:"f60",tier:3,category:"供水史・東江入港",question:"東江水正式開始供應香港，是哪一年？",options:["1960年","1963年","1968年","1965年"],answer:3,explanation:"東江水於1965年3月1日正式供港；1963年的嚴重旱災則是相關工程的重要背景。擰開水龍頭好快，背後工程唔係一晚煲出嚟。",hint:"分清旱災發生與正式供水的年份。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"水務署・東江供水歷史",url:"https://www.wsd.gov.hk/filemanager/common/annual_report/2023_24/vendor/flipbook/39/"},review:"2026-11-26按列明來源核對；用語按情境解釋，年份限定事件，不以信仰或傳說作效果保證。"}].map(t=>Object.freeze({...t,options:Object.freeze(t.options),source:Object.freeze(t.source),focus:Object.freeze(t.focus),modes:Object.freeze(t.modes)})));var X=Object.freeze([{id:"v01",tier:2,category:"飲食・茶樓調味",question:"豉汁排骨的豆豉，屬於哪類豆製食品？",options:["經發酵的豆製調味料","剛採收的鮮豆莢","把豆磨成的生粉","糖漬成甜餡的豆沙"],answer:0,explanation:"豆豉是經發酵加工的豆製品，常見黑豆豉用來調味。豉汁好惹味，但唔係排骨自己返去醬園進修。",hint:"看清「豉」與發酵調味的關係。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"食安中心・食品分類",url:"https://www.cfs.gov.hk/tc_chi/public/public_fifdrs/files/FEHB245.pdf"},review:"2026-11-26按列明來源核對；歷史年份限定事件，用語限定情境，不以傳說或信仰作效果保證。"},{id:"v02",tier:1,category:"飲食・茶記炒飯",question:"港式西炒飯常見的酸甜紅色調味，主要來自哪款醬汁？",options:["蠔油","茄汁","黑椒汁","白汁"],answer:1,explanation:"常見西炒飯用茄汁炒出酸甜味，配料可因店家改變。叫西炒飯唔代表要向西面坐低，認醬汁比較實際。",hint:"想想它常見的紅色和番茄味。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"SHARP香港・西炒飯食譜",url:"https://www.sharp-home.com.hk/upload/resource/resource_DQdmw_1742956300.pdf"},review:"2026-11-26按列明來源核對；歷史年份限定事件，用語限定情境，不以傳說或信仰作效果保證。"},{id:"v03",tier:1,category:"飲食・懷舊甜食",question:"用蛋、油和麵粉製成鬆泡炸食，外面沾上白砂糖，最接近哪款舊式甜點？",options:["笑口棗","牛耳仔","沙翁","糖環"],answer:2,explanation:"沙翁是蛋與麵粉等製成的油炸甜食，外面常撒砂糖。食完個嘴角有糖，唔使急住話係落雪。",hint:"不是芝麻包裹的球，也不是有耳形紋的薄片。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"粵典・沙翁",url:"https://words.hk/zidin/%E6%B2%99%E7%BF%81"},review:"2026-11-26按列明來源核對；歷史年份限定事件，用語限定情境，不以傳說或信仰作效果保證。"},{id:"v04",tier:1,category:"飲食・陳皮香氣",question:"香港湯水及糖水常用的陳皮，主要是哪部分植物材料乾燥而成？",options:["柑橘類的果核","柑橘類的樹根","柑橘類的花瓣","柑橘類的成熟果皮"],answer:3,explanation:"陳皮源自橘及栽培變種的乾燥成熟果皮。本題只談食材身分，不是問飲幾碗湯就能醫好甚麼；果皮也有自己的第二職涯。",hint:"香氣來自果皮，不是把整棵樹曬乾。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"香港浸會大學・陳皮資料",url:"https://sys01.lib.hkbu.edu.hk/cmed/mmid/detail.php?pid=B00162"},review:"2026-11-26按列明來源核對；歷史年份限定事件，用語限定情境，不以傳說或信仰作效果保證。"},{id:"v05",tier:2,category:"用語・飲宴文化",question:"街坊說「今晚食九大簋」，通常是在形容怎樣的一餐？",options:["菜式豐盛的筵席","只吃九粒點心的早餐","每人九口飯的便餐","必須九個人分一碗粥"],answer:0,explanation:"九大簋常用來形容豐盛的筵席，不表示所有地方都用同一套九道菜。未坐低已經覺得條褲帶有壓力。",hint:"這是飲宴語境中的豐盛說法，不是精確的進食配額。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"粵典・九大簋",url:"https://words.hk/zidin/%E4%B9%9D%E5%A4%A7%E7%B0%8B"},review:"2026-11-26按列明來源核對；歷史年份限定事件，用語限定情境，不以傳說或信仰作效果保證。"},{id:"v06",tier:1,category:"飲食・涼果工藝",question:"香港涼果店常見的話梅、陳皮梅等，主要屬於哪一類食品？",options:["即摘即食的鮮果","經醃漬、乾製等加工的果品","現榨後立即飲用的果汁","未經處理的果核"],answer:1,explanation:"涼果是果品經糖漬、鹽漬或乾製等工序加工，實際製法依產品而異。名字有個「涼」，唔代表每粒都要插住溫度計。",hint:"想想保存、調味和乾製，而不是只看冷熱。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"非遺辦事處・飲食文化",url:"https://www.icho.hk/documents/Education/exhibition_panels/Exhibition_panel_food_culture.pdf"},review:"2026-11-26按列明來源核對；歷史年份限定事件，用語限定情境，不以傳說或信仰作效果保證。"},{id:"v07",tier:2,category:"非遺・吹糖",question:"傳統吹糖工藝常用哪類材料製成可塑的糖膠？",options:["生米粉加清水","鹽與石灰粉","麥芽糖或粟膠","芝麻油加豉油"],answer:2,explanation:"吹糖技藝利用糖膠塑造小動物等造型，糖的可塑性是關鍵。糖都可以有立體造型，唔只識黐住張糖紙。",hint:"重點在能塑形的糖料，而不是麵糰。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"非遺辦事處・香港非遺清單",url:"https://www.icho.hk/documents/Intangible-Cultural-Heritage-Inventory/2024/ich_inventory_2024_cn.pdf"},review:"2026-11-26按列明來源核對；歷史年份限定事件，用語限定情境，不以傳說或信仰作效果保證。"},{id:"v08",tier:2,category:"非遺・龍鬚糖",question:"龍鬚糖外層一絲絲的糖鬚，傳統上主要怎樣形成？",options:["把糖料逐條用剪刀剪成線","把砂糖直接放入冰水凍成線","把糖霜撒上成品便自然長成絲","把糖料反覆拉伸及摺疊成細絲"],answer:3,explanation:"龍鬚糖以拉製糖絲的手藝形成細緻外層，工序需要控制質地。不是養一條龍等佢剃鬚，師傅雙手先係主角。",hint:"想想拉糖手藝，與單純撒糖粉有何不同。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"非遺辦事處・師傅到2024",url:"https://www.icho.hk/tc/web/icho/2024_meet_the_masters.html"},review:"2026-11-26按列明來源核對；歷史年份限定事件，用語限定情境，不以傳說或信仰作效果保證。"},{id:"v09",tier:2,category:"非遺・客家茶粿",question:"常見客家茶粿的外皮，主要以哪一類粉料製作？",options:["米粉或糯米粉類","麥皮粉","咖啡粉","芝麻粉"],answer:0,explanation:"茶粿是客家飲食中的傳統點心，常以米粉類作外皮，甜鹹餡與配方各異。有茶字，唔等於每件都要加一匙茶葉。",hint:"留意它與米製點心的關係，別把名稱當成配方。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"非遺辦事處・飲食文化",url:"https://www.icho.hk/documents/Education/exhibition_panels/Exhibition_panel_food_culture.pdf"},review:"2026-11-26按列明來源核對；歷史年份限定事件，用語限定情境，不以傳說或信仰作效果保證。"},{id:"v10",tier:3,category:"飲食・海味辨識",question:"傳統海味所說的魚肚、花膠，主要是哪個魚類器官的乾製品？",options:["魚胃","魚鰾","魚肝","魚肺"],answer:1,explanation:"魚肚或花膠通常指經加工乾製的魚鰾，不是魚胃。本題辨認材料，不把坊間保健說法當成效果保證；個名確實好考人。",hint:"它原本與魚在水中的浮沉調節有關。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"香港非遺資料庫・清單",url:"https://www.hkichdb.gov.hk/download/6b614fd1-b768-47f2-909d-d2fab9b764dd"},review:"2026-11-26按列明來源核對；歷史年份限定事件，用語限定情境，不以傳說或信仰作效果保證。"},{id:"v11",tier:1,category:"地區・金魚街",question:"旺角俗稱「金魚街」的路段，主要是哪條街的北段？",options:["花園街","上海街","通菜街","廣東道"],answer:2,explanation:"金魚街位於通菜街北段，以觀賞魚及水族用品店聞名。通菜街不只賣通菜，認街名唔可以完全靠字面買餸。",hint:"不要與稱為波鞋街的花園街混淆。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"香港旅發局・金魚街",url:"https://www.discoverhongkong.com/tc/place-to-go/travel.guide-goldfish-market.html"},review:"2026-11-26按列明來源核對；歷史年份限定事件，用語限定情境，不以傳說或信仰作效果保證。"},{id:"v12",tier:1,category:"地區・花墟",question:"旺角花墟最具代表性的零售商品是哪一類？",options:["皮鞋及鞋帶","鐘錶及手袋","海味及乾貨","鮮花及園藝植物"],answer:3,explanation:"花墟聚集鮮花與園藝店，節慶時尤其熱鬧。去買一盆植物，最後可能要順便買多個位置畀佢曬太陽。",hint:"名稱與店舖的主要商品直接相關。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"香港旅發局・購物樂趣",url:"https://www.discoverhongkong.com/tc/shopping.html"},review:"2026-11-26按列明來源核對；歷史年份限定事件，用語限定情境，不以傳說或信仰作效果保證。"},{id:"v13",tier:2,category:"地區・雀鳥花園",question:"香港著名的雀鳥花園位於哪條街？",options:["園圃街","鴨寮街","利東街","砵典乍街"],answer:0,explanation:"園圃街雀鳥花園與賞雀文化及相關店舖相連。去之前先對清地址，唔好把園圃街當成另一個花墟入口。",hint:"它就在太子、花墟一帶的街區。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"港鐵・太子站街道圖",url:"https://www.mtr.com.hk/archive/en/services/maps/pre.pdf"},review:"2026-11-26按列明來源核對；歷史年份限定事件，用語限定情境，不以傳說或信仰作效果保證。"},{id:"v14",tier:2,category:"地區・喜帖街",question:"昔日因印刷喜帖而聞名的灣仔「喜帖街」，是哪條街？",options:["春園街","利東街","汕頭街","船街"],answer:1,explanation:"利東街曾以印刷業及喜帖店聞名，後來經歷重建。呢題問街道歷史，唔係暗示你今晚一定要派帖。",hint:"不要與上環的文具印刷街區混淆。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"香港旅發局・利東街",url:"https://www.discoverhongkong.com/tc/place-to-go/travel.guide-lee-tung-avenue.html"},review:"2026-11-26按列明來源核對；歷史年份限定事件，用語限定情境，不以傳說或信仰作效果保證。"},{id:"v15",tier:2,category:"地區・石板街",question:"中環俗稱「石板街」、以階梯石面聞名的街道是哪條？",options:["荷李活道","德輔道中","砵典乍街","干諾道中"],answer:2,explanation:"砵典乍街的石階是中環的熟悉街景。斜路行得多可以練腳力，記街名就要練另一種肌肉。",hint:"留意它的階梯路面，不是平坦的主要行車道。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"香港旅發局・中環街坊滋味",url:"https://www.discoverhongkong.com/tc/neighbourhoods/old-town-central/neighbourhood-taste.html"},review:"2026-11-26按列明來源核對；歷史年份限定事件，用語限定情境，不以傳說或信仰作效果保證。"},{id:"v16",tier:2,category:"地區・古玩街",question:"上環摩羅上街最廣為遊人熟悉的店舖及攤檔，主要售賣哪類物品？",options:["新鮮魚肉","大型建築鋼材","汽車輪胎","古玩、二手收藏及紀念品"],answer:3,explanation:"摩羅上街以古玩與收藏品店攤聞名。睇中一件「懷舊物」，記得懷舊與真偽鑑定是兩回事。",hint:"是尋寶式逛街，不是日常買餸的街市。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"香港旅發局・摩羅上街",url:"https://www.discoverhongkong.com/tc/place-to-go/travel.guide-upper-lascar-row.html"},review:"2026-11-26按列明來源核對；歷史年份限定事件，用語限定情境，不以傳說或信仰作效果保證。"},{id:"v17",tier:1,category:"地區・赤柱市集",question:"赤柱市集位於香港島哪一個行政區？",options:["南區","東區","灣仔區","中西區"],answer:0,explanation:"赤柱市集位於港島南區，是海邊旅遊街區的一部分。講到港島，唔好自動以為所有海景都在中環附近。",hint:"它在赤柱，不在維港北岸一帶。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"香港旅發局・赤柱市集",url:"https://www.discoverhongkong.com/tc/place-to-go/travel.guide-stanley-market.html"},review:"2026-11-26按列明來源核對；歷史年份限定事件，用語限定情境，不以傳說或信仰作效果保證。"},{id:"v18",tier:3,category:"古蹟・牛棚藝術村",question:"土瓜灣「牛棚」藝術村的歷史建築，前身主要是哪項設施？",options:["馬頭角電車廠","馬頭角牲畜檢疫站","啟德水上飛機站","九龍海軍糧倉"],answer:1,explanation:"牛棚原為前馬頭角牲畜檢疫站，後來活化作藝術用途。以前照顧牲口，今天照顧創作，地方一樣可以有第二人生。",hint:"「牛棚」的俗稱保留了昔日用途的線索。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"康文署・牛棚藝術公園",url:"https://www.lcsd.gov.hk/tc/parks/cdap/index.html"},review:"2026-11-26按列明來源核對；歷史年份限定事件，用語限定情境，不以傳說或信仰作效果保證。"},{id:"v19",tier:3,category:"文化・JCCAC",question:"石硤尾工廠大廈活化為賽馬會創意藝術中心（JCCAC），在哪一年開幕？",options:["1998年","2003年","2008年","2013年"],answer:2,explanation:"JCCAC於2008年以藝術中心面貌登場，原址曾容納本地工業作業。由山寨廠到藝術工作室，樓裏照樣有人認真趕工。",hint:"在2000年代末，早於元創方的活化開幕。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"香港旅發局・深水埗自助遊",url:"https://partnernet.hktb.com/filemanager/collateral/1022/tc/Sham%20Shui%20Po%20Self-guided%20Walks_TC.PDF"},review:"2026-11-26按列明來源核對；歷史年份限定事件，用語限定情境，不以傳說或信仰作效果保證。"},{id:"v20",tier:2,category:"地區・蓬瀛仙館",question:"蓬瀛仙館位於哪個新界地區？",options:["屯門","荃灣","西貢","粉嶺"],answer:3,explanation:"蓬瀛仙館位於粉嶺，是本地道教文化地標之一。認地方靠地址，唔係見到「仙」字就把路線交畀雲層導航。",hint:"它近粉嶺站一帶，別與屯門的青松觀混淆。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"蓬瀛仙館・官方資料",url:"https://www.fysk.org/"},review:"2026-11-26按列明來源核對；歷史年份限定事件，用語限定情境，不以傳說或信仰作效果保證。"},{id:"v21",tier:1,category:"文化・太空館",question:"在尖沙咀看到熟悉的蛋形外殼，最令人想到哪間博物館？",options:["香港太空館","香港文化博物館","香港科學館","香港鐵路博物館"],answer:0,explanation:"香港太空館的蛋形外殼是尖沙咀地標。這隻「蛋」不是用來整蛋撻，裏面裝住的是天文與太空故事。",hint:"它有天象廳，不是把所有科學展覽都放在同一館。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"香港旅發局・香港太空館",url:"https://www.discoverhongkong.com/tc/place-to-go/travel.guide-hong-kong-space-museum.html"},review:"2026-11-26按列明來源核對；歷史年份限定事件，用語限定情境，不以傳說或信仰作效果保證。"},{id:"v22",tier:3,category:"文化・科學館展品",question:"香港科學館標誌展品「能量穿梭機」高約多少米？",options:["12米","22米","32米","42米"],answer:1,explanation:"科學館介紹能量穿梭機高22米，圓球運動展示能量轉換。你追住個波望上望落，頸部都有一點工作量。",hint:"它貫穿多層展覽樓面，但不是一座摩天大廈。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"香港科學館・能量穿梭機",url:"https://hk.science.museum/tc/web/scm/exhibition/em.html"},review:"2026-11-26按列明來源核對；歷史年份限定事件，用語限定情境，不以傳說或信仰作效果保證。"},{id:"v23",tier:3,category:"文化・香港故宮",question:"香港故宮文化博物館在哪一年首次開放予公眾參觀？",options:["2017年","2019年","2022年","2024年"],answer:2,explanation:"香港故宮於2022年開放予公眾。這題問香港館開幕，唔係問北京故宮的歷史年表，兩本筆記要分開。",hint:"它晚於M+在2021年的開幕。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"香港故宮文化博物館・正式開放",url:"https://www.hkpm.org.hk/tc/about/press-release/hong-kong-palace-museum-officially-opens-doors-to-public"},review:"2026-11-26按列明來源核對；歷史年份限定事件，用語限定情境，不以傳說或信仰作效果保證。"},{id:"v24",tier:1,category:"文化・M+",question:"西九文化區的M+，主要以哪個領域的收藏與展示為特色？",options:["古代天文觀測儀器","鐵路機車工程","海洋生物標本","當代視覺文化"],answer:3,explanation:"M+關注視覺藝術、設計、建築及流動影像等當代視覺文化。個名有加號，唔代表入去要先做一頁加數。",hint:"看藝術、設計和影像，而不是只按建築外形猜用途。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"M+・開放予公眾參觀",url:"https://www.mplus.org.hk/tc/press/m-plus-opens-to-public-211112/"},review:"2026-11-26按列明來源核對；歷史年份限定事件，用語限定情境，不以傳說或信仰作效果保證。"},{id:"v25",tier:3,category:"文化・戲曲中心",question:"西九文化區戲曲中心在哪一年舉行正式開幕典禮？",options:["2019年","2015年","2017年","2021年"],answer:0,explanation:"戲曲中心於2019年正式揭幕，重點推廣戲曲表演文化。問正式開幕，不把開幕前的試演當成同一日。",hint:"它早於M+及香港故宮開幕。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"香港政府新聞網・戲曲中心揭幕",url:"https://www.news.gov.hk/chi/2019/01/20190120/20190120_203329_293.html"},review:"2026-11-26按列明來源核對；歷史年份限定事件，用語限定情境，不以傳說或信仰作效果保證。"},{id:"v26",tier:1,category:"文化・中央圖書館",question:"香港中央圖書館位於哪個地區？",options:["中環","銅鑼灣","尖沙咀","沙田"],answer:1,explanation:"香港中央圖書館位於銅鑼灣高士威道。名字叫中央，位置卻不在中環；香港街坊考卷最鍾意呢類轉彎位。",hint:"不要把「中央」直接當成「中環」。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"香港公共圖書館・香港中央圖書館",url:"https://www.hkpl.gov.hk/tc/locations/central-library/hong-kong-central.html"},review:"2026-11-26按列明來源核對；歷史年份限定事件，用語限定情境，不以傳說或信仰作效果保證。"},{id:"v27",tier:3,category:"文化・香港藝術館",question:"香港藝術館經大規模擴建及翻新後，於哪一年重新開放？",options:["2015年","2017年","2019年","2022年"],answer:2,explanation:"香港藝術館在2019年11月30日重開。本題問這次翻新後的重開，不是藝術館最初成立年份。",hint:"工程在2015年開始，重開在四年之後。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"香港藝術館・館史小冊子",url:"https://hk.art.museum/documents/About-Us/HKMoA_Booklet_2023_CHI.pdf"},review:"2026-11-26按列明來源核對；歷史年份限定事件，用語限定情境，不以傳說或信仰作效果保證。"},{id:"v28",tier:2,category:"文化・電影資料館",question:"香港電影資料館位於哪個港島地區？",options:["堅尼地城","黃竹坑","赤柱","西灣河"],answer:3,explanation:"香港電影資料館位於西灣河鯉景道，保存與展示本地電影資料。去睇舊戲前先認路，否則可能自己先拍一套迷路記。",hint:"它在港島東，並不在尖沙咀電影海報常見的街景附近。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"香港電影資料館・認識我們",url:"https://www.filmarchive.gov.hk/tc/web/hkfa/about-us.html"},review:"2026-11-26按列明來源核對；歷史年份限定事件，用語限定情境，不以傳說或信仰作效果保證。"},{id:"v29",tier:3,category:"文化・香港大會堂",question:"中環現址的香港大會堂在哪一年落成啟用？",options:["1962年","1952年","1959年","1972年"],answer:0,explanation:"現有香港大會堂於1962年落成啟用，與更早的一代大會堂須分清。建築可以同名，年份就唔可以隨便代班。",hint:"題目指愛丁堡廣場的現有建築群。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"康文署・香港大會堂引言",url:"https://www.lcsd.gov.hk/tc/hkch/aboutus/introduction.html"},review:"2026-11-26按列明來源核對；歷史年份限定事件，用語限定情境，不以傳說或信仰作效果保證。"},{id:"v30",tier:3,category:"文化・三棟屋博物館",question:"三棟屋全面復修後，在哪一年以博物館形式開放？",options:["1977年","1987年","1981年","1997年"],answer:1,explanation:"三棟屋在1987年復修成博物館。本題問開館年份，不是村落建立或列為古蹟之年。",hint:"與1981年列為古蹟分開看，留意事件名稱。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"古蹟辦・三棟屋",url:"https://www.amo.gov.hk/tc/historic-buildings/monuments/new-territories/monuments_10/index.html"},review:"2026-11-26按列明來源核對；歷史年份限定事件，用語限定情境，不以傳說或信仰作效果保證。"},{id:"v31",tier:2,category:"古蹟・饒宗頤文化館",question:"饒宗頤文化館的活化建築群，前身是哪項設施？",options:["前九龍海關","前荔枝角火車站","前荔枝角醫院","前青山警署"],answer:2,explanation:"饒宗頤文化館由前荔枝角醫院建築群活化而成。今日去睇文化活動，唔使帶住舊時看病的預約紙。",hint:"留意荔枝角的建築歷史，不是名字相近的其他機構。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"發展局・營運中的活化項目",url:"https://www.heritage.gov.hk/tc/about-us/revitalisation-scheme/index.html"},review:"2026-11-26按列明來源核對；歷史年份限定事件，用語限定情境，不以傳說或信仰作效果保證。"},{id:"v32",tier:2,category:"古蹟・綠匯學苑",question:"大埔綠匯學苑由哪項歷史設施活化而成？",options:["舊大埔郵政局","舊大埔火車站","舊大埔消防局","舊大埔警署"],answer:3,explanation:"綠匯學苑的前身是舊大埔警署，以活化方式保留建築與社區記憶。以前接報案，今天可以接觸另一種地方故事。",hint:"不是現為鐵路博物館的舊大埔墟火車站。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"發展局・營運中的活化項目",url:"https://www.heritage.gov.hk/tc/about-us/revitalisation-scheme/index.html"},review:"2026-11-26按列明來源核對；歷史年份限定事件，用語限定情境，不以傳說或信仰作效果保證。"},{id:"v33",tier:2,category:"古蹟・大澳文物酒店",question:"大澳文物酒店的建築，前身是哪項設施？",options:["舊大澳警署","舊大澳郵政局","舊大澳製鹽廠","舊大澳消防局"],answer:0,explanation:"大澳文物酒店由舊大澳警署活化。以前是守護水鄉的工作地點，今天以另一種方式接待來訪者。",hint:"與大澳海上治安歷史有關，不是所有海邊建築都曾經曬鹽。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"發展局・營運中的活化項目",url:"https://www.heritage.gov.hk/tc/about-us/revitalisation-scheme/index.html"},review:"2026-11-26按列明來源核對；歷史年份限定事件，用語限定情境，不以傳說或信仰作效果保證。"},{id:"v34",tier:2,category:"古蹟・雷生春活化",question:"雷生春活化後，主要作哪類醫療及教學用途？",options:["牙科鑄模工場","中醫藥服務及教學","獸醫急症中心","放射治療中心"],answer:1,explanation:"雷生春活化為中醫藥服務及教學設施，延續建築與醫藥文化的聯繫。本題不提供診療建議，認用途就已經得分。",hint:"原有藥業背景，與今日中醫藥教學相呼應。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"香港浸會大學中醫藥學院・雷生春堂",url:"https://scm.hkbu.edu.hk/lsc/"},review:"2026-11-26按列明來源核對；歷史年份限定事件，用語限定情境，不以傳說或信仰作效果保證。"},{id:"v35",tier:3,category:"古蹟・元創方前史",question:"PMQ所在土地在成為已婚警察宿舍前，曾是哪所官立學校的校址？",options:["英皇書院","拔萃男書院","中央書院（後稱皇仁書院）","聖保羅書院"],answer:2,explanation:"元創方原址曾為中央書院校舍，其後才建成已婚警察宿舍。學校、宿舍與創意地標，地址同一個，履歷可以好豐富。",hint:"不要只記住前警察宿舍；再往前翻一頁歷史。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"PMQ元創方・歷史導賞",url:"https://www.pmq.org.hk/heritage/guided-tour/?lang=zh"},review:"2026-11-26按列明來源核對；歷史年份限定事件，用語限定情境，不以傳說或信仰作效果保證。"},{id:"v36",tier:3,category:"古蹟・美荷樓",question:"石硤尾美荷樓是哪一年落成的徙置大廈？",options:["1949年","1953年","1964年","1954年"],answer:3,explanation:"美荷樓於1954年落成，與1953年石硤尾大火後的安置歷史相連。問落成年份，唔好被災難年份帶走。",hint:"大火與大廈落成不是同一年。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"香港青年旅舍協會・美荷樓生活館",url:"https://www.yha.org.hk/zh/our-services/mei-ho-house-revitalisation-project/heritage-mei-ho-house/"},review:"2026-11-26按列明來源核對；歷史年份限定事件，用語限定情境，不以傳說或信仰作效果保證。"},{id:"v37",tier:3,category:"古蹟・文武廟年表",question:"上環荷李活道文武廟，一般相信始建於哪一年？",options:["1847年","1841年","1857年","1867年"],answer:0,explanation:"文武廟一般相信始建於1847年，並在華人社區發揮宗教與社會作用。這是史料常見的說法，保留「一般相信」的範圍。",hint:"在香港開埠初期的1840年代，並非所有附屬建築都同時興建。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"古蹟辦・文武廟",url:"https://www.amo.gov.hk/tc/historic-buildings/monuments/hong-kong-island/monuments_96/index.html"},review:"2026-11-26按列明來源核對；歷史年份限定事件，用語限定情境，不以傳說或信仰作效果保證。"},{id:"v38",tier:3,category:"古蹟・聚星樓建築",question:"屏山聚星樓的平面及台基，主要呈哪種幾何形狀？",options:["四方形","六角形","五角形","八角形"],answer:1,explanation:"聚星樓以青磚砌成，呈六角形。這題考建築幾何，不是見到古塔就自動把角數加到八。",hint:"它是香港現存古塔，不要與其他城市常見塔形混在一起。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"古蹟辦・聚星樓",url:"https://www.amo.gov.hk/tc/heritage-trails/ping-shan-heritage-trail/tsui-sing-lau-pagoda/index.html"},review:"2026-11-26按列明來源核對；歷史年份限定事件，用語限定情境，不以傳說或信仰作效果保證。"},{id:"v39",tier:3,category:"古蹟・聖約翰座堂",question:"中環聖約翰座堂在哪一年落成啟用？",options:["1841年","1859年","1849年","1869年"],answer:2,explanation:"聖約翰座堂於1849年落成啟用，之後亦有改動。題目問座堂，不是旁邊較後建成的新座。",hint:"留意19世紀中葉與1840年代的時間。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"古蹟辦・聖約翰座堂",url:"https://www.amo.gov.hk/tc/historic-buildings/monuments/hong-kong-island/monuments_60/"},review:"2026-11-26按列明來源核對；歷史年份限定事件，用語限定情境，不以傳說或信仰作效果保證。"},{id:"v40",tier:2,category:"古蹟・灣仔藍屋",question:"談到灣仔藍屋建築群，「留屋留人」保育理念最接近哪一項？",options:["只保存外牆顏色而不理會社區","將所有住戶搬到同一幢新商場","把建築完全重建成全新式樣","保留建築，也重視居民與社區生活延續"],answer:3,explanation:"「留屋留人」重視歷史建築與社區生活的連繫，不只是保留一幅漂亮外牆。保育唔係把街坊從合照裏剪走。",hint:"看見「人」字，想想生活與社區關係。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"香港歷史文物・藍屋建築群",url:"https://www.heritage.gov.hk/tc/home/index.html"},review:"2026-11-26按列明來源核對；歷史年份限定事件，用語限定情境，不以傳說或信仰作效果保證。"},{id:"v41",tier:1,category:"生態・香港瘰螈",question:"香港瘰螈在動物分類上屬於哪一類？",options:["兩棲類","爬行類","硬骨魚類","哺乳類"],answer:0,explanation:"香港瘰螈是兩棲動物，不是因為有尾巴就變成蜥蜴。名字有香港，也不表示只在香港分布；分類與分布要分開看。",hint:"別單靠像不像蜥蜴的外形判斷。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"香港生物多樣性資訊站・香港瘰螈",url:"https://bih.gov.hk/tc/fast-facts/species-named-after-hong-kong/index-id-4.html"},review:"2026-11-26按列明來源核對；歷史年份限定事件，用語限定情境，不以傳說或信仰作效果保證。"},{id:"v42",tier:3,category:"生態・盧氏小樹蛙",question:"盧氏小樹蛙在1952年最初被發現於哪個香港島嶼？",options:["大嶼山","南丫島","蒲台島","赤鱲角"],answer:1,explanation:"盧氏小樹蛙最初在南丫島被發現，其後在其他地方亦找到族群。問最初發現，不是問所有分布地，考卷又想你快手認錯。",hint:"其他選項亦與這個物種的分布史有關，留意「最初」。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"漁護署・盧氏小樹蛙",url:"https://www.afcd.gov.hk/tc_chi/conservation/con_fau/con_fau_rom/con_fau_rom_gen/con_fau_rom_gen_eco.html"},review:"2026-11-26按列明來源核對；歷史年份限定事件，用語限定情境，不以傳說或信仰作效果保證。"},{id:"v43",tier:3,category:"地質・恐龍化石",question:"香港在2024年公布首次發現恐龍化石，發現地是哪個島？",options:["東平洲","蒲台島","赤洲","吉澳"],answer:2,explanation:"2024年香港首次公布在赤洲發現恐龍化石，相關研究其後持續進行。行過一塊石頭，原來可能比街坊的故事更古老。",hint:"不要與以層狀沉積岩聞名的東平洲混淆。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"古蹟辦・赤洲恐龍化石",url:"https://www.amo.gov.hk/tc/news/index_id_157.html?year=2024"},review:"2026-11-26按列明來源核對；歷史年份限定事件，用語限定情境，不以傳說或信仰作效果保證。"},{id:"v44",tier:3,category:"水塘・萬宜年表",question:"萬宜水庫在哪一年落成？",options:["1968年","1971年","1983年","1978年"],answer:3,explanation:"水務署記載萬宜水庫於1978年落成。1971年與計劃展開有關，唔好把開工的剪綵當成完工合照。",hint:"它是1970年代後期的大型供水工程。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"水務署・水務里程",url:"https://www.wsd.gov.hk/tc/about-us/our-milestone/index.html"},review:"2026-11-26按列明來源核對；歷史年份限定事件，用語限定情境，不以傳說或信仰作效果保證。"},{id:"v45",tier:3,category:"水塘・船灣年表",question:"船灣淡水湖首期在哪一年落成？",options:["1968年","1958年","1963年","1978年"],answer:0,explanation:"水務署記載船灣淡水湖在1968年落成，其後另有擴建。本題問首期，不把後來增加容量的工程當成同一個日子。",hint:"比萬宜水庫落成早十年，兩個水庫不要交換身份證。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"水務署・水務及水塘歷史",url:"https://www.wsd.gov.hk/tc/water-matters/harvesting-water/02/"},review:"2026-11-26按列明來源核對；歷史年份限定事件，用語限定情境，不以傳說或信仰作效果保證。"},{id:"v46",tier:2,category:"郊遊・梧桐寨",question:"梧桐寨瀑布群主要位於哪座山的北面一帶？",options:["獅子山","大帽山","鳳凰山","太平山"],answer:1,explanation:"梧桐寨瀑布群位於大帽山北面一帶，與林村地區相連。知道方位不代表只靠一句提示就可以當行山路線圖。",hint:"想想大埔林村上方的高山。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"漁護署・郊野樂行",url:"https://www.hiking.gov.hk/trail"},review:"2026-11-26按列明來源核對；歷史年份限定事件，用語限定情境，不以傳說或信仰作效果保證。"},{id:"v47",tier:2,category:"地理・東平洲",question:"東平洲位於香港東北面的哪個海灣？",options:["銀礦灣","深水灣","大鵬灣","愉景灣"],answer:2,explanation:"東平洲位於大鵬灣，與大嶼山附近的坪洲是兩個不同地方。多一個「東」字，船程和地圖位置都唔同。",hint:"別把東平洲縮寫成坪洲後就照住另一張地圖出發。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"香港地質公園・東平洲",url:"https://www.geopark.gov.hk/tc/discover/attractions/tung-ping-chau"},review:"2026-11-26按列明來源核對；歷史年份限定事件，用語限定情境，不以傳說或信仰作效果保證。"},{id:"v48",tier:1,category:"地區・石澳",question:"石澳泳灘位於香港哪個大區域？",options:["九龍半島西部","大嶼山西北部","新界西北平原","香港島東南部"],answer:3,explanation:"石澳泳灘位於港島東南部，是熟悉的海邊休閒地點。香港地名熟口熟面，但個腦偶爾都會把海灘搬去隔離區。",hint:"它與大浪灣同在港島東南一帶。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"康文署・香港島泳灘資料",url:"https://www.lcsd.gov.hk/tc/beach/index/beach-location.html"},review:"2026-11-26按列明來源核對；歷史年份限定事件，用語限定情境，不以傳說或信仰作效果保證。"},{id:"v49",tier:1,category:"地區・南生圍",question:"南生圍位於新界哪個行政區？",options:["元朗","沙田","西貢","北區"],answer:0,explanation:"南生圍位於元朗，以河道、濕地及鄉郊景觀為人熟悉。影相認得個風景，答題仲要認埋個區名。",hint:"想想錦田河與山貝河一帶。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"香港自遊樂在18區・元朗區",url:"https://www.gohk.gov.hk/tc/districts/yl.php"},review:"2026-11-26按列明來源核對；歷史年份限定事件，用語限定情境，不以傳說或信仰作效果保證。"},{id:"v50",tier:2,category:"郊遊・鶴藪水塘",question:"鶴藪水塘主要位於哪個新界地區附近？",options:["屯門西部","粉嶺東北一帶","將軍澳南部","荃灣西岸"],answer:1,explanation:"鶴藪水塘位於粉嶺東北一帶，鄰近鶴藪與流水響等鄉郊地方。名字都有水，唔代表所有水塘都在同一個站落車。",hint:"留意流水響、鶴藪與新界東北的連繫。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"漁護署・郊野樂行",url:"https://www.hiking.gov.hk/trail"},review:"2026-11-26按列明來源核對；歷史年份限定事件，用語限定情境，不以傳說或信仰作效果保證。"},{id:"v51",tier:3,category:"交通・地鐵首段",question:"1979年地鐵首段載客服務，連接哪兩個總站？",options:["尖沙咀與金鐘","中環與荃灣","石硤尾與觀塘","九龍塘與羅湖"],answer:2,explanation:"1979年首段服務連接石硤尾與觀塘，與後來過海或其他延綫須分清。今日路綫圖好複雜，當年第一筆未畫到咁多地方。",hint:"這段最初的路綫在九龍，尚未過海。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"港鐵・鐵路解碼",url:"https://stationrailvoyageinfo.mtr.com.hk/tc/decoding-rail"},review:"2026-11-26按列明來源核對；歷史年份限定事件，用語限定情境，不以傳說或信仰作效果保證。"},{id:"v52",tier:3,category:"交通・獅隧年表",question:"獅子山隧道第一條管道在哪一年通車？",options:["1957年","1972年","1978年","1967年"],answer:3,explanation:"獅子山隧道第一條管道在1967年通車，另一條管道較後啟用。題目有個「第一」，唔好讓第二條管道搶先答。",hint:"1978年是另一條管道的年份。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"運輸署・隧道資料及位置",url:"https://www.td.gov.hk/tc/transport_in_hong_kong/tunnels_and_bridges_n/location_map/index.html"},review:"2026-11-26按列明來源核對；歷史年份限定事件，用語限定情境，不以傳說或信仰作效果保證。"},{id:"v53",tier:2,category:"交通・大欖隧道",question:"大欖隧道主要連接哪兩個地區一帶？",options:["汀九與元朗八鄉","沙田大圍與九龍塘","鑽石山與馬鞍山","香港仔與灣仔"],answer:0,explanation:"大欖隧道連接汀九與八鄉一帶，屬新界西的重要道路通道。隧道名容易一口氣背熟，走線就要逐條認。",hint:"不要與獅隧、大老山隧道或香港仔隧道混淆。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"運輸署・隧道資料及位置",url:"https://www.td.gov.hk/tc/transport_in_hong_kong/tunnels_and_bridges_n/location_map/index.html"},review:"2026-11-26按列明來源核對；歷史年份限定事件，用語限定情境，不以傳說或信仰作效果保證。"},{id:"v54",tier:1,category:"地區・車公廟",question:"香火鼎盛的沙田車公廟，實際位於哪個地區一帶？",options:["上水","大圍","青衣","荃灣"],answer:1,explanation:"沙田車公廟位於大圍一帶，與新界其他車公廟亦須分清。本題只問地方，不把祈願當成可以保證考滿分的捷徑。",hint:"留意「沙田」廟宇的指定地點，不是西貢蠔涌那座。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"華人廟宇委員會・官方資料",url:"https://www.ctc.org.hk/"},review:"2026-11-26按列明來源核對；歷史年份限定事件，用語限定情境，不以傳說或信仰作效果保證。"},{id:"v55",tier:1,category:"交通・機場巴士",question:"城巴A11、A21等A字頭「機場快線」巴士，主要服務哪類行程？",options:["只在離島村落內行駛","只在跑馬地馬場內接駁","來往機場與市區","只接駁工廠貨倉並禁載乘客"],answer:2,explanation:"城巴A線是機場快線服務。本題辨認服務類別，不考即日票價或班次；拖住行李認路，已經夠考手力。",hint:"留意「機場快線」是巴士服務名稱，並非港鐵機場快綫。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"城巴・機場快線A線",url:"https://www.citybus.com.hk/routes/airport-bus/route/index.aspx?intLangID=2"},review:"2026-11-26按列明來源核對；歷史年份限定事件，用語限定情境，不以傳說或信仰作效果保證。"},{id:"v56",tier:1,category:"交通・分段車費",question:"巴士路線設下行分段收費，通常表示甚麼？",options:["任何站上車都必須每站另買票","巴士每轉一個彎便加一次費","所有乘客下車時一定獲全數退款","在指定路段上車可按該段較低車費乘搭"],answer:3,explanation:"下行分段車費通常按指定上車路段設定，實際以營辦商資料為準。唔係把一程車費分開幾期畀，拍卡機唔係供款櫃位。",hint:"這裏談上車位置所適用的車費，不是分期付款。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"運輸署・公共巴士",url:"https://www.td.gov.hk/tc/transport_in_hong_kong/public_transport/buses/index.html"},review:"2026-11-26按列明來源核對；歷史年份限定事件，用語限定情境，不以傳說或信仰作效果保證。"},{id:"v57",tier:1,category:"用語・街坊禮貌",question:"有人替你扶住門，你對他說「唔該晒」，在這個情境主要表達甚麼？",options:["感謝對方幫忙","要求對方立即離開","表示不認識這道門","詢問對方的工作時間"],answer:0,explanation:"「唔該」可以用於請求或感謝；在對方已幫忙扶門的情境，主要表示謝意。兩個字講得自然，街坊日常就順一點。",hint:"題目已說對方完成幫忙，留意情境。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"粵典・唔該",url:"https://words.hk/zidin/%E5%94%94%E8%A9%B2"},review:"2026-11-26按列明來源核對；歷史年份限定事件，用語限定情境，不以傳說或信仰作效果保證。"},{id:"v58",tier:1,category:"用語・茶記閒聊",question:"朋友說「坐低吹陣水」，在相約聊天的情境通常想做甚麼？",options:["練習向水面吹氣","輕鬆閒聊","叫你去關水喉","安排泳池換水"],answer:1,explanation:"吹水在這個情境指聊天；其他語境也可有誇口等意思。今日先吹陣水，唔使真係帶個面盆赴約。",hint:"它是口語比喻，別按字面準備工具。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"粵典・吹水",url:"https://words.hk/zidin/%E5%90%B9%E6%B0%B4"},review:"2026-11-26按列明來源核對；歷史年份限定事件，用語限定情境，不以傳說或信仰作效果保證。"},{id:"v59",tier:1,category:"用語・醒目街坊",question:"街坊稱讚你「幾醒目喎」，在讚你反應快的情境通常指甚麼？",options:["衣服一定反光","眼睛剛做了檢查","機靈、懂得領會","昨晚完全沒有睡覺"],answer:2,explanation:"醒目在這個情境指機靈、領會快；另有搶眼等用法，要按上下文理解。唔係所有醒目人都要著螢光衫。",hint:"題目指定是在稱讚反應與理解。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"粵典・醒目",url:"https://words.hk/zidin/%E9%86%92%E7%9B%AE"},review:"2026-11-26按列明來源核對；歷史年份限定事件，用語限定情境，不以傳說或信仰作效果保證。"},{id:"v60",tier:1,category:"用語・辦公室文化",question:"同事最後一天上班派「散水餅」，通常是在做甚麼？",options:["通知辦公室水喉爆裂","慶祝茶水間換新水機","要求所有人立即下班","離職前向同事道別及分享西餅"],answer:3,explanation:"散水餅是香港辦公室常見的離職道別做法，並不是每個人都必須遵行。餅盒一開，群組討論的通常不止是哪款口味。",hint:"留意最後一天上班的情境，不是供水安排。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,source:{label:"粵典・散水餅",url:"https://words.hk/zidin/%E6%95%A3%E6%B0%B4%E9%A4%85"},review:"2026-11-26按列明來源核對；歷史年份限定事件，用語限定情境，不以傳說或信仰作效果保證。"}].map(t=>Object.freeze({...t,options:Object.freeze(t.options),source:Object.freeze(t.source),focus:Object.freeze(t.focus),modes:Object.freeze(t.modes)})));var $=Object.freeze([{id:"n01",tier:1,category:"飲食・元朗唐餅",question:"元朗老餅家常見的冬蓉老婆餅，甜糯餡料主要由哪種瓜製成？",options:["冬瓜","南瓜","木瓜","節瓜"],answer:0,explanation:"冬蓉老婆餅的代表餡料是冬瓜蓉，另有其他口味，不能把所有老婆餅配方混為一談。買一盒返屋企，最緊張的通常唔係老婆，係件餅會唔會壓扁。",hint:"留意「冬蓉」的「冬」，不是叫你放雪櫃食。",art:"bun",focus:{x:50,y:50},modes:["text"],imageAlt:"香港本地文化主題原創插畫；並非本題地點實景、製作工序圖或官方文件。",source:{label:"恆香老餅家・老婆餅",url:"https://www.hangheung.com.hk/pages/hangheung-wife-cake"},review:"2026-11-26核對列明來源；以文字知識作答，插畫只作主題輔助。",textOnly:!0},{id:"n02",tier:1,category:"飲食・手工蛋卷",question:"師傅把蛋漿烘成薄片後，傳統手工蛋卷通常怎樣成形？",options:["放涼後壓成厚餅","趁熱捲成筒狀","趁熱切成麵條","浸水後摺成方塊"],answer:1,explanation:"手工蛋卷會在薄片仍柔軟時捲起，放涼後變得酥脆。動作慢半拍，可能由蛋卷師傅轉職成碎餅供應商；不同工場會用不同工具。",hint:"薄片放涼會變脆，成形要趁佢仲肯合作。",art:"bun",focus:{x:50,y:50},modes:["text"],textOnly:!0,imageAlt:"香港本地文化主題原創插畫；並非本題地點實景、製作工序圖或官方文件。",source:{label:"香港文匯報・元朗唐餅手作採訪",url:"https://www.wenweipo.com/a/202603/22/AP69bf4840e4b04d7d56d995d2.html"},review:"2026-11-26核對列明來源；以文字知識作答，插畫只作主題輔助。"},{id:"n03",tier:1,category:"飲食・佐粥小菜",question:"早餐枱上一小碟腐乳，主要是哪種食材經受控發酵製成？",options:["雞蛋","蘿蔔","豆腐","魚肉"],answer:2,explanation:"腐乳是豆腐經受控發酵及調味加工的食品，不是把家中變壞的豆腐照食。小小一磚配白粥，存在感可以大過成張早餐枱。",hint:"名稱有個「腐」字，跟豆品家族有關。",art:"milk",focus:{x:50,y:50},modes:["text"],textOnly:!0,imageAlt:"香港本地文化主題原創插畫；並非本題地點實景、製作工序圖或官方文件。",source:{label:"食物安全中心・食物安全焦點239期",url:"https://www.cfs.gov.hk/english/multimedia/multimedia_pub/files/FSF239_2026_06_17.pdf"},review:"2026-11-26核對列明來源；以文字知識作答，插畫只作主題輔助。"},{id:"n04",tier:2,category:"飲食・漁村醬料",question:"大澳海味舖常見的傳統蝦醬，其獨特鹹鮮味主要經哪類加工形成？",options:["加糖煮成果醬","先烘成蝦乾再磨粉","用醋把生蝦即時泡熟","鹽漬及發酵"],answer:3,explanation:"傳統蝦醬以小蝦配鹽，經發酵形成風味，各家工藝有別；保存須依產品指示。開樽一刻，全屋都知道你今晚有大計。",hint:"不是單純把蝦磨碎，也不是甜果醬的做法。",art:"ferry",focus:{x:50,y:50},modes:["text"],textOnly:!0,imageAlt:"香港本地文化主題原創插畫；並非本題地點實景、製作工序圖或官方文件。",source:{label:"消費者委員會・調味品儲存及發酵製品",url:"https://www.consumer.org.hk/tc/article/526-condiment-storage/526_condiment_storage"},review:"2026-11-26核對列明來源；以文字知識作答，插畫只作主題輔助。"},{id:"n05",tier:1,category:"飲食・潮州滷水",question:"香港潮州食店的「滷水鵝」，一般以哪種方式賦予主要風味？",options:["在調味滷汁中煮製或浸製","只以乾鹽風乾","先裹粉再炸至酥脆","只用蒸氣不加調味"],answer:0,explanation:"潮州滷水食品以調配好的滷汁處理食材，香料與調味因店家而異。叫得滷水鵝，重點係入味，唔係叫隻鵝落海游一轉。",hint:"留意「滷」所指的是一種調味加工方法。",art:"bun",focus:{x:50,y:50},modes:["text"],imageAlt:"香港本地文化主題原創插畫；並非本題地點實景、製作工序圖或官方文件。",source:{label:"非遺辦事處・飲食文化展板",url:"https://www.icho.hk/documents/Education/exhibition_panels/Exhibition_panel_food_culture.pdf"},review:"2026-11-26核對列明來源；以文字知識作答，插畫只作主題輔助。",textOnly:!0},{id:"n06",tier:2,category:"飲食・蝦子麵",question:"傳統蝦子麵的「蝦子」，主要指製麵時加入的甚麼？",options:["蝦殼碎","蝦卵","整隻幼蝦","蝦鬚粉"],answer:1,explanation:"傳統蝦子麵會把蝦子等材料加入麵糰，再加工成麵餅。這裏的「子」指蝦卵，唔係麵裏住咗一隻迷你蝦仔。",hint:"這個「子」跟魚子中的「子」意思相近。",art:"bun",focus:{x:50,y:50},modes:["text"],textOnly:!0,imageAlt:"香港本地文化主題原創插畫；並非本題地點實景、製作工序圖或官方文件。",source:{label:"非遺辦事處・香港非遺清單2024年更新版",url:"https://www.icho.hk/documents/Intangible-Cultural-Heritage-Inventory/2024/ich_inventory_2024_cn.pdf"},review:"2026-11-26核對列明來源；以文字知識作答，插畫只作主題輔助。"},{id:"n07",tier:3,category:"飲食・皮蛋科學",question:"茶記皮蛋瘦肉粥裏的皮蛋，製作時哪種作用令蛋白逐漸凝固？",options:["酸性醃料滲入，令蛋白質結成酸凝乳","高壓蒸氣穿過蛋殼，把蛋液蒸熟","鹼性醃料滲入，促使蛋白質變性及聚合","低溫凍結蛋液，解凍後永久定形"],answer:2,explanation:"皮蛋的典型加工利用鹼性物質透過蛋殼作用於蛋內蛋白質，並非普通水煮。早餐睇落一碗粥，背後原來有個化學部門開緊工。",hint:"關鍵是酸鹼環境，不是把蛋放得愈耐就自然變皮蛋。",art:"bun",focus:{x:50,y:50},modes:["text"],textOnly:!0,imageAlt:"香港本地文化主題原創插畫；並非本題地點實景、製作工序圖或官方文件。",source:{label:"香港科學館・皮蛋的製作原理",url:"https://hk.science.museum/tc/web/scm/online-explore/qkpost-roadshow-food/centuryegg.html"},review:"2026-11-26核對列明來源；以文字知識作答，插畫只作主題輔助。"},{id:"n08",tier:3,category:"飲食・酥皮蛋撻",question:"港式酥皮蛋撻焗後層層鬆化，製皮時哪種結構最關鍵？",options:["把油脂完全攪勻，令麵糰沒有分層","在成品表面撒乾麵粉，模擬薄層","先把撻皮浸透蛋液，再自然風乾","反覆摺疊形成麵糰與油脂的交替薄層"],answer:3,explanation:"酥皮的分層來自麵糰與油脂層的安排，焗製時水分與熱力令層次展開。食一啖跌幾塊酥皮，唔一定係你論盡，係個結構太認真。",hint:"想想「層層」從哪裏來，而不只是用了多少牛油。",art:"bun",focus:{x:50,y:50},modes:["text"],textOnly:!0,imageAlt:"香港本地文化主題原創插畫；並非本題地點實景、製作工序圖或官方文件。",source:{label:"香港科學館・酥皮蛋撻",url:"https://hk.science.museum/tc/web/scm/online-explore/qkpost-roadshow-food/eggtart.html"},review:"2026-11-26核對列明來源；以文字知識作答，插畫只作主題輔助。"},{id:"n09",tier:2,category:"飲食・醬園工藝",question:"香港傳統醬園釀製生抽，以下哪種豆類是代表原料？",options:["黃豆","紅豆","綠豆","眉豆"],answer:0,explanation:"傳統生抽釀製以黃豆等原料經蒸煮、發酵及曬製等工序完成，不同醬園配方有別。點豉油之前，粒豆已經返咗好多日工。",hint:"跟豆腐常見原料同屬一個豆家族，但加工路線不同。",art:"milk",focus:{x:50,y:50},modes:["text"],textOnly:!0,imageAlt:"香港本地文化主題原創插畫；並非本題地點實景、製作工序圖或官方文件。",source:{label:"非遺辦事處・香港非遺清單2024年更新版",url:"https://www.icho.hk/documents/Intangible-Cultural-Heritage-Inventory/2024/ich_inventory_2024_cn.pdf"},review:"2026-11-26核對列明來源；以文字知識作答，插畫只作主題輔助。"},{id:"n10",tier:1,category:"飲食・茶樓器物",question:"茶樓傳統蒸籠通常以哪種植物材料製作，兼顧保溫及透氣？",options:["藤","竹","稻草","椰葉"],answer:1,explanation:"傳統蒸籠以竹片等竹材製作，能保溫並疏導蒸氣；現代亦有其他材質蒸具。點心未開場，個籠已經默默做足後勤。",hint:"想想薄片、竹篾與一籠籠蒸點心的器具。",art:"buns",focus:{x:50,y:50},modes:["text"],imageAlt:"香港本地文化主題原創插畫；並非本題地點實景、製作工序圖或官方文件。",source:{label:"非遺辦事處・教育小冊子",url:"https://www.icho.hk/documents/Education/edu_booklet/edu_booklet_2.pdf"},review:"2026-11-26核對列明來源；以文字知識作答，插畫只作主題輔助。",textOnly:!0},{id:"n11",tier:1,category:"交通・樂園鐵路",question:"搭港鐵去香港迪士尼樂園，通常在哪個站轉乘迪士尼綫？",options:["東涌","青衣","欣澳","南昌"],answer:2,explanation:"迪士尼綫連接欣澳與迪士尼站。這題只考轉車站，不考即日班次；未見到米奇之前，先唔好喺東涌落錯車。",hint:"轉乘站位於東涌綫，但不是東涌終點站。",art:"tram",focus:{x:50,y:50},modes:["text"],imageAlt:"香港本地文化主題原創插畫；並非本題地點實景、製作工序圖或官方文件。",source:{label:"香港迪士尼樂園・港鐵交通",url:"https://www.hongkongdisneyland.com/zh-hk/guest-services/travel-information/mtr-disneyland-resort-line/"},review:"2026-11-26核對列明來源；以文字知識作答，插畫只作主題輔助。",textOnly:!0},{id:"n12",tier:1,category:"交通・大嶼山纜車",question:"昂坪360纜車的兩端，主要連接哪一組地方？",options:["梅窩與昂坪","東涌與大澳","愉景灣與梅窩","東涌與昂坪"],answer:3,explanation:"昂坪纜車主要連接東涌與昂坪，不等於大嶼山各村落之間都有纜車。空中睇風景好寫意，認錯總站就未必咁寫意。",hint:"一端近港鐵東涌站，另一端在大佛所在高地。",art:"mountain",focus:{x:50,y:50},modes:["original"],imageAlt:"香港本地文化主題原創插畫；並非本題地點實景、製作工序圖或官方文件。",source:{label:"昂坪360・昂坪纜車",url:"https://www.np360.com.hk/cable-cars"},review:"2026-11-26核對列明來源；以文字知識作答，插畫只作主題輔助。"},{id:"n13",tier:2,category:"交通・紅隧歷史",question:"香港首條行車過海隧道——海底隧道（紅隧），在哪一年通車？",options:["1972年","1967年","1979年","1989年"],answer:0,explanation:"海底隧道在1972年建成啟用，是香港首條貫通維港兩岸的行車隧道。講開塞車人人有故事，講通車年份就要靠真正記性。",hint:"早於港鐵過海，也早於東隧及西隧。",art:"harbour",focus:{x:50,y:50},modes:["text"],textOnly:!0,imageAlt:"香港本地文化主題原創插畫；並非本題地點實景、製作工序圖或官方文件。",source:{label:"路政署・香港第一條海底隧道",url:"https://www.hyd.gov.hk/tc/information_corner/trivia/first_cross_harbour_tunnel/index.html"},review:"2026-11-26核對列明來源；以文字知識作答，插畫只作主題輔助。"},{id:"n14",tier:2,category:"交通・西隧走線",question:"西區海底隧道在香港島的一端，位於哪個地區？",options:["鰂魚涌","西營盤","北角","香港仔"],answer:1,explanation:"西隧連接西營盤與西九龍；不要把它與東隧的鰂魚涌端混淆。個名有個「西」字，今次真係有方向可跟。",hint:"先分清港島西面與東面，再排除香港仔。",art:"harbour",focus:{x:50,y:50},modes:["original"],imageAlt:"香港本地文化主題原創插畫；並非本題地點實景、製作工序圖或官方文件。",source:{label:"運輸署・隧道及橋樑資料",url:"https://www.td.gov.hk/tc/transport_in_hong_kong/tunnels_and_bridges_n/location_map/index.html"},review:"2026-11-26核對列明來源；以文字知識作答，插畫只作主題輔助。"},{id:"n15",tier:3,category:"交通・電車年表",question:"香港電車在20世紀哪一年開始載客服務？",options:["1901年","1908年","1904年","1911年"],answer:2,explanation:"香港電車於1904年開始服務；本題問開辦年份，不是雙層化或某條支線的年份。叮叮慢慢行，歷史其實行得好前。",hint:"是九廣鐵路英段通車之前的20世紀初。",art:"tram",focus:{x:50,y:50},modes:["text"],textOnly:!0,imageAlt:"香港本地文化主題原創插畫；並非本題地點實景、製作工序圖或官方文件。",source:{label:"香港電車・歷史",url:"https://www.hktramways.com/en/our-story"},review:"2026-11-26核對列明來源；以文字知識作答，插畫只作主題輔助。"},{id:"n16",tier:3,category:"交通・輕鐵年表",question:"新界西北輕鐵第一期在哪一年投入服務？",options:["1982年","1985年","1993年","1988年"],answer:3,explanation:"輕鐵在1988年投入服務，初期服務屯門及元朗，其後擴展。平時熟到閉眼都識搭，考年份時對眼就要擘大啲。",hint:"在1980年代末，早於1990年代的天水圍延伸。",art:"tram",focus:{x:50,y:50},modes:["text"],textOnly:!0,imageAlt:"香港本地文化主題原創插畫；並非本題地點實景、製作工序圖或官方文件。",source:{label:"九廣鐵路公司・歷史",url:"https://www.kcrc.com/tc/about-kcrc/history.html"},review:"2026-11-26核對列明來源；以文字知識作答，插畫只作主題輔助。"},{id:"n17",tier:3,category:"交通・九鐵年表",question:"九廣鐵路英段首次通車的年份是哪一年？",options:["1910年","1904年","1912年","1920年"],answer:0,explanation:"九廣鐵路英段在1910年通車，與今日東鐵綫有歷史承接關係。呢條題目考年表，唔係考你上次喺月台等咗幾耐。",hint:"介乎電車開辦與香港大學成立之間。",art:"clock",focus:{x:50,y:50},modes:["text"],textOnly:!0,imageAlt:"香港本地文化主題原創插畫；並非本題地點實景、製作工序圖或官方文件。",source:{label:"九廣鐵路公司・歷史",url:"https://www.kcrc.com/tc/about-kcrc/history.html"},review:"2026-11-26核對列明來源；以文字知識作答，插畫只作主題輔助。"},{id:"n18",tier:2,category:"交通・機場鐵路",question:"以下哪個車站同時有東涌綫及機場快綫月台？",options:["欣澳","青衣","荔景","奧運"],answer:1,explanation:"青衣站同時服務東涌綫及機場快綫，另外三站不具這個配搭。兩條綫都見到青衣，唔代表每班車都會載你去機場。",hint:"位於青衣島；留意同站轉乘與列車途經是兩回事。",art:"tram",focus:{x:50,y:50},modes:["text"],imageAlt:"香港本地文化主題原創插畫；並非本題地點實景、製作工序圖或官方文件。",source:{label:"港鐵・機場快綫青衣站",url:"https://www.mtr.com.hk/ch/customer/services/aestations_ty.html"},review:"2026-11-26核對列明來源；以文字知識作答，插畫只作主題輔助。",textOnly:!0},{id:"n19",tier:1,category:"交通・跨島大橋",question:"青馬大橋跨越海面，直接連接哪兩個島嶼？",options:["青衣與坪洲","馬灣與南丫島","青衣與馬灣","青衣與香港島"],answer:2,explanation:"青馬大橋連接青衣與馬灣，是機場陸路及鐵路通道的重要一環。橋名把兩端各借一個字，今次唔使靠估廣告標語。",hint:"「青」與「馬」各自來自橋兩端地名。",art:"harbour",focus:{x:50,y:50},modes:["original"],imageAlt:"香港本地文化主題原創插畫；並非本題地點實景、製作工序圖或官方文件。",source:{label:"路政署・青馬大橋",url:"https://www.hyd.gov.hk/tc/information_corner/trivia/longest_span_bridge/index.html"},review:"2026-11-26核對列明來源；以文字知識作答，插畫只作主題輔助。"},{id:"n20",tier:3,category:"交通・道路編號",question:"一號、二號、三號幹線分別經紅隧、東隧及西隧，其編號依據是甚麼？",options:["隧道由西至東的地理次序","隧道由短至長的長度次序","隧道由低至高的造價次序","三條隧道開通的先後次序"],answer:3,explanation:"運輸署指出，三條南北走向幹線的號碼按過海隧道通車先後編訂。不是把地圖由左掃到右，導航個腦要轉個彎。",hint:"紅隧最先通車；不要只按東西方向排數字。",art:"harbour",focus:{x:50,y:50},modes:["text"],textOnly:!0,imageAlt:"香港本地文化主題原創插畫；並非本題地點實景、製作工序圖或官方文件。",source:{label:"運輸署・主要幹線編號",url:"https://www.td.gov.hk/tc/road_safety/road_users_code/index/chapter_8_the_language_of_the_road/major_road_route_numbers_/index.html"},review:"2026-11-26核對列明來源；以文字知識作答，插畫只作主題輔助。"},{id:"n21",tier:1,category:"文化・油麻地戲院",question:"油麻地戲院在2012年活化為演藝場地後，特別支持哪類本地表演新秀？",options:["粵劇","西洋歌劇","交響樂","芭蕾舞"],answer:0,explanation:"2012年啟用的活化項目為戲曲、尤其粵劇新秀及新進劇團提供演出和培訓設施。這裏講歷史定位，不代表任何日期都可直接入場睇戲。",hint:"留意香港傳統戲曲，不是把所有舞台表演當成同一類。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,imageAlt:"香港本地文化主題原創插畫；並非本題地點實景、製作工序圖或官方文件。",source:{label:"康文署・油麻地戲院簡介",url:"https://www.lcsd.gov.hk/tc/ymtt/aboutus/introduction.html"},review:"2026-11-26核對列明來源；以文字知識作答，插畫只作主題輔助。"},{id:"n22",tier:1,category:"文化・香港文化博物館",question:"香港文化博物館位於哪個新市鎮？",options:["大埔","沙田","屯門","荃灣"],answer:1,explanation:"香港文化博物館位於沙田文林路，收藏與展覽涵蓋本地文化藝術。約朋友睇展覽前，先唔好把沙田同尖沙咀混成一站。",hint:"它近城門河一帶，並非尖沙咀的歷史博物館。",art:"river",focus:{x:50,y:50},modes:["text"],textOnly:!0,imageAlt:"香港本地文化主題原創插畫；並非本題地點實景、製作工序圖或官方文件。",source:{label:"香港文化博物館・位置",url:"https://www.heritagemuseum.gov.hk/tc/opening_hours_locations.html"},review:"2026-11-26核對列明來源；以文字知識作答，插畫只作主題輔助。"},{id:"n23",tier:2,category:"古蹟・孫中山紀念館",question:"孫中山紀念館所在的歷史大宅，原名是甚麼？",options:["景賢里","雷生春","甘棠第","大夫第"],answer:2,explanation:"孫中山紀念館設於甘棠第；大宅曾是何甘棠的住宅，不應誤當為孫中山故居。紀念一個人，唔代表個地址就係佢屋企。",hint:"名字與原業主何甘棠有關。",art:"temple",focus:{x:50,y:50},modes:["text"],textOnly:!0,imageAlt:"香港本地文化主題原創插畫；並非本題地點實景、製作工序圖或官方文件。",source:{label:"古蹟辦・甘棠第",url:"https://www.amo.gov.hk/tc/heritage-trails/cw-trails/sheungwan/section-a/a8/index.html"},review:"2026-11-26核對列明來源；以文字知識作答，插畫只作主題輔助。"},{id:"n24",tier:2,category:"古蹟・上環街市",question:"今天稱為西港城的紅磚建築，前身是哪項設施的一部分？",options:["舊中區警署西翼","舊灣仔街市南座","舊中央郵政總局","舊上環街市北座"],answer:3,explanation:"西港城前身是舊上環街市北座，後經保育活化。名字有個「城」，以前卻係買餸地方，唔係用來守城門。",hint:"從上環的日常商業設施想起，不要只看名稱的「城」。",art:"temple",focus:{x:50,y:50},modes:["text"],textOnly:!0,imageAlt:"香港本地文化主題原創插畫；並非本題地點實景、製作工序圖或官方文件。",source:{label:"古蹟辦・舊上環街市北座",url:"https://www.amo.gov.hk/tc/heritage-trails/cw-trails/sheungwan/section-b/b35/index.html"},review:"2026-11-26核對列明來源；以文字知識作答，插畫只作主題輔助。"},{id:"n25",tier:2,category:"文化・海防博物館",question:"香港抗戰及海防博物館位於哪個港島地區？",options:["筲箕灣","堅尼地城","赤柱","北角"],answer:0,explanation:"博物館位於筲箕灣東喜道，利用鯉魚門一帶的歷史軍事設施介紹海防與抗戰歷史。本題不考即日開放安排，免得答啱都摸門釘。",hint:"它面向港島東端附近的鯉魚門海峽。",art:"harbour",focus:{x:50,y:50},modes:["text"],textOnly:!0,imageAlt:"香港本地文化主題原創插畫；並非本題地點實景、製作工序圖或官方文件。",source:{label:"香港抗戰及海防博物館・參觀",url:"https://hk.waranddefence.museum/tc/web/mcd/visit.html"},review:"2026-11-26核對列明來源；以文字知識作答，插畫只作主題輔助。"},{id:"n26",tier:3,category:"古蹟・虎豹別墅",question:"香港大坑的虎豹別墅，是哪位有「萬金油大王」之稱的商人家族居所？",options:["胡雪巖","胡文虎","何東","李陞"],answer:1,explanation:"虎豹別墅與胡文虎及其家族在香港的生活有關，並曾毗鄰萬金油花園。這題考業主，唔係問屋企有冇老虎同豹子入住。",hint:"虎標萬金油與建築名稱都提供了線索。",art:"temple",focus:{x:50,y:50},modes:["text"],textOnly:!0,imageAlt:"香港本地文化主題原創插畫；並非本題地點實景、製作工序圖或官方文件。",source:{label:"古蹟辦・虎豹別墅",url:"https://www.amo.gov.hk/tc/about-us/online-articles/20230608/index.html"},review:"2026-11-26核對列明來源；以文字知識作答，插畫只作主題輔助。"},{id:"n27",tier:3,category:"古蹟・九龍寨城",question:"九龍寨城公園保留的衙門，原本是哪類官署的辦公地方？",options:["九龍海關稅務官署","新安縣縣學","九龍司巡檢的官署","九龍水師船塢衙署"],answer:2,explanation:"前九龍寨城衙門原為九龍司巡檢辦公之所，後來有不同用途。今日遊公園可以慢慢行，當年入衙門未必有咁輕鬆。",hint:"清代的地方巡查與治安職務，比另外三項更貼近。",art:"temple",focus:{x:50,y:50},modes:["text"],textOnly:!0,imageAlt:"香港本地文化主題原創插畫；並非本題地點實景、製作工序圖或官方文件。",source:{label:"古蹟辦・前九龍寨城衙門",url:"https://www.amo.gov.hk/tc/historic-buildings/monuments/kowloon/monuments_63/index.html"},review:"2026-11-26核對列明來源；以文字知識作答，插畫只作主題輔助。"},{id:"n28",tier:3,category:"古蹟・屏山活化",question:"屏山鄧族文物館暨文物徑訪客中心，由哪項舊設施改建而成？",options:["舊屏山郵政局","舊屏山火車站","舊屏山海關分站","舊屏山警署"],answer:3,explanation:"文物館由舊屏山警署改建，介紹宗族歷史及文物徑。以前來報案，今日來補文化常識；同樣都希望唔好認錯地方。",hint:"主樓的瞭望設計，反映它曾有維持治安的用途。",art:"temple",focus:{x:50,y:50},modes:["text"],textOnly:!0,imageAlt:"香港本地文化主題原創插畫；並非本題地點實景、製作工序圖或官方文件。",source:{label:"古蹟辦・屏山鄧族文物館",url:"https://www.amo.gov.hk/tc/heritage-trails/ping-shan-heritage-trail/visitors-centre/index.html"},review:"2026-11-26核對列明來源；以文字知識作答，插畫只作主題輔助。"},{id:"n29",tier:3,category:"古蹟・茶具文物館",question:"現為茶具文物館的舊三軍司令官邸，於哪一年建成？",options:["1846年","1844年","1856年","1864年"],answer:0,explanation:"現為茶具文物館的舊三軍司令官邸在1844至1846年間興建。要分清建成年與後來改設博物館的年份；昔日指揮部，今日品茶，轉型幅度真係唔細。",hint:"留意它是19世紀中葉的建築，並非後來開設博物館的年份。",art:"clock",focus:{x:50,y:50},modes:["text"],textOnly:!0,imageAlt:"香港本地文化主題原創插畫；並非本題地點實景、製作工序圖或官方文件。",source:{label:"古蹟辦・舊三軍司令官邸",url:"https://www.amo.gov.hk/tc/historic-buildings/monuments/hong-kong-island/monuments_36/index.html"},review:"2026-11-26核對列明來源；以文字知識作答，插畫只作主題輔助。"},{id:"n30",tier:3,category:"古蹟・灣仔郵政",question:"舊灣仔郵政局建於1912至1913年間，但正式以郵政局開放服務是哪一年？",options:["1912年","1915年","1913年","1921年"],answer:1,explanation:"古蹟辦記載，建築在1915年3月1日正式作灣仔郵政局開放。興建與啟用是兩件事，封信未必跟得上個地盤交樓日。",hint:"別把1912至1913年的興建期，當成開始服務的年份。",art:"clock",focus:{x:50,y:50},modes:["text"],textOnly:!0,imageAlt:"香港本地文化主題原創插畫；並非本題地點實景、製作工序圖或官方文件。",source:{label:"古蹟辦・舊灣仔郵政局",url:"https://www.amo.gov.hk/tc/historic-buildings/monuments/hong-kong-island/monuments_40/index.html"},review:"2026-11-26核對列明來源；以文字知識作答，插畫只作主題輔助。"},{id:"n31",tier:1,category:"非遺・紙紮工藝",question:"傳統紙紮祭祀用品常以甚麼做骨架，再裱上紙張？",options:["棉線繩結","陶泥條","竹篾","石膏條"],answer:2,explanation:"傳統紙紮會用竹篾等材料搭骨架，再裱紙及裝飾；製品與做法各有差異。睇落輕飄飄，師傅背後其實好有結構。",hint:"和竹編有材料上的關係，不是把整件物品燒成陶器。",art:"lantern",focus:{x:50,y:50},modes:["original"],imageAlt:"香港本地文化主題原創插畫；並非本題地點實景、製作工序圖或官方文件。",source:{label:"非遺辦事處・首份非遺清單",url:"https://www.icho.hk/documents/Intangible-Cultural-Heritage-Inventory/First_hkich_inventory_C.pdf"},review:"2026-11-26核對列明來源；以文字知識作答，插畫只作主題輔助。"},{id:"n32",tier:1,category:"非遺・神功戲",question:"香港一些廟會舉辦「神功戲」，其傳統目的最貼近哪一項？",options:["專為考取戲曲文憑","專為售賣戲服配件","只為選出村中歌王","酬神、祈福及還願"],answer:3,explanation:"神功戲與社區祭祀、酬神及祈福傳統相關，亦讓街坊聚首。觀眾唔止台下街坊，但這是信仰文化，不是保證轉運的服務合約。",hint:"留意「神功」與廟會的關係，不只是售票演出的形式。",art:"temple",focus:{x:50,y:50},modes:["original"],imageAlt:"香港本地文化主題原創插畫；並非本題地點實景、製作工序圖或官方文件。",source:{label:"香港政府・首份非遺代表作名錄簡介",url:"https://gia.info.gov.hk/general/201708/14/P2017081400644_265202_1_1502705234028.pdf"},review:"2026-11-26核對列明來源；以文字知識作答，插畫只作主題輔助。"},{id:"n33",tier:1,category:"非遺・潮州茶藝",question:"街坊提到「潮州工夫茶」，通常是在說哪一類技藝？",options:["沖泡及品飲茶的技藝","製作茶果的手藝","把茶葉磨成藥粉的技術","為茶具鍍金的工藝"],answer:0,explanation:"工夫茶指講究器具與沖泡等環節的茶藝，不是茶名裏寫了工夫就要先耍一套拳。各流派細節不同，本題只辨認活動類別。",hint:"這個「工夫」重在泡茶與品茶的講究。",art:"milk",focus:{x:50,y:50},modes:["text"],imageAlt:"香港本地文化主題原創插畫；並非本題地點實景、製作工序圖或官方文件。",source:{label:"非遺辦事處・香港非遺清單2024年更新版",url:"https://www.icho.hk/documents/Intangible-Cultural-Heritage-Inventory/2024/ich_inventory_2024_cn.pdf"},review:"2026-11-26核對列明來源；以文字知識作答，插畫只作主題輔助。",textOnly:!0},{id:"n34",tier:1,category:"節慶・新春全盒",question:"新春拜年，主人端出「全盒」通常主要招待甚麼？",options:["熱湯和燉菜","糖果、瓜子及賀年小食","生鮮魚肉","沖好的熱茶"],answer:1,explanation:"全盒用來盛放糖果、瓜子及各式賀年小食，內容隨家庭口味而變。口講「食少少」，手就自動行多兩轉，呢個先係熟悉的拜年節奏。",hint:"是一格格可拈取的小食，不是把整餐飯放在盒裏。",art:"lantern",focus:{x:50,y:50},modes:["original"],imageAlt:"香港本地文化主題原創插畫；並非本題地點實景、製作工序圖或官方文件。",source:{label:"百佳・賀年全盒糖果",url:"https://www.pns.hk/zh-hk/%E5%85%A8%E7%9B%92%E7%B3%96%E6%9E%9C/c/cny-candy"},review:"2026-11-26核對列明來源；以文字知識作答，插畫只作主題輔助。"},{id:"n35",tier:2,category:"非遺・客家舞麒麟",question:"西貢坑口傳統舞麒麟，主要與哪個族群的社區文化相連？",options:["蜑家","葡裔","客家","閩南漁民"],answer:2,explanation:"西貢坑口客家舞麒麟，是當地客家社群在節慶與儀式中傳承的文化。麒麟跳得生猛，重點仍是人與社區把手藝接住。",hint:"這個項目的正式名稱，本身就包含族群名稱。",art:"dragon",focus:{x:50,y:50},modes:["text"],imageAlt:"香港本地文化主題原創插畫；並非本題地點實景、製作工序圖或官方文件。",source:{label:"非遺辦事處・西貢坑口客家舞麒麟等影音",url:"https://www.icho.hk/tc/web/icho/video.html"},review:"2026-11-26核對列明來源；以文字知識作答，插畫只作主題輔助。",textOnly:!0},{id:"n36",tier:2,category:"非遺・南音說唱",question:"香港傳統南音主要以哪種語言說唱？",options:["潮州話","客家話","閩南話","廣府話（粵語）"],answer:3,explanation:"香港的南音是廣府話說唱曲藝，與不同地區同名的音樂傳統須分清。慢慢唱一段故事，資訊量可以多過一串群組語音。",hint:"想想地水南音與本地粵語曲藝的聯繫。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,imageAlt:"香港本地文化主題原創插畫；並非本題地點實景、製作工序圖或官方文件。",source:{label:"非遺辦事處・代表作名錄",url:"https://www.icho.hk/tc/web/icho/the_representative_list_of_hkich.html"},review:"2026-11-26核對列明來源；以文字知識作答，插畫只作主題輔助。"},{id:"n37",tier:2,category:"節慶・天后誕",question:"香港常說的天后誕，傳統生日日期是農曆哪一天？",options:["三月二十三","二月初二","四月初八","六月初六"],answer:0,explanation:"天后誕傳統日期是農曆三月二十三，但各社區活動亦可另選日子。記得生日，不代表所有地方都同一日開席，出發仍要睇主辦安排。",hint:"四月初八是佛誕；先排除相近但不同的節誕。",art:"temple",focus:{x:50,y:50},modes:["original"],imageAlt:"香港本地文化主題原創插畫；並非本題地點實景、製作工序圖或官方文件。",source:{label:"非遺辦事處・香港天后誕",url:"https://www.icho.hk/tc/web/icho/representative_list_tin_hau.html"},review:"2026-11-26核對列明來源；以文字知識作答，插畫只作主題輔助。"},{id:"n38",tier:2,category:"文化・沙頭角魚燈",question:"哪個香港東北邊境社區，以魚燈舞及魚燈廣場展示當地文化？",options:["大澳","沙頭角","榕樹灣","荔枝窩"],answer:1,explanation:"魚燈舞以魚形燈具配合舞步，承載沿海社區傳統。這裏認識文化道具，不是問哪種魚最適合清蒸，唔好即刻諗晚餐。",hint:"留意東北邊境的位置，與區內展示魚燈舞的廣場。",art:"lantern",focus:{x:50,y:50},modes:["original"],imageAlt:"香港本地文化主題原創插畫；並非本題地點實景、製作工序圖或官方文件。",source:{label:"香港旅發局・沙頭角魚燈舞",url:"https://www.discoverhongkong.com/tc/neighbourhoods/sha-tau-kok/unmissable-adventures-await-at-sha-tau-kok.html"},review:"2026-11-26核對列明來源；以文字知識作答，插畫只作主題輔助。"},{id:"n39",tier:3,category:"非遺・粵劇年表",question:"粵劇在哪一年列入聯合國教科文組織的人類非物質文化遺產代表作名錄？",options:["2003年","2006年","2009年","2011年"],answer:2,explanation:"粵劇於2009年列入該代表作名錄，申報涉及粵港澳的共同文化傳承。台上一分鐘，台下十年功；考名錄年份，就要多一點年表功。",hint:"不要與香港公布本地代表作名錄的2017年混淆。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,imageAlt:"香港本地文化主題原創插畫；並非本題地點實景、製作工序圖或官方文件。",source:{label:"非遺辦事處・國家級非遺香港項目",url:"https://www.icho.hk/documents/Intangible-Cultural-Heritage-Inventory/items_on_the_national_list_of_ich_in_hk_TC.pdf"},review:"2026-11-26核對列明來源；以文字知識作答，插畫只作主題輔助。"},{id:"n40",tier:3,category:"非遺・大坑火龍",question:"按大坑舞火龍的傳統紮作，龍身等部分主要以哪種草料紮成？",options:["香茅","水燈心草","班蘭葉","珍珠草"],answer:3,explanation:"大坑火龍以珍珠草紮成各部分，再插上線香等；不同地區的火龍材料可有分別。答大坑就跟大坑，唔好把隔離村的手藝都當同款。",hint:"關鍵是大坑的做法，不可把所有舞火龍工藝一概而論。",art:"dragon",focus:{x:50,y:50},modes:["text"],textOnly:!0,imageAlt:"香港本地文化主題原創插畫；並非本題地點實景、製作工序圖或官方文件。",source:{label:"非遺辦事處・首份非遺清單",url:"https://www.icho.hk/documents/Intangible-Cultural-Heritage-Inventory/First_hkich_inventory_C.pdf"},review:"2026-11-26核對列明來源；以文字知識作答，插畫只作主題輔助。"},{id:"n41",tier:1,category:"地區・流浮山",question:"流浮山最具代表性的傳統水產養殖及海味文化，常與哪種貝類相連？",options:["蠔","鮑魚","青口","帶子"],answer:0,explanation:"流浮山與養蠔、曬蠔等產業有深厚聯繫。去海味舖眼花繚亂，先認住主角；唔係所有有殼海鮮都叫同一款。",hint:"想想流浮山與后海灣沿岸的傳統生計。",art:"ferry",focus:{x:50,y:50},modes:["original"],imageAlt:"香港本地文化主題原創插畫；並非本題地點實景、製作工序圖或官方文件。",source:{label:"香港自遊樂在18區・流浮山",url:"https://www.gohk.gov.hk/tc/spots/spot_detail.php?spot=Lau+Fau+Shan"},review:"2026-11-26核對列明來源；以文字知識作答，插畫只作主題輔助。"},{id:"n42",tier:1,category:"郊遊・八仙嶺",question:"八仙嶺的名稱所指，主要是山脊上哪種地形組合？",options:["八個山谷湖泊","八座相連山峰","八條平行河道","八座離岸小島"],answer:1,explanation:"八仙嶺由八座山峰組成，名稱與八仙意象相連。個名雖然好有仙氣，真正行起上來仍然要靠雙腳，唔會自動獲得騰雲功能。",hint:"數字是線索，但還要認清它描述山峰還是水體。",art:"mountain",focus:{x:50,y:50},modes:["original"],imageAlt:"香港本地文化主題原創插畫；並非本題地點實景、製作工序圖或官方文件。",source:{label:"漁護署郊野樂行・八仙嶺",url:"https://www.afcd.gov.hk/tc_chi/country/cou_vis/cou_vis_cou/cou_vis_cou_psl/cou_vis_cou_psl.html"},review:"2026-11-26核對列明來源；以文字知識作答，插畫只作主題輔助。"},{id:"n43",tier:1,category:"離島・南丫島",question:"榕樹灣與索罟灣這兩個街坊及遊客熟悉的地方，位於哪個島？",options:["坪洲","長洲","南丫島","大嶼山"],answer:2,explanation:"榕樹灣及索罟灣都在南丫島，各有聚落與海鮮餐館。約朋友「碼頭等」仍要講清楚邊個灣，否則同島都可以等到天黑。",hint:"不是長洲的長洲灣，也不是坪洲碼頭。",art:"ferry",focus:{x:50,y:50},modes:["original"],imageAlt:"香港本地文化主題原創插畫；並非本題地點實景、製作工序圖或官方文件。",source:{label:"香港自遊樂在18區・南丫島",url:"https://www.gohk.gov.hk/tc/spots/spot_detail.php?spot=Lamma+Island"},review:"2026-11-26核對列明來源；以文字知識作答，插畫只作主題輔助。"},{id:"n44",tier:2,category:"生態・黑臉琵鷺",question:"香港濕地常見的黑臉琵鷺，最具代表性的嘴喙形狀是哪一款？",options:["短而厚，呈錐形","細長向下急彎，呈鐮形","末端強烈鉤曲，呈鷹鉤形","前端扁闊，呈匙形"],answer:3,explanation:"黑臉琵鷺的獨特喙端像匙子，配合牠在淺水中覓食。像餐具只是外形比喻，觀鳥時仍應保持距離，讓牠安心開飯。",hint:"英文名Spoonbill中的spoon，也在描述嘴喙外形。",art:"river",focus:{x:50,y:50},modes:["original"],imageAlt:"香港本地文化主題原創插畫；並非本題地點實景、製作工序圖或官方文件。",source:{label:"香港生物多樣性資訊站・黑臉琵鷺",url:"https://bih.gov.hk/tc/fast-facts/iconic-species/index-id-6.html"},review:"2026-11-26核對列明來源；以文字知識作答，插畫只作主題輔助。"},{id:"n45",tier:2,category:"郊遊・城門樹林",question:"城門水塘岸邊，以淺色樹幹和層層樹皮聞名的樹林主要是哪種樹？",options:["白千層","細葉榕","木棉","落羽杉"],answer:0,explanation:"城門水塘的白千層林是著名景觀，水位不同會呈現不同景色。樹皮似好多層紙，也唔代表可以隨手揭一張做書籤。",hint:"名字點出淺色、層狀樹皮，別與秋色照片中的樹種混淆。",art:"tree",focus:{x:50,y:50},modes:["text"],imageAlt:"香港本地文化主題原創插畫；並非本題地點實景、製作工序圖或官方文件。",source:{label:"漁護署郊野樂行・城門白千層林",url:"https://www.hiking.gov.hk/promote/info/id/V2JJVDNVR25Lc0lnV1pZdC9NdHVBZz09"},review:"2026-11-26核對列明來源；以文字知識作答，插畫只作主題輔助。",textOnly:!0},{id:"n46",tier:2,category:"地理・汀九橋",question:"汀九橋跨海連接的兩端，主要是哪一組地方？",options:["汀九與馬灣","汀九與青衣","青衣與坪洲","馬灣與深井"],answer:1,explanation:"汀九橋連接汀九與青衣，是新界與青衣道路網的重要通道。附近橋多，認錯一個「青」字，個腦就可能兜多一個圈。",hint:"別與連接青衣和馬灣的青馬大橋混淆。",art:"harbour",focus:{x:50,y:50},modes:["original"],imageAlt:"香港本地文化主題原創插畫；並非本題地點實景、製作工序圖或官方文件。",source:{label:"路政署・汀九橋及高架引道",url:"https://www.hyd.gov.hk/tc/information_corner/hyd_factsheets/doc/C_TingKau_Bridge.pdf"},review:"2026-11-26核對列明來源；以文字知識作答，插畫只作主題輔助。"},{id:"n47",tier:2,category:"地區・梅窩礦業",question:"梅窩銀礦洞的歷史生產，主要開採哪一種金屬？",options:["錫","鎢","銀","鉛"],answer:2,explanation:"梅窩銀礦洞曾出產白銀，後因礦石含銀量低而停止生產。聽見「銀礦」唔等於今日仲可以入去發達，本題只談礦業歷史。",hint:"地名保留了昔日礦業記憶，並非指沙灘真的鋪滿銀。",art:"mountain",focus:{x:50,y:50},modes:["original"],imageAlt:"香港本地文化主題原創插畫；並非本題地點實景、製作工序圖或官方文件。",source:{label:"香港自遊樂在18區・銀礦洞及銀礦瀑布",url:"https://www.gohk.gov.hk/tc/spots/spot_detail.php?spot=Silvermine+Cave+and+Silvermine+Waterfalls"},review:"2026-11-26核對列明來源；以文字知識作答，插畫只作主題輔助。"},{id:"n48",tier:3,category:"地質・馬屎洲",question:"馬屎洲東南岸具代表性的沉積地層，主要屬於哪個地質時期？",options:["泥盆紀","侏羅紀","白堊紀","二疊紀"],answer:3,explanation:"地質公園介紹馬屎洲東南岸的二疊紀地層，包括受變形的泥岩、粉砂岩和砂岩。行一段海岸，岩石資歷可能比你想像中老得多。",hint:"它是古生代地層，但不是香港最古老的泥盆紀黃竹角咀組。",art:"geopark",focus:{x:50,y:50},modes:["text"],textOnly:!0,imageAlt:"香港本地文化主題原創插畫；並非本題地點實景、製作工序圖或官方文件。",source:{label:"香港地質公園・馬屎洲",url:"https://www.geopark.gov.hk/tc/discover/attractions/ma-shi-chau"},review:"2026-11-26核對列明來源；以文字知識作答，插畫只作主題輔助。"},{id:"n49",tier:3,category:"地質・黃竹角咀",question:"香港黃竹角咀組的古老沉積岩，屬於哪個地質時期？",options:["泥盆紀","二疊紀","侏羅紀","白堊紀"],answer:0,explanation:"黃竹角咀組屬泥盆紀，是香港古老出露岩層的重要代表。這題鬥年代，唔係鬥石頭看起來有幾多皺紋；要按地質研究判斷。",hint:"比二疊紀馬屎洲地層更早，仍屬古生代。",art:"geopark",focus:{x:50,y:50},modes:["text"],textOnly:!0,imageAlt:"香港本地文化主題原創插畫；並非本題地點實景、製作工序圖或官方文件。",source:{label:"土木工程拓展署・香港地質考察指引",url:"https://www.cedd.gov.hk/filemanager/tc/content_429/hkgeologyguidebook_c.pdf"},review:"2026-11-26核對列明來源；以文字知識作答，插畫只作主題輔助。"},{id:"n50",tier:3,category:"古蹟・鶴咀燈塔",question:"香港現存歷史最悠久的鶴咀燈塔，首次啟用於哪一年？",options:["1865年","1875年","1885年","1893年"],answer:1,explanation:"鶴咀燈塔在1875年首次啟用，後來曾停用及恢復運作。問「首次」就要睇清楚，唔好用後來重新亮燈的年份頂上。",hint:"它的啟用時間早於1893年的橫瀾燈塔。",art:"harbour",focus:{x:50,y:50},modes:["text"],textOnly:!0,imageAlt:"香港本地文化主題原創插畫；並非本題地點實景、製作工序圖或官方文件。",source:{label:"古蹟辦・鶴咀燈塔",url:"https://www.amo.gov.hk/tc/historic-buildings/monuments/hong-kong-island/monuments_80/index.html"},review:"2026-11-26核對列明來源；以文字知識作答，插畫只作主題輔助。"},{id:"n51",tier:1,category:"用語・香港電影",question:"朋友提醒「套戲就快落畫」，通常是指甚麼？",options:["電影即將首次開拍","電影即將開始售賣預售票","該輪戲院放映即將結束","電影即將改名上映"],answer:2,explanation:"在香港電影語境，「落畫」指結束一輪戲院上映，不代表影片從此不能再重映或在其他平台觀看。拖到下個月，可能就真係只剩張海報畀你睇。",hint:"與「上畫」相對；本題說的是戲院檔期。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,imageAlt:"香港本地文化主題原創插畫；並非本題地點實景、製作工序圖或官方文件。",source:{label:"香港電影發展局・香港電影業資料2024",url:"https://www.fdc.gov.hk/tc/publication/Hong%20Kong%20Film%20Industry%20Data%202024.pdf"},review:"2026-11-26核對列明來源；以文字知識作答，插畫只作主題輔助。"},{id:"n52",tier:1,category:"用語・港幣小數",question:"街坊說「一毫子」，通常是指多少港幣？",options:["0.01元","0.5元","1元","0.1元"],answer:3,explanation:"「毫子」是毫或角的口語，一毫子就是十分之一元。銀碼細細，找錯數照樣會被老闆一眼發現，唔好睇少街坊心算。",hint:"十毫子合成一元，不是一百分之一元。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,imageAlt:"香港本地文化主題原創插畫；並非本題地點實景、製作工序圖或官方文件。",source:{label:"粵典・毫子",url:"https://words.hk/zidin/%E6%AF%AB%E5%AD%90"},review:"2026-11-26核對列明來源；以文字知識作答，插畫只作主題輔助。"},{id:"n53",tier:1,category:"文化・二十元鈔票",question:"2018系列三家發鈔銀行的20元鈔票，共同背面主題是哪一項？",options:["點心和飲茶文化","香港地質公園","粵劇文化","本港蝴蝶"],answer:0,explanation:"2018系列把同面額的設計主題統一，20元以點心及飲茶文化為題。望住張鈔票想飲茶好合理，但唔好把它當成已付款的點心單。",hint:"先排除屬500元的地質公園，再想想茶樓生活。",art:"milk",focus:{x:50,y:50},modes:["text"],textOnly:!0,imageAlt:"香港本地文化主題原創插畫；並非本題地點實景、製作工序圖或官方文件。",source:{label:"香港政府・2018香港新鈔票系列",url:"https://www.info.gov.hk/gia/general/201807/24/P2018072400547.htm"},review:"2026-11-26核對列明來源；以文字知識作答，插畫只作主題輔助。"},{id:"n54",tier:2,category:"文化・五十元鈔票",question:"2018系列三家發鈔銀行的50元鈔票，共同背面主題是甚麼？",options:["香港飲茶文化","在香港棲息的蝴蝶","香港粵劇文化","香港地質公園"],answer:1,explanation:"2018系列50元的主題是本港蝴蝶；與20、100及500元各有分工。銀紙上有蝴蝶，銀包啲錢都唔應該因此飛走。",hint:"100元是粵劇，500元是地質公園。",art:"tree",focus:{x:50,y:50},modes:["text"],textOnly:!0,imageAlt:"香港本地文化主題原創插畫；並非本題地點實景、製作工序圖或官方文件。",source:{label:"香港政府・2018香港新鈔票系列",url:"https://www.info.gov.hk/gia/general/201807/24/P2018072400547.htm"},review:"2026-11-26核對列明來源；以文字知識作答，插畫只作主題輔助。"},{id:"n55",tier:2,category:"文化・發鈔銀行",question:"以下哪組全部都是香港三家發鈔銀行？",options:["滙豐、恒生及中國銀行（香港）","渣打、東亞及中國銀行（香港）","滙豐、渣打及中國銀行（香港）","滙豐、渣打及星展"],answer:2,explanation:"香港三家發鈔銀行是滙豐、渣打及中國銀行（香港）。平日戶口多到密碼都忘記，也不代表每家銀行都會發行自己的港鈔。",hint:"分清「提供銀行服務」與「獲授權發行銀行紙幣」。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,imageAlt:"香港本地文化主題原創插畫；並非本題地點實景、製作工序圖或官方文件。",source:{label:"香港政府・2018香港新鈔票系列",url:"https://www.info.gov.hk/gia/general/201807/24/P2018072400547.htm"},review:"2026-11-26核對列明來源；以文字知識作答，插畫只作主題輔助。"},{id:"n56",tier:2,category:"日常・斜坡編號",question:"街邊斜坡上的登記編號，主要可怎樣配合政府斜坡資訊系統使用？",options:["辨認斜坡施工承建商的商業登記","劃分附近私人地段的法定業權","標示附近樓宇的統一建築年期","檢索及辨認該幅登記斜坡的資料"],answer:3,explanation:"斜坡編號可協助搜尋對應登記斜坡的資料，不等於即時安全評級或崩塌預言。見到編號像密碼，其實係幫斜坡認清身分。",hint:"用途是識別及查資料，並非靠一組號碼預測未來。",art:"mountain",focus:{x:50,y:50},modes:["original"],imageAlt:"香港本地文化主題原創插畫；並非本題地點實景、製作工序圖或官方文件。",source:{label:"土木工程拓展署・斜坡資訊系統",url:"https://hkss.cedd.gov.hk/hkss/chi/sis.aspx"},review:"2026-11-26核對列明來源；以文字知識作答，插畫只作主題輔助。"},{id:"n57",tier:3,category:"金融・聯繫匯率年表",question:"香港現行聯繫匯率制度在1980年代哪一年開始實施？",options:["1983年","1980年","1985年","1988年"],answer:0,explanation:"香港在1983年10月實施聯繫匯率制度。本題只問制度起始年，不代表任何兌換店都提供同一買賣價；換錢之前仍要睇清牌價。",hint:"在1980年代前半段，別與後來的金融事件混淆。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,imageAlt:"香港本地文化主題原創插畫；並非本題地點實景、製作工序圖或官方文件。",source:{label:"金管局・聯繫匯率制度問答",url:"https://www.hkma.gov.hk/media/gb_chi/doc/key-information/insight/20131014c1.pdf"},review:"2026-11-26核對列明來源；以文字知識作答，插畫只作主題輔助。"},{id:"n58",tier:3,category:"文化・中大校訓",question:"香港中文大學校訓「博文約禮」的語句，出自哪部典籍？",options:["《孟子》","《論語》","《大學》","《中庸》"],answer:1,explanation:"中大官方介紹指出，校訓源自《論語》中孔子的教育規訓。四本都耳熟，最怕考試時腦裏自動開咗「四書隨機播放」。",hint:"相關原句是「君子博學於文，約之以禮」。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,imageAlt:"香港本地文化主題原創插畫；並非本題地點實景、製作工序圖或官方文件。",source:{label:"香港中文大學・校訓",url:"https://www.cuhk.edu.hk/chinese/aboutus/mission.html"},review:"2026-11-26核對列明來源；以文字知識作答，插畫只作主題輔助。"},{id:"n59",tier:3,category:"文化・香港大學年表",question:"香港大學正式成立的年份是哪一年？",options:["1901年","1912年","1911年","1921年"],answer:2,explanation:"香港大學在1911年成立，1912年開課。創校與開課有一年之別，唔好以為第一堂上鐘，先算大學正式存在。",hint:"題目問成立，並非第一批教學課程開始的1912年。",art:"clock",focus:{x:50,y:50},modes:["text"],textOnly:!0,imageAlt:"香港本地文化主題原創插畫；並非本題地點實景、製作工序圖或官方文件。",source:{label:"香港大學・歷史及創校年份",url:"https://handbook.hku.hk/ug/full-time-2026-27/about-the-university/past-and-present.html"},review:"2026-11-26核對列明來源；以文字知識作答，插畫只作主題輔助。"},{id:"n60",tier:3,category:"測繪・香港方格網",question:"「香港1980方格網」採用哪種地圖投影法建立本地平面坐標？",options:["卡西尼投影","蘭伯特正形圓錐投影","方位等距投影","橫墨卡托投影"],answer:3,explanation:"地政總署介紹，香港1980方格網以香港大地基準1980及橫墨卡托投影為根據。平時睇地圖找餐廳，今次要認識張地圖背後的數學。",hint:"不要把早期本地方格網的投影，與1980方格網混為一談。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,imageAlt:"香港本地文化主題原創插畫；並非本題地點實景、製作工序圖或官方文件。",source:{label:"地政總署・香港地理資料",url:"https://www.landsd.gov.hk/tc/resources/mapping-information/hk-geographic-data.html"},review:"2026-11-26核對列明來源；以文字知識作答，插畫只作主題輔助。"}].map(t=>Object.freeze({...t,options:Object.freeze(t.options),source:Object.freeze(t.source),focus:Object.freeze(t.focus),modes:Object.freeze(t.modes)})));var J=Object.freeze([{id:"l01",tier:1,category:"飲食・懷舊小食",question:"傳統砵仔糕常見黃糖和白糖版本，糕內常見一粒粒的配料通常是甚麼？",options:["紅豆","紅腰豆","紅棗肉","紅皮花生"],answer:0,explanation:"傳統紅豆砵仔糕會加入紅豆，黃糖或白糖則影響顏色與風味；也有不加紅豆的版本。名字有「仔」，份量細細都可以好有存在感。",hint:"不是每款砵仔糕都有豆；有豆的版本，最常見是哪種豆？",art:"bun",focus:{x:50,y:50},modes:["text"],textOnly:!0,imageAlt:"香港本地文化主題原創插畫，並非本題地點的實景或官方圖則。",source:{label:"香港旅遊發展局・紅豆砵仔糕",url:"https://hkwdf.discoverhongkong.com/zh-cn/food/1603"},review:"2026-11-26核對來源；問法不依賴插畫辨認，保留做法、歷史與俗語的適用範圍。"},{id:"l02",tier:1,category:"飲食・街頭湯羹",question:"常見港式碗仔翅用哪種材料做出一絲絲、近似翅絲的口感？",options:["意粉","粉絲","河粉","烏冬"],answer:1,explanation:"常見碗仔翅以粉絲配冬菇、肉絲等材料煮成濃羹，並不代表一定含魚翅；個別配方仍應向店家確認。碗仔細細，個名可以好有排場。",hint:"諗吓浸軟後會變透明、可以剪短嗰種細條麵。",art:"milk",focus:{x:50,y:50},modes:["text"],textOnly:!0,imageAlt:"香港本地文化主題原創插畫，並非本題地點的實景或官方圖則。",source:{label:"澳門公共圖書館・港式小食食譜",url:"https://www.library.gov.mo/uploads/attachment/2026-01/16753696757e5656e7.pdf"},review:"2026-11-26核對來源；問法不依賴插畫辨認，保留做法、歷史與俗語的適用範圍。"},{id:"l03",tier:1,category:"飲食・糖水舖",question:"糖水舖一碗黑芝麻糊，其主要芝麻香味來自哪種食材？",options:["黑糯米","黑豆","黑芝麻","黑木耳"],answer:2,explanation:"黑芝麻糊以黑芝麻研磨、調製成糊，常見冷熱供應。黑色甜品唔只一款，認味道比單靠顏色可靠。",hint:"題名已經提供原材料線索；唔好被其他黑色食材帶走。",art:"milk",focus:{x:50,y:50},modes:["text"],textOnly:!0,imageAlt:"香港本地文化主題原創插畫，並非本題地點的實景或官方圖則。",source:{label:"香港旅遊發展局・香港傳統甜品",url:"https://www.discoverhongkong.com/tc/food-and-drink/must-try-traditional-hong-kong-desserts.html"},review:"2026-11-26核對來源；問法不依賴插畫辨認，保留做法、歷史與俗語的適用範圍。"},{id:"l04",tier:1,category:"飲食・街頭小食",question:"煎釀三寶常把魚肉餡釀在哪一組食材裡，再煎炸？",options:["蓮子、百合及銀杏","蘋果、梨及蜜瓜","燒鴨、叉燒及燒肉","茄子、青椒及豆腐類"],answer:3,explanation:"常見做法是在茄子、青椒、豆腐等釀入魚肉餡，再煎香或炸熟。三寶的實際組合可因店舖而異，不是全港統一出廠名單。",hint:"「釀」係把餡料放入另一種食材，唔係將三樣餸擺埋一碟。",art:"bun",focus:{x:50,y:50},modes:["text"],textOnly:!0,imageAlt:"香港本地文化主題原創插畫，並非本題地點的實景或官方圖則。",source:{label:"香港旅遊發展局・街頭美食",url:"https://www.discoverhongkong.com/tc/food-and-drink/must-try-street-food-in-hong-kong.html"},review:"2026-11-26核對來源；問法不依賴插畫辨認，保留做法、歷史與俗語的適用範圍。"},{id:"l05",tier:2,category:"飲食・港式甜品",question:"楊枝甘露最具代表性的兩款水果配搭是哪一組？",options:["芒果與柚子","木瓜與香蕉","榴槤與椰棗","草莓與蘋果"],answer:0,explanation:"芒果和柚子是楊枝甘露的代表配搭，常與西米及奶或椰奶類材料一起調製。配方會有變化，但唔係見到黃色就一律叫芒果布甸。",hint:"一種香甜金黃，另一種帶清新微酸的果肉。",art:"milk",focus:{x:50,y:50},modes:["text"],textOnly:!0,imageAlt:"香港本地文化主題原創插畫，並非本題地點的實景或官方圖則。",source:{label:"香港旅遊發展局・香港傳統甜品",url:"https://www.discoverhongkong.com/tc/food-and-drink/must-try-traditional-hong-kong-desserts.html"},review:"2026-11-26核對來源；問法不依賴插畫辨認，保留做法、歷史與俗語的適用範圍。"},{id:"l06",tier:2,category:"飲食・豆品小店",question:"公和荳品一類傳統豆品店的豆腐花，主要由哪種豆類製成？",options:["紅豆","黃豆","綠豆","鷹嘴豆"],answer:1,explanation:"豆腐花主要以黃豆製成的豆漿凝結而成，常配糖漿、薑糖等。凝結得嫩滑係手藝，唔係把豆腐切細就自動升級做甜品。",hint:"豆漿、豆腐同豆腐花，主要原材料有共同之處。",art:"milk",focus:{x:50,y:50},modes:["text"],textOnly:!0,imageAlt:"香港本地文化主題原創插畫，並非本題地點的實景或官方圖則。",source:{label:"香港旅遊發展局・香港傳統甜品",url:"https://www.discoverhongkong.com/tc/food-and-drink/must-try-traditional-hong-kong-desserts.html"},review:"2026-11-26核對來源；問法不依賴插畫辨認，保留做法、歷史與俗語的適用範圍。"},{id:"l07",tier:2,category:"飲食・茶餐廳用語",question:"茶餐廳常見的「走青」，通常是要求食物不要加入哪類配料？",options:["所有綠色蔬菜","所有辛辣醬汁","蔥、芫荽等綠色佐料","所有湯汁和醬油"],answer:2,explanation:"「走青」常指不要蔥、芫荽等綠色佐料，不是要求全餐不能有任何綠色食物；對特定食材過敏或不吃，應直接講清楚。",hint:"「青」通常指撒在麵或飯上面的綠色佐料。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,imageAlt:"香港本地文化主題原創插畫，並非本題地點的實景或官方圖則。",source:{label:"新界鄉議局元朗區中學・茶餐廳特色用語",url:"https://nthykyldss.edu.hk/attachment/publication/publicationPdf/1711522589r84c9.pdf"},review:"2026-11-26核對來源；問法不依賴插畫辨認，保留做法、歷史與俗語的適用範圍。"},{id:"l08",tier:2,category:"飲食・水吧用語",question:"按常見茶餐廳用法，點「茶走」通常以甚麼代替奶茶的淡奶及另外加入的砂糖？",options:["鮮忌廉","椰漿","奶粉","煉奶"],answer:3,explanation:"常見「茶走」用煉奶提供奶味和甜味，取代淡奶及另外加糖；各店細節可不同，並不等於無糖奶茶。「走」咗砂糖，未必走得甩甜味。",hint:"有一種奶本身已經帶甜味；不等於點了走甜。",art:"milk",focus:{x:50,y:50},modes:["original"],imageAlt:"香港本地文化主題原創插畫，並非本題地點的實景或官方圖則。",source:{label:"新界鄉議局元朗區中學・茶餐廳特色用語",url:"https://nthykyldss.edu.hk/attachment/publication/publicationPdf/1711522589r84c9.pdf"},review:"2026-11-26核對來源；問法不依賴插畫辨認，保留做法、歷史與俗語的適用範圍。"},{id:"l09",tier:2,category:"飲食・傳統麵食",question:"傳統「竹昇麵」的名稱，與製麵時哪種工序最直接有關？",options:["用竹竿借助身體重量壓麵糰","用竹筒盛湯煮麵","用竹葉包麵團發酵","把麵條掛在竹林曬乾"],answer:0,explanation:"竹昇製麵以竹竿壓麵糰，是傳統手工技藝。名稱來自工具和工序，不表示麵裡加了竹筍；壓麵功夫唔係餐牌上的裝飾詞。",hint:"留意「竹昇」作為工具，點樣幫師傅把麵糰壓實。",art:"bun",focus:{x:50,y:50},modes:["text"],textOnly:!0,imageAlt:"香港本地文化主題原創插畫，並非本題地點的實景或官方圖則。",source:{label:"坤記竹昇麵・傳統竹昇打麵",url:"https://www.kwankee-hk.com/"},review:"2026-11-26核對來源；問法不依賴插畫辨認，保留做法、歷史與俗語的適用範圍。"},{id:"l10",tier:3,category:"飲食・魚蛋工藝",question:"製作魚蛋時加鹽，除了調味，亦有助魚肉中的哪類物質溶出，形成黏結的魚漿？",options:["魚骨中的鈣質","肌原纖維蛋白","魚皮表面的色素","魚肝內的維他命"],answer:1,explanation:"科學館介紹，鹽有助魚肉中的肌原纖維蛋白溶出，肌球蛋白是魚蛋成形的關鍵之一。彈牙靠材料和製作，唔係真係加咗橡筋。",hint:"魚肉能打成有黏性的漿，關鍵與肌肉的蛋白質有關。",art:"bun",focus:{x:50,y:50},modes:["text"],textOnly:!0,imageAlt:"香港本地文化主題原創插畫，並非本題地點的實景或官方圖則。",source:{label:"香港科學館・魚蛋製作的科學",url:"https://hk.science.museum/tc/web/scm/online-explore/qkpost-roadshow-food/fishball.html"},review:"2026-11-26核對來源；問法不依賴插畫辨認，保留做法、歷史與俗語的適用範圍。"},{id:"l11",tier:1,category:"交通・電車日常",question:"一般乘搭香港電車，車資通常在哪個時候、哪個位置繳付？",options:["在後閘上車前","坐下後由車長逐位收取","在前閘下車時","到達總站後在月台購票"],answer:2,explanation:"一般電車在前閘下車時繳付車資；一般上落客安排為後上前落，現場指示及特別安排為準。唔使跟住巴士習慣，一上車就急住搵機拍卡。",hint:"電車的付款時間與一般巴士上車付款不同。",art:"tram",focus:{x:50,y:50},modes:["original"],imageAlt:"香港本地文化主題原創插畫，並非本題地點的實景或官方圖則。",source:{label:"香港電車・時間表及車費",url:"https://www.hktramways.com/tc/schedules-fares/"},review:"2026-11-26核對來源；問法不依賴插畫辨認，保留做法、歷史與俗語的適用範圍。"},{id:"l12",tier:1,category:"交通・新界西北",question:"香港輕鐵主要穿梭哪三個地區？",options:["沙田、大埔及粉嶺","中環、灣仔及北角","觀塘、將軍澳及西貢","屯門、元朗及天水圍"],answer:3,explanation:"輕鐵主要服務屯門、元朗、天水圍，並接駁屯馬綫。線路密密麻麻，先睇目的地同路綫編號，唔好單憑車色估路。",hint:"這套地面鐵路網絡集中在新界西北。",art:"steel-seats",focus:{x:50,y:50},modes:["original"],imageAlt:"香港本地文化主題原創插畫，並非本題地點的實景或官方圖則。",source:{label:"港鐵・輕鐵及巴士服務",url:"https://www.mtr.com.hk/ch/customer/services/lt_bus_index.html"},review:"2026-11-26核對來源；問法不依賴插畫辨認，保留做法、歷史與俗語的適用範圍。"},{id:"l13",tier:1,category:"交通・鐵路發展",question:"東鐵綫過海段在2022年通車後，列車延伸至哪個港島轉車站？",options:["金鐘","中環","鰂魚涌","堅尼地城"],answer:0,explanation:"東鐵綫過海段於2022年5月15日通車，經會展站到金鐘，讓新界東北與港島可直接以東鐵綫連接。日期限定歷史事件，不把未來延線當既成事實。",hint:"這個站同時接駁港島綫、荃灣綫及南港島綫。",art:"steel-seats",focus:{x:50,y:50},modes:["original"],imageAlt:"香港本地文化主題原創插畫，並非本題地點的實景或官方圖則。",source:{label:"路政署・沙田至中環線",url:"https://www.hyd.gov.hk/tc/our_projects/railway_projects/scl/index.html"},review:"2026-11-26核對來源；問法不依賴插畫辨認，保留做法、歷史與俗語的適用範圍。"},{id:"l14",tier:1,category:"交通・小渡輪",question:"在香港仔漁港聽到「街渡」，通常是指哪類交通服務？",options:["連接跨境碼頭的高速客輪","接載乘客往返短途水域的小型渡輪","設有住宿的遠洋觀光郵輪","運載車輛過海的汽車渡輪"],answer:1,explanation:"街渡一般指服務短途水道或沿岸社區的小型渡輪，香港仔與鴨脷洲一帶可見這類水上交通。它不是在街道上行走的渡輪。",hint:"個「渡」字，係真正過水嗰種。",art:"ferry",focus:{x:50,y:50},modes:["original"],imageAlt:"香港本地文化主題原創插畫，並非本題地點的實景或官方圖則。",source:{label:"香港旅遊發展局・香港仔漁港",url:"https://www.discoverhongkong.com/tc/place-to-go/travel.guide-aberdeen-harbour.html"},review:"2026-11-26核對來源；問法不依賴插畫辨認，保留做法、歷史與俗語的適用範圍。"},{id:"l15",tier:2,category:"交通・離島生活",question:"新渡輪「橫水渡」的常規航線，串連哪一組地點？",options:["中環、尖沙咀、紅磡及北角","西貢、塔門、東平洲及馬料水","坪洲、梅窩、芝麻灣及長洲","香港仔、赤柱、蒲台及鴨脷洲"],answer:2,explanation:"橫水渡常規航線串連坪洲、梅窩、芝麻灣與長洲，讓乘客毋須每次返回中環轉船。工程、天氣或班次調整以營辦商公告為準，本題不考即時船期。",hint:"這條線在大嶼山周邊和離島之間穿梭。",art:"ferry",focus:{x:50,y:50},modes:["original"],imageAlt:"香港本地文化主題原創插畫，並非本題地點的實景或官方圖則。",source:{label:"新渡輪・橫水渡航線",url:"https://www.sunferry.com.hk/zh/route-and-fare/timetable?route=inter-islands"},review:"2026-11-26核對來源；問法不依賴插畫辨認，保留做法、歷史與俗語的適用範圍。"},{id:"l16",tier:2,category:"交通・山頂纜車",question:"山頂纜車沿斜坡路軌行駛，主要靠甚麼牽引車廂？",options:["靠車上齒輪與中央齒軌嚙合爬升","以架空吊纜直接懸掛車廂","只靠車上動力驅動車輪爬升","鋼纜牽引系統"],answer:3,explanation:"山頂纜車屬纜索鐵路，以鋼纜牽引。它與懸在空中的吊車不同，車廂在路軌上行走；名稱有「纜」，但唔一定要吊起架車。",hint:"纜車在路軌上走，牽引裝置藏在另一個關鍵字。",art:"peak",focus:{x:50,y:50},modes:["original"],imageAlt:"香港本地文化主題原創插畫，並非本題地點的實景或官方圖則。",source:{label:"山頂纜車・歷史與牽引系統",url:"https://www.thepeak.com.hk/zh-hant/heritage/history-of-the-peak-tram"},review:"2026-11-26核對來源；問法不依賴插畫辨認，保留做法、歷史與俗語的適用範圍。"},{id:"l17",tier:2,category:"交通・維港航線",question:"天星小輪的中環—尖沙咀航線，連接哪一組地域？",options:["香港島與九龍半島","九龍半島與大嶼山","香港島與南丫島","大嶼山與新界東北"],answer:0,explanation:"中環在香港島，尖沙咀在九龍半島，兩地隔維多利亞港相望。坐船可以看風景，但唔會因此把兩邊坐到變成同一個區。",hint:"想想中環和尖沙咀分別位於維港哪一邊。",art:"ferry",focus:{x:50,y:50},modes:["original"],imageAlt:"香港本地文化主題原創插畫，並非本題地點的實景或官方圖則。",source:{label:"天星小輪・航線及服務",url:"https://www.starferry.com.hk/tc/service"},review:"2026-11-26核對來源；問法不依賴插畫辨認，保留做法、歷史與俗語的適用範圍。"},{id:"l18",tier:2,category:"交通・轉綫知識",question:"截至2026年11月，美孚站可直接轉乘哪兩條港鐵綫？",options:["荃灣綫與觀塘綫","荃灣綫與屯馬綫","屯馬綫與東涌綫","東鐵綫與南港島綫"],answer:1,explanation:"美孚是荃灣綫和屯馬綫的轉車站。路綫名稱按核對日期限定；轉車要看指示，唔係見到同一種顏色扶手就當到站。",hint:"一條由中環往荃灣，另一條連接屯門與烏溪沙。",art:"steel-seats",focus:{x:50,y:50},modes:["original"],imageAlt:"香港本地文化主題原創插畫，並非本題地點的實景或官方圖則。",source:{label:"港鐵・美孚站服務",url:"https://www.mtr.com.hk/ch/customer/services/service_hours_search.php?query_type=search&station=20"},review:"2026-11-26核對來源；問法不依賴插畫辨認，保留做法、歷史與俗語的適用範圍。"},{id:"l19",tier:2,category:"古蹟・鐵路歷史",question:"香港鐵路博物館是在以下哪個舊車站原址改建而成？",options:["舊尖沙咀火車站","舊沙田火車站","舊大埔墟火車站","舊粉嶺火車站"],answer:2,explanation:"鐵路博物館位於舊大埔墟火車站原址，保留歷史車站建築並展示本地鐵路文物；不是現時港鐵大埔墟站的候車區。",hint:"博物館位於大埔墟市中心，舊車站與現役車站並非同一位置。",art:"clock",focus:{x:50,y:50},modes:["original"],imageAlt:"香港本地文化主題原創插畫，並非本題地點的實景或官方圖則。",source:{label:"香港文化博物館・香港鐵路博物館",url:"https://www.heritagemuseum.gov.hk/tc/branch_museum/railway.html"},review:"2026-11-26核對來源；問法不依賴插畫辨認，保留做法、歷史與俗語的適用範圍。"},{id:"l20",tier:2,category:"地理・橋樑連接",question:"鴨脷洲大橋連接鴨脷洲與哪個較大的島嶼？",options:["大嶼山","南丫島","青衣島","香港島"],answer:3,explanation:"鴨脷洲大橋跨越香港仔一帶水道，連接鴨脷洲與香港島南區。鴨脷洲雖然有「洲」，過橋後唔等於去了新界。",hint:"橋另一端接近黃竹坑及香港仔一帶。",art:"harbour",focus:{x:50,y:50},modes:["original"],imageAlt:"香港本地文化主題原創插畫，並非本題地點的實景或官方圖則。",source:{label:"地政總署・香港街地圖",url:"https://www.landsd.gov.hk/tc/resources/mapping-information/ehkg.html"},review:"2026-11-26核對來源；問法不依賴插畫辨認，保留做法、歷史與俗語的適用範圍。"},{id:"l21",tier:1,category:"古蹟・公屋記憶",question:"美荷樓保留下來的早期徙置大廈平面，常用哪個英文字母形容？",options:["H形","U形","Y形","Z形"],answer:0,explanation:"美荷樓兩翼由中間的建築體連接，形成H形平面，是早期公共房屋的代表。這是平面形狀，唔係樓宇評級的字母。",hint:"想想兩邊長樓之間，再加一條中間連接部分。",art:"tong-lau-arcade",focus:{x:50,y:50},modes:["text"],textOnly:!0,imageAlt:"香港本地文化主題原創插畫，並非本題地點的實景或官方圖則。",source:{label:"香港歷史文物・美荷樓資料冊",url:"https://www.heritage.gov.hk/filemanager/heritage/sc/content_56/Resource_kit_Mei_Ho_House.pdf"},review:"2026-11-26核對來源；問法不依賴插畫辨認，保留做法、歷史與俗語的適用範圍。"},{id:"l22",tier:1,category:"古蹟・藥店往事",question:"雷生春在戰前落成時，地下曾經營哪一類店舖？",options:["鐘錶維修店","跌打藥店","照相館","絲綢布莊"],answer:1,explanation:"雷生春地下曾設跌打藥店，上層作住宅。它的歷史與本地中醫藥及家族生活相連，不是單憑一個「春」字判斷為茶樓。",hint:"留意建築名稱曾經與一種本地藥品、醫藥服務有關。",art:"tong-lau-arcade",focus:{x:50,y:50},modes:["text"],textOnly:!0,imageAlt:"香港本地文化主題原創插畫，並非本題地點的實景或官方圖則。",source:{label:"古物古蹟辦事處・雷生春",url:"https://www.amo.gov.hk/tc/historic-buildings/monuments/kowloon/monuments_131/index.html"},review:"2026-11-26核對來源；問法不依賴插畫辨認，保留做法、歷史與俗語的適用範圍。"},{id:"l23",tier:1,category:"古蹟・灣仔街坊",question:"著名的「藍屋」建築群位於香港哪個地區？",options:["深水埗","荃灣","灣仔","大埔"],answer:2,explanation:"藍屋位於灣仔石水渠街一帶，與鄰近黃屋、橙屋形成建築群。記住社區故事，比只記外牆顏色更有意思。",hint:"地點在港島，靠近皇后大道東一帶。",art:"tong-lau-arcade",focus:{x:50,y:50},modes:["text"],textOnly:!0,imageAlt:"香港本地文化主題原創插畫，並非本題地點的實景或官方圖則。",source:{label:"民政事務總署・藍屋",url:"https://www.gohk.gov.hk/tc/spots/spot_detail.php?spot=The+Blue+House"},review:"2026-11-26核對來源；問法不依賴插畫辨認，保留做法、歷史與俗語的適用範圍。"},{id:"l24",tier:2,category:"古蹟・油麻地果欄",question:"油麻地果欄最具代表性的傳統批發商品是哪一類？",options:["鮮魚","布匹","藥材","水果"],answer:3,explanation:"油麻地果欄以水果批發聞名，歷史建築與街坊商業生活交織。到訪也應留意搬運工作，唔好把做生意的通道當成專用攝影棚。",hint:"名字中的「果」不只是裝飾。",art:"red-market-bag",focus:{x:50,y:50},modes:["original"],imageAlt:"香港本地文化主題原創插畫，並非本題地點的實景或官方圖則。",source:{label:"民政事務總署・油麻地果欄",url:"https://www.gohk.gov.hk/tc/spots/spot_detail.php?spot=Yau+Ma+Tei+Wholesale+Fruit+Market"},review:"2026-11-26核對來源；問法不依賴插畫辨認，保留做法、歷史與俗語的適用範圍。"},{id:"l25",tier:2,category:"古蹟・店舖活化",question:"「和昌大押」的「押」，反映建築曾與哪種行業有關？",options:["典當業","印刷業","製傘業","糧食加工業"],answer:0,explanation:"和昌大押曾是當舖，位於灣仔莊士敦道的相連唐樓內；「押」與典當相關。本題考歷史行業，不把現時任何餐廳租戶當固定資料。",hint:"把物品抵押周轉，是這種舊行業的主要服務。",art:"pawn-screen",focus:{x:50,y:50},modes:["original"],imageAlt:"香港本地文化主題原創插畫，並非本題地點的實景或官方圖則。",source:{label:"市區重建局・保育灣仔和昌大押",url:"https://www.ura.org.hk/tc/news-centre/know-more-about-urban-renewal/kmaura_2021122004"},review:"2026-11-26核對來源；問法不依賴插畫辨認，保留做法、歷史與俗語的適用範圍。"},{id:"l26",tier:2,category:"古蹟・地下水務",question:"前深水埗配水庫的歷史用途，與以下哪項公共服務最直接相關？",options:["儲存煤氣","儲水及配水","處理海關貨物","收集鐵路行李"],answer:1,explanation:"配水庫是九龍供水系統的一部分，用於儲水及配水。紅磚拱券很有氣氛，但以前唔係地下宮殿或秘密酒窖。",hint:"建築名稱中的「配水」已經指出本業。",art:"seawater-flushing",focus:{x:50,y:50},modes:["text"],textOnly:!0,imageAlt:"香港本地文化主題原創插畫，並非本題地點的實景或官方圖則。",source:{label:"水務署・前深水埗配水庫",url:"https://www.wsd.gov.hk/tc/water-matters/water-distribution/10/"},review:"2026-11-26核對來源；問法不依賴插畫辨認，保留做法、歷史與俗語的適用範圍。"},{id:"l27",tier:3,category:"古蹟・海事文化",question:"香港海事博物館在2013年遷往中環後，設於哪個碼頭？",options:["中環六號碼頭","中環七號碼頭","中環八號碼頭","中環九號碼頭"],answer:2,explanation:"香港海事博物館於2013年遷至中環八號碼頭，展示香港及南中國海的海事歷史。問法限定這次遷址，唔把最初赤柱館址混在一起。",hint:"這個碼頭就在中環海濱一列碼頭之中。",art:"harbour",focus:{x:50,y:50},modes:["original"],imageAlt:"香港本地文化主題原創插畫，並非本題地點的實景或官方圖則。",source:{label:"香港海事博物館・參觀資訊",url:"https://www.hkmaritimemuseum.org/plan-your-visit"},review:"2026-11-26核對來源；問法不依賴插畫辨認，保留做法、歷史與俗語的適用範圍。"},{id:"l28",tier:2,category:"古蹟・大澳棚屋",question:"大澳棚屋的典型建築方式，最接近以下哪個描述？",options:["把屋身挖進山體內","直接浮在充氣筏上隨潮漂走","把磚屋建在海底供潛水進出","在潮間水道或泥灘上以支柱承托屋身"],answer:3,explanation:"大澳棚屋以支柱在泥灘及水道上支撐屋身，與漁村生活環境相適應；不是隨潮自由漂移的船屋，也不等於任何棚屋都採完全相同物料。",hint:"重點在於屋身下面的承托結構。",art:"harbour",focus:{x:50,y:50},modes:["text"],textOnly:!0,imageAlt:"香港本地文化主題原創插畫，並非本題地點的實景或官方圖則。",source:{label:"香港旅遊發展局・大澳漁村",url:"https://www.discoverhongkong.com/tc/place-to-go/travel.guide-tai-o-village.html"},review:"2026-11-26核對來源；問法不依賴插畫辨認，保留做法、歷史與俗語的適用範圍。"},{id:"l29",tier:2,category:"古蹟・離島工業",question:"坪洲牛皮廠藝術空間的前身，主要從事哪種生產加工？",options:["皮革加工","製作香燭","壓製茶葉","印刷報紙"],answer:0,explanation:"牛皮廠保留了坪洲昔日工業的記憶，後來轉化為藝術空間。本題考廠房舊用途，唔是問今日展出哪位藝術家的作品。",hint:"廠名指向其原本使用的物料。",art:"tong-lau-arcade",focus:{x:50,y:50},modes:["text"],textOnly:!0,imageAlt:"香港本地文化主題原創插畫，並非本題地點的實景或官方圖則。",source:{label:"香港旅遊發展局・坪洲牛皮廠",url:"https://www.discoverhongkong.com/tc/place-to-go/travel.guide-leather-factory.html"},review:"2026-11-26核對來源；問法不依賴插畫辨認，保留做法、歷史與俗語的適用範圍。"},{id:"l30",tier:2,category:"古蹟・鄉郊文化",question:"荔枝窩傳統村落最具代表性的文化背景是哪一種？",options:["以葡式街區為主的文化","客家文化","以近代軍營為主的文化","以遠洋貨櫃港為主的文化"],answer:1,explanation:"荔枝窩是新界東北的歷史客家村落，村屋與文化傳統仍可讓人認識昔日鄉郊生活。唔好單憑村名就當成一個只種荔枝的果園。",hint:"它與新界東北的傳統村落、客家生活有關。",art:"temple",focus:{x:50,y:50},modes:["text"],textOnly:!0,imageAlt:"香港本地文化主題原創插畫，並非本題地點的實景或官方圖則。",source:{label:"鄉郊保育辦公室・荔枝窩",url:"https://cco.gov.hk/tc/project-sites/lai-chi-wo"},review:"2026-11-26核對來源；問法不依賴插畫辨認，保留做法、歷史與俗語的適用範圍。"},{id:"l31",tier:1,category:"節慶・新界祈福",question:"林村許願樹及許願廣場位於香港哪一區？",options:["荃灣","屯門","大埔","沙田"],answer:2,explanation:"林村許願樹在大埔林村，祈福習俗是當地文化之一；現場以指定設施及指引為準，不能把拋擲物件到每棵真樹上當成遊覽方式。",hint:"新界東的林村，與大埔墟並不相隔很遠。",art:"tree",focus:{x:50,y:50},modes:["original"],imageAlt:"香港本地文化主題原創插畫，並非本題地點的實景或官方圖則。",source:{label:"民政事務總署・林村許願樹",url:"https://www.gohk.gov.hk/tc/spots/spot_detail.php?spot=Lam+Tsuen+Wishing+Trees"},review:"2026-11-26核對來源；問法不依賴插畫辨認，保留做法、歷史與俗語的適用範圍。"},{id:"l32",tier:1,category:"節慶・平安寓意",question:"長洲太平清醮的「平安包」，名稱主要表達甚麼願望？",options:["保證食用後永不生病","表示包子只准平日出售","代表所有包子都沒有餡料","祈求平安吉祥"],answer:3,explanation:"平安包帶有祈福、平安的文化寓意，不是醫療保證，也不代表每間店配方一樣。食包可以開心，保養身體仍要靠日常照顧。",hint:"把包上的祝福文字當作文化寓意，唔是產品功效。",art:"buns",focus:{x:50,y:50},modes:["original"],imageAlt:"香港本地文化主題原創插畫，並非本題地點的實景或官方圖則。",source:{label:"香港文化古蹟資源中心・平安包文化工作坊",url:"https://cache.org.hk/blog/bun_wsmar19/"},review:"2026-11-26核對來源；問法不依賴插畫辨認，保留做法、歷史與俗語的適用範圍。"},{id:"l33",tier:1,category:"節慶・佛誕",question:"香港佛誕又稱「浴佛節」，傳統儀式中的「浴佛」是甚麼？",options:["以水灌沐佛像以表敬意","替寺院所有樹木澆水","讓龍舟在海上繞圈","將燈籠放入河裡漂走"],answer:0,explanation:"浴佛儀式以水灌沐佛像，表達敬意與淨化心靈的象徵。這是宗教儀式，唔係每位訪客都要參與的遊覽規定。",hint:"留意「浴」的對象是佛像。",art:"temple",focus:{x:50,y:50},modes:["original"],imageAlt:"香港本地文化主題原創插畫，並非本題地點的實景或官方圖則。",source:{label:"香港旅遊發展局・中華節慶與浴佛儀式",url:"https://www.discoverhongkong.com/tc/culture/celebrate-with-these-time-honoured-chinese-festivities.html"},review:"2026-11-26核對來源；問法不依賴插畫辨認，保留做法、歷史與俗語的適用範圍。"},{id:"l34",tier:2,category:"節慶・年宵花市",question:"香港傳統年宵市場最常與哪個節日相連？",options:["端午節","農曆新年","重陽節","聖誕節"],answer:1,explanation:"年宵市場通常在農曆新年前夕舉辦，花卉及賀年用品是熟悉的街景。每年地點、日期及安排會公布，本題不要求記某年的開放時間。",hint:"年近歲晚，買年花、迎新歲。",art:"lantern",focus:{x:50,y:50},modes:["original"],imageAlt:"香港本地文化主題原創插畫，並非本題地點的實景或官方圖則。",source:{label:"食環署・2027農曆新年年宵市場",url:"https://www.fehd.gov.hk/tc_chi/events/cnyf2027/index.html"},review:"2026-11-26核對來源；問法不依賴插畫辨認，保留做法、歷史與俗語的適用範圍。"},{id:"l35",tier:2,category:"節慶・元宵",question:"香港的元宵綵燈活動所慶祝的元宵節，傳統上是農曆哪一天？",options:["正月初五","五月十五","正月十五","八月十五"],answer:2,explanation:"元宵節是農曆正月十五，常與賞燈等活動相連；八月十五是中秋。兩晚都可能有燈，日曆就唔好一齊對調。",hint:"春節尾聲的第一個月圓節日。",art:"lantern",focus:{x:50,y:50},modes:["original"],imageAlt:"香港本地文化主題原創插畫，並非本題地點的實景或官方圖則。",source:{label:"香港旅遊發展局・農曆新年習俗",url:"https://www.discoverhongkong.com/tc/culture/the-ultimate-guide-to-chinese-new-year-in-hong-kong.html"},review:"2026-11-26核對來源；問法不依賴插畫辨認，保留做法、歷史與俗語的適用範圍。"},{id:"l36",tier:2,category:"節慶・鵝頸橋",question:"香港鵝頸橋底最廣為人知、在驚蟄前後特別熱鬧的民間習俗是甚麼？",options:["舞醉龍","搶花炮","盂蘭搶孤","打小人"],answer:3,explanation:"鵝頸橋底以打小人民俗聞名，驚蟄前後尤其受關注。它是民間文化及象徵儀式，不代表能證實改變他人的命運或健康。",hint:"傳統儀式常用鞋底拍打紙製人形。",art:"temple",focus:{x:50,y:50},modes:["text"],textOnly:!0,imageAlt:"香港本地文化主題原創插畫，並非本題地點的實景或官方圖則。",source:{label:"香港教育大學・打小人民俗",url:"https://www.eduhk.hk/chineseculture/content/hkculture/tm/custom/custom01.pdf"},review:"2026-11-26核對來源；問法不依賴插畫辨認，保留做法、歷史與俗語的適用範圍。"},{id:"l37",tier:2,category:"節慶・大埔夜龍",question:"大埔「端午遊夜龍」與日間龍舟競賽相比，最貼近哪種傳統活動？",options:["端午前夕至凌晨的水上龍舟巡遊祈福","中秋夜在街道舞香火龍","新年時在山上追逐紙龍","重陽節在屋頂曬龍舟"],answer:0,explanation:"大埔端午遊夜龍是端午前夕晚上至初五清早的水上巡遊傳統，具有祈求水陸平安的意義；不可與中秋街上的舞火龍混為一談。",hint:"留意「端午」、「夜」和在水上進行的背景。",art:"dragon",focus:{x:50,y:50},modes:["original"],imageAlt:"香港本地文化主題原創插畫，並非本題地點的實景或官方圖則。",source:{label:"非物質文化遺產辦事處・香港非遺清單",url:"https://www.icho.hk/documents/Intangible-Cultural-Heritage-Inventory/First_hkich_inventory_C.pdf"},review:"2026-11-26核對來源；問法不依賴插畫辨認，保留做法、歷史與俗語的適用範圍。"},{id:"l38",tier:2,category:"工藝・廣彩",question:"香港廣彩製作技藝，主要是在甚麼器物上繪飾彩色圖案？",options:["竹製蒸籠","瓷器","皮革行李箱","木製船槳"],answer:1,explanation:"廣彩以瓷器彩繪見稱，香港製作亦融入本地圖案與技法，有「港彩」之稱。名字有「彩」，並不表示所有彩色工藝都屬廣彩。",hint:"茶杯、碟、碗一類器物，是常見的載體。",art:"milk",focus:{x:50,y:50},modes:["text"],textOnly:!0,imageAlt:"香港本地文化主題原創插畫，並非本題地點的實景或官方圖則。",source:{label:"非物質文化遺產辦事處・廣彩製作技藝",url:"https://www.icho.hk/tc/web/icho/representative_list_guangcai_making_technique.html"},review:"2026-11-26核對來源；問法不依賴插畫辨認，保留做法、歷史與俗語的適用範圍。"},{id:"l39",tier:2,category:"工藝・麻雀牌",question:"傳統人手製作麻雀牌，切割及打磨牌身後，主要還要進行哪兩項工序？",options:["發酵及烘烤","鍍金及充氣","雕刻牌面及上色","染布及縫紉"],answer:2,explanation:"人手製牌包含切割、打磨、雕刻與上色，師傅要把牌面符號刻得清楚。不是每副現售麻雀都人手雕刻，題目限定傳統手工製法。",hint:"把白色牌身變成可以辨認的「筒索萬」，還欠甚麼？",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,imageAlt:"香港本地文化主題原創插畫，並非本題地點的實景或官方圖則。",source:{label:"非物質文化遺產辦事處・手藝教育小冊子",url:"https://www.icho.hk/documents/Education/edu_booklet/edu_booklet_2.pdf"},review:"2026-11-26核對來源；問法不依賴插畫辨認，保留做法、歷史與俗語的適用範圍。"},{id:"l40",tier:2,category:"工藝・裙褂",question:"傳統中式婚禮的「裙褂」，通常是由哪兩部分配成？",options:["長褲與背心","披肩與短褲","連帽衣與圍裙","上褂與下裙"],answer:3,explanation:"裙褂是上褂與下裙的配搭，常見精細刺繡；不同年代與店舖款式可有差異。不能把裙褂一律叫作單件式旗袍。",hint:"名稱中的兩個字，分別對應上、下身服裝。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,imageAlt:"香港本地文化主題原創插畫，並非本題地點的實景或官方圖則。",source:{label:"非物質文化遺產辦事處・中式長衫和裙褂製作技藝",url:"https://www.icho.hk/tc/web/icho/representative_list_cheongsam_kwan_kwa.html"},review:"2026-11-26核對來源；問法不依賴插畫辨認，保留做法、歷史與俗語的適用範圍。"},{id:"l41",tier:1,category:"生活・香港設計",question:"香港人說「紅白藍袋」，最典型是指哪類日常物件？",options:["紅白藍條紋的塑膠織布袋","紅白藍三層的紙製公文袋","只有紅色袋身和藍色拉鏈的皮袋","香港三種不同顏色的法定回收袋"],answer:0,explanation:"紅白藍塑膠織布與耐用袋具，是香港生活和設計文化的熟悉符號，也被設計師用於創作；不代表它是指定的政府分類回收袋。",hint:"重點是條紋塑膠織布，常見於耐用的大袋。",art:"red-market-bag",focus:{x:50,y:50},modes:["text"],textOnly:!0,imageAlt:"香港本地文化主題原創插畫，並非本題地點的實景或官方圖則。",source:{label:"M+・又一山人《香港建築03／紅白藍》",url:"https://www.mplus.org.hk/tc/collection/objects/building-hong-kong-03-redwhiteblue-2017149/"},review:"2026-11-26核對來源；問法不依賴插畫辨認，保留做法、歷史與俗語的適用範圍。"},{id:"l42",tier:1,category:"生活・街角士多",question:"街坊說「落樓下間士多買汽水」，「士多」一般是哪種店？",options:["大型百貨公司的電器部","小型雜貨店","專門維修汽車的店","只售賣處方藥的店"],answer:1,explanation:"「士多」借自英文store，常指售汽水、零食及日用品的小型雜貨店。店細細，街坊需要的東西有時反而好齊。",hint:"是一種舊式街角小店的叫法。",art:"tong-lau-arcade",focus:{x:50,y:50},modes:["original"],imageAlt:"香港本地文化主題原創插畫，並非本題地點的實景或官方圖則。",source:{label:"粵典・士多",url:"https://words.hk/zidin/士多"},review:"2026-11-26核對來源；問法不依賴插畫辨認，保留做法、歷史與俗語的適用範圍。"},{id:"l43",tier:1,category:"生活・茶記搭枱",question:"茶餐廳伙計問「介唔介意搭枱？」，通常是問你是否願意怎樣用餐？",options:["與別人合併付款帳單","與其他客人點同一套套餐","與不相識的客人共用一張枱","把座位預留給尚未到場的客人"],answer:2,explanation:"搭枱是與其他客人共桌，各自用餐，不表示一定合併點菜或付款。先問一聲，張枱可以共用，界線都可以講清楚。",hint:"共用的是座位和枱面，唔一定共用份餐。",art:"milk",focus:{x:50,y:50},modes:["original"],imageAlt:"香港本地文化主題原創插畫，並非本題地點的實景或官方圖則。",source:{label:"粵典・搭枱",url:"https://words.hk/zidin/搭枱"},review:"2026-11-26核對來源；問法不依賴插畫辨認，保留做法、歷史與俗語的適用範圍。"},{id:"l44",tier:2,category:"生活・兩餸飯",question:"街坊點一份「兩餸飯」，一般是甚麼組合？",options:["兩碗白飯配一份固定餸","一款餸分成兩個飯盒","兩款湯麵各半份","一份飯配兩款自選餸菜"],answer:3,explanation:"兩餸飯一般讓客人選兩款餸配飯，個別貴價餸或加量的收費按店方標示。兩餸唔等於必須一肉一菜，也不保證全港同價。",hint:"「兩」數的是餸菜款數，不是白飯碗數。",art:"bun",focus:{x:50,y:50},modes:["text"],textOnly:!0,imageAlt:"香港本地文化主題原創插畫，並非本題地點的實景或官方圖則。",source:{label:"食物安全中心・兩餸飯業界指引",url:"https://www.cfs.gov.hk/english/multimedia/multimedia_pub/files/Rice_with_Two_Sides_Chi.pdf"},review:"2026-11-26核對來源；問法不依賴插畫辨認，保留做法、歷史與俗語的適用範圍。"},{id:"l45",tier:2,category:"生活・冰室往事",question:"舊式香港「冰室」早期主要供應哪一類餐飲？",options:["飲品及簡單小食","以火鍋海鮮套餐為主","只供應生鮮肉類批發","只供應婚宴大菜"],answer:0,explanation:"冰室早期以飲品及簡單小食為主，與後來菜式更多元的茶餐廳有歷史關聯。名稱雖有「冰」，不是只准賣凍飲。",hint:"奶茶、咖啡、麵包、多士，先從輕食想起。",art:"milk",focus:{x:50,y:50},modes:["original"],imageAlt:"香港本地文化主題原創插畫，並非本題地點的實景或官方圖則。",source:{label:"香港旅遊發展局・茶餐廳文化",url:"https://www.discoverhongkong.com/tc/food-and-drink/must-visit-cha-chaan-tengs.html"},review:"2026-11-26核對來源；問法不依賴插畫辨認，保留做法、歷史與俗語的適用範圍。"},{id:"l46",tier:2,category:"生活・唐樓格局",question:"不少舊式香港唐樓採「下舖上居」，是指哪種安排？",options:["地面住宅，天台碼頭","地面店舖，上層住宅","地下車房，上層農田","樓下學校，樓上船塢"],answer:1,explanation:"下舖上居把商業和居住放在同一幢樓內，反映舊區的街坊生活；不是每幢唐樓都必定有同一格局，也不表示每幢都有騎樓。",hint:"把「舖」和「居」分別放回地面及樓上。",art:"tong-lau-arcade",focus:{x:50,y:50},modes:["original"],imageAlt:"香港本地文化主題原創插畫，並非本題地點的實景或官方圖則。",source:{label:"香港歷史文物・歷史建築旅遊冊",url:"https://www.heritage.gov.hk/filemanager/heritage/Publication/sc/upload/4/heritageBookletChi.pdf"},review:"2026-11-26核對來源；問法不依賴插畫辨認，保留做法、歷史與俗語的適用範圍。"},{id:"l47",tier:2,category:"生活・公營房屋",question:"房委會所說的公共租住房屋與居者有其屋計劃，主要分別是哪一項？",options:["前者只供遊客，後者只供商戶","兩者都只供免費短期住宿","前者提供租住，後者協助合資格人士置業","前者只作辦公室，後者只作倉庫"],answer:2,explanation:"公共租住房屋提供租住單位；居者有其屋計劃屬資助置業安排。資格、轉售及申請條件須看最新公布，本題只考兩者的基本性質。",hint:"留意「租住」與「有其屋」的分別。",art:"tong-lau-arcade",focus:{x:50,y:50},modes:["original"],imageAlt:"香港本地文化主題原創插畫，並非本題地點的實景或官方圖則。",source:{label:"房屋委員會・公屋發展歷程",url:"https://www.housingauthority.gov.hk/tc/about-us/public-housing-heritage/public-housing-development/index.html"},review:"2026-11-26核對來源；問法不依賴插畫辨認，保留做法、歷史與俗語的適用範圍。"},{id:"l48",tier:2,category:"生活・點餐份量",question:"在食肆說「加底」前，哪個做法最能避免對份量和收費有誤解？",options:["假設所有餸菜都會加倍","假設加底必定免費","按鄰桌的份量自行推算","問清增加哪部分、多少份量及價錢"],answer:3,explanation:"消委會提醒，食肆對加底、加大的定義可能不同，應確認所加的主食、份量及收費。肚餓可以加底，默契唔好自行加到滿。",hint:"同一句術語，各店可能有不同解讀。",art:"milk",focus:{x:50,y:50},modes:["original"],imageAlt:"香港本地文化主題原創插畫，並非本題地點的實景或官方圖則。",source:{label:"消費者委員會・解構食肆常見術語",url:"https://www.consumer.org.hk/tc/article/471-4230"},review:"2026-11-26核對來源；問法不依賴插畫辨認，保留做法、歷史與俗語的適用範圍。"},{id:"l49",tier:2,category:"生活・廣東話",question:"在餐廳說「唔該，埋單」，一般是要求甚麼？",options:["計算消費並結帳","把點好的菜式送進廚房","要求把未煮的餐點打包","預付下一餐的訂金"],answer:0,explanation:"埋單即計算消費、付款結帳，與落單點餐不同。兩個都係「單」，一個令食物入場，一個令荷包出場。",hint:"飯後講這句，通常已經準備付款。",art:"calligraphy",focus:{x:50,y:50},modes:["text"],textOnly:!0,imageAlt:"香港本地文化主題原創插畫，並非本題地點的實景或官方圖則。",source:{label:"粵典・埋單",url:"https://words.hk/zidin/埋單"},review:"2026-11-26核對來源；問法不依賴插畫辨認，保留做法、歷史與俗語的適用範圍。"},{id:"l50",tier:2,category:"生活・流動圖書館",question:"香港公共圖書館的流動圖書館，主要如何把借閱服務帶到不同社區？",options:["把固定圖書館每日搬遷至新址","使用設有館藏的圖書車，按站點服務","以流動售書攤出售館藏","只提供往返固定總館的接駁巴士"],answer:1,explanation:"流動圖書館以圖書車到各服務站提供借還等服務，停站安排按圖書館公布。會郁的是圖書車，唔係要讀者追住一本會行路的書。",hint:"車廂可以放書架，服務站會有停站時間。",art:"bus-route-sheet",focus:{x:50,y:50},modes:["original"],imageAlt:"香港本地文化主題原創插畫，並非本題地點的實景或官方圖則。",source:{label:"香港公共圖書館・流動圖書館",url:"https://www.hkpl.gov.hk/tc/locations/opening-hours-03.html"},review:"2026-11-26核對來源；問法不依賴插畫辨認，保留做法、歷史與俗語的適用範圍。"},{id:"l51",tier:1,category:"地理・濕地保育",question:"香港濕地公園位於哪個新界新市鎮？",options:["將軍澳","馬鞍山","天水圍","東涌"],answer:2,explanation:"香港濕地公園位於天水圍，兼具濕地保育、教育和生態旅遊功能。與米埔同屬值得認識的濕地，但不是同一個園區。",hint:"地點在新界西北，鄰近輕鐵網絡。",art:"river",focus:{x:50,y:50},modes:["original"],imageAlt:"香港本地文化主題原創插畫，並非本題地點的實景或官方圖則。",source:{label:"漁護署・香港濕地公園",url:"https://enjoyleisure.afcd.gov.hk/zh-HK/activities/fisheries/hong-kong-wetland-park-54"},review:"2026-11-26核對來源；問法不依賴插畫辨認，保留做法、歷史與俗語的適用範圍。"},{id:"l52",tier:1,category:"地理・主題街道",question:"想找電子零件、音響配件或二手器材，深水埗哪條街最有代表性？",options:["太原街","花墟道","春秧街","鴨寮街"],answer:3,explanation:"鴨寮街以電子產品、零件及二手器材聞名。它不只售賣鴨，亦不是每個攤檔都一定賣同一類貨品。",hint:"街坊常簡稱這一帶為「鴨記」。",art:"tong-lau-arcade",focus:{x:50,y:50},modes:["original"],imageAlt:"香港本地文化主題原創插畫，並非本題地點的實景或官方圖則。",source:{label:"香港旅遊發展局・鴨寮街",url:"https://www.discoverhongkong.com/tc/place-to-go/travel.guide-apliu-street.html"},review:"2026-11-26核對來源；問法不依賴插畫辨認，保留做法、歷史與俗語的適用範圍。"},{id:"l53",tier:1,category:"地理・童年玩具",question:"灣仔哪條街因玩具店集中，而常被稱為「玩具街」？",options:["太原街","上海街","廟街","砵蘭街"],answer:0,explanation:"灣仔太原街有多間售賣新款及懷舊玩具的店，形成玩具街形象；街上亦有其他日用品及攤檔，不是全街只有玩具。",hint:"在灣仔，而不是旺角或油麻地。",art:"tong-lau-arcade",focus:{x:50,y:50},modes:["original"],imageAlt:"香港本地文化主題原創插畫，並非本題地點的實景或官方圖則。",source:{label:"香港旅遊發展局・太原街",url:"https://www.discoverhongkong.com/tc/place-to-go/travel.guide-tai-yuen-street.html"},review:"2026-11-26核對來源；問法不依賴插畫辨認，保留做法、歷史與俗語的適用範圍。"},{id:"l54",tier:2,category:"地理・波鞋街",question:"旺角所稱的「波鞋街」，主要是哪條街的一段？",options:["通菜街","花園街","西洋菜南街","洗衣街"],answer:1,explanation:"登打士街與亞皆老街之間一段花園街，因運動用品及波鞋店集中而有此稱呼。不要把整條花園街的每個路段都當作同一市集。",hint:"名字像一座花園，實際有一段最出名賣運動鞋。",art:"sport",focus:{x:50,y:50},modes:["original"],imageAlt:"香港本地文化主題原創插畫，並非本題地點的實景或官方圖則。",source:{label:"民政事務總署・波鞋街",url:"https://www.gohk.gov.hk/tc/spots/spot_detail.php?spot=Sneaker+Street"},review:"2026-11-26核對來源；問法不依賴插畫辨認，保留做法、歷史與俗語的適用範圍。"},{id:"l55",tier:2,category:"地理・夜市文化",question:"香港著名的廟街夜市，位於哪個區域一帶？",options:["北角與鰂魚涌","荃灣與葵涌","油麻地與佐敦","大埔與太和"],answer:2,explanation:"廟街位於油麻地、佐敦一帶，是本地夜市及街頭飲食文化的代表。各檔開門時間會有差異，本題不把某個時段當作全街硬性規定。",hint:"在九龍油尖旺區，鄰近榕樹頭和天后廟。",art:"lantern",focus:{x:50,y:50},modes:["original"],imageAlt:"香港本地文化主題原創插畫，並非本題地點的實景或官方圖則。",source:{label:"香港旅遊發展局・廟街夜市",url:"https://www.discoverhongkong.com/tc/place-to-go/travel.guide-temple-street-night-market.html"},review:"2026-11-26核對來源；問法不依賴插畫辨認，保留做法、歷史與俗語的適用範圍。"},{id:"l56",tier:2,category:"地理・海洋公園",question:"香港海洋公園的黃竹坑正門，位於香港哪個行政區？",options:["東區","觀塘區","離島區","南區"],answer:3,explanation:"海洋公園黃竹坑正門在香港島南區，與港鐵海洋公園站相連。香港有海洋的地方好多，公園地點仍要分清楚。",hint:"先想黃竹坑在香港島的哪一邊。",art:"harbour",focus:{x:50,y:50},modes:["original"],imageAlt:"香港本地文化主題原創插畫，並非本題地點的實景或官方圖則。",source:{label:"民政事務總署・南區",url:"https://www.gohk.gov.hk/tc/districts/so.php"},review:"2026-11-26核對來源；問法不依賴插畫辨認，保留做法、歷史與俗語的適用範圍。"},{id:"l57",tier:2,category:"地理・鹽田生活",question:"西貢鹽田梓保留下來的鹽田，最直接見證哪種傳統生計？",options:["利用海水曬鹽","利用山泉養珍珠","把煤炭燒成木炭","把珊瑚磨成麵粉"],answer:0,explanation:"西貢鹽田梓的村落歷史與曬鹽、捕魚相連，復修鹽田亦成為文化保育的一部分。本題明確指西貢的小島，避免與大埔同名地點混淆。",hint:"「鹽田」中的田，收成不一定是稻米。",art:"river",focus:{x:50,y:50},modes:["text"],textOnly:!0,imageAlt:"香港本地文化主題原創插畫，並非本題地點的實景或官方圖則。",source:{label:"民政事務總署・鹽田仔",url:"https://www.gohk.gov.hk/tc/spots/spot_detail.php?spot=Yim+Tin+Tsai"},review:"2026-11-26核對來源；問法不依賴插畫辨認，保留做法、歷史與俗語的適用範圍。"},{id:"l58",tier:3,category:"地理・自然教育",question:"嘉道理農場暨植物園的地址位於新界哪條公路？",options:["荃錦公路","林錦公路","荃錦坳道","錦田公路"],answer:1,explanation:"嘉道理農場暨植物園位於大埔林錦公路，工作涵蓋保育及環境教育。它不是一般售賣農產品的街市，也不是只供參觀牲畜的牧場。",hint:"這條路連接林村與錦田方向。",art:"tree",focus:{x:50,y:50},modes:["original"],imageAlt:"香港本地文化主題原創插畫，並非本題地點的實景或官方圖則。",source:{label:"嘉道理農場暨植物園・聯絡我們",url:"https://www.kfbg.org/tc/contact-us"},review:"2026-11-26核對來源；問法不依賴插畫辨認，保留做法、歷史與俗語的適用範圍。"},{id:"l59",tier:2,category:"自然・海洋動物",question:"香港水域的中華白海豚，屬於哪一類動物？",options:["硬骨魚類","爬行類","哺乳類","兩棲類"],answer:2,explanation:"中華白海豚是海洋哺乳類，靠肺呼吸，並以乳汁哺育幼兒。生活在海裡不代表是魚；觀察時亦應尊重牠們的活動空間。",hint:"牠要到水面換氣，也會哺育幼兒。",art:"harbour",focus:{x:50,y:50},modes:["original"],imageAlt:"香港本地文化主題原創插畫，並非本題地點的實景或官方圖則。",source:{label:"漁護署・中華白海豚",url:"https://www.afcd.gov.hk/tc_chi/conservation/con_mar/con_mar_chi/con_mar_chi_chi/con_mar_chi_chi_int.html"},review:"2026-11-26核對來源；問法不依賴插畫辨認，保留做法、歷史與俗語的適用範圍。"},{id:"l60",tier:2,category:"地理・香港仔漁港",question:"香港仔避風塘的傳統水上生活，主要與哪個社群的生計相連？",options:["高山伐木工人","內陸礦工","山區茶農","漁民社群"],answer:3,explanation:"香港仔原是傳統漁村，避風塘及船上生活與漁業社群密切相關。今天仍可從漁港、船廠及水上交通認識這段生活史。",hint:"停泊的漁船不只用來拍照，也與一代代人的生活和工作有關。",art:"harbour",focus:{x:50,y:50},modes:["original"],imageAlt:"香港本地文化主題原創插畫，並非本題地點的實景或官方圖則。",source:{label:"民政事務總署・香港仔港灣",url:"https://www.gohk.gov.hk/tc/spots/spot_detail.php?spot=Aberdeen+Harbour"},review:"2026-11-26核對來源；問法不依賴插畫辨認，保留做法、歷史與俗語的適用範圍。"}].map(t=>Object.freeze({...t,options:Object.freeze(t.options),focus:Object.freeze(t.focus),modes:Object.freeze(t.modes),source:Object.freeze(t.source)})));var P=Object.freeze(["s01","s02","s04","s06","s09","s10","s15","s17","s19","s20","s25","s26","s29","s47","s50","s58"]),Ee=Object.freeze([...P,"s05","s08","s11","s13","s14","s24","s41","s42"]);var Tt=[{id:"s01",sourceNumber:1,tier:2,category:"街道・城市設計",question:"石邊這排金屬件，最可能有甚麼用途？",options:["固定石欄上的扶手","提供轉彎的觸覺提示","防止滑板沿石邊磨滑","讓石槽內積水排走"],answer:2,explanation:"圖中的金屬凸粒打斷原本連續的平滑石邊，屬防滑板磨滑裝置的常見形式。不是觸覺引路磚，亦不能把所有石邊金屬件都當成這種用途。",hint:"留意凸粒有冇打斷一條可以滑行嘅直邊。",source:{label:"屋宇署・設計手冊及舊版本索引（暢通無阻的通道）",url:"https://www.bd.gov.hk/tc/resources/codes-and-references/codes-and-design-manuals/index.html"},art:"street-01",modes:["partial","original"],review:"保留題材；限定圖中裝置，移除所有花槽均如此設計的概括。",textQuestion:"花槽石壆邊緣的防滑板金屬凸粒，主要阻止哪種活動？",focus:{x:50,y:50},observation:{clue:"連續石邊上等距的短金屬凸粒",alt:"連續石邊上等距的短金屬凸粒",crop:{x:260,y:195,width:280,height:110},mirrorAxis:"horizontal"}},{id:"s02",sourceNumber:2,tier:1,category:"建築・公共空間",question:"圖中門板留空的位置，最直接方便甚麼？",options:["加強門板的隔音能力","阻隔清潔用水進入廁格","讓門鎖能由外部自動開啟","地面清潔及空氣流通"],answer:3,explanation:"廁格門底空隙可方便地面清潔及空氣流通，也可能讓人察覺異常。各場地須兼顧私隱與無障礙設計，沒有一個適用所有公廁的統一高度，亦不應自行鑽門施救。",hint:"睇清楚空位喺門頂、門邊定門底。",source:{label:"屋宇署・設計手冊及舊版本索引（暢通無阻的通道）",url:"https://www.bd.gov.hk/tc/resources/codes-and-references/codes-and-design-manuals/index.html"},art:"street-02",modes:["partial","original"],review:"刪除統一高度及保證救援說法，改問可觀察的空隙效果。",textQuestion:"廁格門底留有空隙，哪組實用影響最合理？",focus:{x:50,y:50},observation:{clue:"門板下緣與地面之間的空隙",alt:"門板下緣與地面之間的空隙",crop:{x:260,y:195,width:280,height:110},mirrorAxis:"horizontal"}},{id:"s03",sourceNumber:3,tier:2,category:"道路・街頭標記",question:"辨認地面字樣，哪個配對正確？",options:["巴士停車處；非獲准車輛不應停車","行人過路處；所有車輛可停車","上落貨車位；只限私家車停車","的士候客處；只限巴士停車"],answer:0,explanation:"圖中巴士停車處的標記須連同現場標誌理解。運輸署列明巴士站等地點不准停車，特許使用者除外；不應把停車限制改寫成所有其他車輛一律禁止駛過。",hint:"先還原地上嘅英文字，唔好只憑黃線估。",source:{label:"運輸署・不准停車的地點",url:"https://www.td.gov.hk/tc/road_safety/road_users_code/index/chapter_5_for_all_drivers/where_not_to_stop_/index.html"},art:"street-03",modes:["mirrored","original"],review:"修正原稿把不准停車誤寫為一概不准駛入。",textQuestion:"巴士站停車處內，非獲准使用車輛應遵守哪項限制？",focus:{x:50,y:50},observation:{clue:"黃色BUS STOP字樣及站邊標記",alt:"黃色BUS STOP字樣及站邊標記",crop:{x:260,y:195,width:280,height:110},mirrorAxis:"horizontal",mirroredPrompt:"還原地面倒轉字樣，哪個用途配對正確？",overview:{x:220,y:205,width:360,height:90}}},{id:"s04",sourceNumber:4,tier:2,category:"建築・公共空間",question:"只看這段頂部輪廓，哪件事較難做到？",options:["沿着欄杆看清邊界","在頂部穩妥平放物件","看見欄杆後方的景物","辨認欄杆的立柱位置"],answer:1,explanation:"圓管頂部沒有寬闊的平面，物件較難穩妥擺放；但這不是所有欄杆的唯一設計動機。不要坐上欄杆或在高處擺放雜物。",hint:"比較圓弧頂同平板頂可以放幾穩。",source:{label:"屋宇署・設計手冊及舊版本索引（暢通無阻的通道）",url:"https://www.bd.gov.hk/tc/resources/codes-and-references/codes-and-design-manuals/index.html"},art:"street-04",modes:["partial","original"],review:"刪除全港欄杆統一防坐動機，改考圖示形狀的直接效果。",textQuestion:"欄杆頂部呈圓管而不是平板，哪件事相對較難？",focus:{x:50,y:50},observation:{clue:"欄杆頂部向下彎的圓弧邊",alt:"欄杆頂部向下彎的圓弧邊",crop:{x:260,y:195,width:280,height:110},mirrorAxis:"horizontal"}},{id:"s05",sourceNumber:5,tier:1,category:"交通・日常設計",question:"這對裝置一高一低，最直接照顧甚麼？",options:["同一車輛前後輪的高度","乘客分別支付入場與泊車費","不同車輛駕駛座的高度","同一卡片不同的付款密碼"],answer:2,explanation:"不同高度的讀卡位置方便不同車身及駕駛座高度的司機伸手拍卡。並非每個停車場均採同一設計，也不是讓同一程車重複付款。",hint:"想像坐跑車同坐客貨車，伸手位置有咩唔同。",source:{label:"消費者委員會・消費資訊",url:"https://www.consumer.org.hk/tc"},art:"street-05",modes:["blurred","partial","original"],review:"限定圖中雙層配置，不虛構所有停車場的規格。",textQuestion:"停車場同一入口設不同高度的拍卡器，主要照顧甚麼差異？",focus:{x:50,y:50},observation:{clue:"同一柱上兩塊一高一低的感應面板",alt:"同一柱上兩塊一高一低的感應面板",crop:{x:320,y:140,width:160,height:210},mirrorAxis:"horizontal"}},{id:"s06",sourceNumber:6,tier:1,category:"交通・乘車日常",question:"沿圖中箭嘴排隊，中央應留給誰？",options:["等候上車的第三條隊","職員放置清潔器材","候車乘客停放大行李","先下車的乘客"],answer:3,explanation:"兩側排隊及中央留空讓下車乘客先離開，減少上落客互相阻擋。應按現場標線排隊、先落後上，不必將此包裝成固定的流體力學定律。",hint:"兩邊入，中間條直路要先畀人出。",source:{label:"港鐵・乘客服務",url:"https://www.mtr.com.hk/ch/customer/services/index.php"},art:"street-06",modes:["partial","original"],review:"保留先落後上；移除未量證的縮短停站幅度。",textQuestion:"月台排隊箭嘴向車門兩側展開，中央留空是為了甚麼？",focus:{x:50,y:50},observation:{clue:"車門中央直行箭嘴與兩側候車箭嘴",alt:"車門中央直行箭嘴與兩側候車箭嘴",crop:{x:250,y:175,width:300,height:110},mirrorAxis:"horizontal"}},{id:"s07",sourceNumber:7,tier:2,category:"交通・香港地理",question:"認出三種顏色的車，哪個地點三者皆可到？",options:["香港國際機場客運大樓","灣仔會議展覽中心","旺角朗豪坊","赤柱市集"],answer:0,explanation:"按運輸署資料，三類的士均可在機場客運大樓、港珠澳大橋香港口岸和迪士尼樂園提供服務。新界的士前往指定地點仍須使用准許路線，不等於可在全港自由行走。",hint:"三種顏色服務範圍唔同，但有共同嘅交通樞紐。",source:{label:"運輸署・的士服務",url:"https://www.td.gov.hk/tc/transport_in_hong_kong/public_transport/taxi/index_t.html"},art:"street-07",modes:["blurred","original"],review:"核對運輸署准許服務地點；不用「突破禁區」誤導。",textQuestion:"哪個地點可由紅色、綠色及藍色三類香港的士提供服務？",focus:{x:50,y:50},observation:{clue:"並排的紅、綠、藍色車身與頂燈",alt:"並排的紅、綠、藍色車身與頂燈",crop:{x:260,y:195,width:280,height:110},mirrorAxis:"horizontal"}},{id:"s08",sourceNumber:8,tier:2,category:"交通・車廂設計",question:"車尾這段隆起地板下，通常要容納甚麼？",options:["供乘客上層行李托運","後置引擎及傳動等機件","供落車門板收回的空間","供車頂集電桿轉向的機件"],answer:1,explanation:"不少後置引擎柴油巴士的尾部機械設備佔用空間，影響車尾地板及座位安排。電動、不同底盤及不同年代車型不可一概而論。",hint:"望吓呢段台階係靠近前門定車尾。",source:{label:"九巴・乘客服務",url:"https://www.kmb.hk/"},art:"street-08",modes:["partial","original"],review:"限定後置柴油車型，不聲稱所有巴士用同一底盤。",textQuestion:"後置引擎柴油雙層巴士的下層車尾地板較高，常與甚麼有關？",focus:{x:50,y:50},observation:{clue:"後輪附近升高的地板與向上兩級台階",alt:"後輪附近升高的地板與向上兩級台階",crop:{x:260,y:195,width:280,height:110},mirrorAxis:"horizontal"}},{id:"s09",sourceNumber:9,tier:1,category:"交通・車廂設計",question:"圖中兩種地板顏色，最直接讓你辨認甚麼？",options:["不同票價座位的範圍","所有優先座的年齡限制","車門旁與車廂中央的不同區域","上車與下車的付費金額"],answer:2,explanation:"圖示用色塊區分門區及內部通道。實際列車設計各異；乘客宜向車廂內移動、保持車門暢通，不能聲稱這是港鐵所有地板的唯一官方心理設計。",hint:"比較兩種色塊同車門位置嘅關係。",source:{label:"港鐵・乘客服務",url:"https://www.mtr.com.hk/ch/customer/services/index.php"},art:"street-09",modes:["original"],review:"移除未獲確認的潛意識設計動機，改問可見分區。",textQuestion:"車廂地面用兩種顏色區分車門附近與中央，能提供甚麼視覺資訊？",focus:{x:50,y:50},observation:{clue:"車門旁深色地板與車廂中央淺色地板",alt:"車門旁深色地板與車廂中央淺色地板",crop:{x:260,y:195,width:280,height:110},mirrorAxis:"horizontal"}},{id:"s10",sourceNumber:10,tier:2,category:"交通・城市文化",question:"這條車身折線與紅色塗裝，對應哪個主題？",options:["海港波浪","山峰輪廓","鐵路網絡","城市脈搏"],answer:3,explanation:"九巴發展里程記錄2017年推出紅巴，主題為「城市脈搏」。插畫只借紅色與脈搏折線作辨識線索，不把每條線的位置附會成官方指定的窗框意義。",hint:"條折線令人聯想起一種有節奏嘅訊號。",source:{label:"九巴・發展里程",url:"https://www.kmb.hk/milestones.html"},art:"street-10",modes:["blurred","partial","original"],review:"採九巴官方主題；刪除未證實的車窗與樓梯連線象徵。",textQuestion:"2017年九巴推出紅色車身「紅巴」，配合哪個官方主題？",focus:{x:50,y:50},observation:{clue:"紅色車身上的銀白色脈搏形折線",alt:"紅色車身上的銀白色脈搏形折線",crop:{x:260,y:195,width:280,height:110},mirrorAxis:"horizontal"}},{id:"s11",sourceNumber:11,tier:2,category:"飲食・香港味道",question:"圖中包身切開後露出的甜餡，常見起源說法是？",options:["把剩麵包碎混合糖等做餡","以雞蛋黃與雞油為唯一餡料","以雞尾酒浸過的完整葡萄作餡","以炒碎雞肉與洋蔥作鹹餡"],answer:0,explanation:"常見說法是麵包師傅把剩餘麵包加工成甜餡，雞尾包後來常有椰絲等材料。起源、年代和配方有不同版本，不能把單一傳說當成唯一確證。",hint:"睇吓餡料係細碎嘅甜餡，定一整件肉。",source:{label:"香港旅遊發展局・香港飲食文化",url:"https://www.discoverhongkong.com/tc/explore/dining.html"},art:"street-11",modes:["blurred","partial","original"],review:"把起源標為常見說法，刪除唯一發明年代與固定原始配方。",textQuestion:"雞尾包餡料的常見起源說法，與哪種節省食材做法有關？",focus:{x:50,y:50},observation:{clue:"長形麵包的切面露出淺黃色碎粒餡",alt:"長形麵包的切面露出淺黃色碎粒餡",crop:{x:260,y:195,width:280,height:110},mirrorAxis:"horizontal"}},{id:"s12",sourceNumber:12,tier:2,category:"飲食・茶記科學",question:"圖中這個先做的步驟，主要避免甚麼？",options:["減少茶葉在杯內繼續發酵","冷杯吸走飲品的部分熱量","阻止牛奶在壺內受熱","使瓷杯與飲品永遠同溫"],answer:1,explanation:"預熱杯子可減少冷杯最初從飲品吸熱。厚瓷有較大的熱容量，但未預熱時也會吸熱；不能把厚壁一律說成比所有材料更隔熱。",hint:"杯本身凍冰冰時，熱飲要先分啲熱力畀佢。",source:{label:"香港旅遊發展局・香港飲食文化",url:"https://www.discoverhongkong.com/tc/explore/dining.html"},art:"street-12",modes:["original"],review:"修正厚杯必然保溫的絕對物理說法；改考預熱。",textQuestion:"沖熱奶茶前先用熱水暖瓷杯，最直接可減少哪種熱量損失？",focus:{x:50,y:50},observation:{clue:"熱水先倒入空瓷杯，旁邊奶茶仍在壺中",alt:"熱水先倒入空瓷杯，旁邊奶茶仍在壺中",crop:{x:260,y:195,width:280,height:110},mirrorAxis:"horizontal"}},{id:"s13",sourceNumber:13,tier:2,category:"生活・物件觀察",question:"圖中套疊位置留了小空隙，有何實用效果？",options:["讓水桶裝水時能同時排水","使桶內容量刻度更精確","較易分開，減少兩桶卡緊","方便把提手當作密封蓋"],answer:2,explanation:"止疊凸緣或間隔設計可防止桶身套得過深，利於分開。不是所有紅色塑膠桶的每條橫紋都為此而設，也不能只憑品牌或顏色推斷結構。",hint:"要睇套疊接觸位，唔係見到紅色就估品牌。",source:{label:"消費者委員會・消費資訊",url:"https://www.consumer.org.hk/tc"},art:"street-13",modes:["partial","original"],review:"限定有止疊凸緣的示意，不推定某品牌所有橫紋的唯一用途。",textQuestion:"套疊水桶若有止疊凸緣留出間隙，最直接有何好處？",focus:{x:50,y:50},observation:{clue:"兩個套疊桶口之間的凸緣與小間隙",alt:"兩個套疊桶口之間的凸緣與小間隙",crop:{x:260,y:195,width:280,height:110},mirrorAxis:"horizontal"}},{id:"s14",sourceNumber:14,tier:1,category:"飲食・街頭文化",question:"認出這個器物的外形，最常見於哪類舖頭？",options:["中式醬油店","街市香燭舖","傳統米行","涼茶舖"],answer:3,explanation:"葫蘆形金屬容器是部分傳統涼茶舖的視覺標記，可與盛載涼茶的器具結合。造型及實際用途因店舖而異，不能保證所有裝飾葫蘆都盛着熱飲。",hint:"上下兩個肚，中間收窄，係邊類老店常見嘅輪廓？",source:{label:"香港旅遊發展局・香港飲食文化",url:"https://www.discoverhongkong.com/tc/explore/dining.html"},art:"street-14",modes:["blurred","partial","original"],review:"保留文化物件辨識，不把民俗象徵或保溫性能說成統一功能。",textQuestion:"傳統涼茶舖常見葫蘆形金屬壺，通常與哪類飲品有關？",focus:{x:50,y:50},observation:{clue:"上下圓鼓、中間收腰的金色容器與壺嘴",alt:"上下圓鼓、中間收腰的金色容器與壺嘴",crop:{x:260,y:195,width:280,height:110},mirrorAxis:"horizontal"}},{id:"s15",sourceNumber:15,tier:2,category:"生活・物件觀察",question:"圖中杯底中央有凹位，倒扣時可能怎樣？",options:["凹位仍可能積水，需要瀝乾","凹位一定會令水自動蒸發","杯底有凹位即代表可放明火","凹位能把膠杯變成保溫瓶"],answer:0,explanation:"杯底凹陷的製造及結構用途因杯款而異；倒扣時凹位可能形成積水位置。原稿「必定避免杯底積水」並不成立，清潔後應按實際形狀瀝乾。",hint:"杯倒轉咗，原本向下嘅凹位而家向邊？",source:{label:"食物安全中心・食物安全資訊",url:"https://www.cfs.gov.hk/tc_chi/"},art:"street-15",modes:["original"],review:"修正凹底一定避免積水的倒置說法，不虛構製造商設計理由。",textQuestion:"杯底有凹槽時，倒扣晾乾應留意甚麼？",focus:{x:50,y:50},observation:{clue:"倒扣膠杯底部朝上的圓形凹坑與一滴水",alt:"倒扣膠杯底部朝上的圓形凹坑與一滴水",crop:{x:260,y:195,width:280,height:110},mirrorAxis:"horizontal"}},{id:"s16",sourceNumber:16,tier:2,category:"街道・標牌解碼",question:"讀圖中H下方的數字，所示距離是多少米？",options:["5.2米","2.5米","150米","15米"],answer:1,explanation:"這類消防栓指示牌可提供喉管尺寸及距離等資訊；本圖下方示例為2.5米，不要與上方150混淆。圖是教學示意，實際標牌按現場規格閱讀，不可自行操作消防供水設施。",hint:"先搵橫線下面嗰組數字，小數點都要睇清。",source:{label:"水務署・敷設水管實務手冊",url:"https://www.wsd.gov.hk/filemanager/en/content_1456/Manual%20of%20Mainlaying%20Practice%20%28Amendment%20No.%201_2021%29.pdf"},art:"street-16",modes:["mirrored","original"],review:"保留標牌與上下數字辨識，限定示例單位，不把所有黃牌當成相同制式。",textQuestion:"圖示消防供水指示牌H下方寫2.5，這個數字以米表示距離。距離是多少？",focus:{x:50,y:50},observation:{clue:"H下方橫線以下寫着2.5，上方為150",alt:"黃色牌上有H、上方150與下方2.5，鏡像模式時整牌左右反轉",crop:{x:260,y:195,width:280,height:110},mirrorAxis:"horizontal",mirroredPrompt:"先還原倒轉標牌，再讀H下方距離：幾多米？",overview:{x:270,y:90,width:260,height:320}}},{id:"s17",sourceNumber:17,tier:2,category:"建築・天氣應變",question:"兩側長槽與疊起的板材，應配成甚麼裝置？",options:["升降機門的導軌","商舖鐵閘的捲軸","阻擋洪水的防洪板","展示架的掛價錢牌"],answer:2,explanation:"槽道讓相配的防洪板定位，配合密封和固定減少水流入。須由合適人員按裝置程序部署，並兼顧安全通行，並非任何凹槽都可自行塞板防洪。",hint:"睇埋板材同門框，兩件嘢係點樣配合。",source:{label:"港鐵・氣候變化與自然環境",url:"https://www.mtr.com.hk/sustainability/ch/climate-and-nature.html"},art:"street-17",modes:["partial","original"],review:"限定有配套防洪板的凹槽；不保證任意入口完全防水。",textQuestion:"入口兩側金屬槽配合可插入的防洪板，有甚麼作用？",focus:{x:50,y:50},observation:{clue:"入口側邊直槽及槽內一小段銀色板材",alt:"入口側邊直槽及槽內一小段銀色板材",crop:{x:260,y:195,width:280,height:110},mirrorAxis:"horizontal"}},{id:"s18",sourceNumber:18,tier:2,category:"建築・維修常識",question:"圖中外牆喉管接駁位有滲漏，應怎辦？",options:["用布包住後長期不再理會","自行爬出外牆拆走喉管","認為外露喉管永遠不用保養","通知管理方安排合適人員檢查維修"],answer:3,explanation:"外露管道較容易看見部分滲漏，但仍需合適的檢查、維修及安全工作安排。不能聲稱所有大廈排污渠都外露，或外露就能杜絕臭氣及病菌。",hint:"留意水漬出現喺接駁位，處理要兼顧高空安全。",source:{label:"屋宇署・樓宇保養及維修",url:"https://www.bd.gov.hk/tc/safety-inspection/"},art:"street-18",modes:["original"],review:"不把外露等同衛生保證；以合理報修取代危險自行處理。",textQuestion:"外露排水管發現滲漏後，哪個處理方向合適？",focus:{x:50,y:50},observation:{clue:"外牆喉管接駁口旁的水滴及深色滲痕",alt:"外牆喉管接駁口旁的水滴及深色滲痕",crop:{x:260,y:195,width:280,height:110},mirrorAxis:"horizontal"}},{id:"s19",sourceNumber:19,tier:2,category:"街道・日常設計",question:"圖中屋頂與管口的組合，主要有甚麼用途？",options:["讓雨水流向去水位置","把空氣吹進候車亭","替頂棚提供隔熱電源","收集巴士車輪的震動"],answer:0,explanation:"有斜度的頂板配合溝槽和去水管，可將雨水導往預定位置。不同候車亭排水方向不一，不可說全港都向行人路後方傾斜。",hint:"水會順斜面向低處流，睇吓低處有冇管。",source:{label:"九巴・乘客服務",url:"https://www.kmb.hk/"},art:"street-19",modes:["partial","original"],review:"刪除所有亭頂一律向後傾斜的概括，以示意排水路徑出題。",textQuestion:"候車亭頂板有斜度並接往去水管，這個組合主要做甚麼？",focus:{x:50,y:50},observation:{clue:"傾斜頂板低端連着垂直去水管",alt:"傾斜頂板低端連着垂直去水管",crop:{x:260,y:195,width:280,height:110},mirrorAxis:"horizontal"}},{id:"s20",sourceNumber:20,tier:2,category:"康樂・設施設計",question:"池邊這排狹長格柵，主要接收甚麼？",options:["池底沉沙，直接排入街渠","溢出的池水，送往循環處理","泳池補水，直接流入更衣室","泳客用水，直接流入飲水機"],answer:1,explanation:"溢水槽收集溢出的表面池水，配合循環、過濾與水質管理。格柵不是休息座位，亦不保證單靠溢水槽便可清除全部污染。",hint:"格柵同水面咁接近，先諗水會流去邊。",source:{label:"康文署・公眾游泳池",url:"https://www.lcsd.gov.hk/tc/beach/swim-intro.html"},art:"street-20",modes:["partial","original"],review:"保留表面水循環用途；不把減浪或消毒說成絕對成效。",textQuestion:"泳池池邊溢水槽接收表面水，通常連接哪個處理程序？",focus:{x:50,y:50},observation:{clue:"水面旁狹長排水格柵與向槽流動的水線",alt:"水面旁狹長排水格柵與向槽流動的水線",crop:{x:260,y:195,width:280,height:110},mirrorAxis:"horizontal"}},{id:"s21",sourceNumber:21,tier:2,category:"交通・拍卡考眼力",question:"看清兩部機器的字樣，正確拍卡次序是？",options:["上車前綠色出站，下車後橙色入站","只需在橙色機拍一次，不用出站","上車前橙色入站，下車後綠色出站","只在到站後任選一部機拍兩次"],answer:2,explanation:"八達通乘客須在登車站入站收費器確認，到目的地後在出站收費器確認。機身橙綠有助辨認，仍應看入站／出站標示；不是兩部都在上車前拍。",hint:"先分清入站同出站，唔好見綠燈就當綠色機。",source:{label:"港鐵・正確使用車票",url:"https://www.mtr.com.hk/ch/customer/main/correct-use-ticket.html"},art:"street-21",modes:["mirrored","original"],review:"修正按站數退差額的簡化說法，以官方入出站確認流程為準。",textQuestion:"輕鐵八達通橙色入站機與綠色出站機，正確拍卡次序是甚麼？",focus:{x:50,y:50},observation:{clue:"橙色機寫入站ENTRY，綠色機寫出站EXIT",alt:"橙色機寫入站ENTRY，綠色機寫出站EXIT",crop:{x:210,y:190,width:380,height:85},mirrorAxis:"horizontal",mirroredPrompt:"還原兩部機的倒轉字樣，正確拍卡次序是？",overview:{x:215,y:185,width:370,height:90}}},{id:"s22",sourceNumber:22,tier:2,category:"交通・車廂設計",question:"兩片重疊接片會相對移動，最配合哪個情況？",options:["列車切換不同軌距","車輪在路軌上調整直徑","列車車頂在入隧道時降高","車廂過彎時轉動，仍保留可步行地面"],answer:3,explanation:"車廂之間需要容許一定角度和位移，活動接片等結構維持通行面。不同車型接頭各異；不應把手、鞋尖或物件放近活動縫隙。",hint:"諗吓兩節車卡過彎，唔會永遠排成一直線。",source:{label:"港鐵・乘客服務",url:"https://www.mtr.com.hk/ch/customer/services/index.php"},art:"street-22",modes:["partial","original"],review:"不把全港列車一律描述為相同兩片半圓板；不承諾縫隙完全無風險。",textQuestion:"車廂連接處可相對移動的地板接片，主要兼顧甚麼？",focus:{x:50,y:50},observation:{clue:"車廂接縫兩側互相覆疊的圓弧金屬接片",alt:"車廂接縫兩側互相覆疊的圓弧金屬接片",crop:{x:260,y:195,width:280,height:110},mirrorAxis:"horizontal"}},{id:"s23",sourceNumber:23,tier:2,category:"交通・拍卡考眼力",question:"圖中車門旁另一部指定機器，標示要做甚麼？",options:["按路線條款領取分段車費回贈","重新扣除一次全程車費","為下一程預先繳付按金","查詢八達通所有者的姓名"],answer:0,explanation:"適用路線可在指定位置拍卡取得分段收費回贈，須符合路線、區段、付款工具及拍卡安排。並非每條巴士線均適用，亦不是任意按距離退費。",hint:"睇清楚機身係寫回贈，定係上車付款。",source:{label:"九巴・八達通轉乘與分段收費優惠",url:"https://www.kmb.hk/fare.html"},art:"street-23",modes:["mirrored","original"],review:"限定指定路線及條款，不承諾所有行程按實際里數退款。",textQuestion:"指定巴士雙向分段收費路線，下車拍指定回贈器一般為了甚麼？",focus:{x:50,y:50},observation:{clue:"車門旁裝置印有回贈REBATE字樣",alt:"車門旁裝置印有回贈REBATE字樣",crop:{x:260,y:195,width:280,height:110},mirrorAxis:"horizontal",mirroredPrompt:"還原機身字樣，這次拍卡應處理甚麼？",overview:{x:325,y:185,width:150,height:105}}},{id:"s24",sourceNumber:24,tier:1,category:"交通・城市老朋友",question:"圖中車窗的開啟方式，主要有甚麼直接用途？",options:["把窗固定為密封隔音結構","室外空氣","擴大雨刷在玻璃上的範圍","改變車頂集電桿的接線角度"],answer:1,explanation:"可開啟窗戶為車廂提供自然通風。不同車輛及天氣安排各異，乘客不可自行伸身或物件出窗，也不能保證開窗一定令所有玻璃不起霧。",hint:"睇吓窗邊打開咗嘅窄縫。",source:{label:"香港電車・電車文化",url:"https://www.hktramways.com/tc/"},art:"street-24",modes:["partial","original"],review:"限定非空調舊車設計，不作除霧或安全的絕對承諾。",textQuestion:"舊式非空調電車可推開前窗，主要有甚麼直接效果？",focus:{x:50,y:50},observation:{clue:"擋風玻璃向外傾開，窗邊留有通風縫",alt:"擋風玻璃向外傾開，窗邊留有通風縫",crop:{x:260,y:195,width:280,height:110},mirrorAxis:"horizontal"}},{id:"s25",sourceNumber:25,tier:1,category:"交通・旅客設施",question:"座位旁這個架，主要是哪類旅客設施？",options:["只供報紙與車票的展示","用作乘客上層座位的腳踏","供旅客放穩行李的層架","供職員暫放清潔廢水"],answer:2,explanation:"機場快綫有服務旅客的行李設施，行李應放穩並保持通道暢通。沒有依據說每張車票都分配專屬座位或嚴格保證人人有位，不應以不設吊環推導該承諾。",hint:"個架夠放旅行喼，唔係要塞滿條走廊。",source:{label:"港鐵・機場快綫簡介",url:"https://www.mtr.com.hk/ch/customer/services/airport_express_index.html"},art:"street-25",modes:["blurred","partial","original"],review:"移除機場快綫保證每人指定座位及控制售票的錯誤推論。",textQuestion:"機場快綫車廂的行李架，主要讓旅客怎樣放置大型行李？",focus:{x:50,y:50},observation:{clue:"車廂座位旁的層架放着一個直立旅行喼",alt:"車廂座位旁的層架放着一個直立旅行喼",crop:{x:260,y:195,width:280,height:110},mirrorAxis:"horizontal"}},{id:"s26",sourceNumber:26,tier:1,category:"飲食・水吧工藝",question:"壺上懸着這個布袋，主要隔開甚麼？",options:["咖啡粉與咖啡機零件","糖粒與冰水","奶泡與熱牛奶","茶渣與茶湯"],answer:3,explanation:"布袋用於過濾茶渣，反覆沖濾是港式奶茶工藝的一部分。茶袋需妥善清潔及維護，並非越舊或不清洗就必然更香滑。",hint:"細碎茶葉要留低，茶湯就要流落壺。",source:{label:"非物質文化遺產辦事處・港式奶茶製作技藝",url:"https://www.icho.hk/tc/web/icho/home.html"},art:"street-26",modes:["blurred","partial","original"],review:"不宣稱越舊越好；移除未證實的纖維孔隙與茶油保證。",textQuestion:"港式奶茶用棉布茶袋反覆濾茶，這個步驟主要隔開甚麼？",focus:{x:50,y:50},observation:{clue:"掛在金屬圈上的長布袋，茶湯流入壺內",alt:"掛在金屬圈上的長布袋，茶湯流入壺內",crop:{x:260,y:195,width:280,height:110},mirrorAxis:"horizontal"}},{id:"s27",sourceNumber:27,tier:2,category:"飲食・香港味道",question:"圖中層次讓麵少浸在湯裏，主要想保留甚麼？",options:["較爽彈的口感","凍硬如雪條的狀態","油炸後完全乾燥的外殼","生麵粉原封不動的味道"],answer:0,explanation:"一些雲吞麵店以雲吞承托麵條，減少麵條長時間泡湯而軟脹。盛法、湯匙位置及麵量因店而異，並非每店都遵守一套固定層次。",hint:"麵浸湯太耐會有咩變化？",source:{label:"香港旅遊發展局・香港飲食文化",url:"https://www.discoverhongkong.com/tc/explore/dining.html"},art:"street-27",modes:["original"],review:"保留常見擺放思路，避免把所有店及湯匙位置統一化。",textQuestion:"雲吞放下、麵放上的上桌方式，有助維持麵條哪項口感？",focus:{x:50,y:50},observation:{clue:"碗內雲吞在下、麵條較高並露出湯面",alt:"碗內雲吞在下、麵條較高並露出湯面",crop:{x:260,y:195,width:280,height:110},mirrorAxis:"horizontal"}},{id:"s28",sourceNumber:28,tier:2,category:"生活・安全設計",question:"認出圖中最長的一腳，接駁次序有甚麼作用？",options:["讓火線先接通再接零線","接地連接可先接通、後斷開","使插頭內毋須裝設保險絲","讓所有三腳插頭都無需接地"],answer:1,explanation:"標準接地腳較長，使接地先接通、後斷開，並可配合插座安全活門。部分雙重絕緣電器用絕緣開門腳，不代表它有金屬接地連接；不可自行改裝插頭。",hint:"三腳唔係同一長度，留意最長嗰支先接觸。",source:{label:"機電工程署・家居電氣安全手冊",url:"https://www.emsd.gov.hk/tc/electricity_safety/publications/general/household_electrical_safety_handbook/part_2/2_1/index.html"},art:"street-28",modes:["partial","original"],review:"區分金屬接地腳與絕緣開門腳，不宣稱所有三腳電器都接地。",textQuestion:"英式三腳插頭的接地腳通常較長，與哪個安全次序有關？",focus:{x:50,y:50},observation:{clue:"三腳插頭上方一腳明顯長於另外兩腳",alt:"三腳插頭上方一腳明顯長於另外兩腳",crop:{x:270,y:150,width:260,height:140},mirrorAxis:"horizontal"}},{id:"s29",sourceNumber:29,tier:2,category:"生活・光學觀察",question:"圖中小鏡筒能廣角看門外，哪個說法正確？",options:["光線只能單向傳播，永不反向","所有貓眼都靠人體靜電變透明","鏡片組改變視野，並非絕對單向保密","鏡片能保證門外永遠看不見室內"],answer:2,explanation:"光學貓眼以鏡片組取得較廣視野，反向觀看的成像與亮度不同；但光路可逆，不能把它當成絕對單向的私隱保證。需要私隱可採合適遮蓋，勿假設門外永遠看不見。",hint:"廣角鏡同真正單向傳光係兩回事。",source:{label:"消費者委員會・消費資訊",url:"https://www.consumer.org.hk/tc"},art:"street-29",modes:["original"],review:"修正光學單向且永不外洩的錯誤說法，不給不實私隱保證。",textQuestion:"大門防盜眼從屋內看有廣角，但反方向通常難看清，哪個說法正確？",focus:{x:50,y:50},observation:{clue:"門板中的圓形廣角鏡與鏡筒邊緣",alt:"門板中的圓形廣角鏡與鏡筒邊緣",crop:{x:260,y:195,width:280,height:110},mirrorAxis:"horizontal"}},{id:"s30",sourceNumber:30,tier:1,category:"飲食・包裝觀察",question:"圖中兩款包裝手感不同，可直接證明甚麼？",options:["玻璃樽必定多加兩成黃豆","紙盒裝一定未經安全處理","玻璃樽一定加入二氧化碳","不能單憑包裝手感判斷配方濃度"],answer:3,explanation:"包裝材質、溫度、配方與加工方式都可能影響體驗。玻璃較冷的觸感不能證明飲品更濃；應看產品成分和營養標籤，不虛構品牌特別配方或零氣味保證。",hint:"樽身凍唔凍，同入面落幾多黃豆唔係同一件事。",source:{label:"食物安全中心・食物安全資訊",url:"https://www.cfs.gov.hk/tc_chi/"},art:"street-30",modes:["original"],review:"移除未經品牌證實的濃度、殺菌及紙盒異味比較，改考證據判斷。",textQuestion:"同一飲品的玻璃樽與紙盒包裝，能否單憑手感斷定玻璃樽配方更濃？",focus:{x:50,y:50},observation:{clue:"並排的玻璃瓶及紙盒，均沒有成分數字",alt:"並排的玻璃瓶及紙盒，均沒有成分數字",crop:{x:260,y:195,width:280,height:110},mirrorAxis:"horizontal"}},{id:"s31",sourceNumber:31,tier:2,category:"道路・方向考眼力",question:"按地面這句提示，應先留意哪個方向？",options:["右方，並繼續留意其他來車","左方，按鏡中箭嘴直接判斷","背後，只看候車乘客","前方，只看對面路緣"],answer:0,explanation:"圖中的LOOK RIGHT意為望右。香港靠左行車，但不同路口、單程路或交通安排會影響來車方向，不能一律只望某一邊；須依現場提示及交通情況安全過路。",hint:"先把英文字還原，唔好跟住反轉畫面嘅箭嘴就行。",source:{label:"運輸署・道路使用者守則",url:"https://www.td.gov.hk/tc/road_safety/road_users_code/index.html"},art:"street-31",modes:["mirrored","original"],review:"把鏡像方向與實際提示分清，不用含糊的左右上落口訣。",textQuestion:"過路處地面寫LOOK RIGHT，按該字樣應先留意哪個方向？",focus:{x:50,y:50},observation:{clue:"LOOK RIGHT字樣及指向原圖右方的箭嘴",alt:"LOOK RIGHT字樣及指向原圖右方的箭嘴",crop:{x:205,y:210,width:390,height:70},mirrorAxis:"horizontal",mirroredPrompt:"還原倒轉地面字樣後，提示你先留意哪邊？",overview:{x:205,y:200,width:390,height:120}}},{id:"s32",sourceNumber:32,tier:2,category:"道路・過路安全",question:"綠色人像開始閃動時，尚未開始過路的行人應怎辦？",options:["立即衝出馬路，趕在紅燈前跑完","不要開始過路；已在路上的應繼續小心通過","一律停在行車線中央不再移動","只憑聲音快慢，完全不用看燈"],answer:1,explanation:"綠色人像閃動表示過路時段將結束，未開始過路者不應起步；已在路上者應小心繼續到安全位置。發聲裝置與燈號配合，不能把不同階段的聲音簡化成由慢突然轉快。",hint:"未開始同已行到路中間，處理並唔相同。",source:{label:"運輸署・電子行人過路發聲裝置",url:"https://www.td.gov.hk/tc/transport_in_hong_kong/pedestrians/pedestrian_crossing_facilities/electronic_audible_traffic_signal/index_t.html"},art:"street-32",modes:["text"],review:"修正原稿聲頻描述與鼓勵加速衝燈的風險，按官方過路規則出題。",textOnly:!0},{id:"s33",sourceNumber:33,tier:2,category:"街道・城市設計",question:"認出底座有鎖的這種柱，哪個用法合理？",options:["任何司機均可自行拆柱進入","商戶可隨時拆除以擴大攤位","由獲授權人員按需要開放受控通道","固定鎖孔只供清洗時排水"],answer:2,explanation:"可拆式柱讓管理方按緊急、維修或獲准進出安排控制通道。不是任何人都可自行開鎖，亦不能保證每條行人街都使用同款柱或同一把鎖。",hint:"有鎖代表受控制，唔係叫大家隨意拔走。",source:{label:"運輸署・道路使用者守則",url:"https://www.td.gov.hk/tc/road_safety/road_users_code/index.html"},art:"street-33",modes:["partial","original"],review:"保留受控通道彈性，不假設所有柱只為消防或可供商戶自行拆卸。",textQuestion:"有鎖的可拆卸防撞柱，與固定柱相比提供哪種管理彈性？",focus:{x:50,y:50},observation:{clue:"圓形鐵柱底座的鎖孔與可分離接縫",alt:"圓形鐵柱底座的鎖孔與可分離接縫",crop:{x:260,y:195,width:280,height:110},mirrorAxis:"horizontal"}},{id:"s34",sourceNumber:34,tier:2,category:"建築・香港家居",question:"部分住宅外鐵閘配內門，談通風時亦應留意哪項安全？",options:["鐵閘可代替所有防火門和逃生要求","裝兩道門就永遠不用檢查門鎖","任何樓宇都可隨意改動走火通道","防火門不應因通風而長期被楔開"],answer:3,explanation:"部分家庭以鐵閘配內門兼顧通風及訪客交流，但不可推論每戶依法必須有雙門。防火門、走火通道和外開門位置仍須按樓宇規定處理，通風不能取代防火要求。",hint:"通風方便之外，諗埋走火同防煙。",source:{label:"屋宇署・樓宇保養及維修",url:"https://www.bd.gov.hk/tc/safety-inspection/"},art:"street-34",modes:["text"],review:"不鼓勵把防火門長開；不把雙門稱為全港法定標配。",textOnly:!0},{id:"s35",sourceNumber:35,tier:2,category:"街道・招牌文化",question:"圖中支架生鏽的懸臂招牌，最需關注甚麼？",options:["結構及墮物對公眾的安全風險","霓虹氣體是否在全球一律禁用","是否用了所有舊招牌相同字體","是否一律干擾機場導航系統"],answer:0,explanation:"招牌受建築規管及安全維護要求約束。部分符合條件的舊小型違例招牌可按檢核計劃處理，不是所有霓虹招牌都須因某一同時發生的政策一律清拆。",hint:"先睇掛住個招牌嘅支架，唔係只睇霓虹顏色。",source:{label:"屋宇署・招牌監管制度",url:"https://www.bd.gov.hk/tc/building-works/signboards/signboard-control-system/index.html"},art:"street-35",modes:["original"],review:"採屋宇署現行招牌監管說明，避免捏造單一政策觸發事件。",textQuestion:"香港招牌安全檢核或清拆，最直接保障甚麼？",focus:{x:50,y:50},observation:{clue:"懸臂招牌的生鏽螺栓與鬆脫支架",alt:"懸臂招牌的生鏽螺栓與鬆脫支架",crop:{x:260,y:195,width:280,height:110},mirrorAxis:"horizontal"}},{id:"s36",sourceNumber:36,tier:3,category:"文化・城市聲音",question:"曾為港鐵錄製經典英語廣播的Cheri Chan，中文名是甚麼？",options:["鄭子誠","陳如茵","李慧玲","林欣"],answer:1,explanation:"教育工作者陳如茵曾為港鐵等錄製廣播。不同年代、路線及臨時廣播可能採其他聲音，不應把所有英語廣播都說成同一人，也沒有依據稱她當時是港鐵職員。",hint:"佢亦從事英語教育，唔係網片中模仿廣播嘅人。",source:{label:"香港01・港鐵廣播聲音與陳如茵的訪問",url:"https://www.hk01.com/即時娛樂/467770/"},art:"street-36",modes:["text"],review:"修正「前港鐵職員」身份；不聲稱所有現有英語廣播均同一人錄製。",textOnly:!0},{id:"s37",sourceNumber:37,tier:2,category:"交通・車廂科技",question:"巴士樓梯客流感應器估算上層餘位，應怎樣理解顯示數字？",options:["等同每張椅子都必有重量感應器","數字保證百分百準確且永不延遲","是輔助估算，仍須留意現場座位及安全","數字為零也可坐在上層樓梯"],answer:2,explanation:"部分車型利用樓梯客流或其他感應方式估算上層餘位，不同系統及車型可能有差異。顯示可有誤差或延遲，不能憑數字推斷所有座位裝置或在樓梯停留。",hint:"感應器係輔助，不係保證你一定有張凳。",source:{label:"九巴・乘客服務",url:"https://www.kmb.hk/"},art:"street-37",modes:["text"],review:"移除所有新車一律同款感應器及精準無誤的承諾。",textOnly:!0},{id:"s38",sourceNumber:38,tier:2,category:"交通・城市老朋友",question:"留意圖中車頂接觸位置，這情況俗稱甚麼？",options:["失壓","轉轍","回廠","甩辮"],answer:3,explanation:"電車以集電桿從架空線取電，脫離接觸線俗稱甩辮，須由職員安全處理。並非因每次轉彎必然發生，乘客不可觸碰電線或嘗試重放集電桿。",hint:"長桿就好似一條搭上電線嘅辮。",source:{label:"香港電車・電車文化",url:"https://www.hktramways.com/tc/"},art:"street-38",modes:["blurred","partial","original"],review:"保留甩辮術語，不鼓勵乘客模仿操作。",textQuestion:"電車集電桿脫離架空接觸線，俗稱甚麼？",focus:{x:50,y:50},observation:{clue:"車頂斜向集電桿與架空電線之間有明顯空隙",alt:"車頂斜向集電桿與架空電線之間有明顯空隙",crop:{x:350,y:85,width:250,height:145},mirrorAxis:"horizontal"}},{id:"s39",sourceNumber:39,tier:2,category:"交通・乘車安全",question:"年滿15歲的小巴乘客坐在有安全帶的座位，佩戴責任如何？",options:["乘客有責任正確佩戴可用的安全帶","只需車長提醒後才有佩戴責任","只有前排乘客需要佩戴","車速低便可自行解除安全帶"],answer:0,explanation:"公共小巴乘客須按規定使用已安裝的安全帶；年滿15歲者須為自身佩戴負責。兒童安排、豁免及損壞情況另有規定，不宜用「任何乘客全責」概括。發現損壞應通知司機並在安全可行情況下改坐。",hint:"題目特別講明年滿15歲、有可用安全帶。",source:{label:"運輸署・公共小巴後座安全帶問與答",url:"https://www.td.gov.hk/filemanager/en/content_4949/plbnet08.pdf"},art:"street-39",modes:["text"],review:"限定年齡及可用安全帶，不列易變罰款或把所有兒童情境一概歸責。",textOnly:!0},{id:"s40",sourceNumber:40,tier:2,category:"交通・尺寸考眼力",question:"讀圖中三個尺寸，長闊高總和是多少？",options:["140厘米","150厘米","110厘米","90厘米"],answer:1,explanation:"60＋50＋40＝150厘米。按運輸署指引，放在的士乘客車廂而長闊高總和超過140厘米的行李涉及附加費；另有行李位置及豁免安排，輪椅、拐杖等按官方規定處理。",hint:"三邊都要加，唔係只加正面兩條邊。",source:{label:"運輸署・的士收費表",url:"https://www.td.gov.hk/tc/transport_in_hong_kong/public_transport/taxi/taxi_fare_of_hong_kong/index.html"},art:"street-40",modes:["mirrored","original"],review:"改為可驗算的三邊觀察題；保留140厘米指引，不固定所有車種行李費。",textQuestion:"行李三邊為60、50、40厘米，長闊高總和是多少？",focus:{x:50,y:50},observation:{clue:"旅行喼旁三個尺寸數字60、50、40厘米",alt:"旅行喼旁三個尺寸數字60、50、40厘米",crop:{x:210,y:165,width:380,height:130},mirrorAxis:"horizontal",mirroredPrompt:"還原倒轉尺寸數字，再算長闊高總和是多少？",overview:{x:210,y:80,width:380,height:240}}},{id:"s41",sourceNumber:41,tier:2,category:"飲食・街頭工藝",question:"圖中上下合起再反轉的模具，主要令蛋漿怎樣？",options:["讓模具內的蛋白蛋黃分離","把未熟蛋漿全部甩出模外","流向另一半模面，較均勻分布","把所有氣泡只集中在一面"],answer:2,explanation:"翻模有助尚未凝固的蛋漿分布到兩面凹槽，配合火候形成雞蛋仔形狀。配方、模具與操作時間不一，不能說不在固定秒數反轉就必然失敗或保證每顆完全中空。",hint:"先睇模入面係平面，定一個個半球凹槽。",source:{label:"香港旅遊發展局・香港飲食文化",url:"https://www.discoverhongkong.com/tc/explore/dining.html"},art:"street-41",modes:["blurred","partial","original"],review:"移除固定秒數、一定中空及不用翻便一定半圓的絕對說法。",textQuestion:"雞蛋仔合模後轉動烤模，主要幫助蛋漿怎樣分布？",focus:{x:50,y:50},observation:{clue:"連成片的半球凹槽與合模翻轉弧線",alt:"連成片的半球凹槽與合模翻轉弧線",crop:{x:260,y:195,width:280,height:110},mirrorAxis:"horizontal"}},{id:"s42",sourceNumber:42,tier:2,category:"飲食・點心工藝",question:"圖中半透明點心邊緣的褶紋，主要兼顧甚麼？",options:["以每褶數字決定蒸煮分鐘","以褶紋取代加熱和保鮮","符合全港統一十三褶法例","收口包餡及塑造外形"],answer:3,explanation:"蝦餃捏褶是收口及塑形工藝，褶數會隨師傅、大小和風格而異。沒有一個法定的十二或十三褶標準，食物安全亦不能單靠褶數保證。",hint:"睇褶位點樣把薄皮收埋。",source:{label:"香港旅遊發展局・香港飲食文化",url:"https://www.discoverhongkong.com/tc/explore/dining.html"},art:"street-42",modes:["blurred","partial","original"],review:"保留工藝觀察，刪除固定褶數為普遍標準及保證不爆餡的說法。",textQuestion:"蝦餃澄麵皮上捏褶，通常同時兼顧哪兩件事？",focus:{x:50,y:50},observation:{clue:"半透明彎月形外皮與邊緣的密褶",alt:"半透明彎月形外皮與邊緣的密褶",crop:{x:260,y:195,width:280,height:110},mirrorAxis:"horizontal"}},{id:"s43",sourceNumber:43,tier:1,category:"飲食・標籤考眼力",question:"讀清標籤，兩樽合共多少毫升？",options:["200毫升","100毫升","500毫升","1,000毫升"],answer:0,explanation:"圖示每樽100毫升，兩樽合計200毫升。香港常見益力多產品有100毫升規格，但不同市場及產品可有不同包裝，不能捏造品牌只准迷你樽的唯一科學原因。",hint:"先睇每樽嘅標示，再乘兩樽。",source:{label:"惠康・益力多100毫升產品標示",url:"https://www.wellcome.com.hk/en/p/Yakult%20Lactic%20Drink%2010%20X%20100ML%20%28Random%20Packaging%29/i/113309134.html"},art:"street-43",modes:["mirrored","original"],review:"採產品容量可驗算資訊，刪除從不推出其他規格及糖分保證。",textQuestion:"標籤寫100mL的一樽乳酸飲品，兩樽共有多少毫升？",focus:{x:50,y:50},observation:{clue:"兩個小瓶，正面各印100mL",alt:"兩個小瓶，正面各印100mL",crop:{x:245,y:195,width:310,height:105},mirrorAxis:"horizontal",mirroredPrompt:"還原倒轉容量標籤，兩樽合共多少毫升？",overview:{x:245,y:205,width:310,height:70}}},{id:"s44",sourceNumber:44,tier:2,category:"飲食・煮食觀察",question:"圖中瓦煲底部的金黃薄層，還需要控制甚麼？",options:["只需煲身有鐵線便一定成功","火力、時間和水分","只需加入食用金粉","只需把生米完全不加熱"],answer:1,explanation:"飯焦形成與鍋底溫度、含水量及時間有關。瓦煲的熱性質與金屬鍋不同，但不能保證永不燒焦，亦不能聲稱金屬鍋無法做出飯焦。",hint:"香脆同燒焦只差火候同水分，唔係認住個煲就得。",source:{label:"香港旅遊發展局・香港飲食文化",url:"https://www.discoverhongkong.com/tc/explore/dining.html"},art:"street-44",modes:["partial","original"],review:"保留煲仔飯題材，不宣稱粗陶必然均勻或不會瞬間焦苦。",textQuestion:"煲仔飯瓦煲有蓄熱特性，飯焦是否只需換上瓦煲就保證成功？",focus:{x:50,y:50},observation:{clue:"瓦煲剖面底部金黃色飯焦薄層",alt:"瓦煲剖面底部金黃色飯焦薄層",crop:{x:260,y:265,width:280,height:110},mirrorAxis:"horizontal"}},{id:"s45",sourceNumber:45,tier:1,category:"飲食・茶記文化",question:"圖中兩壺倒進同一杯，調成甚麼組合？",options:["檸檬茶與橙汁","可樂與豆漿","奶茶與咖啡","可可與椰汁"],answer:2,explanation:"港式鴛鴦結合奶茶與咖啡，配比因店舖和口味而異。歷史起源有不同流傳說法，不把碼頭工人或某個固定年代寫成唯一可證實的發明原因。",hint:"一壺有茶味，一壺有咖啡味。",source:{label:"香港旅遊發展局・香港飲食文化",url:"https://www.discoverhongkong.com/tc/explore/dining.html"},art:"street-45",modes:["original"],review:"保留飲品組合，不聲稱固定黃金比例或唯一勞工起源。",textQuestion:"茶餐廳飲品「鴛鴦」由哪兩種飲品混合？",focus:{x:50,y:50},observation:{clue:"兩壺棕色深淺不同的飲品同時倒入杯中",alt:"兩壺棕色深淺不同的飲品同時倒入杯中",crop:{x:260,y:195,width:280,height:110},mirrorAxis:"horizontal"}},{id:"s46",sourceNumber:46,tier:2,category:"道路・隱藏科技",question:"這組封閉切線形狀，最可能藏着哪種設施？",options:["用來量度貨車總重的地磅","讓柏油熱脹冷縮的伸縮縫","供道路雨水流走的排水槽","偵測車輛的感應線圈"],answer:3,explanation:"感應線圈可偵測車輛，供交通燈控制或相關交通系統使用。並非每個路口都以同一方式即時調節綠燈，部分系統另用影像、雷達等感測。",hint:"睇下切線係咪圍成封閉圈，而唔係一路延伸嘅伸縮縫。",source:{label:"機電工程署・交通燈與感應線圈",url:"https://www.emsd.gov.hk/minisites/voice/tc/issue20/cvoicelink_web01_6.html"},art:"street-46",modes:["partial","original"],review:"限定感應線圈功能，不把所有路口一概說成即時AI調燈。",textQuestion:"停車線前路面埋設的感應線圈，通常偵測甚麼供交通控制使用？",focus:{x:50,y:50},observation:{clue:"柏油路上成封閉長方形的黑色切線與引線",alt:"柏油路上成封閉長方形的黑色切線與引線",crop:{x:240,y:175,width:320,height:125},mirrorAxis:"horizontal"}},{id:"s47",sourceNumber:47,tier:2,category:"道路・視覺設計",question:"圖中這圈淺色輪廓，主要有助甚麼？",options:["讓燈組與複雜背景更易分辨","令三種燈色的電壓一樣","顯示此處一定設有衝燈相機","標記交通燈的維修年份"],answer:0,explanation:"背板及對比邊界有助交通信號從背景中顯現。實際背板規格及反光配置因設施而異，不要把白邊當成中央控制或固定降溫功能的代碼。",hint:"唔好只睇燈色，試吓留意成組燈同背景嘅分界。",source:{label:"運輸署・道路使用者守則",url:"https://www.td.gov.hk/tc/road_safety/road_users_code/index.html"},art:"street-47",modes:["partial","original"],review:"保留對比辨識用途，刪除全港所有燈箱一律相同的概括。",textQuestion:"交通燈黑色背板外的白色邊框，主要有助甚麼？",focus:{x:50,y:50},observation:{clue:"黑色燈組背板外的一圈白色輪廓",alt:"黑色燈組背板外的一圈白色輪廓",crop:{x:260,y:195,width:280,height:110},mirrorAxis:"horizontal"}},{id:"s48",sourceNumber:48,tier:2,category:"道路・明暗適應",question:"圖中洞口前這個結構，主要緩和甚麼變化？",options:["讓車輛適應突然改變的車道寬度","由明亮環境進入較暗環境的變化","替所有入隧道車輛自動減速","把洞內廢氣完全擋回隧道"],answer:1,explanation:"隧道入口的照明與部分遮光設計有助明暗過渡及看清前方。不同隧道採用不同措施，不能說香港每條隧道都有相同百葉棚或保證不會出現視覺適應問題。",hint:"太陽下同洞入面，光暗相差好大。",source:{label:"運輸署・道路使用者守則",url:"https://www.td.gov.hk/tc/road_safety/road_users_code/index.html"},art:"street-48",modes:["blurred","partial","original"],review:"限定圖示遮光結構，不逐名聲稱所有隧道均有同款棚。",textQuestion:"隧道入口設過渡遮光結構，通常有助駕駛者適應甚麼？",focus:{x:50,y:50},observation:{clue:"隧道洞口前一排遮光條及由亮至暗的路面",alt:"隧道洞口前一排遮光條及由亮至暗的路面",crop:{x:260,y:195,width:280,height:110},mirrorAxis:"horizontal"}},{id:"s49",sourceNumber:49,tier:2,category:"道路・應變物資",question:"先辨認箱上字樣，這類物料可協助做甚麼？",options:["用來吸走路面積水的消毒粉","替拋錨車輛補充的備用油","吸附路面油漬，減低滑溜風險","供車輛自行補胎的橡膠粒"],answer:2,explanation:"砂等合適物料可協助吸附油污及控制滑溜風險，實際事故由相關人員處理。不能鼓勵途人進入車道，也不把砂箱描述成適用所有燃料火災的滅火工具。",hint:"字樣指向一種顆粒狀物料，唔係油箱。",source:{label:"運輸署・道路使用者守則",url:"https://www.td.gov.hk/tc/road_safety/road_users_code/index.html"},art:"street-49",modes:["mirrored","original"],review:"刪除市民可用砂撲油火的概括指導，限定道路事故專業處理。",textQuestion:"路旁標示SAND的砂箱，在漏油事故時可供合適人員作甚麼用途？",focus:{x:50,y:50},observation:{clue:"箱面SAND字樣與蓋邊少量細顆粒",alt:"箱面SAND字樣與蓋邊少量細顆粒",crop:{x:260,y:195,width:280,height:110},mirrorAxis:"horizontal",mirroredPrompt:"還原箱上倒轉字樣，這類物料可協助做甚麼？",overview:{x:250,y:205,width:300,height:100}}},{id:"s50",sourceNumber:50,tier:2,category:"道路・觸覺提示",question:"認出路邊這組凸紋，主要有甚麼作用？",options:["以條紋直接指示綠燈剩餘秒數","保證所有輪胎在雨天不打滑","用圓點數目表示路口編號","透過觸感提示接近車路邊界"],answer:3,explanation:"下斜路緣附近的觸覺警示帶協助辨識邊界。凸點與長條紋各有作用，須按現場配置理解；顏色不一定全為黃色，亦不能用觸覺磚代替交通燈指示。",hint:"比較圓點同一路延伸嘅長條紋。",source:{label:"建築署・觸覺警示帶",url:"https://www.archsd.gov.hk/archsd/html/ua2-chinese/sc-pdf/ASD_UA2_4.6.pdf"},art:"street-50",modes:["partial","original"],review:"保留邊界提示，移除所有路口必定同一顏色及配置的說法。",textQuestion:"下斜路緣邊的凸點警示帶，主要向視障人士提供甚麼資訊？",focus:{x:50,y:50},observation:{clue:"下斜路緣前一排整齊凸點，旁邊另有長條紋",alt:"下斜路緣前一排整齊凸點，旁邊另有長條紋",crop:{x:260,y:195,width:280,height:110},mirrorAxis:"horizontal"}},{id:"s51",sourceNumber:51,tier:2,category:"建築・天氣應變",question:"圖中入口高起並裝板，主要想減少甚麼？",options:["街道積水流入地底車站","列車在站內自動改變軌距","空調把車站吹離地面","乘客手機的訊號外洩"],answer:0,explanation:"港鐵資料提及大部分出入口高於街面，並配合防洪板、防水門等措施。仍有無障礙通道及不同場地設計，不能稱所有入口都有樓梯、必高於歷史最高水位或絕不水浸。",hint:"街面啲水想流入地下，入口有咩阻擋？",source:{label:"港鐵・氣候變化與自然環境",url:"https://www.mtr.com.hk/sustainability/ch/climate-and-nature.html"},art:"street-51",modes:["original"],review:"修正所有入口必有梯級及高於歷史最高水位線的過度說法。",textQuestion:"港鐵部分入口提高地台並可部署防洪板，主要降低甚麼風險？",focus:{x:50,y:50},observation:{clue:"街面積水、抬高入口與橫向防洪板",alt:"街面積水、抬高入口與橫向防洪板",crop:{x:260,y:195,width:280,height:110},mirrorAxis:"horizontal"}},{id:"s52",sourceNumber:52,tier:2,category:"交通・緊急裝備",question:"這件車上應急工具，哪個使用方法正確？",options:["只要見到玻璃，平日也可試敲","只在緊急時依指定車窗及現場指示使用","不看指示，一律敲任何窗正中央","玻璃一碎，便保證沒有割傷風險"],answer:1,explanation:"逃生錘須配合指定緊急出口及該車的使用指示。車窗材料、標示和工具不同，不能保證所有玻璃都敲四角即碎，或碎片完全沒有傷害風險。",hint:"先搵配套指示，唔係見到錘就任意敲。",source:{label:"運輸署・道路使用者守則",url:"https://www.td.gov.hk/tc/road_safety/road_users_code/index.html"},art:"street-52",modes:["blurred","partial","original"],review:"移除所有車窗一律強化玻璃及碎片無銳角的保證。",textQuestion:"巴士緊急逃生錘應如何使用？",focus:{x:50,y:50},observation:{clue:"固定座內紅柄小錘與指定車窗標示",alt:"固定座內紅柄小錘與指定車窗標示",crop:{x:260,y:195,width:280,height:110},mirrorAxis:"horizontal"}},{id:"s53",sourceNumber:53,tier:2,category:"街道・投寄考眼力",question:"讀清兩個投信口，寄往東京應選哪一類？",options:["本港郵件","只收包裹的窗口","外地郵件","只收現金的窗口"],answer:2,explanation:"東京屬外地目的地；按郵筒實際標示分類投寄有助初步分流。郵筒類型及投信口標示各異，沒有自動秤重拒收郵資不足郵件的普遍機制。",hint:"唔好只睇畫面左邊右邊，要讀目的地分類。",source:{label:"香港郵政・郵筒與郵件投寄",url:"https://www.hongkongpost.hk/tc/sending_mail/"},art:"street-53",modes:["mirrored","original"],review:"保留分類用途，不宣稱所有郵筒均雙口或有自動秤重功能。",textQuestion:"雙投信口分本港與外地時，寄往東京的平郵信應選哪類投信口？",focus:{x:50,y:50},observation:{clue:"兩個口分寫本港LOCAL與外地OVERSEAS",alt:"兩個口分寫本港LOCAL與外地OVERSEAS",crop:{x:205,y:200,width:390,height:90},mirrorAxis:"horizontal",mirroredPrompt:"還原投信口倒轉字樣，寄往東京應選哪一類？",overview:{x:205,y:177,width:390,height:120}}},{id:"s54",sourceNumber:54,tier:3,category:"天氣・香港常識",question:"黑色暴雨警告指廣泛地區已錄得或預料有雨勢持續，每小時雨量超過多少？",options:["30毫米","50毫米","100毫米","70毫米"],answer:3,explanation:"天文台黑色暴雨警告表示廣泛地區已錄得或預料會有每小時超過70毫米的豪雨，而且雨勢可能持續。黃、紅門檻分別為30及50毫米；局部一個站的數字不一定等於全港警告。",hint:"黑雨比紅雨嘅50毫米門檻再高一級。",source:{label:"天文台・暴雨警告系統",url:"https://www.hko.gov.hk/tc/publica/gen_pub/rain.htm"},art:"street-54",modes:["text"],review:"保留官方門檻及廣泛地區、預料和持續條件，不把單站數字等同發警告。",textOnly:!0},{id:"s55",sourceNumber:55,tier:2,category:"生活・公共服務",question:"公立醫院急症室分流第一類「危殆」病人的目標診治安排是甚麼？",options:["毋須等候，即時診治","先到先得，按登記時間排隊","所有病人一律等候15分鐘","等齊五類病人才統一診治"],answer:0,explanation:"急症室按病情分流，危殆類別毋須等候，會即時獲得治理。這是分流服務安排，並非病人自行揀類別，也不能用遊戲題目判斷真實病情。",hint:"危殆係最急嗰級，唔係普通先到先得。",source:{label:"醫院管理局・急症室服務及分流",url:"https://www.ha.org.hk/visitor/ha_serviceguide_details.asp?Content_ID=10051&Lang=CHIB5"},art:"street-55",modes:["text"],review:"按醫管局服務資料；不用虛構最低分鐘數及自行診斷暗示。",textOnly:!0},{id:"s56",sourceNumber:56,tier:2,category:"飲食・茶記點餐",question:"按圖中餐牌，換指定品牌麵應怎樣付款？",options:["因為全港法例規定統一加4元","依標示加4元，先確認有無其他條件","因為所有品牌麵都要另付授權費","因為所有廚師依法必須逐包煮"],answer:1,explanation:"品牌麵加價屬店舖餐牌及成本定價安排。品牌、包裝、份量和經營成本各異，沒有全港固定加價，也不能捏造品牌授權費或必須逐包連味粉單獨烹煮的規定。",hint:"睇清餐牌寫嘅金額，唔好把店規當成全港法例。",source:{label:"消費者委員會・消費資訊",url:"https://www.consumer.org.hk/tc"},art:"street-56",modes:["mirrored","original"],review:"移除逐包單獨烹煮及品牌授權費的無依據因果，改成實用讀餐牌。",textQuestion:"茶記餐牌寫「轉指定品牌麵加4元」，應如何理解？",focus:{x:50,y:50},observation:{clue:"餐牌一行轉指定品牌麵＋$4",alt:"餐牌一行轉指定品牌麵＋$4",crop:{x:260,y:195,width:280,height:110},mirrorAxis:"horizontal",mirroredPrompt:"還原餐牌倒轉字樣，換指定品牌麵應怎樣付款？",overview:{x:230,y:190,width:340,height:130}}},{id:"s57",sourceNumber:57,tier:2,category:"生活・食水常識",question:"香港食水處理加入適量氟化物，主要目的為何？",options:["取代所有食水消毒程序","使所有礦物質完全消失","協助預防蛀牙","保證任何人永遠不會蛀牙"],answer:2,explanation:"香港自1961年起依衞生建議在食水加入氟化物，目的是保護牙齒、預防蛀牙。它不同於消毒用氯，亦不能取代刷牙、飲食管理或牙科照護。",hint:"氟化物同牙齒有關，唔好同消毒用嘅氯混淆。",source:{label:"水務署・食水處理",url:"https://www.wsd.gov.hk/tc/core-businesses/operation-and-maintenance-of-waterworks/water-treatment/index.html"},art:"street-57",modes:["text"],review:"保留1961年及預防目的，不重複未核實研究百分比或保證個人效果。",textOnly:!0},{id:"s58",sourceNumber:58,tier:2,category:"街市・色彩觀察",question:"觀察帶子與葉片的配色，哪個判斷合理？",options:["紅帶是已通過農藥檢測的標記","紅色保證葉片在常溫不會腐壞","綁帶顏色可判斷蔬菜的產地","對比明顯，但不能證明蔬菜較新鮮"],answer:3,explanation:"紅與綠並置形成鮮明色彩對比，但新鮮度須看食材狀況及儲存等資訊。不能因此斷言所有檔販都基於同一心理學動機選紅帶，也不能把顏色當安全認證。",hint:"顏色可以襯托，唔等於品質證書。",source:{label:"食物安全中心・食物安全資訊",url:"https://www.cfs.gov.hk/tc_chi/"},art:"street-58",modes:["partial","original"],review:"把主觀效果與檔販歷史動機分開，不以配色推定安全或新鮮。",textQuestion:"紅帶綁綠葉蔬菜時，紅綠配色最直接有何視覺效果？",focus:{x:50,y:50},observation:{clue:"綠葉中間一道紅色綑帶",alt:"綠葉中間一道紅色綑帶",crop:{x:260,y:195,width:280,height:110},mirrorAxis:"horizontal"}},{id:"s59",sourceNumber:59,tier:2,category:"飲食・唐餅文化",question:"看切面中的細薑片，主要增添哪種風味？",options:["辛香與微酸的層次","濃郁的咖啡焦香","純粹的鹹辣椒味","明顯的薄荷清涼感"],answer:0,explanation:"部分餅家的皮蛋酥會加入子薑，與皮蛋、蓮蓉形成風味對比；配方因店舖而異。不能說酸薑必然化學中和所有氨味，或所有皮蛋酥完全沒有蛋味。",hint:"薑片嘅風味，唔同蓮蓉嘅甜味。",source:{label:"奇華餅家・傳統唐餅",url:"https://keewah.com/hk/"},art:"street-59",modes:["partial","original"],review:"保留常見配料但不統一所有品牌配方；刪除完全去氨味的化學保證。",textQuestion:"部分皮蛋酥在蓮蓉與皮蛋之外加入子薑，主要增添哪種風味？",focus:{x:50,y:50},observation:{clue:"酥皮剖面的深色皮蛋、蓮蓉與淡粉色薑片",alt:"酥皮剖面的深色皮蛋、蓮蓉與淡粉色薑片",crop:{x:260,y:195,width:280,height:110},mirrorAxis:"horizontal"}},{id:"s60",sourceNumber:60,tier:2,category:"生活・置業讀圖",question:"看圖中戶門界線，哪個空間不應攤入單位實用面積？",options:["單位內睡房的樓面","門外公用升降機大堂","單位內客廳的樓面","單位內廚房的樓面"],answer:1,explanation:"一手住宅銷售規管要求以實用面積表達單位面積及單價，以利比較。公用升降機大堂等不應攤分計入單位實用面積；牆、露台等如何計算另有法定定義，不等於只量可行走的淨地面。",hint:"先搵單位大門，分清私人單位同門外公用地方。",source:{label:"政府新聞公報・採用實用面積表達住宅面積及售價",url:"https://www.info.gov.hk/gia/general/201405/21/P201405210482.htm"},art:"street-60",modes:["original"],review:"限定一手住宅銷售；不把實用面積簡化為所有建築物買賣或純室內淨面積。",textQuestion:"一手住宅價單以實用面積表達面積和呎價，圖中哪個範圍不應攤分計入？",focus:{x:50,y:50},observation:{clue:"單位邊界、戶門及門外公用升降機大堂",alt:"單位邊界、戶門及門外公用升降機大堂",crop:{x:260,y:195,width:280,height:110},mirrorAxis:"horizontal"}}],tt=Object.freeze(Tt.map(t=>Object.freeze({...t,options:Object.freeze(t.options),modes:Object.freeze(P.includes(t.id)?[...t.modes,"spotlight"]:t.modes),source:Object.freeze(t.source),...t.observation?{focus:Object.freeze(t.focus),observation:Object.freeze({...t.observation,crop:Object.freeze(t.observation.crop)})}:{}})));var et=Object.freeze([{id:"u01",tier:3,category:"交通・歷史設計",art:"tram-lifeguard",focus:{x:50,y:70},modes:["partial","original","text"],question:"昔日部分香港電車曾裝有「救生網閘／救生網盤」。這套車底裝置的設計目的是甚麼？",options:["固定電車停在斜坡時的車輪","清掃路軌上的積水和碎石","接住被撞倒的人，減低捲入車輪的風險","替車底機件降溫"],answer:2,explanation:"這是歷史安全裝置：救生網閘及網盤原意是減少被撞倒者捲入車輪的風險。1987年立法局已討論拆除事宜，不能說現今每輛電車都有，也不能把它描述為保證救人的電子感應器。插畫只示意舊式裝置的位置。",hint:"諗吓車頭同車輪之間，點樣減少人跌入去嘅風險；唔係清潔工具。",source:{label:"立法局會議紀錄・1987年5月27日",url:"https://www.legco.gov.hk/yr86-87/chinese/lc_sitg/hansard/h870527.pdf"}},{id:"u02",tier:2,category:"交通・小輪設計",art:"ferry-bench",focus:{x:50,y:52},modes:["mirrored","original","text"],question:"天星小輪的傳統木椅椅背可以前後翻轉，最切合哪項船隻設計？",options:["翻開椅背便可啟動救生艇","所有船隻都要靠椅背平衡重量","椅背是調整船速的機關","雙頭式船身可反向航行，乘客可調整座位朝向"],answer:3,explanation:"傳統天星小輪採雙頭式設計，往返兩岸不必每次掉轉整艘船。可前後調校的椅背讓乘客按航向選擇面向的方向；不是救生衣或救生艇的開關。",hint:"去程同回程未必要掉船頭；坐低前，睇吓想面向邊一邊。",source:{label:"香港地方志中心・天星小輪船身設計",url:"https://web.hkchronicles.org.hk/香港志/經濟/天星小輪陪伴港人走過125年歲月_看清四代船身設計變化"}},{id:"u03",tier:2,category:"交通・車廂物料",art:"steel-seats",focus:{x:50,y:59},modes:["partial","original","text"],question:"港鐵不少市區綫列車設有不銹鋼硬座椅。相較布面軟墊，這類金屬座椅有哪組實用特點？",options:["必定可以令整列車完全不會起火","表面耐用、易清潔，金屬本身不易燃燒","能隔絕所有無線電訊號","會令列車行駛時完全沒有震動"],answer:1,explanation:"不銹鋼硬座的實用特點包括耐用、表面易清潔及物料不易燃。港鐵資料記載1979年首代列車已採不銹鋼座椅；不同綫路和車種的座椅仍有差異，不能推論全車任何物料都不會燃燒。",hint:"每日咁多人坐，清潔同耐用都好重要；唔好將物料特點當成全車保證。",source:{label:"港鐵・解構鐵路（Decoding Rail）",url:"https://stationrailvoyageinfo.mtr.com.hk/en/decoding-rail"}},{id:"u04",tier:1,category:"交通・巴士行話",art:"bus-route-sheet",focus:{x:51,y:51},modes:["blurred","original","text"],question:"巴士迷俗稱「豬紙」的巴士站路線資料紙，主要讓候車乘客查閱甚麼？",options:["沿途站名、服務時間及車費等路線資料","巴士司機的私人住址","每日街市豬肉售價","所有巴士乘客的姓名"],answer:0,explanation:"「豬紙」是巴士迷對路線資料紙的俗稱，展示沿途站名、服務時間、班次、車費等資訊。名稱來源有不同流傳說法，這題只考可確認的用途，不把「包豬肉的蠟紙」說法當成史實。圖中站名、路線及時間均為示意。",hint:"企喺站頭等車，最想知架車去邊、幾時有、要幾多錢。",source:{label:"香港巴士大典・乳豬紙（巴士迷術語資料）",url:"https://hkbus.fandom.com/wiki/乳豬紙"}},{id:"u05",tier:1,category:"交通・截的士",art:"taxi-light",focus:{x:50,y:41},modes:["original","text"],question:"夜間看到香港的士車頂「TAXI」燈亮起，而且沒有「暫停載客」等標示，一般表示甚麼？",options:["已載客，不能接客","亮燈一律代表司機在休息","一般為空車待客，仍須留意車內標示及可上落客位置","乘客必須先在網上付款"],answer:2,explanation:"亮起的車頂燈一般用作辨識空車待客，但不能只憑一盞燈判斷所有情況；仍要留意暫停載客或預約等標示，並在合法、安全的地方截車。",hint:"唔好只望車頂，車內有冇掛暫停載客牌都要睇。",source:{label:"運輸署・的士則例簡介",url:"https://www.td.gov.hk/filemanager/tc/content_5216/GuidelinestoTaxiRegulations_TC_202309_With%20Notice.pdf"}},{id:"u06",tier:2,category:"建築・斜坡安全",art:"weep-holes",focus:{x:51,y:53},modes:["partial","original","text"],question:"擋土牆上伸出的小排水管或疏水孔，主要有甚麼作用？",options:["讓牆後泥土接收免費無線網絡","定期排出防蟻藥水","專門用來種植花卉","排走牆後積水，減低水壓對斜坡和擋土牆的影響"],answer:3,explanation:"疏水孔及排水設施協助排走牆後的水，減低水壓。淤塞會影響排水，斜坡需定期檢查及維修；有排水孔不代表保證不會發生山泥傾瀉。",hint:"落完大雨，泥土入面嘅水都需要有路走。",source:{label:"土木工程拓展署・斜坡維修",url:"https://hkss.cedd.gov.hk/hkss/tc/prevention-of-landslide-hazards/slope-maintenance/index.html"}},{id:"u07",tier:2,category:"街舖・典當文化",art:"pawn-screen",focus:{x:50,y:54},modes:["partial","original","text"],question:"傳統當舖入口的高大木屏風，俗稱「遮醜板」。其主要文化用途是甚麼？",options:["展示每位客人的欠款和姓名","遮擋街外視線，照顧典當客人的私隱和面子","防止當舖內所有聲音傳到街上","讓當舖可以完全不用裝門"],answer:1,explanation:"傳統上典當常被視為周轉困難，入口屏風可避免街外行人直接看見當客，照顧私隱和面子。這是舊式當舖的文化設計，並非說典當本身可恥。",hint:"行過街嘅人望唔到裡面，對嚟周轉嘅客人有咩好處？",source:{label:"香港教育大學・香港傳統文化民間風俗",url:"https://www.eduhk.hk/chineseculture/content/hkculture/tm/custom/custom05.pdf"}},{id:"u08",tier:1,category:"生活・自動梯安全",art:"escalator-brush",focus:{x:50,y:56},modes:["partial","original","text"],question:"扶手電梯梯級兩旁的黑色毛刷，真正的主要用途是甚麼？",options:["把腳和鬆散衣物導離梯級與裙板之間的縫隙，減低夾困風險","讓乘客把鞋伸過去擦乾淨","為乘客鞋底自動消毒","替梯級上的每件物品分類回收"],answer:0,explanation:"這是裙板偏轉裝置，作用是把鞋履、腳及鬆散衣物導離危險縫隙，減低夾困風險。它不是擦鞋工具；搭自動梯應企穩、握扶手，腳和衣物遠離梯級邊緣。",hint:"呢排毛刷係安全裝置，唔係免費擦鞋服務。",sharePrompt:"我日日搭扶手電梯，今日先認真留意兩旁黑色毛刷！你知唔知真正用途？",source:{label:"機電工程署・升降機及自動梯安全指引",url:"https://www.emsd.gov.hk/tc/lifts_and_escalators_safety/publications/guidance_notes_guidelines/"}},{id:"u09",tier:2,category:"建築・唐樓智慧",art:"tong-lau-arcade",focus:{x:50,y:53},modes:["mirrored","original","text"],question:"舊式唐樓「騎樓」由柱子支撐，樓層伸到行人路上方。這項設計有哪組實用作用？",options:["讓雙層巴士直接駛進住宅","把地下街舖完全隔絕於行人路外","樓下有蓋通道可遮陽擋雨，樓上可增加可用空間","保證建築物不受任何風暴影響"],answer:2,explanation:"騎樓把上層空間延伸至柱廊上方，下方形成有蓋行人通道，適應炎熱多雨的環境。並非每幢唐樓都有騎樓，也不能把它當成抵禦所有風暴的保證。",hint:"一邊係樓上多啲地方用，一邊係樓下行人落雨唔使即刻開遮。",source:{label:"香港房屋委員會・香港騎樓",url:"https://www.housingauthority.gov.hk/tc/about-us/publications-and-statistics/housing-dimensions/article/20151218/20151218_book.html"}},{id:"u10",tier:3,category:"生活・水資源",art:"seawater-flushing",textOnly:!0,question:"按水務署海水沖廁資料頁的概算，每年海水沖廁節省的食水，相當於香港總水用量約多少？",options:["約5%","約50%","約75%","約20%"],answer:3,explanation:"按水務署資料頁（2026年11月核對），海水沖廁每年約節省3.2億立方米食水，相當於本港總水用量約兩成。分母是「總水用量」，不能寫成「食水消耗量」；這是概算，並非每年固定不變的精確比例。",hint:"唔係一半，更唔係四分三；大概每五份總用水裡面有一份。",source:{label:"水務署・海水沖廁",url:"https://www.wsd.gov.hk/tc/core-businesses/water-resources/seawater-for-flushing/"}},{id:"u11",tier:1,category:"街頭・緊急定位",art:"lamppost-number",focus:{x:50,y:50},modes:["partial","original","text"],question:"在沒有清楚門牌的地方遇上緊急事故，附近燈柱上的編號可以怎樣幫忙？",options:["代替所有急救，讀出後便可離開現場","報警求助時提供編號，配合地點描述協助救援人員定位","用來登入任何免費Wi-Fi","直接顯示當地醫院候診時間"],answer:1,explanation:"求助時可提供附近燈柱編號，連同道路、地標、行車方向等資料協助定位，並聽從接線員指示。編號不是Wi-Fi密碼，也不能保證單憑它在任何地方都能即時精準定位。圖中編號為虛構示例，不作導航。",hint:"附近冇門牌，都可以搵啲固定設施嘅編號，幫接線員搵到你。",sharePrompt:"街邊燈柱呢塊細細嘅編號牌，除咗維修，緊急時仲可以點樣幫到人？",source:{label:"消防處・社區應急先鋒訓練講義",url:"https://www.hkfsd.gov.hk/sc/education/FSDCER_Training_Notes.pdf"}},{id:"u12",tier:2,category:"生活・香港硬幣",art:"scalloped-coins",focus:{x:50,y:50},modes:["partial","original","text"],question:"現行流通香港硬幣中，哪兩種面額的外形具有波浪形邊緣？",options:["2元及2毫","5元及5毫","1元及1毫","10元及2元"],answer:0,explanation:"2元與2毫硬幣的外形有波浪形邊緣。硬幣的大小、形狀和邊緣特徵有助觸覺辨識；波浪形輪廓不要與其他硬幣側邊的細槽紋混淆。插畫不含面額及官方幣面，避免直接提示答案。",hint:"留意輪廓一凹一凸，唔係圓形硬幣側面嗰啲細坑紋。",source:{label:"香港金融管理局・香港硬幣防偽特徵",url:"https://www.hkma.gov.hk/media/chi/doc/key-functions/monetary-stability/notes-and-coins/leaflet_c.pdf"}},{id:"u13",tier:2,category:"街頭・道路安全",art:"yellow-box",focus:{x:50,y:50},modes:["blurred","original","text"],question:"駕車直行穿過有「黃格仔」的路口，即使是綠燈，遇上哪種情況仍不應駛入？",options:["車內有乘客","路邊有巴士站","出口車道擠塞，無法完全駛出黃色方格","路面天氣晴朗"],answer:2,explanation:"直行時要確定出口暢通，能完全駛離黃格才可進入；綠燈不代表可以堵塞路口。一般路口在指定右轉線等候右轉有特定情況，涉及電車或輕鐵路軌的黃格限制亦不同，所以題目明確限定直行。",hint:"綠燈都要望遠少少：過咗路口有冇位畀成架車停？",source:{label:"運輸署・有交通燈的路口",url:"https://www.td.gov.hk/tc/road_safety/road_users_code/index/chapter_5_for_all_drivers/traffic_light_junctions_/index.html"}},{id:"u14",tier:1,category:"生活・街市日常",art:"red-market-bag",focus:{x:50,y:51},modes:["blurred","original","text"],question:"紅膠袋是香港街市常見的日常物件。以下哪項說法最恰當？",options:["紅色代表食物已通過政府檢驗","紅色塑膠必定可自然降解","紅袋本身可以殺菌，毋須清潔食物","它是盛載購物的袋，顏色不保證食品安全或可降解"],answer:3,explanation:"紅膠袋是香港日常街景和街市文化的一部分，用來盛載購物。紅色不是食品安全或可降解的認證；「當初為了遮血水才普及」未有可靠依據，不宜當成唯一歷史答案。",hint:"袋嘅顏色同食物有冇經過安全檢查，係兩回事。",source:{label:"香港大學美術博物館・在香港攜著紅色膠袋的人",url:"https://umag.hku.hk/wp-content/uploads/Press-release-Man-with-Red-Plastic-Bag-in-Hong-Kong-CH.pdf"}}]);var Nt={mtr:["港鐵・車站及乘客服務","https://www.mtr.com.hk/ch/customer/services/index.php"],td:["運輸署・公共交通及道路使用者守則","https://www.td.gov.hk/tc/road_safety/road_users_code/index.html"],hkma:["香港金融管理局・香港貨幣","https://www.hkma.gov.hk/chi/key-functions/money/hong-kong-currency/"],afcd:["漁護署・郊野公園","https://www.afcd.gov.hk/tc_chi/country/cou_vis/cou_vis.html"],geo:["香港聯合國教科文組織世界地質公園","https://www.geopark.gov.hk/tc/"],ich:["非物質文化遺產辦事處","https://www.icho.hk/tc/web/icho/home.html"],amo:["古物古蹟辦事處・歷史建築","https://www.amo.gov.hk/tc/historic-buildings/monuments/index.html"],museum:["香港歷史博物館","https://hk.history.museum/tc/web/mh/index.html"],tourism:["香港旅遊發展局・本地文化","https://www.discoverhongkong.com/tc/culture.html"],hko:["香港天文台・熱帶氣旋警告","https://www.hko.gov.hk/tc/informtc/tcMain.htm"],wsd:["水務署・水資源","https://www.wsd.gov.hk/tc/core-businesses/water-resources/"],lcsd:["康樂及文化事務署・康樂設施","https://www.lcsd.gov.hk/tc/facilities/facilitieslist.html"],post:["香港郵政・郵政歷史","https://www.hongkongpost.hk/tc/about_us/whats_new/index.html"],octopus:["八達通・消費者資訊","https://www.octopus.com.hk/tc/consumer/index.html"],fsd:["香港消防處・消防安全資訊","https://www.hkfsd.gov.hk/chi/"],fehd:["食物環境衞生署・環境衞生","https://www.fehd.gov.hk/tc_chi/"],labour:["勞工處・竹棚架工作安全守則","https://www.labour.gov.hk/tc/public/content2_8.htm"],stadium:["啟德體育園・啟德主場館","https://www.kaitaksportspark.com.hk/"],olympic:["中國香港體育協會暨奧林匹克委員會","https://www.hkolympic.org/zh/"],racing:["香港賽馬會・賽事資訊","https://racing.hkjc.com/"],film:["香港電影資料館","https://www.filmarchive.gov.hk/tc/web/hkfa/home.html"],csd:["懲教署・香港懲教博物館","https://www.csd.gov.hk/emuseum/tc/museum.html"],lands:["地政總署・測繪處","https://www.landsd.gov.hk/tc/survey-mapping.html"],hku:["香港大學・研究與發現","https://www.hku.hk/research/"]},ot={25:[50,24],54:[50,72],58:[50,24],64:[50,42],65:[50,35],66:[45,35]};function a(t,e,o,r,i,n,c,u,h,p=["original","blurred","text"],x="保留主題，改成有完整線索及唯一正解的四選一。"){let l=(t+1)%4,d=[...n];d.splice(l,0,i);let[R,M]=Nt[h];return Object.freeze({id:"c"+String(t).padStart(2,"0"),sourceNumber:t,tier:e,category:o,question:r,options:Object.freeze(d),answer:l,explanation:c,hint:u,art:"comic-"+String(t).padStart(2,"0"),focus:Object.freeze({x:ot[t]?.[0]??50,y:ot[t]?.[1]??52}),modes:Object.freeze(p),...p.length===1&&p[0]==="text"?{textOnly:!0}:{},source:Object.freeze({label:R,url:M}),review:x})}var rt=Object.freeze([a(1,1,"港鐵・城市色彩","漫畫中的車站牆用七色橫帶作提示，最切合以下哪個香港站名？","彩虹",["荃灣","旺角","鑽石山"],"彩虹站的多色車站設計呼應站名。插畫以七色牆作提示，不把一小塊單色瓷磚當成足以辨認任何車站的證據。","將七種顏色連埋一齊，會諗起邊個站名？","mtr",["original","blurred","text"],"原稿只見單色馬賽克不能唯一辨站；改以七色整體作線索。"),a(2,2,"街頭・小巴水牌","手寫小巴水牌上的「大角咀」，屬於香港哪個行政區？","油尖旺區",["北區","離島區","南區"],"大角咀位於九龍油尖旺區。香港手寫小巴水牌是本地招牌文化的一部分；只見一個「大」字不足以判定目的地。","個地名喺九龍西，近旺角同奧運一帶。","td",["original","text"],"保留手寫水牌；顯示完整地名，避免以一個字猜多個目的地。"),a(3,1,"貨幣・硬幣細節","漫畫放大的花形圖案，常見於香港1993年起發行的新設計硬幣正面。它是甚麼花？","洋紫荊",["向日葵","牡丹","玫瑰"],"洋紫荊圖案出現在1993年起發行的新設計香港硬幣。不同面額可有相同花形，不能只靠一片花瓣猜面額。","香港市花，花形有五瓣。","hkma",["original","partial","blurred","text"],"原稿同一花瓣可見於多種面額；改考可唯一辨認的圖案。"),a(4,1,"郊野・標距柱","遠足徑標距柱上的編號以「M」開頭，例如M001，一般屬於哪條長途遠足徑？","麥理浩徑",["衛奕信徑","港島徑","鳳凰徑"],"麥理浩徑標距柱用M字頭；衛奕信徑、港島徑、鳳凰徑分別常用W、H、L。求助時應同時交代地點，","M同個英文名MacLehose有關。","afcd",["original","text"]),a(5,2,"地質・海蝕景觀","漫畫中的海蝕斷崖與六角岩柱，提示萬宜水庫東壩附近哪個著名地質景點？","破邊洲",["昂坪","鯉魚門","林村"],"破邊洲在萬宜水庫東壩附近，是海蝕作用令岬角部分與陸地分離而成的海蝕柱景觀。插畫表現海蝕與岩柱的概念特徵。","個名有個「破」字，喺西貢地質公園一帶。","geo",["original","mirrored","text"]),a(6,3,"郊野・公園知識","按個別已劃定郊野公園的面積比較，以下哪個是香港面積最大的郊野公園？","南大嶼郊野公園",["北大嶼郊野公園","西貢東郊野公園","八仙嶺郊野公園"],"南大嶼郊野公園面積約56平方公里，比單一的大帽山、香港仔或獅子山郊野公園大。不要把郊野公園與特別地區混作同一項統計。","答案喺香港最大嘅島上。","afcd",["text"],"刪除不精確的全港土地比例，限定比較個別郊野公園。"),a(7,2,"街頭・文字藝術","香港街頭文字文化中，被稱為「九龍皇帝」的創作者是誰？","曾灶財",["區建公","金庸","李小龍"],"曾灶財因其街頭墨跡及「九龍皇帝」自稱而廣為人知。漫畫字牆是原創示意，並非其真跡或可供考證的摹本。","佢姓曾，唔係題寫商舖招牌嘅區建公。","museum",["original","text"]),a(8,1,"飲食・手寫菜牌","手寫菜牌上的「乾炒牛河」，當中的「河」通常指哪種食材？","河粉",["意大利粉","米線","烏冬"],"乾炒牛河以牛肉和河粉等炒製；河粉是米製的扁闊粉條。菜牌是清楚可讀的漫畫字，不假冒任何書法家的草書作品。","唔係條河，係碟入面嗰種扁扁闊闊嘅粉。","tourism",["original","text"],"把難以可靠辨認的草書，改成手寫菜牌加飲食知識。"),a(9,1,"漢字・地名聯想","漫畫用鬃毛、四腳和尾巴畫成一個「馬」的造字示意。以下哪個香港地名以這個字開頭？","馬鞍山",["牛頭角","九龍","象山"],"馬鞍山以「馬」字開頭，山形亦令人聯想到馬鞍。圖中是便於理解的造字示意，不是出土甲骨文的複製。","睇吓動物係馬，定係牛、龍、象。","museum",["original","text"]),a(10,1,"節慶・長洲","長洲太平清醮的飄色巡遊及搶包山活動，通常集中在哪個農曆日期前後舉行？","農曆四月初八",["農曆正月十五","農曆八月十五","農曆九月初九"],"長洲太平清醮的主要公眾活動通常配合農曆四月初八佛誕，搶包山比賽一般於當晚舉行。實際活動安排仍以主辦單位公布為準。","同佛誕假期有關，唔係中秋。","ich",["original","blurred","text"],"避免把整個醮期說成只有一天，或保證每年安排完全相同。"),a(11,2,"節慶・火龍細節","中秋舞火龍隊伍拿着插滿線香的「龍珠」。以下哪個銅鑼灣附近社區，以這項傳統聞名？","大坑",["赤柱","元朗屏山","東涌"],"大坑舞火龍是香港代表性的中秋傳統，龍身和龍珠上的線香形成火光。漫畫表現線香火光與隊伍形態，並非活動照片。","問題已畀咗社區線索，記住呢項中秋傳統個名。","ich",["original","partial","blurred","text"]),a(12,1,"工藝・戲棚","香港傳統神功戲的臨時戲棚，常以哪種材料搭建主要棚架？","竹",["玻璃","紙皮箱","冰塊"],"竹是傳統戲棚常用的主要棚架材料，搭建涉及專業工藝與安全要求。這門工藝亦與節慶、地方信仰及戲曲文化相連。","又輕又有韌性，搭棚師傅好熟悉。","ich",["original","partial","text"]),a(13,2,"體育・新地標","圖中的主場館約有五萬座位及可開合上蓋，屬於香港哪個大型體育項目？","啟德體育園",["香港文化中心","香港濕地公園","香港動植物公園"],"啟德主場館是啟德體育園的一部分，約有五萬個座位及可開合上蓋。漫畫表現場館概念輪廓，並非工程圖。","舊機場一帶嘅大型體育新地標。","stadium",["original","mirrored","text"]),a(14,2,"體育・奧運劍擊","張家朗在東京2020及巴黎2024奧運奪得男子個人金牌的項目，使用哪種劍？","花劍",["重劍","佩劍","西洋長矛"],"張家朗在這兩屆奧運贏得男子個人花劍金牌。花劍、重劍及佩劍的有效部位與規則不同，不能只憑一個通用劍擊剪影分辨。","香港人講起佢，成日會講「花劍」。","olympic",["original","text"],"明確指定運動員與兩屆賽事，避免混合泳手及不同兵器。"),a(15,3,"歷史・舊機場","啟德機場仍營運時，香港國際機場使用的IATA三字代碼是甚麼？","HKG",["KAI","KOW","HKA"],"啟德機場使用HKG；1998年機場搬到赤鱲角後，香港國際機場繼續使用HKG。IATA三字代碼與ICAO四字代碼並不相同。","搬機場唔代表香港嘅三字代碼一定要換。","museum",["text"]),a(16,2,"歷史・舊地名","旺角的歷史舊稱，以下哪個寫法曾經使用？","芒角",["網角","忘角","皇角"],"「芒角」是旺角的歷史舊稱之一。地名來源有不同說法，不把「曾種滿某植物」當成唯一已證實原因。","個字有個草花頭，讀音同「旺」唔同。","museum",["text"],"保留舊稱，刪除未有充分依據的單一植物起源說法。"),a(17,2,"飲食・茶記暗號","部分茶餐廳行話中的「和尚跳海」，通常指哪種飲品？","滾水蛋",["凍檸茶","絲襪奶茶","齋啡"],"「和尚跳海」常被用來形容滾水蛋。茶餐廳暗號可因店舖及年代而異，點餐時直接講飲品名稱更清楚。","個「和尚」圓碌碌，落咗杯熱水入面。","tourism",["original","text"],"只問一個常見暗號；不把不同店舖的206或打爛用法混成同一答案。"),a(18,1,"飲食・公雞碗","漫畫餐具上畫着紅冠、黑尾的公雞，香港人常把這類傳統飯碗叫甚麼？","雞公碗",["魚蛋碗","龍舟碗","菠蘿碗"],"雞公碗的公雞花樣是粵地及香港飲食文化中常見的餐具圖案。此圖是原創公雞，沒有複製特定品牌包裝。","望住碗身嗰隻動物就有線索。","tourism",["original","partial","blurred","text"]),a(19,1,"飲食・飲茶文化","粵式飲茶說的「一盅兩件」，「一盅」一般指甚麼？","一盅茶",["一盅飯","一盅咖喱","一盅糖水"],"「一盅兩件」通常指茶配兩件或兩款點心，反映悠閒飲茶的說法，不是要求每次點餐都必須嚴格兩件。","「飲茶」兩個字已經畀咗提示。","tourism",["original","text"]),a(20,2,"建築・屋邨天井","以圓筒形樓宇與圓形天井著名、位於大坑的住宅屋邨是哪個？","勵德邨",["彩虹邨","華富邨","坪石邨"],"勵德邨以獨特的圓筒形樓宇和天井為人熟悉。這是住宅地方，參觀應尊重住戶私隱和管理安排。","個名有個「勵」字，唔係彩虹嗰個球場。","tourism",["original","mirrored","text"]),a(21,3,"設計・舊街牌","舊式香港街牌字體俗稱「監獄體」，這個稱呼主要與哪段製作背景有關？","部分街牌曾由在囚人士製作",["因先在監獄附近街道試用而得名","字形模仿監獄鐵閘的比例","以一間街牌印刷廠的名字命名"],"「監獄體」是對一類舊街牌字形的俗稱，與昔日由在囚人士製作街牌的背景有關，並非官方統一字體名稱。","個俗稱講緊製作背景，唔係街牌指向邊度。","csd",["original","text"],"不把俗稱當正式字體名稱，刪除過於絕對的製作年份。"),a(22,2,"街舖・當舖招牌","傳統當舖招牌的蝙蝠與銅錢，利用「蝠／福」和「錢／前」諧音，寓意甚麼？","福在眼前",["招財進寶","五福臨門","金玉滿堂"],"蝙蝠的「蝠」與「福」同音，錢與「前」構成吉祥聯想，常解作「福在眼前」。民俗寓意不代表典當或借貸能保證獲利。","將「蝠」換成「福」，「錢」換成「前」試吓。","museum",["original","blurred","text"]),a(23,2,"歷史・香木貿易","一種常見的香港名稱來源說法，與昔日轉運哪類本地香木產品有關？","土沉香",["檀香木","龍涎香","丁香"],"香港地名與香木貿易的關係是常見說法之一，土沉香亦與本地歷史有關。地名來源有多種解釋，不宜把一種說法當成唯一結論。","係香木，唔係現代樽裝香水。","museum",["original","text"],"改為「常見說法之一」，不斷言香港得名只有單一來源。"),a(24,2,"節慶・大澳龍舟","大澳在端午舉行、由當地龍舟巡遊水道的傳統活動，稱為甚麼？","龍舟遊涌",["搶包山","飄色巡遊","舞火龍"],"大澳端午龍舟遊涌把龍舟、水道與地方信仰連在一起，是香港重要的傳統節慶活動。「舟」的漫畫圖只作造字聯想。","大澳有水道，端午就諗起龍舟。","ich",["original","blurred","text"]),a(25,3,"民俗・盂蘭勝會","潮籍盂蘭勝會常見的紙紮「大士王」，頭頂通常設哪位神明的小像？","觀音",["財神趙公明","土地公","北帝"],"傳統大士王形象常在頭頂設觀音小像，反映相關民俗信仰。不同地方的造型可有差異，漫畫不是宗教造像的標準圖樣。","「大士」都會令人聯想到觀音。","ich",["original","partial","text"]),a(26,2,"地質・層狀岩石","香港東北面哪個島，以層狀沉積岩和「千層糕」般的海岸岩石聞名？","東平洲",["長洲","青衣","馬灣"],"東平洲的沉積岩、海蝕平台及岩層紋理是重要地質特色。不是所有條紋岩石都能單憑局部照片確定出處，題目附有東北面島嶼線索。","個名有個「洲」字，而且唔係長洲。","geo",["original","partial","mirrored","text"]),a(27,3,"歷史・水務古蹟","港島大潭水塘群中，1917年落成、以大型砌石壩聞名的水塘是哪個？","大潭篤水塘",["大潭上水塘","大潭副水塘","大潭中水塘"],"大潭篤水塘於1917年落成，其砌石壩是大潭水務文物的重要部分。不要把壩頂溢洪口與附近不同橋樑的拱孔數目混淆。","名字喺「大潭」後面再加一個字。","amo",["original","text"],"刪除原稿未可靠區分的21個拱門說法，改考可確認的水塘與年份。"),a(28,2,"自然・香港市花","洋紫荊通常不能靠自然結出的種子繁殖，主要原因是甚麼？","它是天然雜交而不育的品種",["它的花粉只能由外地昆蟲傳播","它的種子必須經海水浸泡才能萌芽","它只在低於攝氏十度時結出種子"],"洋紫荊被視為天然雜交而不育的品種，通常以扦插、嫁接等無性方法繁殖。不能把它與其他可以結莢的同屬植物混為一談。","唔係每種開花植物，都一定可以靠種子傳宗接代。","afcd",["text"]),a(29,3,"貨幣・2018系列","2018系列三家發鈔銀行的500元鈔票，共同採用哪個背面主題？","香港聯合國教科文組織世界地質公園",["香港茶點","粵劇文化","蝴蝶"],"2018系列500元共同主題是世界地質公園；100元是粵劇文化、20元是茶點。不同銀行的具體構圖有別，題圖不是鈔票複製品。","六角岩柱會令你諗起邊種香港自然景觀？","hkma",["original","text"],"限定2018系列與共同主題，不把一個通用水袖局部當成所有鈔票的唯一面額證據。"),a(30,3,"氣象・信號演變","1973年香港把原來不同數字的烈風信號統一改稱八號各方向信號，主要有助消除甚麼誤解？","誤以為數字不同便代表風力強弱不同",["誤以為數字等於颱風中心風速級別","誤以為信號數字表示颱風與香港距離","誤以為信號數字表示距離登陸的時數"],"舊烈風信號的不同數字對應不同方向，容易令人誤會數字越大風力越強。1973年起以八號加方向區分，更清楚表達其性質。","重點係原本數字講方向，唔係風力排名。","hko",["text"]),a(31,2,"道路・斑馬線","斑馬線前後的白色之字形標線，對駕駛者主要標示甚麼範圍？","受停車及超越限制的行人過路處控制區",["可以隨時停車上落客的免費區","只准電單車停泊的區域","所有車必須倒車通過的區域"],"之字形標線標示行人過路處控制區，設有停車及超越限制，以維持視線及行人安全。具體規定及例外應按道路使用者守則理解。","行人準備過馬路，司機視線唔應該畀停車遮住。","td",["original","text"],"用控制區及限制的準確表述，避免籠統說任何情況都嚴禁所有停車或超越。"),a(32,3,"體育・賽馬回憶","2024年退役、三度獲香港馬王稱號，並贏得10場一級賽的賽駒是誰？","金鎗六十",["美麗傳承","爪皇凌雨","精英大師"],"金鎗六十於2024年退役，曾三度成為香港馬王並贏得10場一級賽。題目鎖定其退役時成就，不把可能更新的獎金或紀錄排名寫成永恆事實。","個名有個數字「六十」。","racing",["text"],"限定2024年退役時成就，不斷言截至現在仍保持最多一級賽紀錄。"),a(33,2,"電影・經典天台","「對唔住，我係差人」的著名天台對白，出自哪部2002年香港電影？","無間道",["少林足球","歲月神偷","食神"],"這句對白來自2002年的《無間道》。漫畫天台是原創場景，並非電影截圖，也不提供未經確認的拍攝大廈位置。","兩個身份互相角力嘅經典警匪片。","film",["original","text"],"原稿的北角拍攝地點說法未能可靠核對，改考可確認的電影與年份。"),a(34,1,"體育・第一面金牌","李麗珊在1996年阿特蘭大奧運，為香港贏得首面金牌的項目是甚麼？","滑浪風帆",["游泳","乒乓球","單車"],"李麗珊於1996年奪得女子滑浪風帆金牌，是香港首面奧運金牌。她的成就亦令更多人認識香港水上運動。","有塊帆，借風力喺海上前進。","olympic",["original","text"],"以可確認的體育成就出題，避免以多句改寫名言混淆直接引語。"),a(35,2,"數字・街市花碼","價牌明確標示以「元」為單位，花碼寫着「〤〥」。這個數值是多少？","45元",["25元","48元","95元"],"蘇州碼子又稱花碼，〤代表4、〥代表5。實際街市價牌還可能配合位值、單位及其他記號；題目已明確指定單位，避免單靠兩個符號猜價格。","先認出兩個數字，再留意題目寫明嘅單位。","museum",["original","text"],"不以缺少位值和單位的符號直接斷定價錢。"),a(36,3,"書法・香港招牌","香港不少舊式招牌採用雄渾方折、受北朝碑刻影響的字風，通常稱為甚麼體？","北魏體",["宋體","隸書","楷書"],"北魏體的方折、厚重筆意，與香港許多傳統招牌的視覺記憶相關。漫畫字是原創排寫，並非區建公或其他書法家的摹本。","名稱直接提到中國北朝其中一個政權。","museum",["original","text"]),a(37,2,"工藝・花牌","竹篾、彩紙與鮮艷大字組成的傳統花牌，主要是甚麼用途？","為慶典、醮會或開張等場合作祝賀及公告",["量度風速的官方儀器","永久建築物的承重牆","海上救生浮具"],"花牌紮作把竹篾結構、裝飾與文字結合，常用於節慶、醮會、婚慶及開張等。是否出現於某個花市並非可靠的排他判準。","遠遠都睇到，用嚟傳遞喜慶消息。","ich",["original","blurred","text"],"原稿「通常不出現在哪場合」有歧義，改考工藝與用途。"),a(38,2,"郊野・測量設施","山頂常見的黑白標高柱，主要與哪項專業工作有關？","測繪與三角測量",["量度山頂降雨量","監測空氣質素","記錄地震振幅"],"標高柱是測量控制設施的一種，醒目的標記有助觀測辨認。它不是避雷保證、氣溫計或供遊人攀爬的裝置。","望遠鏡對準固定點，先可以準確測量。","lands",["original","partial","text"],"保留辨識與測量用途，不把所有黑白油漆設施都說成相同儀器。"),a(39,3,"建築・鑊耳山牆","傳統鑊耳式山牆高出屋頂，其建築功能之一是甚麼？","減少火勢沿相連屋頂蔓延",["集中收集屋頂雨水","支撐屋頂中央的旗桿","為瓦面提供通風槽"],"高起的封火山牆有助阻隔火勢沿相連屋頂蔓延，鑊耳外形亦有地方文化象徵。不能單憑一幅牆就斷定屋主一定考取過功名。","題目講建築功能，留意「封火牆」呢個名。","amo",["original","mirrored","text"],"保留鑊耳屋，改考防火功能，不以外形斷言家族官階或指認不相符的建築。"),a(40,3,"工程・船灣淡水湖","船灣淡水湖在1960年代落成，其建造方法最特別之處是甚麼？","築壩圍起海灣，把部分海面轉成淡水庫",["在天然淡水湖邊加高堤壩","完全利用地下洞穴蓄水","把河道改成抽水蓄能上池"],"船灣淡水湖利用海灣建壩成庫，再處理鹹水及蓄存淡水，是香港代表性的水務工程。題目考工程方法，不把「全球第一」的不同定義混為定論。","原本係海水，點樣圍起嚟變水庫？","wsd",["original","text"],"避開全球首個等須界定工程類型的絕對紀錄說法。"),a(41,1,"漢字・百年交通","漫畫把車輪和車軸畫成「車」的造字示意。1904年起在港島服務、響鈴行走的雙層交通工具是甚麼？","香港電車",["山頂纜車","機場快綫","天星小輪"],"香港電車於1904年投入服務，清脆車鈴帶來「叮叮」別稱。漫畫是造字聯想示意，不是假稱出土的古文字。","有路軌，又會喺港島馬路上響叮叮。","td",["original","text"]),a(42,2,"漢字・海港地名","把魚的輪廓與舊石礦場文化連起來，哪個香港海港地名最切合漫畫提示？","鯉魚門",["馬鞍山","牛頭角","長沙灣"],"鯉魚門以海港、海鮮及石礦歷史等為人熟悉，地名包含「魚」。圖中魚形是教學插畫，不是考古字形的摹本。","三個字，中間嗰個就係「魚」。","tourism",["original","text"]),a(43,2,"歷史・西貢小島","西貢哪個小島以客家村落、曬鹽歷史及聖若瑟小堂聞名？","鹽田梓",["坪洲","南丫島","蒲台島"],"西貢鹽田梓的鹽田、客家聚落與天主教小堂，構成獨特的文化景觀。相關保育項目曾獲國際文化遺產保護獎項肯定。","個名有個「鹽」字，喺西貢海域。","amo",["original","text"]),a(44,3,"工藝・飄色支架","長洲飄色中，支撐表演小朋友、並巧妙藏入裝飾的鋼枝結構，俗稱甚麼？","色芯",["龍舟槳","花劍","包山"],"「色芯」是飄色支撐結構的傳統用語之一，配合服裝及裝飾營造凌空效果。結構配合表演者姿勢，讓巡遊呈現「飄」的效果。","個名同「飄色」嘅「色」有關。","ich",["original","partial","text"]),a(45,1,"民俗・觀音借庫","觀音借庫所得紅紙上的大額數字，主要應如何理解？","祈求財運的民俗意頭，不是真實借款",["廟宇真的會即場借出該筆現金","政府保證可以兌換的支票","銀行已批准的貸款額"],"觀音借庫是祈福民俗，紅紙金額象徵財運及吉祥，不是可兌現的借貸或投資承諾。","求個好意頭，同簽銀行借貸合約係兩回事。","ich",["original","blurred","text"]),a(46,1,"民俗・車公風車","到車公廟轉風車的民俗，通常寄託哪種心願？","祈求轉運與平安",["保證即日中六合彩","依法取消所有欠款","量度廟內精確風速"],"轉風車常寄託轉運、平安等心願。方向說法可能因傳統或講法而異，不能當成有唯一客觀正解的規則，也不代表保證帶來財富。","係民俗祈願，唔係保證獲利嘅機器。","ich",["original","mirrored","text"],"刪除沒有唯一準則的順逆時針判分，保留民俗意義。"),a(47,2,"科學・山頂纜車","乘山頂纜車時，窗外大廈看似傾斜，較合理的解釋是甚麼？","傾斜車廂與身體姿勢改變了視覺和平衡參考",["車窗的特殊鏡片把大廈影像折彎","該區大廈刻意建成相同傾角","車速造成透視形狀永久改變"],"車廂沿斜坡傾斜，身體姿勢、視覺及重力參考的組合可產生傾斜錯覺。這不表示窗外大廈真的按同一角度歪斜。","自己坐緊斜車廂，會影響點樣判斷「直」。","hku",["original","text"]),a(48,1,"社區・街場","漫畫中的圍網、球場界線及球架，最符合哪種社區設施？","戶外籃球場",["郵政信箱區","機場登機閘口","渡輪機房"],"戶外球場常見圍網、球架及地面界線。球場配色會隨設計及翻新改變，不宜把某兩種顏色說成全港統一的標準。","見到個籃球架，再望地上條線。","lcsd",["original","partial","blurred","text"],"以設施特徵辨識，刪除全港街場固定配色的斷言。"),a(49,2,"歷史・郵筒","退役的舊式郵筒保存作展品，主要有甚麼文化價值？","記錄郵政設計及城市生活的變遷",["證明仍可免郵資寄信","保證內有可提取現金","作為通用免費Wi-Fi密碼"],"舊郵筒可作郵政歷史與設計的實物見證。顏色、徽號及是否仍收信要按現場標示判斷，不能假設所有紅色郵筒都仍在服務。","保留下來嘅舊物，可以講出城市點樣改變。","post",["original","partial","text"],"不聲稱1997年一夜全面改色，或僅憑顏色判定位置與服務狀態。"),a(50,2,"體育・七欖回憶","香港國際七人欖球賽於2025年移師啟德前，長期舉辦賽事並以南看台文化聞名的是哪個場地？","香港大球場",["旺角大球場","荃灣體育館","香港文化中心"],"香港大球場位於掃桿埔，曾長期舉辦香港國際七人欖球賽；2025年賽事移至啟德主場館。題目明確限定移師前的歷史。","喺掃桿埔，唔係旺角。","lcsd",["original","text"]),a(51,1,"生活・八達通","漫畫中的「8」形色帶提示八達通。它最代表香港哪種日常付款方式？","非接觸式儲值支付",["只限在銀行櫃位寫支票","必須把硬幣逐個投入卡內","只能付款一次便作廢"],"八達通於1997年推出，把非接觸式儲值支付帶進交通與零售日常。圖中是原創色帶聯想，不複製官方商標，也不替品牌猜測唯一設計寓意。","拍一拍就可以付款，唔使每次搵散紙。","octopus",["original","text"],"保留8形生活印記，改考可確認的付款功能，不臆測品牌唯一設計動機。"),a(52,2,"海灘・防鯊網","公眾泳灘海面的一列浮波連着水下網，若屬防鯊網設施，主要作用是甚麼？","減低鯊魚進入指定泳區的風險",["保證所有水母都不能進入","把所有海浪完全消除","自動替泳客量血壓"],"防鯊網旨在減低鯊魚進入泳區的風險，但不是對所有海洋生物或事故的保證。游泳仍應留意旗號、天氣及救生員指示。","個名已講咗主要針對邊種海洋動物。","lcsd",["original","partial","text"]),a(53,2,"街頭・渠蓋","只看渠蓋的格紋或放射紋，應否斷定下方一定是雨水渠或污水渠？","不應，應連同標記、設施資料及標準核對",["應，所有城市的花紋都完全統一","應，只要是圓形就一定是煤氣管","應，顏色能顯示所有地下電壓"],"渠蓋紋理可有防滑、製造及不同標準的考慮，不能把一種花紋與所有地下管道作一對一通用對照。辨認時需要更多設施資料作依據。","街上唔同年代、唔同機構嘅渠蓋，未必用同一套圖案。","wsd",["original","partial","text"],"原稿花紋與管道的一對一說法未可靠核實，改考辨識限制。"),a(54,2,"無障礙・過路裝置","部分行人過路裝置設觸覺振動功能，最直接協助哪類使用者接收過路提示？","需要以觸覺接收提示的人，包括部分視聽障人士",["需要以按鈕升降路面的輪椅使用者","需要計算步速的跑步人士","需要尋找嬰兒車泊位的家長"],"聲響、視覺及觸覺提示配合，能照顧不同需要。實際過路裝置的按鈕及振動設計可有差異，仍須按現場指示安全過路。","唔係靠睇或聽，而係靠手感受。","td",["original","partial","text"],"保留觸覺輔助，刪除所有裝置都必然有相同旋轉圓錐的說法。"),a(55,3,"消防・消防栓顏色","香港一般消防栓的紅、黃配色，常用來區分哪組供水？","紅色淡水、黃色海水",["紅色海水、黃色淡水","紅色高壓、黃色低壓","紅色街道主管、黃色大廈支管"],"一般以紅色標示淡水消防栓、黃色標示海水消防栓。這是供水種類的辨識，不是日夜使用時段的區分。","留意題目講緊供水種類，唔係日間同夜間。","fsd",["original","text"],"更正原稿把紅色海水、黃色淡水倒置的答案。"),a(56,2,"交通・泊車收費錶","遇到不同顏色或型號的泊車收費錶，判斷可泊多久最可靠的方法是甚麼？","查看現場交通標誌及收費錶顯示的適用限制",["只靠外殼是藍色還是灰色","問隔鄰車主停了多久便照做","只憑今天是不是星期日猜測"],"泊車地點的適用時段、收費及最長停留時間，要按現場標誌與設備顯示核對。設備會更新，不應把某種舊外殼顏色當成永遠適用的規則。","新舊咪錶會變，現場標誌先係要睇清楚嘅資料。","td",["original","blurred","text"],"刪除未可靠核實的藍色一律30分鐘說法，改考現場限制。"),a(57,2,"街道・門牌箭咀","街牌上寫着「← 1–45」，最直接提供哪種資訊？","該方向的門牌號碼範圍提示",["該道路的最高行車速度","該路段的泊車收費時段","巴士路線編號及行車方向"],"箭咀與號碼範圍協助行人找地址，不保證每個號碼都存在，也不能由單一街牌推斷所有街道的單雙號分布。","你搵緊地址，唔係搵車速。","lands",["original","text"],"保留門牌箭咀，避免把左右單雙號慣例寫成所有香港街道的絕對規則。"),a(58,2,"交通・巴士細節","部分雙層巴士上層車頭外的弧形「樹擋」，主要用來做甚麼？","把低垂樹枝導開，減低撞及車窗的風險",["作為車載通訊系統的天線","清潔擋風玻璃的外置裝置","改善車頂空氣流動的導流架"],"樹擋的用途是減少低垂枝葉撞及車頭上層玻璃等部位的風險。不是每款車都採同樣外形，亦不代表能防止所有碰撞。","個名已經講咗係擋邊樣嘢。","td",["original","partial","text"]),a(59,2,"交通・小巴車速","小巴車廂的車速顯示器，主要讓乘客知道甚麼？","車輛當時的行駛速度",["整段旅程的平均車速","到下一站尚需的分鐘","本班車累積行駛的公里"],"車速顯示器讓乘客看到當時車速，警報是輔助提示。是否超速仍要按道路速度限制及車種規定判斷，不能把警報門檻當作所有路段的合法速度。","個紅色數字講緊架車行得幾快。","td",["original","blurred","text"],"保留裝置用途，不把警報速度與所有道路的法定限速混為一談。"),a(60,1,"道路・斑馬線閃燈","沒有交通燈控制的斑馬線上已有行人過路，駕駛者應怎樣做？","停車讓行人安全通過",["響號催促行人讓車","只要閃燈亮着便可加速","把行人當成一定會停下"],"斑馬線的閃燈提醒駕駛者留意過路處。應停車讓已在過路處的行人安全通過，接近時亦須留意準備過路的人；行人也要確認車輛停下才安全通過。","黃色閃光唔係叫你搶快，係叫你留意行人。","td",["original","blurred","text"]),a(61,1,"無障礙・觸覺引路徑","看到有長條及圓點凸紋的觸覺引路徑，以下哪個做法最合適？","保持暢通，不用行李或貨物堵塞",["把貨物堆上去方便辨認","把凸點磨平令地面更滑","在上面長時間擺攤"],"觸覺引路徑以不同紋理協助使用者辨認方向、位置或需要留意的地方。功能須按現場設計理解，保持通道暢通比單憑一塊磚猜所有意思更重要。","對有需要嘅人，呢條路係重要嘅提示。","mtr",["original","partial","text"],"避免把所有圓點磚及轉彎位置一概說成相同危險信號。"),a(62,1,"生活・拍卡提示","八達通拍卡後，要確認實際扣款與剩餘金額，最可靠是看甚麼？","收費器顯示的交易及餘額資料",["只憑自己聽到一下或兩下嘟聲","只看卡套的顏色","只看旁邊乘客付了多少"],"聲響可作提示，但不同營運者、卡種及交易狀態可能有不同設定。應配合屏幕交易結果核對，必要時向職員查詢，不能用固定嘟聲數通用判定所有卡種。","聲響係提示，實際金額就睇顯示。","octopus",["text"],"刪除兩聲必然代表某卡種的通用斷言，保留拍卡辨識題材。"),a(63,2,"街市・紅燈罩","肉檔的紅色照明，為何可能令肉類看起來更紅潤？","照明的光譜與色調會影響人眼看到的顏色",["紅光可保證肉類永不變壞","紅燈能代替冷藏及衞生管理","紅燈能把任何肉類變成同一品種"],"照明色調會影響肉類外觀，但外觀紅潤不等於新鮮或安全，仍需留意儲存、來源與衞生。不是「紅光折射就能保鮮」。","個燈改變嘅係你見到嘅顏色，唔係保鮮期。","fehd",["original","blurred","text"],"把錯用的折射及保鮮暗示，修正為照明影響觀感。"),a(64,2,"街頭・廢屑箱","街邊廢屑箱縮小投入口的措施，主要希望減少哪種不當使用？","塞入整袋家居或商業垃圾",["雨水進入桶內","不同可回收物被混放","清潔工人壓縮桶內垃圾的時間"],"街邊廢屑箱供處理零星廢物，縮小投入口旨在減少整袋家居或商業垃圾被棄置其中。不同時期型號可有不同尺寸，不能把一個尺寸當成全港固定規格。","街邊細桶唔係成袋家居垃圾嘅收集站。","fehd",["original","partial","text"],"保留政策用途，刪除所有現役垃圾桶都固定23×15厘米的說法。"),a(65,3,"工藝・竹棚綁帶","竹棚接點常用的專用捆紮膠帶，師傅會稱作甚麼？","膠篾／篾仔",["電索","膠喉","吊帶"],"傳統竹篾及現代專用膠篾與竹棚捆紮工藝有關，材料規格及操作必須依專業安全要求。「篾」亦連起了傳統材料與現代捆紮工藝。","個字讀音近「蔑」，係捆紮用嘅。","labour",["original","partial","text"],"以專用膠篾作答，不把任何黑色塑膠帶或一般尼龍帶都視為合規材料。"),a(66,1,"社區・舊信箱","部分舊式金屬信箱門上的小孔，除了通風，還方便住戶做甚麼？","不開鎖也可初步查看裡面有沒有信件",["保證郵件不會遺失","讓任何人把鎖直接拆開","自動讀出信件內容"],"小孔或窄縫可讓人初步看到信箱內是否有東西，但設計因款式而異，也不保證所有信件都能看清。這種小設計反映了昔日屋邨的生活需要。","望一眼有冇信，唔使每次都即刻開鎖。","museum",["original","partial","mirrored","text"]),a(67,2,"交通・速度算一算","假設一部自動梯以每秒0.75米運行，另一部為0.5米，前者快多少百分比？","50%",["25%","100%","10%"],"差額0.25除以原來0.5，等於50%。這是指定數值的數學比較，不表示所有港鐵或外國自動梯都固定用這兩種速度。","比較百分比，要用差額除以原本個數。","mtr",["text"],"把未核實的全港與外國標準速度對比，改成清楚列明假設的數學題。")]);var jt={road:["運輸署・道路使用者守則","https://www.td.gov.hk/tc/road_safety/road_users_code/index.html"],studs:["運輸署・白線及行車線","https://www.td.gov.hk/tc/road_safety/road_users_code/index/chapter_5_for_all_drivers/white_lines_and_traffic_lanes_/"],stopping:["運輸署・不准停車的地點","https://www.td.gov.hk/tc/road_safety/road_users_code/index/chapter_5_for_all_drivers/where_not_to_stop_/index.html"],signs:["運輸署・方向標誌","https://www.td.gov.hk/tc/road_safety/road_users_code/index/chapter_8_the_language_of_the_road/direction_signs_/index.html"],speed:["運輸署・安全駕駛，請勿超速","https://www.td.gov.hk/tc/publications_and_press_releases/publications/free_publications/safe_speed_safe_drive__/index.html"],probation:["運輸署・暫准駕駛執照須知","https://www.td.gov.hk/filemanager/tc/content_178/c%20booklet.pdf"],tram:["香港電車・電車文化","https://www.hktramways.com/tc/"],bus:["九龍巴士・乘客資訊","https://www.kmb.hk/"],id:["入境事務處・智能身份證符號","https://www.immd.gov.hk/hkt/services/hkid/smartid.html"],hawker:["食環署・流動小販牌照","https://www.fehd.gov.hk/tc_chi/pleasant_environment/hawker/itinerant.html"],licence:["食環署・小販牌照常見問答","https://www.fehd.gov.hk/tc_chi/pleasant_environment/hawker/hawker_faq.html"],notes:["金管局・紙幣","https://www.hkma.gov.hk/chi/key-functions/money/hong-kong-currency/notes/"],tactile:["金管局・2018系列鈔票介紹","https://www.hkma.gov.hk/media/chi/doc/key-functions/money/notes-and-coins/design-and-security/2018/Leaflet_Chi.pdf"],octopus:["八達通・使用指南","https://www.octopuscards.com/consumer/doc/tc/UserGuide_chi.pdf"],fire:["消防處・消防安全資訊","https://www.hkfsd.gov.hk/chi/"],mini:["消防處・迷你消防車","https://www.hkfsd.gov.hk/chi/aboutus/gallery/fireappliances/MFT.html"],mtr:["港鐵・乘客服務","https://www.mtr.com.hk/ch/customer/services/index.php"],first:["港鐵・頭等服務","https://www.mtr.com.hk/ch/customer/tourist/firstclass_index.html"],handrail:["am730・港鐵回應扶手帶圓點用途","https://www.am730.com.hk/article/1025208"],accessible:["屋宇署・設計手冊及舊版本索引（暢通無阻的通道）","https://www.bd.gov.hk/tc/resources/codes-and-references/codes-and-design-manuals/index.html"],weather:["天文台・熱帶氣旋注意事項","https://www.hko.gov.hk/tc/informtc/precaution.htm"],housing:["房屋委員會・屋邨管理","https://www.housingauthority.gov.hk/tc/"],meter:["水務署・水錶讀數指引","https://www.wsd.gov.hk/filemanager/sc/content_1476/meter_reading_guide.pdf"],water:["水務署・供水設施","https://www.wsd.gov.hk/tc/"],food:["食物安全中心・食物安全資訊","https://www.cfs.gov.hk/tc_chi/"],consumer:["消費者委員會・消費資訊","https://www.consumer.org.hk/tc"],culture:["香港旅遊發展局・本地文化","https://www.discoverhongkong.com/tc/culture.html"],floors:["政府新聞公報・樓宇樓層編號","https://www.info.gov.hk/gia/general/200911/04/P200911040202.htm"],bags:["環保署・塑膠購物袋收費常見問答","https://www.epd.gov.hk/epd/tc_chi/environmentinhk/waste/pro_responsibility/psb_faq.html"],recycling:["環保署・廢物回收","https://www.wastereduction.gov.hk/zh-hk"],tv:["通訊辦・接收數碼地面電視服務","https://www.ofca.gov.hk/tc/consumer_focus/guide/help_for_consumers/digital_terrestrial_tv/reception_of_dtt/index.html"],taxi:["運輸署・的士則例簡介","https://www.td.gov.hk/filemanager/tc/content_5216/GuidelinestoTaxiRegulations_TC_202309_With%20Notice.pdf"],crossing:["運輸署・電子行人過路發聲裝置","https://www.td.gov.hk/tc/transport_in_hong_kong/pedestrians/pedestrian_crossing_facilities/electronic_audible_traffic_signal/index_t.html"],labour:["勞工處・建造業職安健資訊","https://www.labour.gov.hk/tc/osh/OSHInfoCI.htm"],park:["康文署・康樂設施","https://www.lcsd.gov.hk/tc/facilities/facilitieslist.html"],toll:["運輸署・易通行","https://www.hketoll.gov.hk/"],ac:["食環署・2026年冷氣機滴水執法資訊","https://www.fehd.gov.hk/tc_chi/news/details/20260505_12371.html"],ich:["非物質文化遺產辦事處・傳統文化","https://www.icho.hk/tc/web/icho/home.html"]};function s(t,e,o,r,i,n,c,u,h,p=["original","blurred","partial","text"],x="保留題材，限定適用情境，避免把設計用途說成所有型號的統一規定。"){let l=(t+2)%4,d=[...n];d.splice(l,0,i);let[R,M]=jt[h];return Object.freeze({id:"d"+String(t).padStart(2,"0"),sourceNumber:t,tier:e,category:o,question:r,options:Object.freeze(d),answer:l,explanation:c,hint:u,art:"daily-"+String(t).padStart(2,"0"),focus:Object.freeze({x:50,y:52}),modes:Object.freeze(p),...p.length===1&&p[0]==="text"?{textOnly:!0}:{},source:Object.freeze({label:R,url:M}),review:x})}var it=Object.freeze([s(1,2,"道路・反光路釘","按香港道路使用者守則，紅色反光路釘一般標示車道哪一邊？","左面邊緣",["右面近中央分隔帶","只供巴士使用的行車線","前方有超速攝影機"],"紅色路釘標示車道左面邊緣；白色通常標示行車線或路中央，琥珀色標示右面近中央分隔帶。反光路釘依靠反射車燈提升夜間辨識，不一定自行閃光。","香港靠左行車，紅色幫你認出車道其中一側。","studs"),s(2,2,"交通・道路執法","香港道路上的固定式偵速攝影機，最直接有助達到哪項道路安全目的？","阻嚇超速，促使駕駛者遵守車速限制",["令車輛可以在鏡頭後任意加速","以機箱顏色取代所有車速限制標誌","偵測每輛車的燃油存量"],"偵速攝影機用於打擊及阻嚇超速。駕駛者應全程遵守限速，不應只在鏡頭前減速；不同型號的外觀不能被說成一律相同，也沒有「國際法例規定一律橙色」的依據。","安全目標係令車速合適，唔係教人避鏡頭。","speed",["original","blurred","text"],"移除所有機箱一律橙色及未證實的官方配色動機，只考可確認的安全用途。"),s(3,2,"道路・限制區","路邊雙黃實線通常表示全日不准停車；單黃線的生效時間應怎樣確認？","查看現場時間字牌及相關交通標誌",["一律只在星期日生效","只看路邊有沒有的士","假設每次可以停三分鐘"],"雙黃實線及／或全日不准停車標誌表示全日限制。單黃線須連同時間字牌閱讀；限制區內上落客貨亦受管制，不能把單黃線當成准許短暫停車的保證。","黃色線要連旁邊塊時間牌一齊睇。","stopping"),s(4,2,"電車・轉轍","電車車長用轉轍棒操作路軌的道岔，主要是為了甚麼？","轉換路軌接續方向，讓電車走所需路線",["把架空電纜的電壓調低","為車輪補充潤滑油","量度乘客上車的人數"],"道岔讓軌道車輛在分支路軌之間選路。部分道岔操作可用轉轍棒完成；這不是讓乘客模仿的動作，市民不應進入路軌或碰觸轉轍裝置。","分叉路軌要接去左定右，需要有個轉換裝置。","tram"),s(5,1,"巴士・落車鐘","巴士落車鐘已亮起「停站」提示，再按一下通常代表甚麼？","落車要求已登記，不必為同一站反覆按鐘",["取消剛才的落車要求","要求巴士立刻在路中心停下","自動替下一名乘客付車費"],"落車鐘登記停站要求。許多車型會保持提示而不重複鳴響；重置方式依車型而異，不能說每部巴士的電路必定相同。應及早按鐘，在安全位置等候停站。","燈已經着咗，車長已收到落車要求。","bus",["original","blurred","text"]),s(6,3,"證件・星號符號","香港身份證上的「***」符號，按入境處說明表示甚麼？","持證人年滿18歲，並有資格申領香港特區回港證",["持證人未滿18歲，並有資格申領香港特區回港證","持證人有資格申領香港特區護照，毋須理會年齡","持證人已獲准無條件逗留，但不能申領回港證"],"「***」關乎持證人的年齡及申領香港特區回港證資格，不是家族三代的出生證明。永久性居民身份及其他資格應按相應標記與官方規定判斷。插畫只用虛構符號，不含真人證件資料。","星號講嘅係證件資格，唔係族譜。","id",["original","partial","text"],"保留官方年齡及回港證資格解釋，不把星號本身等同所有居留身分。"),s(7,3,"街頭・雪糕車牌照","流動雪糕車涉及的小販牌照，以下哪個說法符合食環署現行流動小販政策？","流動小販牌照一般不容許繼承或轉讓",["牌照可隨車輛轉手而自動生效","牌照只可由持牌人的成年子女繼承","牌照可透過公司股份買賣自動轉移"],"冰凍甜點屬流動小販的牌照類別之一；流動小販牌照的一般政策不容許繼承或轉讓。牌照、車輛及食品經營要求各有規管，不能用固定車數或未核實年份概括全部制度。","車可以買賣，經營牌照未必可以跟住自由轉手。","hawker",["text"],"移除「一直只有14架」及未核實的停牌年份，以官方牌照政策出題。"),s(8,2,"貨幣・政府發鈔","現行10元塑質鈔票，是由哪個機構發行？","香港特別行政區政府",["香港上海滙豐銀行","渣打銀行（香港）","中國銀行（香港）"],"政府透過金管局發行10元流通鈔票；三家發鈔銀行發行現行其他五種主要面額。早年的銀行10元紙幣仍可能具有法定貨幣地位，故本題特別指定塑質10元。","留意鈔票上寫嘅發行機構，而唔係只睇銀碼。","notes",["original","blurred","text"]),s(9,2,"支付・八達通備用餘額","八達通使用了備用餘額後，下次增值會怎樣處理該筆負數？","先補回已使用的備用餘額",["把負數永久免除","將負數直接變成現金獎勵","取消卡內所有過往交易"],"備用餘額讓符合條件、餘額為正但不足以支付的交易，在限額內完成；下次增值時會先補回。限額及適用交易受卡種和服務條款限制，不是任意透支，也不是所有入閘情況都只需一毫子。","先前借用咗少少餘額，增值時要先填返。","octopus",["original","partial","text"],"改考可確認的補回機制，不把任何正數餘額都可通行或最初設計動機當作保證。"),s(10,1,"社區・手動火警鐘","走廊紅色手動火警報警裝置上的按壓標示，主要有甚麼用途？","指示按裝置說明觸發火警警報的位置",["顯示即時室內溫度","讓住戶重設大廈Wi-Fi","用來申請電梯優先使用"],"手動報警裝置讓發現火警的人按現場指示觸發警報。不同裝置可使用可復位面板或其他結構，不能把黑點一律說成弱化玻璃，更不能保證徒手壓碎任何玻璃都不會受傷。","紅色盒係報警用，唔係普通牆上開關。","fire",["original","partial","text"],"移除所有型號都使用弱化玻璃、以拇指壓碎必然安全的說法。"),s(11,2,"鐵路・頭等車廂","東鐵綫保留頭等車廂，與以下哪段鐵路歷史最有關？","前身九廣鐵路的不同等級車廂傳統",["它曾經是只載貨物的地下鐵","它原本是山頂纜車的一段","所有車廂都曾經只准皇室乘搭"],"東鐵綫承接九廣鐵路的歷史及頭等服務傳統。現時乘搭頭等需支付相應車費，使用八達通亦須按規定取得頭等確認；不是因為拿着大行李就自動獲准。","諗吓東鐵以前個名，同城際火車嘅車廂等級。","first",["original","blurred","text"]),s(12,1,"公園・長椅扶手","長椅上的扶手對長者或行動不便人士，有哪項直接幫助？","提供扶握及借力的位置，協助坐下或站起",["代替輪椅使用者所需的斜道","自動量度使用者的血壓","保證椅面永遠不會濕滑"],"扶手可提供支撐，協助坐下或起身。不同長椅還有座位分隔等設計效果，不能把每個公園的採購原因都歸為同一項政策。","由坐低到企起身，有個穩固扶手可以借力。","accessible"),s(13,2,"防風・玻璃窗","打風前在玻璃貼「米」字膠紙後，以下哪個做法仍然必要？","檢查並關緊窗戶，強風時遠離當風玻璃",["因為貼了膠紙，就可把窗完全打開","站在窗邊測試玻璃是否夠硬","用膠紙取代已損壞的窗鉸"],"天文台的防風建議包括檢查門窗及適當防護。貼膠紙不能保證玻璃不破，也不能取代修妥窗鉸、鎖扣或避開危險位置；效果會受玻璃及施工情況影響。","膠紙唔係窗戶維修，更唔係防爆保證。","weather",["original","blurred","text"],"改成穩妥的防風判斷，避免把黏碎片或抗風效果說成適用所有玻璃的保證。"),s(14,2,"屋邨・晾衣架","窗外「三支香」式晾衣架及竹竿，為甚麼需要留意固定和防墜措施？","鬆脫物件可能由高處墮下，危及途人",["它會令電視訊號自動消失","竹竿只要夠長就不用固定","衣物在室外不會受風影響"],"伸出外牆的晾衣裝置須留意狀況、安裝與屋邨規定，鬆脫的架、竿或物件可造成墮物危險。不同屋邨有不同設計，不能說全港所有窗外晾衣架均已禁止。","物件伸咗出街，首先要諗下面行過嘅人。","housing",["original","blurred","text"],"移除全港一律清拆及禁止的概括說法，改考可確認的墮物風險。"),s(15,1,"街市・摺疊排檔","傳統鐵皮排檔的摺門及可收合層架，最直接方便哪種日常操作？","開檔時陳列貨品，收檔時收合上鎖",["每晚自動變成地下停車場","不需牌照就可無限擴闊路面攤位","自動把所有食物冷藏"],"不少固定攤檔以可收合門板和層架節省收檔空間。實際擺放仍須遵守牌照及通道要求；摺合鐵箱並不等於具防火、防爆或全面防水認證。","日頭打開做生意，夜晚要收返好。","licence"),s(16,2,"港鐵・扶手帶圓點","港鐵回應傳媒時，指部分自動梯扶手帶的圓形標示主要方便乘客做甚麼？","辨識扶手帶移動方向與速度，方便緊握",["按圓點即可延長綠燈時間","用貼紙感應每名乘客身份","查看列車的車廂溫度"],"港鐵向傳媒解釋，圓形標示協助乘客看出扶手帶的移動方向和速度。不要把網民推測的載客感應、維修用途或固定手位說成官方統一功能。","望到個點郁，就容易知道扶手帶向邊移動。","handrail",["original","partial","text"],"採用傳媒引述港鐵的實際回應，移除未獲確認的維修監測功能。"),s(17,1,"離島・迷你消防車","離島使用體積小巧的迷你消防車，主要適應哪種環境？","狹窄或較難通行的路段",["只准大型貨車使用的高速公路","完全沒有任何道路的深海","只可垂直起降的天台"],"消防處介紹迷你消防車可快速在狹窄或越野地形執行滅火工作，並在離島支援其他小型車輛。不同款式尺寸不同，不把某一型號的長闊當成全部車輛的數值。","路窄、彎多，大車未必入到。","mini",["original","blurred","text"],"保留離島應用，移除未核實且可能混淆型號的2.24米統一尺寸。"),s(18,1,"港鐵・關門提示","月台幕門的閃燈配合關門聲，有助聽不到提示聲的人怎樣判斷？","透過視覺知道車門正在關閉，避免衝門",["看閃燈就可以不用留意月台空隙","閃燈亮起代表一定還有一分鐘上車","閃燈用來顯示車廂冷氣強弱"],"關門的聲音及視覺提示提供不同接收方式，對聽障人士尤其有用。見到關門提示不應衝門；不同門型的燈色和形式可有差異。","聽唔到聲，仍可以睇到門開始關。","mtr",["original","blurred","text"],"考視覺提示的實際作用，不虛構最初設計的唯一對象或統一燈色。"),s(19,2,"道路・橫條減速","快速公路支路出口或迴旋處前的黃色橫條道路標記，主要提醒司機甚麼？","在適當時候減低車速，準備應付前方路況",["每條橫線都代表一部測速相機","任何車輛都須在第一條線立即停車","黃色路面可讓輪胎抓地力必定加倍"],"運輸署說明，黃色橫條及開始減速標誌用來提示適時減速。部分設計的密度可提供速度感，但不能把所有橫條一律說成震動帶、固定限速點或保證產生某種錯覺。","離開快速路段，要提早準備唔同車速同彎位。","speed",["original","partial","text"],"以官方確認的減速用途出題，不把視覺錯覺或震動效果說成所有標記的統一原理。"),s(20,3,"駕駛・P牌限速","暫准駕駛者駛經限速100公里的路段，其暫准資格所設的最高車速是多少？","每小時70公里",["每小時80公里","每小時90公里","每小時100公里"],"暫准駕駛執照持有人，即使行駛於限速高於70公里的路段，亦不得超過每小時70公里。如現場限速更低，仍須遵守較低限制及其他適用規定。","P牌有自己嘅上限，唔係跟住較高嘅路牌數字。","probation",["original","blurred","text"],"保留70公里法定限制，移除未交代例外的最右線一概禁用敘述。"),s(21,1,"建築・透明玻璃門","透明玻璃門加上對比鮮明的橫條或圖案，主要防止甚麼？","行人沒察覺玻璃阻隔而撞上",["玻璃門被誤認為自動售賣機","玻璃內的Wi-Fi訊號外洩","門把金屬產生靜電"],"清楚可見的標記可讓不同視力及身高的人辨識玻璃門。具體尺寸及位置須按適用設計規定，不把原稿的兩組高度說成所有玻璃門的統一法例要求。","玻璃太透明，要有嘢提醒前面有道門。","accessible"),s(22,2,"泳池・更衣室入口","更衣室入口設轉折通道，對私隱有甚麼直接作用？","遮擋由外面直接望入更衣區的視線",["令所有聲音都完全傳不出去","代替更衣櫃的門鎖","保證室內永遠沒有濕氣"],"L形或其他轉折通道可阻隔直接視線，並讓入口保留通行空間。實際通風、消防及無障礙設計仍須整體考慮，不是所有泳池更衣室都沒有門。","唔係加一幅透明牆，而係令視線唔能夠直入。","accessible",["original","blurred","text"],"改考轉折與視線的關係，移除所有更衣室一律無門、完全解決通風的絕對說法。"),s(23,2,"屋邨・通風花格磚","舊式屋邨走廊的鏤空花格磚，與實心牆相比有甚麼特點？","容許空氣和部分自然光穿過",["只靠花格磚就可取代全部消防設施","保證颱風不會吹進走廊","可以防止所有雨水濺入"],"鏤空花格磚兼具幾何裝飾、採光及通風作用。消防安全須按整體建築設計評估，不能因有孔洞就斷言符合某項排煙豁免或完全不需機械設備。","啲孔唔止係花紋，仲可以畀風同光經過。","housing",["original","partial","text"],"移除未獲證實的消防法規豁免說法，保留可觀察的建築作用。"),s(24,2,"家居・水錶讀數","水務署指引中，水錶右方紅底白字部分代表甚麼？","以立方米計的小數位",["整數立方米以外的水壓讀數","住戶的門牌號碼","用水量的港幣金額"],"水錶以立方米作單位。水務署指引把白底黑字列為整數位、紅底白字列為小數位；一立方米等於1000公升。不同錶面格式應按其標示閱讀，不把每個紅字一律當成一公升。","紅色部分喺小數點右邊，記得先睇單位。","meter",["original","partial","text"],"依水務署讀數指引改為小數立方米，避免把所有紅色數位統稱為公升。"),s(25,2,"貨幣・觸感設計","2018系列銀行鈔票的手感線、點字及凹凸銀碼，主要方便哪類使用者？","視障人士辨別鈔票面額",["自動櫃員機維修員辨認螺絲尺寸","只供外國旅客查匯率","讓持有人即時知道戶口結餘"],"2018系列銀行鈔票包括20、50、100、500及1000元，設多種視障輔助特徵。10元塑鈔屬另一設計，不可把六種流通面額說成五種，也不能保證單一特徵能辨別所有情況。","唔一定要靠眼睇，觸感都可以提供線索。","tactile",["original","partial","text"],"修正五種與六種面額的矛盾，明確限定2018系列銀行鈔票。"),s(26,1,"生活・紙包飲品","拿紙包飲品時，避免用力擠壓盒身有甚麼好處？","減少飲品從已插入的飲管擠出",["可以讓飲品自動加熱","令所有紙盒都可重複裝熱湯","可把飲品保存期限延長一年"],"擠壓有飲管開口的軟包裝，可能把液體擠出。輕握、不擠壓盒身，或按合適包裝結構握持，可減少噴濺；摺角不是藏防腐劑或保證具承重能力的提手。","飲管已插咗，擠壓個盒會將液體推去邊？","food",["original","blurred","text"],"保留紙包飲品使用技巧，不把所有摺角都當成原廠設計的安全提手。"),s(27,1,"茶餐廳・凍飲加錢","餐牌寫「套餐轉凍飲另加收費」，點餐前最可靠應怎樣做？","看清該店餐牌列出的加價及適用飲品",["假設全港統一加兩元","假設加冰必定免費","認為每家店的凍飲配方必定相同"],"凍飲加價、杯量及沖調方法由食肆訂定，應看清餐牌或向店員查詢。不能把全港統一加價、固定多用三至五成原料，或收取冷氣費當作共同規定。","同一條街兩間茶記，價錢同配方都可以唔同。","consumer",["original","blurred","text"],"移除未證實的統一價格及原料增加百分比，以實際消費資訊出題。"),s(28,2,"茶餐廳・卡位文化","茶餐廳所說的「卡位」，通常指哪種座位安排？","配合餐桌的固定靠背長椅式座位",["掛在天花的單人吊椅","只供站立的車票售賣窗口","必須持會員卡才可使用的包廂"],"卡位是港式餐飲的常見空間及座位形式，常見固定靠背長椅與餐桌組合。各店尺寸、擺法及翻枱安排不同，不把故意讓人不舒服或加快離座說成已證實的唯一發明原因。","諗吓兩邊有靠背、面對面坐低食餐嗰種位。","culture",["original","blurred","text"],"保留卡位辨識，移除卡位英文詞源及刻意令客人擠迫以加快翻枱的推論。"),s(29,2,"建築・樓層編號","部分舊有大廈省略4或13樓的編號，常與哪類文化觀念有關？","數字諧音及被視為不吉利的數字忌諱",["這些樓層在物理上全部不存在","所有4樓都必須是消防水缸","13樓只能供升降機馬達使用"],"「4」的粵語諧音及西方對13的忌諱，常見於跳層編號討論。樓層編號不等於實際樓層數；規範會更新，不能概括為屋宇署容許任意跳過任何樓層。","號碼唔吉利係文化觀念，唔代表嗰層樓消失咗。","floors",["original","text"],"限定舊有編號現象，不把原稿所述跳層方式當作現行全面認可的規定。"),s(30,2,"環保・膠袋收費","依環保署的食品衞生豁免原則，以下哪項最可能可獲提供首個免費膠袋？","盛載沒有包裝的散裝鮮魚",["盛載全新書本及文具","盛載已密封的瓶裝汽水和餅乾","因為自備環保袋裝滿而再索袋"],"符合條件的無包裝或並非完全載於任何包裝的食品，可按食品衞生理由獲膠袋豁免；一般以每單交易一個免費袋為原則。已完全包裝的冷凍食品，不會只因有倒汗水便自動豁免。","重點係食品及包裝狀態，唔係凍就一定免費。","bags",["text"],"依2022年收緊的豁免原則改寫，移除非密封冷凍包裝一概豁免的錯誤。"),s(31,2,"街舖・門口土地","傳統店舖近地面的「門口土地」小神龕，主要屬於哪種民俗？","祈求守護一方水土及店舖平安的土地信仰",["所有商店必須遵守的消防規例","供顧客繳付泊車費的裝置","用來測量地震的科學儀器"],"土地信仰寄託地方守護、平安及生意順遂等願望，擺放習俗因地區與店家而異。民俗寓意不等於科學機制，也不能說所有神像依法或必須擺在某個高度。","個名有「土地」，講緊地方守護嘅民間信仰。","ich",["original","blurred","text"],"保留民俗文化，不把接地氣或所有神像擺法說成物理定律或統一規矩。"),s(32,2,"中環・半山扶梯","中環至半山自動扶梯一般早段向下、其後向上，主要配合甚麼？","不同時段往中環及半山的人流需要",["每次反向都會免費產生電力","避免所有扶手帶每星期斷裂","每天必須為地球自轉作補償"],"方向安排配合早上落中環及其後上半山的人流。實際開放時間、維修及惡劣天氣安排應看現場與官方告示，不把某一分鐘的轉向或世界紀錄稱號當成本題前提。","早上返工落山，其他時段上山嘅需要唔同。","road",["original","blurred","text"],"移除世界最長的時效性稱號及必定10時自動反向，保留可確認的人流考量。"),s(33,2,"小巴・營運制度","綠色專線小巴與紅色公共小巴相比，哪項通常屬專線小巴的營運規定？","按批准路線、班次及收費等條件提供服務",["一律只收現金，禁止電子付款","可以不受任何道路限制","所有車輛均必須是純電動"],"專線小巴須按批准的營運條件提供服務；紅色公共小巴的路線及收費安排較有彈性，但仍受法例、行車範圍及其他規定限制。兩者都不是全無監管或只可在某一大區行駛。","專線個「專」字，同批准咗嘅服務安排有關。","road",["original","blurred","text"]),s(34,2,"電視・魚骨天線","香港停止模擬電視廣播後，以下哪個說法正確？","接收設備須支援數碼電視；合適天線仍可用來接收訊號",["所有魚骨天線都因數碼化而失去接收能力","免費電視只可透過收費寬頻收看","每個住戶都依法必須拆除天線"],"2020年12月1日起停止模擬電視廣播，不代表金屬天線本身一律失效。接收數碼地面電視可使用合適天線與數碼電視機或機頂盒，公共天線系統亦可能需要調校。","訊號格式轉咗，唔代表所有收訊天線都要報廢。","tv",["original","blurred","text"],"修正原稿核心錯誤：停播的是模擬訊號，不是所有魚骨天線的接收功能。"),s(35,1,"隧道・車道燈號","行車線上方亮起紅色交叉燈號，通常表示甚麼？","不得使用該行車線",["可以加速超車","該行車線的隧道費較便宜","只需開車頭高燈便可駛入"],"車道管制燈號顯示車道是否開放；綠箭咀通常表示可用，紅交叉表示不可使用。仍須遵守其他交通指示，不可把易通行的繳費方式與車道管制混為一談。","紅叉唔係車費提示，係條線唔畀行。","road",["original","blurred","text"]),s(36,2,"巴士・樓梯凸面鏡","巴士樓梯轉角裝凸面鏡，凸面形狀有甚麼實用特點？","提供較廣視野，減少轉角看不到的位置",["把上層乘客重量減半","讓鏡中物件全部變成真實大小","防止樓梯在行駛時震動"],"凸面鏡可用較小鏡面提供較廣視野，協助觀察轉角或盲點，但鏡像大小和距離感會改變，不能代替小心行走及扶穩。實際安裝及觀察用途依車型而異。","凸出嚟嘅鏡面，通常可以睇闊啲。","road",["original","blurred","text"]),s(37,2,"的士・交更","的士展示「交更」資訊時，這個詞在行業日常最接近甚麼意思？","司機準備交接車輛或更次",["車輛已永久取消的士牌照","所有路段即時變成免費接載","司機可不受任何載客法例約束"],"交更是司機換更及交接車輛的安排，時間及地點因車行與司機而異。交更標示不等於法律豁免，不能說全港一律在同一時刻交更或可任意拒載。","個「更」係工作更次，唔係改路名。","taxi",["original","blurred","text"],"移除全港統一下午交更及可隨意只載順路客的概括說法。"),s(38,1,"港鐵・月台空隙","部分月台邊緣的橡膠空隙填補條，主要用來做甚麼？","減少列車與月台邊緣之間的部分空隙",["清潔所有列車的車輪","保證任何乘客都不會踏空","取代所有月台幕門"],"空隙填補設施可在適用位置縮小空隙，但不能完全消除風險。上下車仍須留意月台空隙、照顧同行小朋友，輪椅使用者可按需要尋求職員協助。","用柔性物料填一部分空位，唔代表完全冇罅。","mtr",["original","partial","text"],"不把原稿列出的站名、顏色或防墜效果概括為所有車站的保證。"),s(39,2,"道路・指路牌顏色","香港快速公路上的方向標誌，通常使用哪種底色？","綠色",["粉紅色","紫色","橙色"],"運輸署說明，一般重要交通路線的方向標誌多為藍底白邊，快速公路則使用綠底。不是所有主要幹道都等同快速公路，其他旅遊或臨時標誌亦有不同配色。","藍色同綠色有分工，題目指定咗快速公路。","signs",["original","blurred","text"],"收窄為快速公路，修正把所有主要幹道都列為綠底的說法。"),s(40,2,"道路・限高預警","低矮隧道前懸掛的限高提示條，主要提供哪種預警？","讓可能超高的車輛在到達低矮結構前收到提示",["替所有車輛自動調低車身高度","撞過提示條後便可合法超高通行","用來清洗貨車頂部"],"限高設施及標誌提醒司機核對車輛連貨物的總高度；部分懸掛式裝置可提供接觸或聲響提示。不能把警告裝置當成撞上也無危險的保護保證。","先有提醒，唔好等到撞到真正嘅隧道頂先知。","road",["original","blurred","text"]),s(41,1,"飲茶・溫杯","飲茶前用熱水溫杯，對沖泡或品茶有哪項直接作用？","提高杯子的初始溫度，減少茶湯很快被冷杯降溫",["保證數秒沖水便消滅所有病菌","讓杯子永久不會破裂","把茶葉變成零咖啡因"],"溫杯是常見品茶步驟，與茶具溫度及飲用體驗有關。餐具衞生仍依賴妥善清洗消毒，不能把餐桌上短暫沖洗當成可靠滅菌程序。","凍杯會吸走熱茶嘅熱，先暖杯可以少啲降溫。","culture",["original","blurred","text"],"保留溫杯用途，不把餐前沖洗等同有效消毒，也不稱為香港獨有。"),s(42,2,"工地・白飯魚","工地足部防護方面，以下哪個說法較恰當？","須按工作風險選合適防滑與防護鞋，白布鞋不等於安全鞋",["任何白飯魚都保證絕緣及防刺穿","只要鞋底綠色就符合所有安全要求","勞工處規定所有搭棚者只能穿白布鞋"],"「白飯魚」是香港白布鞋的常見俗稱，但文化記憶不能取代職安要求。不同工序須評估滑倒、墮物、尖物或其他風險，選用適當裝備並遵從安全工作程序。","熟悉嘅鞋款名，唔係安全性能認證。","labour",["original","blurred","text"],"移除未證實的專業抓地及絕緣推論，不把一般布鞋推薦為高空作業標準裝備。"),s(43,1,"茶餐廳・凍檸茶","飲凍檸茶時，長柄茶匙最方便做哪件事？","攪拌及輕壓檸檬片，調整茶與檸檬的味道",["把冰塊即時加熱至沸騰","量度飲品含有多少咖啡因","保證所有茶底都變得完全不苦"],"茶匙可攪拌飲品及壓出部分檸檬汁。過度搗壓果皮白色部分可能帶來苦味，口味及茶底因店而異；沒有每杯必須用同一力度或一定附匙的統一規則。","杯又高又有檸檬，長柄方便伸落去攪同壓。","culture",["original","partial","text"]),s(44,1,"環保・三色回收桶","香港傳統三色分類回收桶中，啡色一般對應哪一類？","廢塑膠",["廚餘","廢玻璃","舊電池"],"傳統配色為藍色廢紙、黃色金屬、啡色塑膠。實際可收物品要看回收點標示，投放前盡量清空、清洗及分類，不能把所有髒污或複合物料都放入啡桶。","經典口訣有「啡膠樽」，不過實際分類要睇標示。","recycling",["original","blurred","partial","text"]),s(45,1,"公園・石春路","公園內用圓滑小卵石鋪成的凹凸步徑，香港人常叫它甚麼？","石春路",["消防車通道","快速單車徑","電子引路帶"],"石春路是以小卵石形成凹凸腳底觸感的步徑。它可作休憩設施，但不能保證治病或令所有人血液循環改善；使用時宜量力而為，有足部疾病者應先諮詢醫護。","個名同細細粒圓石有關，唔係春天專用。","park",["original","blurred","partial","text"],"改考設施辨識，移除足底穴位治療及延伸健康效果的確定承諾。"),s(46,3,"街道・水掣蓋字母","供水設施小蓋上的SV及FH，通常分別指甚麼？","Sluice Valve（水閘／水掣）及Fire Hydrant（消防栓）",["Sluice Valve（水閘／水掣）及Fire Hose（消防喉）","Safety Valve（安全閥）及Fire Hydrant（消防栓）","Stop Valve（截流閥）及Freshwater Head（食水接頭）"],"SV及FH是供水及消防供水設施常見的英文縮寫。辨識文字比只看蓋面格紋可靠；設施不可自行開啟或操作，實際用途仍以管理部門紀錄為準。","V係Valve，H係Hydrant，兩者都同水有關。","water",["original","partial","text"]),s(47,2,"過路處・觸覺箭咀","部分電子行人過路發聲裝置的觸覺箭咀，主要向視障人士提供甚麼資訊？","行人過路處的橫過方向",["附近餐廳的折扣方向","最近港鐵站的車費","所有車輛的行車速度"],"觸覺箭咀可提示過路方向，震動或聲音則提示行人燈號狀態。新舊款式及箭咀位置可不同，不能只憑摸到箭咀便認為現在可以過馬路。","方向同可唔可以過路，係兩種唔同資訊。","crossing",["original","partial","text"],"不限定箭咀必在頂部；保留方向與燈號的區別，配合更新中的新舊型號。"),s(48,2,"道路・障礙物標記","路邊障礙物前的反光危險標記，主要提醒駕駛者甚麼？","前方或路旁有障礙，須依現場指示安全通過",["該物件是可供車輛碰撞的緩衝遊戲","任何斜紋都等於准許跨越所有實線","標記後的道路一律沒有車速限制"],"危險標記增加路邊物件或障礙的可見度，須連同通行方向及其他標誌判斷。不能單憑一小塊斜紋推斷完整道路配置，亦不能把警告標記當成解除其他限制。","反光牌想你提早見到障礙，唔係畀你無視路牌。","studs",["original","partial","text"],"保留障礙物辨識，不用欠缺完整場景的斜紋方向代替強制通行指示。"),s(49,2,"建築・旋轉門旁通道","旋轉門附近另設合適的普通門或通道，主要照顧哪些需要？","無障礙進出及符合適用的逃生通道設計",["讓所有人都必須爬過旋轉門","以普通門代替全部消防系統","只為讓商店多放廣告牌"],"旋轉門對輪椅及部分使用者並不方便，入口與逃生設計須提供符合要求的通道。實際門型、數量及位置應按建築和消防規定，不能概括每座樓左右都必定各一扇。","輪椅進出，同緊急時人流疏散，都唔可以只靠旋轉門。","accessible",["original","blurred","text"]),s(50,2,"港鐵・重複站名","月台柱身在不同高度重複顯示站名，有甚麼閱讀上的好處？","讓不同位置及視線高度的乘客較易看到站名",["讓站名每隔一小時自動改變","替列車車窗提供防曬功能","讓柱子能承受更多樓層重量"],"重複的站名增加乘客從不同視線、車窗或位置看見資訊的機會。這是辨識上的效果，不把未核實的設計師原話或唯一歷史動機當成史實。","車窗停嘅位置唔次次相同，多幾個站名就易睇。","mtr",["original","blurred","text"]),s(51,2,"巴士・輪椅位置","按指定位置背向行車方向停泊輪椅並靠緊背板，有甚麼安全作用？","煞車時由背板提供承托，配合制動及固定裝置減少移動",["有背板就完全不用上輪椅制動器","讓輪椅可在行駛途中自由轉圈","以後不必理會車長或車內指示"],"巴士指定輪椅位置的背板及固定設施應按車內指示使用，輪椅須上好制動並使用提供的適當固定裝置。不能把某種車型的配置概括為所有交通工具通用，也不能保證防止任何傷害。","急煞時人同輪椅會因慣性移動，需要按設計承托同固定。","bus",["original","blurred","text"]),s(52,2,"小巴・手寫水牌","一塊小巴水牌大字寫「旺角」，小字寫「經紅隧」。小字最直接補充甚麼？","行車途經的路線資訊",["必須支付的深夜附加費數字","司機的姓名和住址","小巴車輛的輪胎尺寸"],"小巴水牌可用大小字體補充目的地及途經地點；本題以完整文字作判斷。不同寫牌師傅及車線的配色不必相同，不把紅字、藍字各自用途當成法定標準。","「經」即係途經，唔係目的地改咗名。","culture",["original","text"],"以實際示例牌文字出題，不把水牌紅藍配色當成一律相同的規則。"),s(53,1,"巴士・通宵路線","如N121一類巴士路線編號中的N，通常提示哪種服務？","通宵服務",["所有班次都只在中午行走","只准新牌司機駕駛","乘客一律免費乘搭"],"N常用作Night通宵服務的提示，可放在編號前方。不同營辦商的命名及個別路線有差異，仍應查正式路線及時間表，不把所有英文字母都稱為編號後綴。","N通常同Night有關，題目講緊深夜搭車。","bus",["original","blurred","text"],"修正把N121的N寫成後綴；不概括其他字母在所有營辦商的含義。"),s(54,1,"車牌・前白後黃","香港一般車輛常見的反光車牌，前後配色是哪一組？","車頭白底黑字，車尾黃底黑字",["車頭黃底黑字，車尾白底黑字","前後都必須紅底白字","前後都必須藍底黃字"],"一般常見的反光車牌為前白後黃、黑色字。車牌另有字體、尺寸及其他規定；不把未經確認的眩光原理解說當成規例訂立的唯一原因。","平時望車頭同車尾，底色其實唔同。","road",["original","blurred","text"],"改考可確認的前後配色，移除未獲佐證的黃色防眩光政策動機。"),s(55,2,"紅隧・不停車繳費","紅隧在2023年實施易通行後，正常通行的繳費方式有甚麼轉變？","以系統處理隧道費，不再逐車停在收費亭付款",["所有車輛由此永久免收隧道費","必須在隧道中段下車投幣","只接受以現金向車長付款"],"易通行是不停車繳費安排，並不表示免費。車主仍須按規定處理車輛及繳費資料；本題不推斷每個舊收費亭的拆卸、保育或移置去向。","唔使停亭付款，同唔使畀隧道費係兩回事。","toll",["original","blurred","text"],"保留紅隧收費模式變化，移除未核實的收費亭保留數目及去向。"),s(56,1,"飲茶・壺蓋暗號","飲茶時把茶壺蓋掀開或斜放，常見的無聲意思是甚麼？","請侍應添熱水",["請立即收走全桌食物","代表同桌客人已全部離開","要求把茶壺換成冷氣遙控器"],"掀蓋示意加水是常見飲茶習慣，實際仍可禮貌向侍應提出需要。關於畫眉鳥等起源故事屬民間流傳，不應當成已證實的清代史實或唯一來源。","冇大聲叫人，只係畀個添水提示。","culture",["original","blurred","text"],"保留暗號意思，把畫眉鳥故事限定為傳說而不以其作唯一正解。"),s(57,2,"燒味・燒肉插針","製作脆皮燒肉時在豬皮刺小孔，通常是為了甚麼？","協助水分及油脂在烤焗時散出，令表皮較易起泡變脆",["讓豬皮永遠保持生冷不受熱","保證任何爐溫都不會燒焦","完全不用乾燥、醃製或控制火候"],"插針是一些脆皮燒肉做法的工序，配合表皮乾燥、調味及控制火候，幫助形成脆皮。工序和效果因做法而異，不能保證節省一半時間或完全防止油濺。","皮要乾身、蒸氣同油脂有路走，再配合火候。","food",["original","partial","text"],"保留烹調技巧，去除決定性保證、防爆油承諾及未核實的節能百分比。"),s(58,3,"家居・冷氣機滴水","按食環署2026年資料，不遵辦冷氣滴水「妨擾事故通知」而被定罪，最高罰款是多少？","25,000元，另可按妨擾持續日數罰款",["10,000元，另可按妨擾持續日數罰款","5,000元，另可按妨擾持續日數罰款","50,000元，另可按妨擾持續日數罰款"],"食環署2026年5月資料列明，不遵辦妨擾事故通知可被檢控，定罪最高罰款25,000元，並可就妨擾持續每一日罰款450元。須區分通知、檢控及定罪，不是見到一滴水便自動罰最高額。","原稿嗰個一萬元數字已經過時，要睇更新後資料。","ac",["text"],"依2026年官方資料修正10,000／200元為25,000／450元，並交代不遵辦通知的法律情境。"),s(59,1,"中藥舖・百子櫃","傳統中藥舖一格格寫有藥名的「百子櫃」，主要用來做甚麼？","分類存放藥材，方便按處方取配",["讓任何人無須專業判斷自行試藥","保證所有藥材永不受潮","用抽屜數目計算顧客的年齡"],"百子櫃透過多個抽屜分類存放藥材，是傳統藥舖的典型器物。藥材使用須有適當專業判斷；沒有可靠依據證明全行都有「不鎖抽屜讓人自行救急」的統一祖訓。","每格有藥名，重點係分類同配藥。","ich",["original","blurred","text"],"保留器物與行業文化，移除無鎖祖訓及可自行取藥救急的未證實敘述。"),s(60,2,"報紙檔・牌照規定","持牌報紙檔的牌照，能否像普通二手貨物般自由轉讓？","不能；須按牌照類別、簽發時間及食環署適用政策處理",["可以自由轉給任何朋友，完全不用申請","只要更換招牌便自動獲新牌","全港所有牌照的繼承條件完全相同"],"小販牌照的繼承及轉讓安排視類別、簽發日期與政策而定。食環署列明新舊政策有差異，部分轉類安排另有條件；不能一概說所有報紙檔只有配偶可接、或每次退休必定立即註銷。","牌照唔只係檔口件傢俬，轉手要跟規定。","licence",["text"],"刪除時效性檔口數量及一概繼承限制，依現行FAQ區分牌照類別與新舊政策。")]);var Ct=Object.freeze([{id:"e01",tier:1,category:"景點",question:"圖中的海港景觀，最接近香港哪一個著名海港？",explanation:"維多利亞港把香港島與九龍半島分隔，也是香港最具代表性的海港景觀。",hint:"我記得搭船過海，一邊係中環，另一邊可以去尖沙咀。",art:"harbour",source:{label:"香港旅遊發展局",url:"https://www.discoverhongkong.com/tc/"},options:["吐露港","后海灣","維多利亞港","赤門海峽"],answer:2,focus:{x:50,y:58},textQuestion:"香港島與九龍半島之間的海港，名稱是甚麼？"},{id:"e02",tier:1,category:"交通",question:"圖中這種在街道上行走的雙層有軌交通工具，香港人常叫它甚麼？",explanation:"香港電車的日常路線位於香港島，車鈴聲令它有「叮叮」的親切稱呼。",hint:"唔係港鐵，係沿住馬路行、上落要行樓梯嗰種。",art:"tram",source:{label:"香港旅遊發展局",url:"https://www.discoverhongkong.com/tc/"},options:["山頂纜車","輕鐵","小巴（司機：有落呀！）","叮叮"],answer:3,focus:{x:55,y:60},textQuestion:"香港有軌雙層電車的常見別稱是甚麼？"},{id:"e03",tier:1,category:"交通",question:"圖中綠白色、往返維港兩岸的船，最接近哪種香港交通服務？",explanation:"天星小輪是往來維港兩岸的渡輪，亦是深受遊客歡迎的香港交通體驗。",hint:"我上次坐佢過海，係有海風、冇路軌嘅。",art:"ferry",source:{label:"香港旅遊發展局",url:"https://www.discoverhongkong.com/tc/"},options:["天星小輪","昂坪纜車","山頂纜車","香港電車"],answer:0,focus:{x:53,y:65},textQuestion:"往返中環與尖沙咀、以綠白色渡輪為人熟悉的交通服務是甚麼？"},{id:"e04",tier:1,category:"景點",question:"圖中山脊的伏臥輪廓，最令人聯想到哪座香港山峰？",explanation:"獅子山的岩石外形令人聯想到伏臥的獅子，山峰亦成為香港的文化象徵。",hint:"試吓望吓山脊嘅輪廓，似隻伏喺度嘅大型貓科動物。",art:"lion",source:{label:"香港旅遊發展局",url:"https://www.discoverhongkong.com/tc/"},options:["大帽山","獅子山","大東山","太平山（搭纜車都算行山？）"],answer:1,focus:{x:55,y:38},textQuestion:"象徵香港精神、外形似伏臥大型貓科動物的山峰是哪一座？"},{id:"e05",tier:1,category:"傳統節日",question:"香港的龍舟競渡，最常與哪個傳統節日連在一起？",explanation:"端午節的重要民俗包括龍舟競渡及吃粽子，香港多處水域都會舉行龍舟活動。",hint:"呢個節日嘅應節食物通常用葉包住，入面有糯米。",art:"dragon",source:{label:"香港旅遊發展局",url:"https://www.discoverhongkong.com/tc/"},options:["重陽節","清明節","端午節","冬至"],answer:2,focus:{x:55,y:55}},{id:"e06",tier:1,category:"傳統節日",question:"傳統的中秋節是農曆哪一天？",explanation:"中秋節在農曆八月十五，賞月、吃月餅及玩燈籠都是常見節慶活動。",hint:"個名有個「秋」字，而賞月通常揀月圓嗰一晚。",art:"lantern",source:{label:"香港旅遊發展局",url:"https://www.discoverhongkong.com/tc/"},options:["五月初五","七月初七","九月初九（月餅遲到咗？）","八月十五"],answer:3,focus:{x:55,y:45}},{id:"e07",tier:1,category:"傳統節日",question:"長洲太平清醮最廣為人知的競賽活動是哪一項？",explanation:"搶包山是長洲太平清醮的著名活動，選手攀上包山架搶取代表祝福的包。",hint:"我記得選手要向上爬，而且成座架都係圓圓嘅包。",art:"buns",source:{label:"香港旅遊發展局",url:"https://www.discoverhongkong.com/tc/"},options:["搶包山","搶花炮","拋橄欖球","競步過火"],answer:0,focus:{x:50,y:40}},{id:"e08",tier:1,category:"傳統節日",question:"大坑舞火龍通常在哪個節日期間舉行？",explanation:"大坑舞火龍是香港著名的中秋民俗活動，火龍身上插滿燃着的線香。",hint:"唔係端午嗰種落水龍舟；呢條龍喺秋天嘅街上行。",art:"dragon",source:{label:"香港旅遊發展局",url:"https://www.discoverhongkong.com/tc/"},options:["聖誕節（聖誕老人接棒？）","中秋節","復活節","元旦"],answer:1,focus:{x:55,y:55}},{id:"e09",tier:1,category:"飲食",question:"圖中表面有裂紋酥皮的麵包，最常見的港式名稱是甚麼？",explanation:"傳統菠蘿包的名稱來自表面酥皮的裂紋，並不代表麵包必須含有菠蘿果肉。",hint:"留意係頂部嘅外觀，唔一定係入面嘅餡。",art:"bun",source:{label:"香港旅遊發展局",url:"https://www.discoverhongkong.com/tc/"},options:["雞尾包","腸仔包","菠蘿包","豬仔包"],answer:2,focus:{x:50,y:58},textQuestion:"港式麵包中，表面有裂紋酥皮、名字帶水果但通常不以該水果作餡的是甚麼？"},{id:"e10",tier:1,category:"飲食",question:"圖中的茶色飲品，若以布袋反覆濾茶，最常被稱為甚麼？",explanation:"港式奶茶用布袋反覆濾茶，布袋形態及染上的茶色令人聯想到絲襪。",hint:"沖茶師傅會用佢隔走茶葉，唔係叫你將衣物放落杯茶。",art:"milk",source:{label:"香港旅遊發展局",url:"https://www.discoverhongkong.com/tc/"},options:["龍井茶","檸檬可樂","凍朱古力（朱古力放假中）","絲襪奶茶"],answer:3,focus:{x:50,y:58},textQuestion:"茶餐廳中，以布袋反覆濾茶再加奶的飲品，通常稱為甚麼？"},{id:"e11",tier:1,category:"飲食",question:"茶餐廳餐牌上的「西多士」，通常是指哪類食物？",explanation:"港式西多士以蘸蛋液的麵包煎或炸製，常配牛油、糖漿，也有花生醬等夾餡版本。",hint:"個名最後兩個字同英文 toast 有關。",art:"milk",source:{label:"香港旅遊發展局",url:"https://www.discoverhongkong.com/tc/"},options:["蘸蛋液後煎或炸的多士","一碗西式麵條","冷凍水果沙律","焗芝士通心粉"],answer:0,focus:{x:50,y:58}},{id:"e12",tier:1,category:"飲食",question:"粵式點心「蝦餃」最具代表性的主要餡料是甚麼？",explanation:"蝦餃以蝦為主要餡料，薄而略帶透明的餃皮也是它的特色。",hint:"呢款點心個名已經俾咗一個好直接嘅海鮮線索。",art:"bun",source:{label:"香港旅遊發展局",url:"https://www.discoverhongkong.com/tc/"},options:["牛肉","蝦","栗子（蝦先生請咗假？）","紅豆"],answer:1,focus:{x:50,y:58}},{id:"e13",tier:1,category:"景點",question:"昂坪的天壇大佛位於香港哪一個島嶼？",explanation:"天壇大佛位於大嶼山昂坪，與寶蓮禪寺相鄰。",hint:"去嗰邊仲可以諗起昂坪纜車，同一個大島上亦有機場。",art:"temple",source:{label:"香港旅遊發展局",url:"https://www.discoverhongkong.com/tc/"},options:["長洲","坪洲","大嶼山","蒲台島"],answer:2,focus:{x:50,y:50}},{id:"e14",tier:1,category:"景點",question:"香港人常說的「山頂」旅遊區，主要位於哪個地區？",explanation:"太平山頂位於香港島，遊客可從高處欣賞維多利亞港與城市景色。",hint:"搭山頂纜車之前，出發點喺港島嘅中環一帶。",art:"peak",source:{label:"香港旅遊發展局",url:"https://www.discoverhongkong.com/tc/"},options:["九龍城","元朗平原","長洲","香港島"],answer:3,focus:{x:55,y:40}},{id:"e15",tier:1,category:"景點",question:"這座著名的舊九廣鐵路鐘樓，位於哪個旅遊區？",explanation:"前九廣鐵路鐘樓位於尖沙咀海旁，鄰近香港文化中心及天星碼頭。",hint:"附近有文化中心，又可以行去搭船過海。",art:"clock",source:{label:"香港旅遊發展局",url:"https://www.discoverhongkong.com/tc/"},options:["尖沙咀","天水圍","將軍澳","赤柱"],answer:0,focus:{x:50,y:35},textQuestion:"香港著名的舊九廣鐵路鐘樓，位於哪個旅遊區？"},{id:"e16",tier:1,category:"交通",question:"香港「港鐵」最主要提供哪一類服務？",explanation:"港鐵是香港主要的鐵路客運系統，服務市區及多個新市鎮。",hint:"佢嘅英文簡稱有個 R，月台通常有路線圖。",art:"tram",source:{label:"港鐵公司",url:"https://www.mtr.com.hk/ch/customer/main/index.html"},options:["遠洋郵輪","鐵路客運","觀光直升機","跨海貨船"],answer:1,focus:{x:55,y:60}},{id:"e17",tier:1,category:"社會",question:"「八達通」最廣為人知的用途是哪一項？",explanation:"八達通是香港常用的儲值支付工具，廣泛用於交通及零售付款。",hint:"我搭車同買嘢都試過「嘟」一下。",art:"star",source:{label:"香港旅遊發展局",url:"https://www.discoverhongkong.com/tc/"},options:["測量風向","收看免費電視","交通及零售電子付款","登記樹木品種"],answer:2,focus:{x:50,y:50}},{id:"e18",tier:1,category:"常識",question:"香港的法定貨幣通常以哪個縮寫表示？",explanation:"港元的國際貨幣代碼是 HKD，遊戲中的金額則只是虛擬獎金。",hint:"三個英文字母，前兩個來自 Hong Kong。",art:"star",source:{label:"香港金融管理局",url:"https://www.hkma.gov.hk/chi/"},options:["JPY","EUR","KRW","HKD"],answer:3,focus:{x:50,y:50}},{id:"e19",tier:1,category:"常識",question:"香港天文台主要向公眾提供哪類資訊？",explanation:"香港天文台負責天氣預報、警告及其他氣象服務。",hint:"帶唔帶遮、颱風消息，我通常都會睇佢。",art:"harbour",source:{label:"香港天文台",url:"https://www.hko.gov.hk/tc/index.html"},options:["天氣及氣象資訊","電影場次","巴士失物清單","商場折扣"],answer:0,focus:{x:50,y:58}},{id:"e20",tier:1,category:"體育",question:"李麗珊為香港奪得奧運金牌的項目是甚麼？",explanation:"李麗珊在1996年亞特蘭大奧運的女子滑浪風帆項目奪金。",hint:"有海、有風，運動員企喺板上控制帆。",art:"sport",source:{label:"中國香港體育協會暨奧林匹克委員會",url:"https://www.hkolympic.org/"},options:["跳水","滑浪風帆","羽毛球","射箭"],answer:1,focus:{x:53,y:52}},{id:"e21",tier:1,category:"體育",question:"張家朗在2024年巴黎奧運奪金的劍擊項目是哪一種？",explanation:"張家朗在2024年巴黎奧運成功衛冕男子個人花劍金牌。",hint:"劍擊有三種劍，佢嗰種同江旻憓嗰種並唔一樣。",art:"sport",source:{label:"中國香港體育協會暨奧林匹克委員會",url:"https://www.hkolympic.org/"},options:["重劍","佩劍","花劍","雙劍"],answer:2,focus:{x:53,y:52}},{id:"e22",tier:1,category:"體育",question:"江旻憓在2024年巴黎奧運奪金的項目是甚麼？",explanation:"江旻憓在2024年巴黎奧運贏得女子個人重劍金牌。",hint:"佢用嘅劍種，名字有個形容重量嘅字。",art:"sport",source:{label:"中國香港體育協會暨奧林匹克委員會",url:"https://www.hkolympic.org/"},options:["女子個人花劍","女子個人佩劍","女子跳高","女子個人重劍"],answer:3,focus:{x:53,y:52}},{id:"e23",tier:1,category:"體育",question:"何詩蓓主要參與哪一類競技運動？",explanation:"何詩蓓是香港游泳代表，曾在奧運自由泳項目獲得獎牌。",hint:"佢比賽時要戴泳帽同泳鏡。",art:"sport",source:{label:"中國香港體育協會暨奧林匹克委員會",url:"https://www.hkolympic.org/"},options:["游泳","場地單車","帆船","乒乓球"],answer:0,focus:{x:53,y:52}},{id:"e24",tier:1,category:"自然",question:"米埔最著名的自然保育特色是哪一項？",explanation:"米埔及內后海灣是重要濕地，為多種水鳥和候鳥提供棲息環境。",hint:"我記得去嗰度通常帶望遠鏡，觀察喺水邊活動嘅動物。",art:"river",source:{label:"漁農自然護理署",url:"https://www.afcd.gov.hk/tc_chi/"},options:["高山冰川","濕地及候鳥","沙漠駱駝","活火山"],answer:1,focus:{x:50,y:50}},{id:"e25",tier:1,category:"旅遊",question:"香港哪一個地區常以海岸風景、離島及郊遊活動聞名？",explanation:"西貢擁有豐富海岸及郊野資源，是香港常見的郊遊目的地。",hint:"佢有「香港後花園」嘅常見稱呼，唔係購物街區。",art:"geopark",source:{label:"香港旅遊發展局",url:"https://www.discoverhongkong.com/tc/"},options:["旺角","深水埗","西貢","銅鑼灣"],answer:2,focus:{x:55,y:60}},{id:"e26",tier:1,category:"象形文字",question:"看這張圓形中間加一點的象形示意，它最接近哪個漢字的早期意象？",explanation:"「日」的早期字形常用太陽的輪廓及內部記號表示太陽；這裡採用教學示意圖。",hint:"諗吓白天提供光同熱嘅天體。",art:"sun",source:{label:"香港教育局・中國語文教育",url:"https://www.edb.gov.hk/tc/curriculum-development/kla/chi-edu/"},options:["月","山","木","日"],answer:3,focus:{x:50,y:50},textQuestion:"早期漢字以圓形中間加一點描繪天體，最接近哪個字？"},{id:"e27",tier:1,category:"象形文字",question:"這張彎曲天體的象形示意，最接近哪個漢字？",explanation:"「月」的早期意象與月亮外形有關；圖像只用來說明象形構字概念。",hint:"佢嘅形狀會隨日子改變，有時圓，有時彎。",art:"moon",source:{label:"香港教育局・中國語文教育",url:"https://www.edb.gov.hk/tc/curriculum-development/kla/chi-edu/"},options:["月","日","川","木"],answer:0,focus:{x:50,y:50},textQuestion:"早期漢字以彎曲的天體形狀描繪天空景物，最接近哪個字？"},{id:"e28",tier:1,category:"象形文字",question:"三個高低不同的山峰示意，最接近哪個漢字？",explanation:"「山」以山峰輪廓表達山岳的概念，是常見的象形字例子。",hint:"香港好多郊遊路線都會經過呢類地形。",art:"mountain",source:{label:"香港教育局・中國語文教育",url:"https://www.edb.gov.hk/tc/curriculum-development/kla/chi-edu/"},options:["水","山","人","口"],answer:1,focus:{x:50,y:50}},{id:"e29",tier:1,category:"象形文字",question:"圖中的樹幹、樹枝與根部示意，最接近哪個漢字？",explanation:"「木」的字形取意於樹木，樹幹、枝條及根部構成基本意象。",hint:"佢可以長出枝葉，唔係天上嘅景物。",art:"tree",source:{label:"香港教育局・中國語文教育",url:"https://www.edb.gov.hk/tc/curriculum-development/kla/chi-edu/"},options:["火","月","木","日"],answer:2,focus:{x:50,y:50},textQuestion:"在早期漢字的構形中，樹幹、樹枝與根部的意象，最接近哪個字？"},{id:"e30",tier:1,category:"象形文字",question:"三道並列流動線條的河流示意，最接近哪個漢字？",explanation:"「川」與河流的象形意象有關，並列線條可用來表達水流；這是教學示意。",hint:"呢個字亦可以喺形容河流嘅詞語入面見到。",art:"river",source:{label:"香港教育局・中國語文教育",url:"https://www.edb.gov.hk/tc/curriculum-development/kla/chi-edu/"},options:["山","日","門","川"],answer:3,focus:{x:50,y:50}},{id:"m01",tier:2,category:"地理",question:"香港面積最大的天然島嶼是哪一個？",explanation:"大嶼山是香港最大的天然島嶼，擁有山地、郊野及大型基建。",hint:"昂坪、東涌同大澳都喺同一個大島。",art:"mountain",source:{label:"香港旅遊發展局",url:"https://www.discoverhongkong.com/tc/"},options:["香港島","南丫島","長洲","大嶼山"],answer:3,focus:{x:50,y:50}},{id:"m02",tier:2,category:"郊遊",question:"香港最高的山峰是哪一座？",explanation:"大帽山海拔957米，是香港最高的山峰。",hint:"佢位於新界，名字唔係因為山頂有隻獅子。",art:"mountain",source:{label:"漁農自然護理署",url:"https://www.afcd.gov.hk/tc_chi/"},options:["大帽山","獅子山","太平山","飛鵝山"],answer:0,focus:{x:50,y:50}},{id:"m03",tier:2,category:"郊遊",question:"麥理浩徑全長約多少公里？",explanation:"麥理浩徑全長約100公里，是香港著名長途遠足徑，分為10段。",hint:"佢嘅全長係一個整百數。",art:"trail",source:{label:"漁農自然護理署",url:"https://www.afcd.gov.hk/tc_chi/"},options:["25公里","100公里","50公里","160公里"],answer:1,focus:{x:55,y:62}},{id:"m04",tier:2,category:"郊遊",question:"港島徑全長約多少公里？",explanation:"港島徑全長約50公里，橫跨香港島多個郊野區域，分為8段。",hint:"呢條路線比麥理浩徑短，大約係後者嘅一半。",art:"trail",source:{label:"漁農自然護理署",url:"https://www.afcd.gov.hk/tc_chi/"},options:["10公里","100公里","50公里","200公里"],answer:2,focus:{x:55,y:62}},{id:"m05",tier:2,category:"郊遊",question:"鳳凰徑全長約多少公里？",explanation:"鳳凰徑是大嶼山的長途遠足徑，全長約70公里，分為12段。",hint:"佢圍繞大嶼山多種山海景觀，長度介乎港島徑同麥理浩徑之間。",art:"trail",source:{label:"漁農自然護理署",url:"https://www.afcd.gov.hk/tc_chi/"},options:["15公里","120公里","250公里","70公里"],answer:3,focus:{x:55,y:62}},{id:"m06",tier:2,category:"郊遊",question:"衛奕信徑全長約多少公里？",explanation:"衛奕信徑全長約78公里，路線跨越香港島及新界，分為10段。",hint:"佢唔係整數百公里，亦唔係只喺港島行一小圈。",art:"trail",source:{label:"漁農自然護理署",url:"https://www.afcd.gov.hk/tc_chi/"},options:["78公里","18公里","40公里","150公里"],answer:0,focus:{x:55,y:62}},{id:"m07",tier:2,category:"自然",question:"東平洲最著名的層狀岩石，主要屬於哪一大類岩石？",explanation:"東平洲以層理分明的沉積岩著名，與西貢火山岩區的地貌不同。",hint:"一層一層累積，再經漫長歲月形成，係個關鍵。",art:"geopark",source:{label:"漁農自然護理署",url:"https://www.afcd.gov.hk/tc_chi/"},options:["花崗岩","沉積岩","大理岩","人工混凝土"],answer:1,focus:{x:55,y:60}},{id:"m08",tier:2,category:"自然",question:"萬宜水庫東壩附近著名的六角岩柱，主要與哪類地質作用有關？",explanation:"西貢的六角形岩柱與古代火山活動及岩石冷卻收縮有關，並非人工切割出來。",hint:"要諗地質形成過程，唔好當佢係工程砌出嚟。",art:"geopark",source:{label:"漁農自然護理署",url:"https://www.afcd.gov.hk/tc_chi/"},options:["現代人工切割","海鹽直接結晶","火山活動後的冷卻收縮","珊瑚堆積"],answer:2,focus:{x:55,y:60}},{id:"m09",tier:2,category:"自然",question:"橋咀洲與橋頭之間的連島沙洲，通常在甚麼潮汐情況較易露出？",explanation:"連島沙洲在較低潮位時會露出；實際潮汐及天氣可查閱官方資料。",hint:"水位低咗，原本被海水蓋住嘅地形先較容易見到。",art:"geopark",source:{label:"漁農自然護理署",url:"https://www.afcd.gov.hk/tc_chi/"},options:["高潮","颱風最強時","完全沒有潮汐時","低潮"],answer:3,focus:{x:55,y:60}},{id:"m10",tier:2,category:"歷史",question:"「PMQ元創方」的建築前身是哪一種設施？",explanation:"PMQ元創方的前身是荷李活道已婚警察宿舍，現發展為創意及設計空間。",hint:"佢個英文名字保留咗原本用途嘅縮寫。",art:"temple",source:{label:"古物古蹟辦事處",url:"https://www.amo.gov.hk/tc/home/"},options:["已婚警察宿舍","製糖工廠","渡輪船塢","電影攝影棚"],answer:0,focus:{x:50,y:50}},{id:"m11",tier:2,category:"歷史",question:"大館所在的歷史建築群，原本包括警署、裁判司署和甚麼設施？",explanation:"大館由中區警署、中央裁判司署及域多利監獄等建築活化而成。",hint:"以前係一組同執法及司法有關嘅設施。",art:"temple",source:{label:"古物古蹟辦事處",url:"https://www.amo.gov.hk/tc/home/"},options:["機場","監獄","船廠","天文台"],answer:1,focus:{x:50,y:50}},{id:"m12",tier:2,category:"歷史",question:"三棟屋博物館主要展示哪一種傳統村落文化？",explanation:"荃灣三棟屋博物館以原有客家圍村建築及生活文化為重要內容。",hint:"佢嘅前身唔係皇宮，而係香港本地一條傳統村落。",art:"temple",source:{label:"康樂及文化事務署",url:"https://www.lcsd.gov.hk/tc/"},options:["愛斯基摩冰屋文化","草原蒙古包文化","客家圍村文化","地中海漁港文化"],answer:2,focus:{x:50,y:50}},{id:"m13",tier:2,category:"景點",question:"錦田吉慶圍位於香港哪一區？",explanation:"吉慶圍位於新界元朗錦田，是香港著名圍村之一。",hint:"留意「錦田」呢個地名，佢唔喺港島或者九龍市區。",art:"temple",source:{label:"古物古蹟辦事處",url:"https://www.amo.gov.hk/tc/home/"},options:["南區","觀塘","離島區","元朗"],answer:3,focus:{x:50,y:50}},{id:"m14",tier:2,category:"建築",question:"志蓮淨苑的主要建築形式，常以哪個朝代的木構風格作為參考？",explanation:"鑽石山志蓮淨苑以唐代風格木構建築著名，毗鄰南蓮園池。",hint:"諗吓佛教建築同中國古代木構，唔係近代洋樓。",art:"temple",source:{label:"香港旅遊發展局",url:"https://www.discoverhongkong.com/tc/"},options:["唐代","清代西式洋樓","古羅馬帝國","維多利亞時代"],answer:0,focus:{x:50,y:50}},{id:"m15",tier:2,category:"文化",question:"上環文武廟中的「文」與「武」，主要分別對應哪兩位神祇？",explanation:"文武廟主要供奉文昌帝君及關聖帝君，分別代表文、武。",hint:"其中一位同讀書功名有關，另一位係廣為人知嘅關帝。",art:"temple",source:{label:"古物古蹟辦事處",url:"https://www.amo.gov.hk/tc/home/"},options:["玉皇大帝與媽祖","文昌帝君與關聖帝君","天后與北帝","土地公與財神"],answer:1,focus:{x:50,y:50}},{id:"m16",tier:2,category:"傳統節日",question:"香港的盂蘭勝會，一般多在農曆哪個月份舉行？",explanation:"香港多個社區會在農曆七月舉行盂蘭相關民俗活動，形式與日期因社區而異。",hint:"呢個月份喺民間習俗中，特別重視祭祀及普度。",art:"lantern",source:{label:"康樂及文化事務署",url:"https://www.lcsd.gov.hk/tc/"},options:["正月","四月","七月","十二月"],answer:2,focus:{x:55,y:45}},{id:"m17",tier:2,category:"傳統節日",question:"重陽節是農曆哪一天？",explanation:"重陽節在農曆九月初九，香港常見習俗包括登高及祭祖。",hint:"個節名講到兩個相同嘅陽數。",art:"mountain",source:{label:"香港旅遊發展局",url:"https://www.discoverhongkong.com/tc/"},options:["八月十五","五月初五","正月十五","九月初九"],answer:3,focus:{x:50,y:50}},{id:"m18",tier:2,category:"傳統節日",question:"以下哪一個節日本身也是二十四節氣之一？",explanation:"清明既是節氣名稱，也形成祭祖掃墓的重要節日，並非以固定農曆日期界定。",hint:"唔好只睇農曆月份，要諗春季嘅節氣。",art:"tree",source:{label:"香港天文台",url:"https://www.hko.gov.hk/tc/index.html"},options:["清明","端午","中秋","重陽"],answer:0,focus:{x:50,y:50}},{id:"m19",tier:2,category:"飲食",question:"傳統圍村「盆菜」最具代表性的進食方式是哪一項？",explanation:"盆菜把多種食材分層盛在大盆，與新界圍村的宴聚文化關係密切。",hint:"佢個名已經提示咗盛載器皿，而且通常係大家一齊食。",art:"bun",source:{label:"香港旅遊發展局",url:"https://www.discoverhongkong.com/tc/"},options:["每人一小杯冷飲","多種食材分層放入大盆共同享用","只吃生果不用熱食","把所有食材磨成粉"],answer:1,focus:{x:50,y:58}},{id:"m20",tier:2,category:"傳統節日",question:"長洲「包山節」所屬的傳統宗教民俗活動，正式常稱為甚麼？",explanation:"長洲太平清醮包含多種儀式和社區活動，搶包山只是其中最為人熟悉的部分。",hint:"個名稱有祈求平安、清醮嘅意思。",art:"buns",source:{label:"康樂及文化事務署",url:"https://www.lcsd.gov.hk/tc/"},options:["打小人","七姐誕","太平清醮","冬至祭海"],answer:2,focus:{x:50,y:40}},{id:"m21",tier:2,category:"體育",question:"李麗珊在1996年哪一個城市舉行的奧運奪金？",explanation:"李麗珊在1996年亞特蘭大奧運贏得女子滑浪風帆金牌。",hint:"呢屆奧運喺美國舉行，唔係澳洲嗰屆。",art:"sport",source:{label:"中國香港體育協會暨奧林匹克委員會",url:"https://www.hkolympic.org/"},options:["悉尼","雅典","北京","亞特蘭大"],answer:3,focus:{x:53,y:52}},{id:"m22",tier:2,category:"體育",question:"香港主辦東亞運動會是哪一年？",explanation:"香港在2009年主辦第五屆東亞運動會，是本地大型體育盛事之一。",hint:"喺2008北京奧運之後一年。",art:"sport",source:{label:"中國香港體育協會暨奧林匹克委員會",url:"https://www.hkolympic.org/"},options:["2009年","1997年","2016年","2024年"],answer:0,focus:{x:53,y:52}},{id:"m23",tier:2,category:"體育",question:"香港國際七人欖球賽的「七人」，指每隊在場上通常有多少名球員？",explanation:"七人欖球與十五人欖球同屬欖球運動，但每隊場上人數及比賽節奏不同。",hint:"題目問嘅唔係後備名額，係場上人數。",art:"sport",source:{label:"香港旅遊發展局",url:"https://www.discoverhongkong.com/tc/"},options:["5名","7名","11名","15名"],answer:1,focus:{x:53,y:52}},{id:"m24",tier:2,category:"地理",question:"獅子山一帶的山脊，常被視為九龍與哪個地區之間的地理分隔？",explanation:"獅子山及九龍群山位於九龍與新界之間，從兩側眺望都有不同城市景觀。",hint:"山北面可以諗起沙田等新市鎮。",art:"lion",source:{label:"漁農自然護理署",url:"https://www.afcd.gov.hk/tc_chi/"},options:["澳門","海南島","新界","台灣"],answer:2,focus:{x:55,y:38}},{id:"m25",tier:2,category:"景點",question:"重慶大廈位於香港哪一個地區？",explanation:"重慶大廈位於尖沙咀彌敦道，以多元文化、旅館及不同地區餐飲聞名。",hint:"佢喺一條好出名嘅九龍大街，唔係郊外村落。",art:"harbour",source:{label:"香港旅遊發展局",url:"https://www.discoverhongkong.com/tc/"},options:["大澳","上水","赤柱","尖沙咀"],answer:3,focus:{x:50,y:58}},{id:"m26",tier:2,category:"旅遊",question:"鯉魚門最廣為遊客熟悉的飲食體驗是哪一項？",explanation:"鯉魚門以海港村落風貌及海鮮餐飲體驗聞名。",hint:"從地名同海邊環境去諗，答案同漁港飲食有關。",art:"ferry",source:{label:"香港旅遊發展局",url:"https://www.discoverhongkong.com/tc/"},options:["海鮮餐飲","雪山火鍋","咖啡種植園","葡萄酒莊"],answer:0,focus:{x:53,y:65}},{id:"m27",tier:2,category:"旅遊",question:"香港著名的玉器市場主要位於哪個傳統市區一帶？",explanation:"油麻地一帶的玉器市場及相關街道，是香港傳統旅遊及市集文化的一部分。",hint:"諗吓九龍舊區，附近仲有廟街。",art:"temple",source:{label:"香港旅遊發展局",url:"https://www.discoverhongkong.com/tc/"},options:["東涌","油麻地","將軍澳","粉嶺"],answer:1,focus:{x:50,y:50}},{id:"m28",tier:2,category:"文化",question:"粵劇常說的「唱、唸、做、打」中，「唸」主要指甚麼？",explanation:"唱、唸、做、打是戲曲表演的基本功分類；「唸」涉及唸白與語言表達。",hint:"唔一定係唱旋律，但觀眾仍然會聽到角色用聲音講故事。",art:"calligraphy",source:{label:"康樂及文化事務署",url:"https://www.lcsd.gov.hk/tc/"},textOnly:!0,options:["畫舞台背景","出售戲票","唸白及說話表達","調校燈光"],answer:2,focus:{x:50,y:50}},{id:"m29",tier:2,category:"書法",question:"草書相對楷書，常見哪一種書寫特徵？",explanation:"草書常以省筆、連筆及流暢筆勢形成風格，辨識時要留意字形的變化。",hint:"留意「草」唔係顏色，而係書寫形態同筆勢。",art:"calligraphy",source:{label:"香港教育局・中國語文教育",url:"https://www.edb.gov.hk/tc/curriculum-development/kla/chi-edu/"},textOnly:!0,options:["每字必須四四方方且禁止連筆","只能以白色顏料書寫","完全不用毛筆","筆畫連綿、省簡而富流動感"],answer:3,focus:{x:50,y:50}},{id:"m30",tier:2,category:"景點",question:"南蓮園池與志蓮淨苑相鄰，位於哪個九龍地區？",explanation:"南蓮園池及志蓮淨苑位於鑽石山，是市區中可欣賞園林及木構建築的景點。",hint:"附近港鐵站嘅名字同一種珍貴石頭有關。",art:"temple",source:{label:"香港旅遊發展局",url:"https://www.discoverhongkong.com/tc/"},options:["鑽石山","土瓜灣","尖沙咀","荔枝角"],answer:0,focus:{x:50,y:50}},{id:"h01",tier:2,category:"郊遊",question:"麥理浩徑官方分為多少段？",explanation:"麥理浩徑全長約100公里，官方分為10段；每段長度及難度並不相同。",hint:"總長約一百公里，分段數係個整十數。",art:"trail",source:{label:"漁農自然護理署",url:"https://www.afcd.gov.hk/tc_chi/"},options:["10段","8段","12段","16段"],answer:0,focus:{x:55,y:62}},{id:"h02",tier:2,category:"郊遊",question:"港島徑官方分為多少段？",explanation:"港島徑全長約50公里，官方分為8段，其中第8段包含龍脊一帶。",hint:"呢條只喺香港島嘅長途徑，分段比麥理浩徑少。",art:"trail",source:{label:"漁農自然護理署",url:"https://www.afcd.gov.hk/tc_chi/"},options:["6段","8段","10段","12段"],answer:1,focus:{x:55,y:62}},{id:"h03",tier:2,category:"郊遊",question:"鳳凰徑官方分為多少段？",explanation:"鳳凰徑全長約70公里，官方分為12段，路線主要在大嶼山。",hint:"比麥理浩徑嘅分段數多兩段。",art:"trail",source:{label:"漁農自然護理署",url:"https://www.afcd.gov.hk/tc_chi/"},options:["8段","10段","12段","20段"],answer:2,focus:{x:55,y:62}},{id:"h04",tier:2,category:"郊遊",question:"衛奕信徑官方分為多少段？",explanation:"衛奕信徑全長約78公里，官方分為10段，橫跨香港島與新界。",hint:"佢同麥理浩徑嘅分段數目相同，但全長唔相同。",art:"trail",source:{label:"漁農自然護理署",url:"https://www.afcd.gov.hk/tc_chi/"},options:["5段","8段","14段","10段"],answer:3,focus:{x:55,y:62}},{id:"h05",tier:3,category:"郊遊",question:"港島徑第8段的官方起訖點是哪一組？",explanation:"港島徑第8段由土地灣至大浪灣，途經著名的龍脊山脊。",hint:"龍脊屬於港島東南部路段，終點喺一個海灣。",art:"trail",source:{label:"漁農自然護理署",url:"https://www.afcd.gov.hk/tc_chi/"},options:["土地灣至大浪灣","大潭道至土地灣","柏架山道至大潭道","黃泥涌峽至柏架山道"],answer:0,focus:{x:55,y:62}},{id:"h06",tier:3,category:"郊遊",question:"麥理浩徑第1段的官方起訖點是哪一組？",explanation:"麥理浩徑第1段由北潭涌至浪茄，路線經萬宜水庫一帶。",hint:"呢段係成條路線嘅開端，會經過水庫景色。",art:"geopark",source:{label:"漁農自然護理署",url:"https://www.afcd.gov.hk/tc_chi/"},options:["浪茄至北潭凹","北潭涌至浪茄","北潭凹至企嶺下","企嶺下至大老山"],answer:1,focus:{x:55,y:60}},{id:"h07",tier:3,category:"郊遊",question:"麥理浩徑第2段的官方起訖點是哪一組？",explanation:"麥理浩徑第2段由浪茄至北潭凹，途經西貢東多處山海景觀。",hint:"接住第1段嘅終點出發，仍然喺西貢區域。",art:"trail",source:{label:"漁農自然護理署",url:"https://www.afcd.gov.hk/tc_chi/"},options:["北潭涌至浪茄","北潭凹至企嶺下","浪茄至北潭凹","企嶺下至大老山"],answer:2,focus:{x:55,y:62}},{id:"h08",tier:3,category:"郊遊",question:"衛奕信徑第1段的官方起訖點是哪一組？",explanation:"衛奕信徑第1段由赤柱峽道至黃泥涌水塘，位於香港島南部。",hint:"呢條路線由港島南面開始，唔係由新界山區開始。",art:"trail",source:{label:"漁農自然護理署",url:"https://www.afcd.gov.hk/tc_chi/"},options:["陽明山莊至鰂魚涌","藍田至井欄樹","井欄樹至沙田坳","赤柱峽道至黃泥涌水塘"],answer:3,focus:{x:55,y:62}},{id:"h09",tier:3,category:"郊遊",question:"鳳凰徑第3段的官方起訖點是哪一組？",explanation:"鳳凰徑第3段由伯公坳至昂坪，途經鳳凰山，是大嶼山的山區路段。",hint:"終點可以聯想到大佛一帶，而起點係一個山坳。",art:"mountain",source:{label:"漁農自然護理署",url:"https://www.afcd.gov.hk/tc_chi/"},options:["伯公坳至昂坪","南山至伯公坳","昂坪至深屈道","梅窩至南山"],answer:0,focus:{x:50,y:50}},{id:"h10",tier:2,category:"郊遊",question:"伯公坳主要位於哪兩座大嶼山山峰之間？",explanation:"伯公坳是大嶼山鳳凰山與大東山之間的重要山坳。",hint:"兩座都係大嶼山著名高峰，唔好揀新界山峰。",art:"mountain",source:{label:"漁農自然護理署",url:"https://www.afcd.gov.hk/tc_chi/"},options:["大帽山與獅子山","鳳凰山與大東山","太平山與歌賦山","飛鵝山與馬鞍山"],answer:1,focus:{x:50,y:50}},{id:"h11",tier:3,category:"自然",question:"香港聯合國教科文組織世界地質公園的兩大地質區域，通常概括為哪一組？",explanation:"香港地質公園主要展示西貢火山岩地貌及新界東北沉積岩地貌。",hint:"一邊有六角岩柱，另一邊可以諗起東平洲嘅層狀岩石。",art:"geopark",source:{label:"漁農自然護理署",url:"https://www.afcd.gov.hk/tc_chi/"},options:["西貢沉積岩與新界東北火山岩","西貢花崗岩與新界東北石灰岩","西貢火山岩與新界東北沉積岩","西貢火山岩與新界西北沉積岩"],answer:2,focus:{x:55,y:60}},{id:"h12",tier:2,category:"歷史",question:"尖沙咀鐘樓原本屬於哪一個鐵路設施？",explanation:"鐘樓是前九廣鐵路尖沙咀總站的遺存，見證九龍鐵路及海旁的變遷。",hint:"佢嘅歷史比今日港鐵部分路線早好多，而且同往廣州嘅鐵路有關。",art:"clock",source:{label:"古物古蹟辦事處",url:"https://www.amo.gov.hk/tc/home/"},options:["港鐵黃埔站","機場快綫香港站","山頂纜車山頂站","九廣鐵路尖沙咀總站"],answer:3,focus:{x:50,y:35}},{id:"h13",tier:2,category:"文化",question:"香港茶具文物館設於哪一個公園內？",explanation:"茶具文物館設於香港公園內的旗桿屋，展示茶具及中國飲茶文化。",hint:"位置喺港島金鐘一帶，唔係尖沙咀嘅公園。",art:"milk",source:{label:"康樂及文化事務署",url:"https://www.lcsd.gov.hk/tc/"},options:["香港公園","九龍公園","維多利亞公園","沙田公園"],answer:0,focus:{x:50,y:58}},{id:"h14",tier:3,category:"歷史",question:"香港醫學博物館所在的歷史建築，前身主要是哪一種設施？",explanation:"香港醫學博物館設於上環舊病理學院，建築及展覽均與香港醫學發展有關。",hint:"建築原本就同醫學研究有關，唔係近年先轉成醫療主題。",art:"temple",source:{label:"古物古蹟辦事處",url:"https://www.amo.gov.hk/tc/home/"},options:["舊細菌學研究所附屬宿舍","舊病理學院","舊精神病院","舊維多利亞醫院產科大樓"],answer:1,focus:{x:50,y:50}},{id:"h15",tier:2,category:"歷史",question:"聚星樓位於香港哪一條著名文物徑沿線？",explanation:"聚星樓位於元朗屏山，是屏山文物徑沿線的重要古蹟。",hint:"佢喺新界西面、同鄧氏聚居歷史有關嘅地區。",art:"temple",source:{label:"古物古蹟辦事處",url:"https://www.amo.gov.hk/tc/home/"},options:["龍躍頭文物徑","中西區文物徑","屏山文物徑","大潭水務文物徑"],answer:2,focus:{x:50,y:50}},{id:"h16",tier:3,category:"歷史",question:"著名古蹟「大夫第」位於元朗哪個地方？",explanation:"大夫第位於元朗新田，是一座具有華南傳統建築特色的歷史宅第。",hint:"個地名有「田」字，但唔係錦田嗰個圍村。",art:"temple",source:{label:"古物古蹟辦事處",url:"https://www.amo.gov.hk/tc/home/"},options:["錦田","八鄉","屏山","新田"],answer:3,focus:{x:50,y:50}},{id:"h17",tier:2,category:"歷史",question:"「曾大屋」位於香港哪一區？",explanation:"曾大屋位於沙田，是香港具代表性的客家圍村建築之一。",hint:"呢條傳統村落喺城門河流域一帶。",art:"temple",source:{label:"古物古蹟辦事處",url:"https://www.amo.gov.hk/tc/home/"},options:["沙田","西貢","深水埗","離島區"],answer:0,focus:{x:50,y:50}},{id:"h18",tier:2,category:"歷史",question:"「龍躍頭文物徑」主要位於哪個新界地區？",explanation:"龍躍頭文物徑位於粉嶺一帶，串連鄧氏聚居地區的多處歷史建築。",hint:"佢喺新界北部，唔係元朗屏山嗰條。",art:"temple",source:{label:"古物古蹟辦事處",url:"https://www.amo.gov.hk/tc/home/"},options:["屯門","粉嶺","荃灣","西貢"],answer:1,focus:{x:50,y:50}},{id:"h19",tier:3,category:"歷史",question:"李鄭屋古墓被認為主要屬於哪個歷史時期？",explanation:"李鄭屋古墓一般被認為屬於東漢時期，是香港重要的考古遺址。",hint:"年代遠早於宋朝，唔係近代圍村墓葬。",art:"temple",source:{label:"古物古蹟辦事處",url:"https://www.amo.gov.hk/tc/home/"},options:["唐代","南宋","東漢","清代"],answer:2,focus:{x:50,y:50}},{id:"h20",tier:3,category:"歷史",question:"佛堂門石刻記載的紀年，屬於哪個朝代？",explanation:"佛堂門石刻位於大廟灣一帶，石刻紀年為南宋咸淳十年，是研究香港歷史的重要資料。",hint:"要諗宋朝，而且係宋室南遷之後嘅時期。",art:"calligraphy",source:{label:"古物古蹟辦事處",url:"https://www.amo.gov.hk/tc/home/"},textOnly:!0,options:["西漢","明代","清代","南宋"],answer:3,focus:{x:50,y:50}},{id:"h21",tier:3,category:"文化",question:"香港民間書寫者「九龍皇帝」的本名是甚麼？",explanation:"曾灶財以在香港街頭書寫獨特文字聞名，被俗稱為「九龍皇帝」。本題以文字回顧香港街頭書寫文化。",hint:"佢唔係小說家，亦唔係填詞人，係一位長年在街頭書寫嘅人物。",art:"calligraphy",source:{label:"康樂及文化事務署",url:"https://www.lcsd.gov.hk/tc/"},textOnly:!0,options:["曾灶財","曾國藩","曾灶榮","曾財灶"],answer:0,focus:{x:50,y:50}},{id:"h22",tier:3,category:"自然",question:"米埔及內后海灣濕地在1995年獲列入哪一項國際濕地名錄？",explanation:"米埔及內后海灣於1995年獲指定為拉姆薩爾濕地，反映其國際濕地保育價值。",hint:"呢個公約專門同濕地保育有關。",art:"river",source:{label:"漁農自然護理署",url:"https://www.afcd.gov.hk/tc_chi/"},options:["《世界遺產公約》世界遺產名錄","拉姆薩爾公約國際重要濕地名錄","聯合國教科文組織世界地質公園網絡","聯合國教科文組織生物圈保護區網絡"],answer:1,focus:{x:50,y:50}},{id:"h23",tier:2,category:"自然",question:"海下灣海岸公園最著名的海洋生態特色之一是甚麼？",explanation:"西貢海下灣海岸公園具有豐富海洋生態，珊瑚群落是其中的重要特色。",hint:"唔使潛到幾千米深，呢種生物會形成海底群落。",art:"geopark",source:{label:"漁農自然護理署",url:"https://www.afcd.gov.hk/tc_chi/"},options:["永久海冰","深海熱泉","珊瑚群落","大型海帶森林"],answer:2,focus:{x:55,y:60}},{id:"h24",tier:2,category:"自然",question:"鶴咀海岸保護區位於香港哪個大區域？",explanation:"鶴咀海岸保護區位於香港島東南部，是本地重要海岸及海洋保育地點。",hint:"位置近石澳一帶，唔係新界北面嘅島嶼。",art:"geopark",source:{label:"漁農自然護理署",url:"https://www.afcd.gov.hk/tc_chi/"},options:["大嶼山西北部","新界西北平原","東平洲北岸","香港島東南部"],answer:3,focus:{x:55,y:60}},{id:"h25",tier:2,category:"郊遊",question:"香港的「大東山」常見英文名稱是甚麼？",explanation:"大東山的英文名稱是 Sunset Peak，位於大嶼山。",hint:"個英文名字同太陽落山嘅時刻有關。",art:"mountain",source:{label:"漁農自然護理署",url:"https://www.afcd.gov.hk/tc_chi/"},options:["Sunset Peak","Victoria Peak","Lion Rock","Tai Mo Shan"],answer:0,focus:{x:50,y:50}},{id:"h26",tier:3,category:"體育",question:"在2024年巴黎奧運，何詩蓓取得銅牌的兩項個人賽事是哪一組？",explanation:"何詩蓓在2024年巴黎奧運取得女子100米及200米自由泳銅牌；不要與東京奧運的銀牌混淆。",hint:"兩項距離相差一倍，泳式係佢最擅長嗰一種。",art:"sport",source:{label:"中國香港體育協會暨奧林匹克委員會",url:"https://www.hkolympic.org/"},options:["女子100米及200米背泳","女子100米及200米自由泳","女子50米及100米自由泳","女子200米及400米自由泳"],answer:1,focus:{x:53,y:52}},{id:"h27",tier:3,category:"體育",question:"張家朗首次取得奧運金牌，來自哪一屆奧運？",explanation:"張家朗在2020東京奧運男子個人花劍奪金；該屆因疫情延至2021年舉行。",hint:"要分清楚賽會正式名稱嘅年份，同實際舉行年份。",art:"sport",source:{label:"中國香港體育協會暨奧林匹克委員會",url:"https://www.hkolympic.org/"},options:["2012倫敦奧運","2016里約熱內盧奧運","2020東京奧運（2021年舉行）","2008北京奧運"],answer:2,focus:{x:53,y:52}},{id:"h28",tier:3,category:"書法",question:"在傳統「六書」構字分類中，「江」通常被視為哪一類？",explanation:"「江」一般以「水」作形旁、「工」作聲旁，是常見的形聲字例子。",hint:"一部分提示意義，另一部分同讀音有關。",art:"calligraphy",source:{label:"香港教育局・中國語文教育",url:"https://www.edb.gov.hk/tc/curriculum-development/kla/chi-edu/"},textOnly:!0,options:["象形","指事","會意","形聲"],answer:3,focus:{x:50,y:50}},{id:"h29",tier:2,category:"書法",question:"「休」由人與木組合，用來表示人在樹旁休息的意象，通常屬於哪類構字？",explanation:"「休」通常被用作會意字例子，由兩個構件組合表達新的意思。",hint:"呢題重點係兩個構件一齊表意，唔係一邊只負責讀音。",art:"tree",source:{label:"香港教育局・中國語文教育",url:"https://www.edb.gov.hk/tc/curriculum-development/kla/chi-edu/"},textOnly:!0,options:["會意","純粹象形","假借","轉注"],answer:0,focus:{x:50,y:50}},{id:"h30",tier:2,category:"書法",question:"傳統書法中，「篆、隸、楷、行、草」主要是在分類甚麼？",explanation:"篆書、隸書、楷書、行書及草書是常見的漢字書體分類，不同書體有各自的筆畫及結構特徵。",hint:"佢哋可以用同一種紙墨書寫，差別唔在工具材料。",art:"calligraphy",source:{label:"香港教育局・中國語文教育",url:"https://www.edb.gov.hk/tc/curriculum-development/kla/chi-edu/"},textOnly:!0,options:["紙張尺寸","書體","墨色濃度","裝裱方向"],answer:1,focus:{x:50,y:50}}].map(t=>Object.freeze({...t,options:Object.freeze(t.options),source:Object.freeze(t.source),focus:Object.freeze(t.focus)}))),k=Object.freeze([...Ct,...et,...rt,...it,...tt,...J,...$,...X,...Z,...G,...Y,...K,...V,...W]);var y="hk-2026-11",Rt=Object.freeze([y]),S=864e5,lt=288e5,Q=Object.freeze([1e3,2e3,3e3,4e3,8e3,1e4,2e4,3e4,4e4,6e4,8e4,15e4,25e4,5e5,1e6]),ct=Object.freeze([{id:"ordinary",name:"運氣平平",min:0,note:"香港故事仲有好多，聽日再接再厲。"},{id:"neighbour",name:"街坊地保",min:8e3,note:"街頭巷尾嘅香港常識，難唔到你。"},{id:"expert",name:"香港通",min:6e4,note:"地理、節慶與文化，你都熟門熟路。"},{id:"peak",name:"太平山神",min:5e5,note:"只差一步登頂，你已經站得好高。"},{id:"millionaire",name:"百萬富翁",min:1e6,note:"十五題全中，今晚香港由你話事！"}]),Ze=Object.freeze(["original","text"]),Xe=Object.freeze({original:"香港知識",text:"地膽常識"}),H=new Map(k.map(t=>[t.id,t])),ut=(t,e)=>e?ut(e,t%e):t;function at(t,e){for(;ut(t,e)!==1;)e++;return e}function Mt(t){return Object.freeze([1,2,3].map(e=>{let o=Object.freeze(t.filter(r=>r.tier===e).map(r=>r.id));return Object.freeze({ids:o,dayStep:at(o.length,17),slotStep:at(o.length,7)})}))}var D=Object.freeze({[y]:Mt(k)}),g=(t=Date.now())=>Math.floor((t+lt)/S),U=t=>(t+1)*S-lt,Pt=t=>new Date(t*S).toISOString().slice(0,7),$e=t=>new Intl.DateTimeFormat("zh-HK",{timeZone:"UTC",month:"long",day:"numeric"}).format(new Date(t*S)),Qt=t=>Math.max(1,t-g(Date.UTC(2026,10,25,16))+1);function m(t){let e=2166136261;for(let o of String(t))e=Math.imul(e^o.codePointAt(0),16777619);return e>>>0}function q(t,e,o=y){let r=Math.floor(e/5),i=D[o]?.[r];if(!i)throw Error("bank-version");let n=(t*i.dayStep+e%5*i.slotStep+r*11)%i.ids.length;return i.ids[n]}